-- ---------- RLS: admissions staff only (public pages use the server) ----------
do $$
declare t text;
begin
  foreach t in array array['admission_leads','lead_activities','admission_events','admission_bookings','admission_sequences',
                           'lead_sequence_runs','admission_templates','application_documents','admission_payments','admission_capacity',
                           'admission_costs','entrance_attempts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_admissions', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_admissions()) with check (tenant_id = public.my_tenant_id() and public.is_admissions())', t || '_admissions', t);
  end loop;
end $$;
alter table public.admission_sequence_steps enable row level security;
drop policy if exists admission_sequence_steps_admissions on public.admission_sequence_steps;
create policy admission_sequence_steps_admissions on public.admission_sequence_steps for all using (
  exists (select 1 from public.admission_sequences s where s.id = admission_sequence_steps.sequence_id and s.tenant_id = public.my_tenant_id() and public.is_admissions())
) with check (
  exists (select 1 from public.admission_sequences s where s.id = admission_sequence_steps.sequence_id and s.tenant_id = public.my_tenant_id() and public.is_admissions()));

-- Payments and entrance results are written only by the server (verified with the provider / marked by the engine).
drop policy if exists admission_payments_admissions on public.admission_payments;
drop policy if exists admission_payments_read on public.admission_payments;
create policy admission_payments_read on public.admission_payments for select using (tenant_id = public.my_tenant_id() and public.is_admissions());
drop policy if exists entrance_attempts_admissions on public.entrance_attempts;
drop policy if exists entrance_attempts_read on public.entrance_attempts;
create policy entrance_attempts_read on public.entrance_attempts for select using (tenant_id = public.my_tenant_id() and public.is_admissions());

insert into storage.buckets (id, name, public) values ('admissions', 'admissions', false) on conflict (id) do nothing;

-- ===== 20260101003000_review_fixes.sql =====
-- =========================================================================
-- EduClass Fusion: fixes from the full-spec review.
--  * The lead webhook key lived in tenant_settings, which every account in a
--    school (students and parents included) can read. It moves to
--    admission_secrets, which only the server can read.
--  * book_admission_event(): public tour / open-day booking checks capacity
--    and inserts in one locked step, so two families cannot both take the
--    last seats.
-- Apply AFTER 20260101002900. Idempotent.
-- =========================================================================

create table if not exists public.admission_secrets (
  tenant_id         uuid primary key references public.tenants(id) on delete cascade,
  lead_webhook_key  text unique,
  updated_at        timestamptz not null default now()
);
alter table public.admission_secrets enable row level security;
-- No policies: only the service role (server) reads or writes this table.
revoke all on public.admission_secrets from anon, authenticated;

do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'tenant_settings' and column_name = 'lead_webhook_key') then
    insert into public.admission_secrets (tenant_id, lead_webhook_key)
      select tenant_id, lead_webhook_key from public.tenant_settings where lead_webhook_key is not null
      on conflict (tenant_id) do update set lead_webhook_key = excluded.lead_webhook_key;
    alter table public.tenant_settings drop column lead_webhook_key;
  end if;
end $$;

-- Atomic booking (p_staff: staff may book unpublished or past sessions). Returns the booking token, or raises 'full' / 'not available' / 'already booked'.
create or replace function public.book_admission_event(p_event uuid, p_lead uuid, p_name text, p_phone text, p_email text, p_party int, p_staff boolean default false)
returns text language plpgsql security definer set search_path = public as $$
declare
  e public.admission_events;
  taken int;
  tok text;
begin
  select * into e from public.admission_events where id = p_event for update;
  if e.id is null or (not p_staff and (not e.published or e.starts_at < now())) then raise exception 'not available'; end if;
  if exists (select 1 from public.admission_bookings where event_id = p_event and status <> 'cancelled' and phone = p_phone) then raise exception 'already booked'; end if;
  select coalesce(sum(party_size), 0) into taken from public.admission_bookings where event_id = p_event and status <> 'cancelled';
  if taken + p_party > e.capacity then raise exception 'full'; end if;
  insert into public.admission_bookings (tenant_id, event_id, lead_id, name, phone, email, party_size)
    values (e.tenant_id, p_event, p_lead, p_name, p_phone, p_email, p_party) returning token into tok;
  return tok;
end $$;
revoke all on function public.book_admission_event(uuid, uuid, text, text, text, int, boolean) from public, anon, authenticated;
grant execute on function public.book_admission_event(uuid, uuid, text, text, text, int, boolean) to service_role;
grant all on public.admission_secrets to service_role;

-- ===== 20260101003100_community_crm.sql =====
-- =========================================================================
-- EduClass Fusion: parent and community CRM (phase 3).
--  * crm_interactions: calls, meetings, visits and notes with families,
--    alumni and partners (the timeline behind the 360° family profile).
--  * tickets / ticket_messages: complaints and requests with SLAs,
--    assignment, escalation and a satisfaction rating when resolved.
--  * surveys / survey_invites / survey_responses: NPS and other surveys
--    answered from a private link; anonymous surveys keep no link to the
--    family.
--  * family_segments: saved family filters for campaigns.
--  * reenrolment_rounds / reenrolment_responses: "Will your child return
--    next session?" with reasons.
--  * referral_rewards: a reward per referred family that enrols.
--  * alumni: former students, from graduation or self-registration.
--  * crm_campaigns: email/SMS/WhatsApp campaigns and newsletters.
--  * crm_partners: vendors, suppliers, sponsors and partner organisations.
-- School admins and principals manage all of it. Any staff member can log a
-- ticket and works the tickets they raised or are assigned; the bursar also
-- sees vendors and referral rewards. Parents act only through the server.
-- Apply AFTER 20260101003000. Idempotent.
-- =========================================================================

alter table public.guardians add column if not exists marketing_opt_out boolean not null default false;
alter table public.guardians add column if not exists unsubscribe_token text;
update public.guardians set unsubscribe_token = encode(gen_random_bytes(16), 'hex') where unsubscribe_token is null;
alter table public.guardians alter column unsubscribe_token set default encode(gen_random_bytes(16), 'hex');
create unique index if not exists guardians_unsubscribe_token on public.guardians(unsubscribe_token);

alter table public.tenant_settings add column if not exists ticket_sla jsonb not null default '{}'::jsonb;   -- { "<priority>": { "respond": hours, "resolve": hours } }
alter table public.tenant_settings add column if not exists referral_reward_kind text not null default 'fee_discount';
alter table public.tenant_settings drop constraint if exists tenant_settings_referral_reward_kind_check;
alter table public.tenant_settings add constraint tenant_settings_referral_reward_kind_check check (referral_reward_kind in ('fee_discount','wallet_credit','gift','cash'));
alter table public.tenant_settings add column if not exists referral_reward_amount numeric(14,2) not null default 0;

create or replace function public.is_bursar_or_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['school_admin','principal','platform_admin','bursar']);
$$;
grant execute on function public.is_bursar_or_admin() to authenticated;

-- ---------- alumni and partners (interactions point at them) ----------
create table if not exists public.alumni (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  student_id        uuid references public.students(id) on delete set null,
  full_name         text not null check (length(full_name) between 2 and 160),
  graduation_year   int check (graduation_year between 1900 and 2200),
  last_class        text,
  email             text,
  phone             text,
  occupation        text,
  employer          text,
  further_study     text,             -- university / college and course
  city              text,
  country           text,
  linkedin          text,
  mentor            boolean not null default false,   -- happy to mentor current students
  consent_contact   boolean not null default true,
  status            text not null default 'active' check (status in ('pending','active','archived')),
  source            text not null default 'graduated' check (source in ('graduated','self','import','staff')),
  notes             text,
  update_token      text not null default encode(gen_random_bytes(16), 'hex'),   -- private self-update link
  unsubscribe_token text not null default encode(gen_random_bytes(16), 'hex'),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (update_token),
  unique (unsubscribe_token)
);
create unique index if not exists alumni_student on public.alumni(tenant_id, student_id) where student_id is not null;
create index if not exists alumni_year on public.alumni(tenant_id, graduation_year);

create table if not exists public.crm_partners (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  name            text not null check (length(name) between 2 and 160),
  kind            text not null default 'vendor' check (kind in ('vendor','supplier','partner','sponsor','ngo','government','media','other')),
  category        text,               -- e.g. "uniforms", "catering", "ICT"
  status          text not null default 'active' check (status in ('prospect','active','inactive')),
  contact_name    text,
  email           text,
  phone           text,
  website         text,
  address         text,
  contract_start  date,
  contract_end    date,
  contract_value  numeric(14,2),
  rating          int check (rating between 1 and 5),
  tags            text[] not null default '{}',
  notes           text,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists crm_partners_kind on public.crm_partners(tenant_id, kind);

-- ---------- interactions ----------
create table if not exists public.crm_interactions (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  guardian_id  uuid references public.guardians(id) on delete cascade,
  student_id   uuid references public.students(id) on delete set null,
  alumni_id    uuid references public.alumni(id) on delete cascade,
  partner_id   uuid references public.crm_partners(id) on delete cascade,
  kind         text not null default 'note' check (kind in ('note','call','meeting','email','sms','whatsapp','visit','retention','other')),
  body         text not null check (length(body) between 1 and 4000),
