-- ---------- referral rewards ----------
create table if not exists public.referral_rewards (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  guardian_id  uuid not null references public.guardians(id) on delete cascade,
  lead_id      uuid references public.admission_leads(id) on delete set null,
  kind         text not null default 'fee_discount' check (kind in ('fee_discount','wallet_credit','gift','cash')),
  amount       numeric(14,2) not null default 0 check (amount >= 0),
  status       text not null default 'pending' check (status in ('pending','approved','issued','cancelled')),
  note         text,
  approved_by  uuid references public.users(id) on delete set null,
  issued_at    timestamptz,
  created_at   timestamptz not null default now()
);
create unique index if not exists referral_rewards_lead on public.referral_rewards(lead_id) where lead_id is not null;

-- A referred family that enrols earns the referrer the school's standard reward, once.
create or replace function public.referral_reward_on_enrol()
returns trigger language plpgsql security definer set search_path = public as $$
declare s record;
begin
  if new.stage = 'enrolled' and new.referred_by is not null and (tg_op = 'INSERT' or old.stage is distinct from 'enrolled') then
    select referral_reward_kind, referral_reward_amount into s from public.tenant_settings where tenant_id = new.tenant_id;
    if s is not null and coalesce(s.referral_reward_amount, 0) > 0 then
      insert into public.referral_rewards (tenant_id, guardian_id, lead_id, kind, amount)
        values (new.tenant_id, new.referred_by, new.id, s.referral_reward_kind, s.referral_reward_amount)
        on conflict (lead_id) where lead_id is not null do nothing;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists admission_leads_referral_reward on public.admission_leads;
create trigger admission_leads_referral_reward after insert or update of stage on public.admission_leads
  for each row execute function public.referral_reward_on_enrol();

-- ---------- campaigns and newsletters ----------
create table if not exists public.crm_campaigns (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(name) between 2 and 120),
  kind          text not null default 'campaign' check (kind in ('campaign','newsletter')),
  subject       text not null check (length(subject) between 2 and 160),
  body          text not null default '',
  blocks        jsonb not null default '[]'::jsonb,       -- newsletter sections: [{ heading, text, image_url, link_url, link_label }]
  channels      text[] not null default '{email}',
  audience      jsonb not null default '{"type":"parents"}'::jsonb,
  status        text not null default 'draft' check (status in ('draft','scheduled','sending','sent','cancelled')),
  scheduled_at  timestamptz,
  sent_at       timestamptz,
  recipients    int not null default 0,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists crm_campaigns_due on public.crm_campaigns(scheduled_at) where status = 'scheduled';

-- Attendance per student over a window, for retention flags (server only).
create or replace function public.attendance_rates(p_tenant uuid, p_since date)
returns table (student_id uuid, present int, total int) language sql stable security definer set search_path = public as $$
  select a.student_id, count(*) filter (where a.status in ('present','late'))::int, count(*)::int
  from public.class_attendance a where a.tenant_id = p_tenant and a.date >= p_since group by a.student_id;
$$;
revoke all on function public.attendance_rates(uuid, date) from public, anon, authenticated;
grant execute on function public.attendance_rates(uuid, date) to service_role;

-- ---------- RLS ----------
do $$
declare t text;
begin
  foreach t in array array['alumni','surveys','survey_invites','survey_responses','family_segments','reenrolment_rounds',
                           'reenrolment_responses','crm_campaigns'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_admin', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_school_admin()) with check (tenant_id = public.my_tenant_id() and public.is_school_admin())', t || '_admin', t);
  end loop;
  foreach t in array array['crm_partners','referral_rewards'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_admin', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_bursar_or_admin()) with check (tenant_id = public.my_tenant_id() and public.is_bursar_or_admin())', t || '_admin', t);
  end loop;
end $$;

-- Responses and invites are written by the server (from the family's private link).
drop policy if exists survey_responses_admin on public.survey_responses;
drop policy if exists survey_responses_read on public.survey_responses;
create policy survey_responses_read on public.survey_responses for select using (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists survey_invites_admin on public.survey_invites;
drop policy if exists survey_invites_read on public.survey_invites;
create policy survey_invites_read on public.survey_invites for select using (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- Interactions: admins see every one; other staff log and see their own.
alter table public.crm_interactions enable row level security;
drop policy if exists crm_interactions_admin on public.crm_interactions;
create policy crm_interactions_admin on public.crm_interactions for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists crm_interactions_own on public.crm_interactions;
create policy crm_interactions_own on public.crm_interactions for all
  using (tenant_id = public.my_tenant_id() and public.is_staff() and actor_id = auth.uid())
  with check (tenant_id = public.my_tenant_id() and public.is_staff() and actor_id = auth.uid() and alumni_id is null and partner_id is null);

-- Tickets: admins see all; other staff see the ones they raised or are assigned.
-- New tickets are numbered by the server, so inserts go through the API.
alter table public.tickets enable row level security;
drop policy if exists tickets_read on public.tickets;
create policy tickets_read on public.tickets for select using (
  tenant_id = public.my_tenant_id() and (public.is_school_admin() or (public.is_staff() and (assigned_to = auth.uid() or created_by = auth.uid()))));
drop policy if exists tickets_update on public.tickets;
create policy tickets_update on public.tickets for update using (
  tenant_id = public.my_tenant_id() and (public.is_school_admin() or (public.is_staff() and assigned_to = auth.uid())))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists tickets_delete on public.tickets;
create policy tickets_delete on public.tickets for delete using (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- Only admins may reassign a ticket; the assignee may not hand it to someone else or change its number.
create or replace function public.tickets_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_school_admin() then return new; end if;
  if new.assigned_to is distinct from old.assigned_to or new.ticket_no <> old.ticket_no or new.tenant_id <> old.tenant_id
     or new.guardian_id is distinct from old.guardian_id or new.token <> old.token then
    raise exception 'only a school admin can reassign or re-file a ticket';
  end if;
  return new;
end $$;
drop trigger if exists tickets_guard on public.tickets;
create trigger tickets_guard before update on public.tickets for each row execute function public.tickets_guard();

alter table public.ticket_messages enable row level security;
drop policy if exists ticket_messages_rw on public.ticket_messages;
create policy ticket_messages_rw on public.ticket_messages for select using (
  tenant_id = public.my_tenant_id() and exists (select 1 from public.tickets t where t.id = ticket_messages.ticket_id));
drop policy if exists ticket_messages_insert on public.ticket_messages;
create policy ticket_messages_insert on public.ticket_messages for insert with check (
  tenant_id = public.my_tenant_id() and author = 'staff' and author_id = auth.uid()
  and exists (select 1 from public.tickets t where t.id = ticket_messages.ticket_id and t.tenant_id = public.my_tenant_id()
              and (public.is_school_admin() or t.assigned_to = auth.uid() or t.created_by = auth.uid())));

grant all on public.alumni, public.crm_partners, public.crm_interactions, public.tickets, public.ticket_messages, public.surveys,
  public.survey_invites, public.survey_responses, public.family_segments, public.reenrolment_rounds, public.reenrolment_responses,
  public.referral_rewards, public.crm_campaigns to service_role;

-- ===== 20260101003200_core_security.sql =====
-- =========================================================================
-- EduClass Fusion: core platform and security (phase 4).
--  * Roles: counsellor (pastoral staff) and alumni (former students; they
--    sign in to their own alumni page and see no school data).
--  * school_sections (Nursery, Primary, Secondary, Sixth form …) with a
--    curriculum framework each; classes belong to a section and may use a
--    different framework (mixed setups).
--  * Currency stored as an ISO code (NGN, GBP, USD …).
--  * data_changes: a record of every create, edit and delete in the
--    school's data, with who did it and what changed. Admins only.
--  * Password rules (length, character mix, expiry) and session rules (idle
--    time-out, maximum session length, sign out other devices).
--  * Staff access restrictions by network (IP allow-list) and/or approved
--    devices, enforced in the database through short-lived access grants.
--  * Single sign-on policy (Google Workspace, Microsoft 365) and phone
--    sign-in codes.
--  * Consent records for children's data (NDPA / GDPR) and a privacy notice.
-- Apply AFTER 20260101003100. Idempotent.
-- =========================================================================

-- ---------- roles ----------
alter table public.users drop constraint if exists users_role_check;
alter table public.users add constraint users_role_check check (role in (
  'student','teacher','school_admin','it_admin','parent','platform_admin',
  'principal','bursar','librarian','hr_manager','qa_officer','gate_officer',
  'transport_officer','hostel_warden','nurse','admissions_officer','cashier',
  'counsellor','alumni','exam_officer'   -- exam_officer: phase 14j (kept here so the update file can be run again)
));
create or replace function public.is_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['teacher','school_admin','it_admin','platform_admin','principal',
    'bursar','librarian','hr_manager','qa_officer','gate_officer','transport_officer',
    'hostel_warden','nurse','admissions_officer','cashier','counsellor']);
$$;
-- Second factor rules never apply to families or alumni.
create or replace function public.mfa_ok(p_setting text, p_role text, p_extra text[])
returns boolean language sql stable set search_path = public as $$
  select case
    when coalesce(p_setting, 'off') = 'off' then true
    when p_role in ('student','parent','alumni') then true
    when public.session_aal() = 'aal2' then true
    when p_setting = 'admins' then not ((array[p_role] || coalesce(p_extra, '{}'))
      && array['school_admin','principal','it_admin','bursar','hr_manager','platform_admin'])
    else false
  end;
$$;
-- Counsellors read health records alongside the nurse.
drop policy if exists medical_read on public.medical_profiles;
create policy medical_read on public.medical_profiles for select using (
  tenant_id = public.my_tenant_id() and (public.has_role(array['nurse','school_admin','principal','platform_admin','hostel_warden','counsellor'])
    or public.teaches_student(student_id) or public.is_guardian_of(student_id)));
drop policy if exists sickbay_read on public.sickbay_visits;
create policy sickbay_read on public.sickbay_visits for select using (
  tenant_id = public.my_tenant_id() and (public.has_role(array['nurse','school_admin','principal','platform_admin','hostel_warden','counsellor'])
    or public.is_guardian_of(student_id)));

alter table public.alumni add column if not exists user_id uuid unique references public.users(id) on delete set null;

-- ---------- settings ----------
update public.tenant_settings set currency = 'NGN' where currency is null or currency !~ '^[A-Z]{3}$';
alter table public.tenant_settings drop constraint if exists tenant_settings_currency_check;
alter table public.tenant_settings add constraint tenant_settings_currency_check check (currency ~ '^[A-Z]{3}$');
alter table public.tenant_settings add column if not exists curriculum text;
alter table public.tenant_settings add column if not exists password_min_length int not null default 8;
alter table public.tenant_settings add column if not exists password_require_mixed_case boolean not null default false;
alter table public.tenant_settings add column if not exists password_require_number boolean not null default true;
alter table public.tenant_settings add column if not exists password_require_symbol boolean not null default false;
alter table public.tenant_settings add column if not exists password_max_age_days int not null default 0;
alter table public.tenant_settings add column if not exists password_policy_scope text not null default 'staff';
alter table public.tenant_settings add column if not exists session_idle_minutes int not null default 0;
alter table public.tenant_settings add column if not exists session_max_hours int not null default 0;
alter table public.tenant_settings add column if not exists staff_access_mode text not null default 'off';
alter table public.tenant_settings add column if not exists staff_access_roles text not null default 'except_admins';
alter table public.tenant_settings add column if not exists staff_ip_allowlist text[] not null default '{}';
alter table public.tenant_settings add column if not exists sso_policy text not null default 'optional';
alter table public.tenant_settings add column if not exists sso_domains text[] not null default '{}';
alter table public.tenant_settings add column if not exists sso_auto_join boolean not null default false;
alter table public.tenant_settings add column if not exists allow_phone_login boolean not null default true;
alter table public.tenant_settings add column if not exists privacy_notice text;
alter table public.tenant_settings add column if not exists privacy_notice_version int not null default 1;
alter table public.tenant_settings add column if not exists audit_retention_days int not null default 730;
do $$
begin
  alter table public.tenant_settings drop constraint if exists tenant_settings_security_check;
  alter table public.tenant_settings add constraint tenant_settings_security_check check (
    password_min_length between 8 and 64 and password_max_age_days between 0 and 730
    and password_policy_scope in ('staff','all')
    and (session_idle_minutes = 0 or session_idle_minutes between 5 and 720)
    and (session_max_hours = 0 or session_max_hours between 1 and 720)
    and staff_access_mode in ('off','ip','device','ip_or_device')
    and staff_access_roles in ('all_staff','except_admins')
    and sso_policy in ('optional','required_staff')
    and audit_retention_days between 30 and 3650);
end $$;

alter table public.users add column if not exists password_changed_at timestamptz;
update public.users set password_changed_at = now() where password_changed_at is null;
alter table public.users alter column password_changed_at set default now();

-- Users cannot move their own password clock; only the server sets it after a change.
create or replace function public.users_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if; -- service role / SQL editor
  if new.tenant_id is distinct from old.tenant_id then
    raise exception 'tenant_id cannot be changed';
  end if;
  if new.password_changed_at is distinct from old.password_changed_at then
    raise exception 'password_changed_at is set by the server';
  end if;
  if (new.role is distinct from old.role or new.extra_roles is distinct from old.extra_roles
      or new.active is distinct from old.active) then
    if new.id = auth.uid() then
      raise exception 'you cannot change your own role or status';
    end if;
    if not public.is_school_admin() then
      raise exception 'only school admins can change roles';
    end if;
    if new.role = 'platform_admin' or 'platform_admin' = any(new.extra_roles) then
      raise exception 'platform_admin cannot be granted from a tenant';
    end if;
  end if;
  return new;
end $$;

