-- ===== 20260101004500_library.sql =====
-- =====================================================================
--  Phase 11c: library.
--
--  * Catalogue: print and digital (e-book, audio, video, link) with cover,
--    description, year, edition, language, price and a barcode for books
--    without an ISBN; digital items open for everyone, staff or students.
--  * Reservations: a queue per title; a returned copy is held for the next
--    reader for a few days, and nobody else can borrow it meanwhile.
--  * Loans: a limit per student, renewals (not when someone is waiting),
--    lost books charged at the book's price, fines owed, paid or waived,
--    overdue reminders.
-- =====================================================================

alter table public.library_books add column if not exists format text not null default 'print' check (format in ('print','ebook','audio','video','link'));
alter table public.library_books add column if not exists barcode text;
alter table public.library_books add column if not exists cover_url text;
alter table public.library_books add column if not exists description text;
alter table public.library_books add column if not exists year int check (year between 1400 and 2200);
alter table public.library_books add column if not exists edition text;
alter table public.library_books add column if not exists language text;
alter table public.library_books add column if not exists price numeric(14,2) check (price >= 0);
alter table public.library_books add column if not exists digital_path text;      -- a file in the library-digital bucket
alter table public.library_books add column if not exists digital_url text;       -- or a link
alter table public.library_books add column if not exists access text not null default 'everyone' check (access in ('everyone','staff','students'));
alter table public.library_books add column if not exists views int not null default 0;
create unique index if not exists library_books_barcode on public.library_books(tenant_id, barcode) where barcode is not null;
create index if not exists library_books_isbn on public.library_books(tenant_id, isbn) where isbn is not null;
insert into storage.buckets (id, name, public) values ('library-digital', 'library-digital', false) on conflict (id) do nothing;

alter table public.library_loans add column if not exists renewals int not null default 0;
alter table public.library_loans add column if not exists fine_status text not null default 'none' check (fine_status in ('none','owed','paid','waived'));
alter table public.library_loans add column if not exists fine_settled_at timestamptz;
alter table public.library_loans add column if not exists fine_settled_by uuid references public.users(id) on delete set null;
alter table public.library_loans add column if not exists lost_at timestamptz;
alter table public.library_loans add column if not exists last_reminded_at timestamptz;

alter table public.tenant_settings add column if not exists library_max_loans int not null default 3 check (library_max_loans between 1 and 50);
alter table public.tenant_settings add column if not exists library_hold_days int not null default 3 check (library_hold_days between 1 and 30);
alter table public.tenant_settings add column if not exists library_max_renewals int not null default 2 check (library_max_renewals between 0 and 20);

create table if not exists public.library_reservations (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  book_id      uuid not null references public.library_books(id) on delete cascade,
  student_id   uuid references public.students(id) on delete cascade,
  staff_id     uuid references public.staff(id) on delete cascade,
  status       text not null default 'waiting' check (status in ('waiting','ready','collected','cancelled','expired')),
  ready_at     timestamptz,
  expires_at   timestamptz,
  notified_at  timestamptz,                 -- the reader was told the book is waiting
  created_at   timestamptz not null default now(),
  check ((student_id is null) <> (staff_id is null))
);
create index if not exists library_reservations_queue on public.library_reservations(book_id, status, created_at);
create unique index if not exists library_reservations_once on public.library_reservations(book_id, coalesce(student_id, staff_id)) where status in ('waiting','ready');

create or replace function public.is_librarian()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['librarian','school_admin','principal','platform_admin']);
$$;
grant execute on function public.is_librarian() to authenticated;

-- Copies held for readers who reserved the book (not for this borrower).
create or replace function public.library_holds_for_others(p_book uuid, p_student uuid, p_staff uuid)
returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from public.library_reservations r
   where r.book_id = p_book and r.status = 'ready' and r.expires_at > now()
     and coalesce(r.student_id, r.staff_id) is distinct from coalesce(p_student, p_staff);
$$;

-- Issue: copies available after holds, digital items never, within the loan limit; a borrower's own hold is collected.
create or replace function public.library_issue(p_book uuid, p_student uuid, p_staff uuid, p_days int)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_book public.library_books; v_id uuid; v_max int; v_open int;
begin
  perform set_config('app.library_fn', 'on', true);
  if not public.is_librarian() then raise exception 'forbidden'; end if;
  select * into v_book from public.library_books where id = p_book and tenant_id = public.my_tenant_id() for update;
  if v_book.id is null then raise exception 'book not found'; end if;
  if v_book.format <> 'print' then raise exception 'digital items are read online, not lent'; end if;
  if v_book.available_copies <= public.library_holds_for_others(p_book, p_student, p_staff) then
    raise exception '%', case when v_book.available_copies > 0 then 'the copies left are held for readers who reserved this book' else 'no copies available; reserve it instead' end;
  end if;
  if p_student is not null then
    select library_max_loans into v_max from public.tenant_settings where tenant_id = v_book.tenant_id;
    select count(*) into v_open from public.library_loans where student_id = p_student and returned_at is null;
    if v_open >= coalesce(v_max, 3) then raise exception 'this student already has % books out (the most allowed)', v_open; end if;
  end if;
  update public.library_books set available_copies = available_copies - 1 where id = p_book;
  insert into public.library_loans (tenant_id, book_id, student_id, staff_id, issued_by, due_at)
  values (v_book.tenant_id, p_book, p_student, p_staff, auth.uid(), now() + make_interval(days => greatest(p_days, 1)))
  returning id into v_id;
  update public.library_reservations set status = 'collected'
   where book_id = p_book and status in ('waiting','ready') and coalesce(student_id, staff_id) = coalesce(p_student, p_staff);
  return v_id;
end $$;

-- Return: fine for late days; the copy goes to the next reader in the queue, held for them.
create or replace function public.library_return(p_loan uuid, p_fine_per_day numeric)
returns numeric language plpgsql security definer set search_path = public as $$
declare v_loan public.library_loans; v_fine numeric; v_hold int; v_next uuid;
begin
  perform set_config('app.library_fn', 'on', true);
  if not public.is_librarian() then raise exception 'forbidden'; end if;
  select * into v_loan from public.library_loans where id = p_loan and tenant_id = public.my_tenant_id() and returned_at is null for update;
  if v_loan.id is null then raise exception 'loan not found or already returned'; end if;
  v_fine := greatest(0, ceil(extract(epoch from (now() - v_loan.due_at)) / 86400.0)) * coalesce(p_fine_per_day, 0);
  update public.library_loans set returned_at = now(), fine_amount = v_fine, fine_status = case when v_fine > 0 then 'owed' else 'none' end where id = p_loan;
  update public.library_books set available_copies = least(total_copies, available_copies + 1) where id = v_loan.book_id;
  select library_hold_days into v_hold from public.tenant_settings where tenant_id = v_loan.tenant_id;
  select id into v_next from public.library_reservations where book_id = v_loan.book_id and status = 'waiting' order by created_at limit 1 for update skip locked;
  if v_next is not null then
    update public.library_reservations set status = 'ready', ready_at = now(), expires_at = now() + make_interval(days => coalesce(v_hold, 3)), notified_at = null where id = v_next;
  end if;
  return v_fine;
end $$;

-- Renew: not overdue by a lot, not past the renewal limit, and nobody waiting for the book.
create or replace function public.library_renew(p_loan uuid)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare v_loan public.library_loans; v_days int; v_max int; v_due timestamptz;
begin
  perform set_config('app.library_fn', 'on', true);
  select * into v_loan from public.library_loans where id = p_loan and tenant_id = public.my_tenant_id() and returned_at is null for update;
  if v_loan.id is null then raise exception 'loan not found'; end if;
  if not (public.is_librarian() or public.is_student_self(v_loan.student_id)
          or exists (select 1 from public.staff s where s.id = v_loan.staff_id and s.user_id = auth.uid())) then raise exception 'forbidden'; end if;
  select library_loan_days, library_max_renewals into v_days, v_max from public.tenant_settings where tenant_id = v_loan.tenant_id;
  if v_loan.renewals >= coalesce(v_max, 2) then raise exception 'this book has been renewed the most times allowed; please return it'; end if;
  if exists (select 1 from public.library_reservations where book_id = v_loan.book_id and status = 'waiting') then raise exception 'someone is waiting for this book; please return it'; end if;
  if not public.is_librarian() and v_loan.due_at < now() - interval '7 days' then raise exception 'this book is well overdue; please bring it to the library'; end if;
  v_due := greatest(v_loan.due_at, now()) + make_interval(days => coalesce(v_days, 14));
  update public.library_loans set due_at = v_due, renewals = renewals + 1 where id = p_loan;
  return v_due;
end $$;

-- Reserve: for yourself (or by the librarian for a reader). If a copy is free now, it is held straight away.
create or replace function public.library_reserve(p_book uuid, p_student uuid, p_staff uuid)
returns text language plpgsql security definer set search_path = public as $$
declare v_book public.library_books; v_hold int; v_status text;
begin
  if not (public.is_librarian() or (p_student is not null and public.is_student_self(p_student))
          or (p_staff is not null and exists (select 1 from public.staff s where s.id = p_staff and s.user_id = auth.uid()))) then raise exception 'forbidden'; end if;
  select * into v_book from public.library_books where id = p_book and tenant_id = public.my_tenant_id();
  if v_book.id is null then raise exception 'book not found'; end if;
  if v_book.format <> 'print' then raise exception 'digital items can be read now; no need to reserve'; end if;
  if exists (select 1 from public.library_loans where book_id = p_book and returned_at is null and coalesce(student_id, staff_id) = coalesce(p_student, p_staff)) then
    raise exception 'you already have this book';
  end if;
  select library_hold_days into v_hold from public.tenant_settings where tenant_id = v_book.tenant_id;
  v_status := case when v_book.available_copies > public.library_holds_for_others(p_book, p_student, p_staff) then 'ready' else 'waiting' end;
  insert into public.library_reservations (tenant_id, book_id, student_id, staff_id, status, ready_at, expires_at)
  values (v_book.tenant_id, p_book, p_student, p_staff, v_status, case when v_status = 'ready' then now() end,
          case when v_status = 'ready' then now() + make_interval(days => coalesce(v_hold, 3)) end);
  return v_status;
exception when unique_violation then raise exception 'you have already reserved this book';
end $$;

-- Lost: the loan closes, the reader owes the book's price (plus any late fine), and the library has one copy fewer.
create or replace function public.library_lost(p_loan uuid)
returns numeric language plpgsql security definer set search_path = public as $$
declare v_loan public.library_loans; v_price numeric;
begin
  perform set_config('app.library_fn', 'on', true);
  if not public.is_librarian() then raise exception 'forbidden'; end if;
  select * into v_loan from public.library_loans where id = p_loan and tenant_id = public.my_tenant_id() and returned_at is null for update;
  if v_loan.id is null then raise exception 'loan not found or already closed'; end if;
  select coalesce(price, 0) into v_price from public.library_books where id = v_loan.book_id;
  update public.library_loans set returned_at = now(), lost_at = now(), fine_amount = v_price, fine_status = case when v_price > 0 then 'owed' else 'none' end where id = p_loan;
  update public.library_books set total_copies = greatest(0, total_copies - 1) where id = v_loan.book_id;
  return v_price;
end $$;

-- Holds not collected in time lapse, and the next reader gets the copy.
create or replace function public.library_expire_holds()
returns int language plpgsql security definer set search_path = public as $$
declare r record; v_next uuid; v_hold int; n int := 0;
begin
  for r in update public.library_reservations set status = 'expired' where status = 'ready' and expires_at < now() returning book_id, tenant_id loop
    select library_hold_days into v_hold from public.tenant_settings where tenant_id = r.tenant_id;
    select id into v_next from public.library_reservations where book_id = r.book_id and status = 'waiting' order by created_at limit 1;
    if v_next is not null then
      update public.library_reservations set status = 'ready', ready_at = now(), expires_at = now() + make_interval(days => coalesce(v_hold, 3)) where id = v_next;
    end if;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.library_expire_holds() from public, anon, authenticated;
grant execute on function public.library_expire_holds() to service_role;
grant execute on function public.library_renew(uuid), public.library_reserve(uuid, uuid, uuid), public.library_lost(uuid) to authenticated;

-- Fines are settled by the library (paid or waived) and nothing else about a loan changes by hand.
drop policy if exists library_loans_settle on public.library_loans;
create policy library_loans_settle on public.library_loans for update using (tenant_id = public.my_tenant_id() and public.is_librarian()) with check (tenant_id = public.my_tenant_id());
create or replace function public.library_loan_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  -- Issue, return, renew and lost go through the library functions, which set this flag for their own statement.
  if (new.book_id, new.student_id, new.staff_id, new.issued_at, new.due_at, new.returned_at, new.fine_amount, new.renewals, new.lost_at)
     is distinct from (old.book_id, old.student_id, old.staff_id, old.issued_at, old.due_at, old.returned_at, old.fine_amount, old.renewals, old.lost_at)
     and current_setting('app.library_fn', true) is distinct from 'on' then
    raise exception 'loans change only by issuing, returning, renewing or marking lost';
  end if;
  if new.fine_status is distinct from old.fine_status and current_setting('app.library_fn', true) is distinct from 'on' then
    if new.fine_status not in ('paid','waived') or old.fine_status <> 'owed' then raise exception 'a fine can only be marked paid or waived'; end if;
    new.fine_settled_at := now(); new.fine_settled_by := auth.uid();
  end if;
  return new;
end $$;
drop trigger if exists library_loan_guard on public.library_loans;
create trigger library_loan_guard before update on public.library_loans for each row execute function public.library_loan_guard();

alter table public.library_reservations enable row level security;
drop policy if exists library_reservations_read on public.library_reservations;
create policy library_reservations_read on public.library_reservations for select using (tenant_id = public.my_tenant_id() and (public.is_librarian()
  or (student_id is not null and (public.is_student_self(student_id) or public.is_guardian_of(student_id)))
  or exists (select 1 from public.staff s where s.id = library_reservations.staff_id and s.user_id = auth.uid())));
drop policy if exists library_reservations_manage on public.library_reservations;
create policy library_reservations_manage on public.library_reservations for update using (tenant_id = public.my_tenant_id() and public.is_librarian()) with check (tenant_id = public.my_tenant_id());
-- readers reserve and cancel through the functions and the server

grant all on public.library_reservations to service_role;
select public.attach_change_log();

-- ===== 20260101004600_inventory_procurement.sql =====
-- =====================================================================
--  Phase 11d: stock, assets and procurement.
--
--  * Stock items with a size or colour (uniforms), a barcode and a selling
--    price; items issued to a student or member of staff; tuck-shop and
--    uniform-shop sales take stock off automatically.
--  * Assets: serial number, supplier, warranty and a maintenance schedule;
--    services and repairs logged; any member of staff can report a fault.
--  * Procurement: suppliers; quotes against a requisition; requisitions above
--    a set amount need a second approver; purchase orders, goods received
--    into stock or the asset register, and payment recorded as an expense.
-- =====================================================================

-- ---------- Stock ----------
alter table public.inventory_items add column if not exists variant text;          -- e.g. size 10, age 7–8, blue
alter table public.inventory_items add column if not exists barcode text;
alter table public.inventory_items add column if not exists sell_price numeric(14,2) check (sell_price >= 0);
alter table public.inventory_items drop constraint if exists inventory_items_tenant_id_name_key;
create unique index if not exists inventory_items_name_variant on public.inventory_items(tenant_id, lower(name), coalesce(lower(variant), ''));
create unique index if not exists inventory_items_barcode on public.inventory_items(tenant_id, barcode) where barcode is not null;

alter table public.inventory_moves add column if not exists student_id uuid references public.students(id) on delete set null;
alter table public.inventory_moves add column if not exists staff_id uuid references public.staff(id) on delete set null;
alter table public.inventory_moves add column if not exists unit_cost numeric(14,2);
alter table public.inventory_moves add column if not exists purchase_order_id uuid;

alter table public.shop_items add column if not exists inventory_item_id uuid references public.inventory_items(id) on delete set null;
alter table public.shop_items add column if not exists barcode text;
create unique index if not exists shop_items_barcode on public.shop_items(tenant_id, barcode) where barcode is not null;

-- Issue stock to a person (uniform, textbooks, a laptop charger …).
create or replace function public.inventory_issue(p_item uuid, p_qty numeric, p_student uuid, p_staff uuid, p_reason text)
returns numeric language plpgsql security definer set search_path = public as $$
declare v_new numeric; v_tenant uuid;
begin
  if not public.has_role(array['bursar','school_admin','principal','platform_admin']) then raise exception 'forbidden'; end if;
  if p_qty is null or p_qty <= 0 then raise exception 'quantity must be positive'; end if;
  if (p_student is null) = (p_staff is null) then raise exception 'choose who receives it'; end if;
  update public.inventory_items set quantity = quantity - p_qty where id = p_item and tenant_id = public.my_tenant_id() returning quantity, tenant_id into v_new, v_tenant;
  if v_tenant is null then raise exception 'item not found'; end if;
  if v_new < 0 then raise exception 'not enough stock'; end if;
  insert into public.inventory_moves (tenant_id, item_id, kind, quantity, reason, recorded_by, student_id, staff_id)
  values (v_tenant, p_item, 'out', p_qty, coalesce(nullif(trim(p_reason), ''), 'Issued'), auth.uid(), p_student, p_staff);
  return v_new;
end $$;
grant execute on function public.inventory_issue(uuid, numeric, uuid, uuid, text) to authenticated;

-- A shop sale takes the stock it sold; a sale cannot sell what is not on the shelf.
create or replace function public.shop_sale_stock() returns trigger
language plpgsql security definer set search_path = public as $$
declare line jsonb; v_item uuid; v_name text; v_left numeric;
begin
  if new.kind <> 'purchase' or new.status <> 'success' then return null; end if;
  for line in select * from jsonb_array_elements(coalesce(new.items, '[]'::jsonb)) loop
    select s.inventory_item_id, s.name into v_item, v_name from public.shop_items s where s.id = (line ->> 'id')::uuid and s.tenant_id = new.tenant_id;
    if v_item is null then continue; end if;
    update public.inventory_items set quantity = quantity - coalesce((line ->> 'qty')::numeric, 1) where id = v_item returning quantity into v_left;
    if v_left < 0 then raise exception 'not enough % in stock', v_name; end if;
    insert into public.inventory_moves (tenant_id, item_id, kind, quantity, reason, reference, recorded_by, student_id)
    values (new.tenant_id, v_item, 'out', coalesce((line ->> 'qty')::numeric, 1), 'Shop sale', new.reference, new.recorded_by, new.student_id);
  end loop;
  return null;
exception when invalid_text_representation then return null;
end $$;
drop trigger if exists shop_sale_stock on public.wallet_transactions;
create trigger shop_sale_stock after insert on public.wallet_transactions for each row execute function public.shop_sale_stock();

-- ---------- Assets ----------
alter table public.assets add column if not exists serial_no text;
alter table public.assets add column if not exists supplier text;
alter table public.assets add column if not exists warranty_expires date;
alter table public.assets add column if not exists maintenance_every_days int check (maintenance_every_days between 1 and 3650);
alter table public.assets add column if not exists last_maintenance_on date;
alter table public.assets add column if not exists next_maintenance_on date;
alter table public.assets add column if not exists purchase_order_id uuid;

create table if not exists public.asset_maintenance (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  asset_id     uuid not null references public.assets(id) on delete cascade,
  kind         text not null default 'service' check (kind in ('service','repair','inspection','calibration','cleaning','fault')),
  status       text not null default 'done' check (status in ('reported','scheduled','done','cancelled')),
  description  text,
  due_on       date,
  done_on      date,
  cost         numeric(14,2) check (cost >= 0),
  vendor       text,
  reported_by  uuid references public.users(id) on delete set null,
  done_by      uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now()
);
create index if not exists asset_maintenance_asset on public.asset_maintenance(asset_id, created_at desc);

-- Work done moves the asset's next service date on; a fault puts it in for repair.
create or replace function public.asset_maintenance_after() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'done' and new.done_on is not null and (tg_op = 'INSERT' or old.status is distinct from 'done') then
    update public.assets set last_maintenance_on = new.done_on,
      next_maintenance_on = case when maintenance_every_days is not null then new.done_on + maintenance_every_days else next_maintenance_on end,
      status = case when status = 'repair' and new.kind in ('repair','fault') then 'in_use' else status end
     where id = new.asset_id;
  elsif new.status = 'reported' and tg_op = 'INSERT' then
    update public.assets set condition = case when condition in ('new','good') then 'fair' else condition end where id = new.asset_id;
  end if;
  return null;
end $$;
drop trigger if exists asset_maintenance_after on public.asset_maintenance;
create trigger asset_maintenance_after after insert or update on public.asset_maintenance for each row execute function public.asset_maintenance_after();

-- ---------- Procurement ----------
create table if not exists public.suppliers (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(trim(name)) between 1 and 160),
  contact_name  text,
  phone         text,
  email         text,
  address       text,
  category      text,
  tax_id        text,
  bank_name     text,
  account_no    text,
  account_name  text,
  notes         text,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  unique (tenant_id, name)
);

alter table public.requisitions drop constraint if exists requisitions_status_check;
alter table public.requisitions add constraint requisitions_status_check check (status in ('submitted','endorsed','approved','rejected','fulfilled','cancelled'));
alter table public.requisitions add column if not exists endorsed_by uuid references public.users(id) on delete set null;
alter table public.requisitions add column if not exists endorsed_at timestamptz;
alter table public.tenant_settings add column if not exists procurement_second_approval_over numeric(14,2) not null default 500000 check (procurement_second_approval_over >= 0);

-- Small requisitions need one approver; larger ones are endorsed first, then approved by the principal or an admin who did not endorse them.
create or replace function public.requisitions_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_limit numeric;
begin
  if auth.uid() is null then return new; end if;
  if new.status is distinct from old.status then
    if new.status = 'cancelled' and old.requested_by = auth.uid() and old.status in ('submitted','endorsed') then return new; end if;
    if not public.has_role(array['school_admin','principal','bursar','platform_admin']) then raise exception 'only approvers can change requisition status'; end if;
    if old.requested_by = auth.uid() and new.status in ('endorsed','approved','rejected') then raise exception 'you cannot approve your own requisition'; end if;
    select procurement_second_approval_over into v_limit from public.tenant_settings where tenant_id = new.tenant_id;
    if new.status = 'endorsed' then
      if old.status <> 'submitted' then raise exception 'only a new requisition can be endorsed'; end if;
      new.endorsed_by := auth.uid(); new.endorsed_at := now();
    elsif new.status = 'approved' then
      if old.status not in ('submitted','endorsed') then raise exception 'this requisition is %', old.status; end if;
      if new.total_amount > coalesce(v_limit, 500000) then
        if old.status <> 'endorsed' then raise exception 'requisitions over % need endorsing first, then a second approver', coalesce(v_limit, 500000); end if;
        if old.endorsed_by = auth.uid() then raise exception 'the second approval must come from someone other than the endorser'; end if;
        if not public.has_role(array['school_admin','principal','platform_admin']) then raise exception 'the principal or a school admin gives the second approval'; end if;
      end if;
    elsif new.status = 'fulfilled' and old.status <> 'approved' then
      raise exception 'only approved requisitions are fulfilled';
    end if;
  end if;
  if new.total_amount is distinct from old.total_amount and old.status <> 'submitted' then raise exception 'the amount cannot change after approval has started'; end if;
  return new;
end $$;

create table if not exists public.supplier_quotes (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  requisition_id  uuid not null references public.requisitions(id) on delete cascade,
  supplier_id     uuid not null references public.suppliers(id) on delete cascade,
  amount          numeric(14,2) not null check (amount >= 0),
  delivery_days   int check (delivery_days between 0 and 365),
  notes           text,
  chosen          boolean not null default false,
  created_at      timestamptz not null default now(),
  unique (requisition_id, supplier_id)
);

create table if not exists public.purchase_orders (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  po_no           text,
  requisition_id  uuid references public.requisitions(id) on delete set null,
  supplier_id     uuid not null references public.suppliers(id),
  status          text not null default 'draft' check (status in ('draft','sent','partly_received','received','cancelled')),
  total           numeric(14,2) not null default 0,
  ordered_on      date,
  expected_on     date,
  notes           text,
  paid_at         timestamptz,
  expense_id      uuid references public.expenses(id) on delete set null,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  unique (tenant_id, po_no)
);
create table if not exists public.purchase_order_lines (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  po_id              uuid not null references public.purchase_orders(id) on delete cascade,
  description        text not null check (length(trim(description)) between 1 and 200),
  quantity           numeric not null check (quantity > 0),
  unit_cost          numeric(14,2) not null check (unit_cost >= 0),
  inventory_item_id  uuid references public.inventory_items(id) on delete set null,
  is_asset           boolean not null default false,
  received_qty       numeric not null default 0 check (received_qty >= 0),
  check (received_qty <= quantity)
);
alter table public.inventory_moves drop constraint if exists inventory_moves_po_fk;
alter table public.inventory_moves add constraint inventory_moves_po_fk foreign key (purchase_order_id) references public.purchase_orders(id) on delete set null;
alter table public.assets drop constraint if exists assets_po_fk;
alter table public.assets add constraint assets_po_fk foreign key (purchase_order_id) references public.purchase_orders(id) on delete set null;
alter table public.expenses add column if not exists purchase_order_id uuid references public.purchase_orders(id) on delete set null;

-- Order totals follow their lines; numbers are given when the order is first sent.
create or replace function public.po_lines_changed() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_po uuid;
begin
  if tg_op = 'DELETE' then v_po := old.po_id; else v_po := new.po_id; end if;
  update public.purchase_orders set total = (select coalesce(sum(round(quantity * unit_cost, 2)), 0) from public.purchase_order_lines where po_id = v_po) where id = v_po;
  return null;
end $$;
drop trigger if exists po_lines_changed on public.purchase_order_lines;
create trigger po_lines_changed after insert or update or delete on public.purchase_order_lines for each row execute function public.po_lines_changed();

create or replace function public.po_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then new.created_by := auth.uid(); new.status := 'draft'; new.po_no := null; new.paid_at := null; new.expense_id := null; end if;
    return new;
  end if;
  -- Receiving goods (po_receive) moves the status itself.
  if auth.uid() is null or current_setting('app.po_fn', true) = 'on' then return new; end if;
  if new.status = 'sent' and old.status = 'draft' then
    if not exists (select 1 from public.purchase_order_lines where po_id = new.id) then raise exception 'add the items before sending the order'; end if;
    new.po_no := coalesce(old.po_no, public.next_doc_no(new.tenant_id, 'po')); new.ordered_on := coalesce(new.ordered_on, current_date);
  elsif new.status is distinct from old.status and new.status in ('partly_received','received') then
    raise exception 'orders are marked received by receiving the goods';
  elsif new.status = 'cancelled' and old.status in ('partly_received','received') then
    raise exception 'goods have been received against this order';
  end if;
  if old.status <> 'draft' and (new.supplier_id is distinct from old.supplier_id) then raise exception 'the supplier cannot change after the order is sent'; end if;
  return new;
end $$;
drop trigger if exists po_guard on public.purchase_orders;
create trigger po_guard before insert or update on public.purchase_orders for each row execute function public.po_guard();

create or replace function public.po_line_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_status text;
begin
  if auth.uid() is null or current_setting('app.po_fn', true) = 'on' then return case when tg_op = 'DELETE' then old else new end; end if;
  select status into v_status from public.purchase_orders where id = case when tg_op = 'DELETE' then old.po_id else new.po_id end;
  if v_status <> 'draft' then
    if tg_op <> 'UPDATE' or (new.description, new.quantity, new.unit_cost, new.inventory_item_id, new.is_asset) is distinct from (old.description, old.quantity, old.unit_cost, old.inventory_item_id, old.is_asset)
       or new.received_qty is distinct from old.received_qty then
      raise exception 'a sent order cannot be changed; cancel it and raise another';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists po_line_guard on public.purchase_order_lines;
create trigger po_line_guard before insert or update or delete on public.purchase_order_lines for each row execute function public.po_line_guard();

-- Goods received: stock goes up, assets are registered, and the order (and its requisition) is closed when everything has arrived.
create or replace function public.po_receive(p_line uuid, p_qty numeric, p_tags text[] default null)
returns text language plpgsql security definer set search_path = public as $$
declare l public.purchase_order_lines; po public.purchase_orders; v_sup text; v_all boolean; i int;
begin
  if not public.is_finance() then raise exception 'forbidden'; end if;
  perform set_config('app.po_fn', 'on', true);
  select * into l from public.purchase_order_lines where id = p_line and tenant_id = public.my_tenant_id() for update;
  if l.id is null then raise exception 'order line not found'; end if;
  select * into po from public.purchase_orders where id = l.po_id for update;
  if po.status not in ('sent','partly_received') then raise exception 'send the order before receiving goods'; end if;
  if p_qty is null or p_qty <= 0 then raise exception 'enter the quantity received'; end if;
  if l.received_qty + p_qty > l.quantity then raise exception 'only % more were ordered', l.quantity - l.received_qty; end if;
  update public.purchase_order_lines set received_qty = received_qty + p_qty where id = l.id;
  if l.inventory_item_id is not null then
    update public.inventory_items set quantity = quantity + p_qty, unit_cost = l.unit_cost where id = l.inventory_item_id;
    insert into public.inventory_moves (tenant_id, item_id, kind, quantity, reason, reference, recorded_by, unit_cost, purchase_order_id)
    values (l.tenant_id, l.inventory_item_id, 'in', p_qty, 'Received', po.po_no, auth.uid(), l.unit_cost, po.id);
  end if;
  if l.is_asset then
    select name into v_sup from public.suppliers where id = po.supplier_id;
    for i in 1 .. floor(p_qty)::int loop
      insert into public.assets (tenant_id, tag, name, cost, purchase_date, supplier, status, purchase_order_id)
      values (l.tenant_id, coalesce(p_tags[i], po.po_no || '-' || substr(l.id::text, 1, 4) || '-' || (l.received_qty::int + i)), l.description, l.unit_cost, current_date, v_sup, 'in_store', po.id);
    end loop;
  end if;
  select bool_and(received_qty >= quantity) into v_all from public.purchase_order_lines where po_id = po.id;
  update public.purchase_orders set status = case when v_all then 'received' else 'partly_received' end where id = po.id;
  if v_all and po.requisition_id is not null then
    update public.requisitions set status = 'fulfilled' where id = po.requisition_id and status = 'approved';
  end if;
  return case when v_all then 'received' else 'partly_received' end;
end $$;
grant execute on function public.po_receive(uuid, numeric, text[]) to authenticated;

-- ---------- RLS ----------
alter table public.asset_maintenance enable row level security;
drop policy if exists asset_maintenance_read on public.asset_maintenance;
create policy asset_maintenance_read on public.asset_maintenance for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists asset_maintenance_write on public.asset_maintenance;
create policy asset_maintenance_write on public.asset_maintenance for all using (tenant_id = public.my_tenant_id() and public.is_finance())
  with check (tenant_id = public.my_tenant_id() and public.is_finance());
drop policy if exists asset_fault_report on public.asset_maintenance;
create policy asset_fault_report on public.asset_maintenance for insert with check (tenant_id = public.my_tenant_id() and public.is_staff()
  and status = 'reported' and kind = 'fault' and reported_by = auth.uid());

do $$
declare t text;
begin
  foreach t in array array['suppliers','supplier_quotes','purchase_orders','purchase_order_lines'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_finance', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_finance()) with check (tenant_id = public.my_tenant_id() and public.is_finance())', t || '_finance', t);
  end loop;
end $$;
-- Requesters follow their own requisition's quotes and orders.
drop policy if exists purchase_orders_requester on public.purchase_orders;
create policy purchase_orders_requester on public.purchase_orders for select using (tenant_id = public.my_tenant_id()
  and exists (select 1 from public.requisitions r where r.id = purchase_orders.requisition_id and r.requested_by = auth.uid()));

grant all on public.asset_maintenance, public.suppliers, public.supplier_quotes, public.purchase_orders, public.purchase_order_lines to service_role;
select public.attach_change_log();

-- ===== 20260101004700_cocurricular.sql =====
-- =====================================================================
--  Phase 11e: co-curricular life.
--
--  * Clubs, societies and teams: who leads them, who may join (open, by
--    approval, or closed), members with roles, sessions and attendance, and a
--    fee for the group linked to fees.
--  * Competitions and events entered, with results that become achievements.
--  * Trips: departure and return, staff going, meeting point, risk
--    assessment, and a roster ticked on the day (gone, back), with an alert if
--    anyone is not back on time.
-- =====================================================================

create table if not exists public.cc_groups (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  name              text not null check (length(trim(name)) between 1 and 120),
  kind              text not null default 'club' check (kind in ('club','society','sport','team','choir','band','drama','other')),
  description       text,
  meets             text,                                  -- e.g. Wednesdays 3–4pm
  location          text,
  capacity          int check (capacity between 1 and 2000),
  lead_id           uuid references public.users(id) on delete set null,
  assistant_ids     uuid[] not null default '{}',
  open_to_class_ids uuid[] not null default '{}',          -- empty = every class
  joining           text not null default 'approval' check (joining in ('open','approval','closed')),
  fee_item_id       uuid references public.fee_items(id) on delete set null,
  house_id          uuid references public.houses(id) on delete set null,
  active            boolean not null default true,
  created_at        timestamptz not null default now(),
  unique (tenant_id, name)
);
create table if not exists public.cc_members (
  group_id      uuid not null references public.cc_groups(id) on delete cascade,
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  student_id    uuid not null references public.students(id) on delete cascade,
  role          text not null default 'member' check (role in ('member','captain','vice_captain','secretary','treasurer','other')),
  status        text not null default 'active' check (status in ('requested','active','left','declined')),
  requested_at  timestamptz not null default now(),
  joined_on     date,
  left_on       date,
  primary key (group_id, student_id)
);
create index if not exists cc_members_student on public.cc_members(student_id);
create table if not exists public.cc_sessions (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  group_id    uuid not null references public.cc_groups(id) on delete cascade,
  held_on     date not null,
  kind        text not null default 'meeting' check (kind in ('meeting','training','rehearsal','match','performance','other')),
  notes       text,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  unique (group_id, held_on, kind)
);
create table if not exists public.cc_attendance (
  session_id  uuid not null references public.cc_sessions(id) on delete cascade,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  status      text not null check (status in ('present','absent','late','excused')),
  primary key (session_id, student_id)
);

create table if not exists public.competitions (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  title       text not null check (length(trim(title)) between 2 and 160),
  kind        text not null default 'sports' check (kind in ('sports','academic','arts','debate','quiz','other')),
  level       text not null default 'school' check (level in ('house','school','local','state','national','international')),
  held_on     date not null,
  venue       text,
  organiser   text,
  group_id    uuid references public.cc_groups(id) on delete set null,
  notes       text,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create table if not exists public.competition_entries (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  competition_id  uuid not null references public.competitions(id) on delete cascade,
  student_id      uuid not null references public.students(id) on delete cascade,
  event           text,                       -- e.g. 100 m, under-14 chess
  team_name       text,
  position        int check (position between 1 and 1000),
  score           text,
  award           text,
  notes           text,
  achievement_id  uuid references public.student_achievements(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists competition_entries_comp on public.competition_entries(competition_id);
create unique index if not exists competition_entries_once on public.competition_entries(competition_id, student_id, coalesce(event, ''));

alter table public.school_events add column if not exists departs_at timestamptz;
alter table public.school_events add column if not exists returns_at timestamptz;
alter table public.school_events add column if not exists meeting_point text;
alter table public.school_events add column if not exists staff_ids uuid[] not null default '{}';
alter table public.school_events add column if not exists risk_assessment text;
alter table public.school_events add column if not exists emergency_contact text;
alter table public.school_events add column if not exists late_alerted_at timestamptz;
create table if not exists public.trip_roster (
  event_id     uuid not null references public.school_events(id) on delete cascade,
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  student_id   uuid not null references public.students(id) on delete cascade,
  status       text not null default 'going' check (status in ('going','departed','returned','absent','cancelled')),
  departed_at  timestamptz,
  returned_at  timestamptz,
  note         text,
  primary key (event_id, student_id)
);

-- ---------- Helpers ----------
create or replace function public.leads_group(p_group uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or exists (select 1 from public.cc_groups g where g.id = p_group and g.tenant_id = public.my_tenant_id()
    and (g.lead_id = auth.uid() or auth.uid() = any(g.assistant_ids)));
$$;
create or replace function public.on_trip_staff(p_event uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or exists (select 1 from public.school_events e where e.id = p_event and e.tenant_id = public.my_tenant_id() and auth.uid() = any(e.staff_ids));
$$;
grant execute on function public.leads_group(uuid), public.on_trip_staff(uuid) to authenticated;

-- Roster times are stamped as the status moves.
create or replace function public.trip_roster_stamp() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'departed' and (tg_op = 'INSERT' or old.status is distinct from 'departed') then new.departed_at := coalesce(new.departed_at, now()); end if;
  if new.status = 'returned' and (tg_op = 'INSERT' or old.status is distinct from 'returned') then new.returned_at := coalesce(new.returned_at, now()); end if;
  return new;
end $$;
drop trigger if exists trip_roster_stamp on public.trip_roster;
create trigger trip_roster_stamp before insert or update on public.trip_roster for each row execute function public.trip_roster_stamp();

-- Leads run their group day to day; who leads it and what it costs stay with admins.
create or replace function public.cc_groups_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_school_admin() then return new; end if;
  if new.lead_id is distinct from old.lead_id or new.assistant_ids is distinct from old.assistant_ids or new.fee_item_id is distinct from old.fee_item_id then
    raise exception 'only admins change who leads a group or its fee';
  end if;
  return new;
end $$;
drop trigger if exists cc_groups_guard on public.cc_groups;
create trigger cc_groups_guard before update on public.cc_groups for each row execute function public.cc_groups_guard();

-- ---------- RLS ----------
alter table public.cc_groups enable row level security;
drop policy if exists cc_groups_read on public.cc_groups;
create policy cc_groups_read on public.cc_groups for select using (tenant_id = public.my_tenant_id());
drop policy if exists cc_groups_write on public.cc_groups;
create policy cc_groups_write on public.cc_groups for insert with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists cc_groups_update on public.cc_groups;
create policy cc_groups_update on public.cc_groups for update using (tenant_id = public.my_tenant_id() and public.leads_group(id)) with check (tenant_id = public.my_tenant_id());
drop policy if exists cc_groups_delete on public.cc_groups;
create policy cc_groups_delete on public.cc_groups for delete using (tenant_id = public.my_tenant_id() and public.is_school_admin());

alter table public.cc_members enable row level security;
drop policy if exists cc_members_read on public.cc_members;
create policy cc_members_read on public.cc_members for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists cc_members_write on public.cc_members;
create policy cc_members_write on public.cc_members for all using (tenant_id = public.my_tenant_id() and public.leads_group(group_id))
  with check (tenant_id = public.my_tenant_id() and public.leads_group(group_id));
-- students ask to join through the server, which checks the group is open to them

alter table public.cc_sessions enable row level security;
drop policy if exists cc_sessions_read on public.cc_sessions;
create policy cc_sessions_read on public.cc_sessions for select using (tenant_id = public.my_tenant_id());
drop policy if exists cc_sessions_write on public.cc_sessions;
create policy cc_sessions_write on public.cc_sessions for all using (tenant_id = public.my_tenant_id() and public.leads_group(group_id))
  with check (tenant_id = public.my_tenant_id() and public.leads_group(group_id));

alter table public.cc_attendance enable row level security;
drop policy if exists cc_attendance_read on public.cc_attendance;
create policy cc_attendance_read on public.cc_attendance for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists cc_attendance_write on public.cc_attendance;
create policy cc_attendance_write on public.cc_attendance for all using (tenant_id = public.my_tenant_id()
  and public.leads_group((select s.group_id from public.cc_sessions s where s.id = session_id)))
  with check (tenant_id = public.my_tenant_id() and public.leads_group((select s.group_id from public.cc_sessions s where s.id = session_id)));

-- Competitions are public in the school; results for a child are seen by staff, the child and their family.
alter table public.competitions enable row level security;
drop policy if exists competitions_read on public.competitions;
create policy competitions_read on public.competitions for select using (tenant_id = public.my_tenant_id());
drop policy if exists competitions_write on public.competitions;
create policy competitions_write on public.competitions for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
alter table public.competition_entries enable row level security;
drop policy if exists competition_entries_read on public.competition_entries;
create policy competition_entries_read on public.competition_entries for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists competition_entries_write on public.competition_entries;
create policy competition_entries_write on public.competition_entries for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());

alter table public.trip_roster enable row level security;
drop policy if exists trip_roster_read on public.trip_roster;
create policy trip_roster_read on public.trip_roster for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_guardian_of(student_id) or public.is_student_self(student_id)));
