-- ===== 20260101004800_portals.sql =====
-- =====================================================================
--  Phase 12a: portals and dashboards.
--
--  * Students already see their own fees (balance, what is due); the school
--    can now turn this off.
--  * A daily snapshot of the school's key numbers, so the head's dashboard
--    shows trends (attendance, fee collection, behaviour, admissions), with
--    targets the school sets.
-- =====================================================================

alter table public.tenant_settings add column if not exists student_sees_fees boolean not null default true;
-- e.g. {"attendance_rate": 95, "collection_rate": 90}
alter table public.tenant_settings add column if not exists kpi_targets jsonb not null default '{}'::jsonb;

create or replace function public.students_see_fees()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select s.student_sees_fees from public.tenant_settings s where s.tenant_id = public.my_tenant_id()), true);
$$;
grant execute on function public.students_see_fees() to authenticated;

-- Students already read their own invoices; the school can now turn that off (parents and the bursar are unaffected).
drop policy if exists fee_invoices_student_read on public.fee_invoices;
drop policy if exists fee_invoice_lines_student_read on public.fee_invoice_lines;
drop policy if exists fee_invoices_read on public.fee_invoices;
create policy fee_invoices_read on public.fee_invoices for select using (
  tenant_id = public.my_tenant_id() and (public.is_finance() or public.is_guardian_of(student_id)
    or (public.students_see_fees() and exists (select 1 from public.students s where s.id = fee_invoices.student_id and s.user_id = auth.uid()))));
drop policy if exists fee_lines_read on public.fee_invoice_lines;
create policy fee_lines_read on public.fee_invoice_lines for select using (
  exists (select 1 from public.fee_invoices i where i.id = fee_invoice_lines.invoice_id and i.tenant_id = public.my_tenant_id()
          and (public.is_finance() or public.is_guardian_of(i.student_id)
               or (public.students_see_fees() and exists (select 1 from public.students s where s.id = i.student_id and s.user_id = auth.uid())))));

-- One row per school per day, written by the daily job.
create table if not exists public.kpi_snapshots (
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  day         date not null,
  metrics     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  primary key (tenant_id, day)
);
alter table public.kpi_snapshots enable row level security;
drop policy if exists kpi_snapshots_read on public.kpi_snapshots;
create policy kpi_snapshots_read on public.kpi_snapshots for select
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.is_finance()));
-- No write policies: only the server writes snapshots.
grant all on public.kpi_snapshots to service_role;

-- Snapshots are written by the server once a day; no need to log every one in the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101004900_apps.sql =====
-- =====================================================================
--  Phase 12b: the apps.
--
--  * Notification choices: each person can turn off groups of messages
--    (never safety alerts) and set quiet hours, when app, WhatsApp and SMS
--    messages wait until the morning. Email is not held.
--  * Outbox messages remember who they are for, so those choices apply
--    when they are sent.
--  * Phones running the native app (Android, iPhone) register for push
--    through Firebase Cloud Messaging alongside web push.
-- =====================================================================

create table if not exists public.notification_prefs (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  user_id      uuid references public.users(id) on delete cascade,          -- staff and students
  guardian_id  uuid references public.guardians(id) on delete cascade,      -- parents (set by the server)
  muted        text[] not null default '{}',
  quiet_from   time,
  quiet_to     time,
  updated_at   timestamptz not null default now(),
  check ((user_id is not null) <> (guardian_id is not null)),
  check (muted <@ array['attendance','learning','fees','messages','transport','activities','work','other']::text[]),
  check ((quiet_from is null) = (quiet_to is null) and (quiet_from is null or quiet_from <> quiet_to))
);
create unique index if not exists notification_prefs_user on public.notification_prefs(user_id) where user_id is not null;
create unique index if not exists notification_prefs_guardian on public.notification_prefs(guardian_id) where guardian_id is not null;

alter table public.notification_prefs enable row level security;
drop policy if exists notification_prefs_own on public.notification_prefs;
create policy notification_prefs_own on public.notification_prefs for all
  using (tenant_id = public.my_tenant_id() and user_id = auth.uid())
  with check (tenant_id = public.my_tenant_id() and user_id = auth.uid() and guardian_id is null);
-- Parents' choices are saved by the server after it identifies them (signed in or by their private link).
grant all on public.notification_prefs to service_role;

alter table public.message_outbox add column if not exists recipient_user_id uuid;
alter table public.message_outbox add column if not exists recipient_guardian_id uuid;
create index if not exists message_outbox_recipient_user on public.message_outbox(recipient_user_id) where recipient_user_id is not null;
create index if not exists message_outbox_recipient_guardian on public.message_outbox(recipient_guardian_id) where recipient_guardian_id is not null;

-- Native app devices: the endpoint holds the Firebase registration token.
alter table public.push_subscriptions add column if not exists kind text not null default 'web';
alter table public.push_subscriptions add column if not exists platform text;
alter table public.push_subscriptions drop constraint if exists push_subscriptions_kind_check;
alter table public.push_subscriptions add constraint push_subscriptions_kind_check check (kind in ('web','fcm'));
alter table public.push_subscriptions drop constraint if exists push_subscriptions_platform_check;
alter table public.push_subscriptions add constraint push_subscriptions_platform_check check (platform is null or platform in ('android','ios','web'));
alter table public.push_subscriptions alter column p256dh drop not null;
alter table public.push_subscriptions alter column auth drop not null;
alter table public.push_subscriptions drop constraint if exists push_subscriptions_keys_check;
alter table public.push_subscriptions add constraint push_subscriptions_keys_check check (kind = 'fcm' or (p256dh is not null and auth is not null));

select public.attach_change_log();

-- ===== 20260101005000_insights.sql =====
-- =====================================================================
--  Phase 13a: analytics and statutory returns.
--
--  * The school's census details (EMIS/school code, state, LGA, ownership…)
--    used on government returns.
--  * Statutory returns (the annual school census for the state ministry /
--    UBEC): figures worked out from the school's records, checked and edited
--    by an admin, then marked submitted with the ministry's reference. A
--    submitted return is kept as sent and cannot be changed.
-- =====================================================================

-- e.g. {"school_code":"LA/IKJ/123","state":"Lagos","lga":"Ikeja","ownership":"private","school_type":"junior_senior_secondary","location":"urban"}
alter table public.tenant_settings add column if not exists census_profile jsonb not null default '{}'::jsonb;

create table if not exists public.statutory_returns (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  kind          text not null default 'annual_school_census' check (kind in ('annual_school_census','enrolment_return','staff_return')),
  period        text not null check (length(trim(period)) between 4 and 20),   -- e.g. 2026/2027
  data          jsonb not null default '{}'::jsonb,
  status        text not null default 'draft' check (status in ('draft','submitted')),
  prepared_by   uuid references public.users(id) on delete set null,
  prepared_at   timestamptz not null default now(),
  submitted_by  uuid references public.users(id) on delete set null,
  submitted_at  timestamptz,
  reference     text,              -- the ministry's acknowledgement number
  notes         text,
  unique (tenant_id, kind, period)
);

-- Once submitted, the return stays as it was sent; only the acknowledgement reference and notes may be added.
create or replace function public.statutory_returns_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'submitted' and auth.uid() is not null then raise exception 'a submitted return cannot be deleted'; end if;
    return old;
  end if;
  if old.status = 'submitted' and (new.status <> 'submitted' or new.data is distinct from old.data or new.period <> old.period
     or new.kind <> old.kind or new.submitted_at is distinct from old.submitted_at or new.submitted_by is distinct from old.submitted_by) then
    raise exception 'a submitted return cannot be changed';
  end if;
  if new.status = 'submitted' and old.status = 'draft' then
    new.submitted_at := coalesce(new.submitted_at, now());
    new.submitted_by := coalesce(new.submitted_by, auth.uid());
  end if;
  return new;
end $$;
drop trigger if exists statutory_returns_guard on public.statutory_returns;
create trigger statutory_returns_guard before update or delete on public.statutory_returns for each row execute function public.statutory_returns_guard();

alter table public.statutory_returns enable row level security;
drop policy if exists statutory_returns_rw on public.statutory_returns;
create policy statutory_returns_rw on public.statutory_returns for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.statutory_returns to service_role;

select public.attach_change_log();

-- ===== 20260101005100_report_builder.sql =====
-- =====================================================================
--  Phase 13b: custom reports.
--
--  * Saved reports: a dataset (students, attendance, results, fees,
--    payments, applications, staff, library, behaviour…), the columns,
--    filters, grouping and totals chosen in the report builder.
--  * Kept private to their author or shared with colleagues (who still
--    only see datasets their role allows).
--  * Sent on a schedule (daily, weekly or monthly) to members of staff of
--    the same school, never to outside addresses or families.
-- =====================================================================

create table if not exists public.saved_reports (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  owner_id       uuid references public.users(id) on delete cascade,
  name           text not null check (length(trim(name)) between 1 and 120),
  description    text,
  dataset        text not null check (dataset ~ '^[a-z_]{2,40}$'),
  spec           jsonb not null default '{}'::jsonb,
  shared         boolean not null default false,
  schedule       text not null default 'none' check (schedule in ('none','daily','weekly','monthly')),
  schedule_day   int check (schedule_day between 1 and 28),       -- weekday 1–7 (Mon–Sun) for weekly, day of month for monthly
  schedule_hour  int not null default 7 check (schedule_hour between 0 and 23),
  recipient_ids  uuid[] not null default '{}',
  next_run_at    timestamptz,
  last_sent_at   timestamptz,
  last_error     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check (schedule = 'none' or cardinality(recipient_ids) between 1 and 50),
  check (schedule <> 'weekly' or schedule_day between 1 and 7),
  check (schedule <> 'monthly' or schedule_day is not null)
);
create index if not exists saved_reports_due on public.saved_reports(next_run_at) where schedule <> 'none';

-- Scheduled copies go only to staff of the same school.
create or replace function public.saved_reports_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if exists (
    select 1 from unnest(new.recipient_ids) r(id)
    where not exists (select 1 from public.users u where u.id = r.id and u.tenant_id = new.tenant_id
                        and u.active and u.role not in ('parent','student'))
  ) then
    raise exception 'reports can only be sent to staff of this school';
  end if;
  if tg_op = 'UPDATE' and auth.uid() is not null and new.owner_id is distinct from old.owner_id and not public.is_school_admin() then
    raise exception 'only admins can hand a report to someone else';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists saved_reports_guard on public.saved_reports;
create trigger saved_reports_guard before insert or update on public.saved_reports for each row execute function public.saved_reports_guard();

alter table public.saved_reports enable row level security;
drop policy if exists saved_reports_read on public.saved_reports;
create policy saved_reports_read on public.saved_reports for select
  using (tenant_id = public.my_tenant_id() and public.is_staff() and (owner_id = auth.uid() or shared or public.is_school_admin()));
drop policy if exists saved_reports_insert on public.saved_reports;
create policy saved_reports_insert on public.saved_reports for insert
  with check (tenant_id = public.my_tenant_id() and public.is_staff() and owner_id = auth.uid());
drop policy if exists saved_reports_update on public.saved_reports;
create policy saved_reports_update on public.saved_reports for update
  using (tenant_id = public.my_tenant_id() and (owner_id = auth.uid() or public.is_school_admin()))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists saved_reports_delete on public.saved_reports;
create policy saved_reports_delete on public.saved_reports for delete
  using (tenant_id = public.my_tenant_id() and (owner_id = auth.uid() or public.is_school_admin()));
grant all on public.saved_reports to service_role;

select public.attach_change_log();

-- ===== 20260101005200_open_api.sql =====
-- =====================================================================
--  Phase 13c: the open API, webhooks and the school website.
--
--  * API keys: admins create keys with chosen scopes for other systems
--    (a website, a data warehouse, a district office). Only a hash is kept;
--    the key is shown once.
--  * Webhooks: other systems are told when things happen (a student is
--    admitted, an application arrives, a payment is received, results are
--    published, news is posted). Events are queued by the database and sent,
--    signed, by the every-minute job, with retries.
--  * Website: news posts for the school's own site, and events marked to
--    show there, served as a JSON feed, RSS and an embeddable widget along
--    with the admissions and enquiry forms.
-- =====================================================================

create table if not exists public.api_keys (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(trim(name)) between 1 and 80),
  prefix        text not null unique,                 -- first characters, to recognise the key
  key_hash      text not null unique,                 -- sha-256 of the full key
  scopes        text[] not null default '{}',
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  last_used_at  timestamptz,
  expires_at    timestamptz,
  revoked_at    timestamptz,
  check (scopes <@ array['students:read','classes:read','staff:read','attendance:read','results:read','fees:read','payments:read',
                         'applications:read','applications:write','events:read','news:read']::text[])
);
alter table public.api_keys enable row level security;
drop policy if exists api_keys_admin on public.api_keys;
create policy api_keys_admin on public.api_keys for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.api_keys to service_role;

create table if not exists public.webhook_endpoints (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  url              text not null check (url ~ '^https://[^\s/$.?#].[^\s]*$' and length(url) <= 500),
  description      text,
  events           text[] not null default '{*}',
  secret           text not null default encode(gen_random_bytes(24), 'hex'),
  active           boolean not null default true,
  failures         int not null default 0,              -- in a row; turned off after 20
  last_status      int,
  last_delivered_at timestamptz,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now(),
  check (events <@ array['*','student.created','student.updated','application.created','application.status_changed',
                         'payment.received','invoice.created','result.published','news.published']::text[] and cardinality(events) > 0)
);
alter table public.webhook_endpoints enable row level security;
drop policy if exists webhook_endpoints_admin on public.webhook_endpoints;
create policy webhook_endpoints_admin on public.webhook_endpoints for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.webhook_endpoints to service_role;

create table if not exists public.webhook_deliveries (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  endpoint_id      uuid not null references public.webhook_endpoints(id) on delete cascade,
  event            text not null,
  payload          jsonb not null,
  status           text not null default 'queued' check (status in ('queued','sending','delivered','failed')),
  attempts         int not null default 0,
  next_attempt_at  timestamptz not null default now(),
  response_code    int,
  last_error       text,
  created_at       timestamptz not null default now(),
  delivered_at     timestamptz
);
create index if not exists webhook_deliveries_due on public.webhook_deliveries(next_attempt_at) where status = 'queued';
create index if not exists webhook_deliveries_endpoint on public.webhook_deliveries(endpoint_id, created_at desc);
alter table public.webhook_deliveries enable row level security;
drop policy if exists webhook_deliveries_read on public.webhook_deliveries;
create policy webhook_deliveries_read on public.webhook_deliveries for select
  using (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.webhook_deliveries to service_role;

-- Queues an event for every active endpoint that wants it. Cheap when a school has none.
create or replace function public.queue_webhook(p_tenant uuid, p_event text, p_payload jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.webhook_endpoints where tenant_id = p_tenant and active) then return; end if;
  insert into public.webhook_deliveries (tenant_id, endpoint_id, event, payload)
  select p_tenant, e.id, p_event, jsonb_build_object('id', gen_random_uuid(), 'event', p_event, 'created_at', now(), 'data', p_payload)
  from public.webhook_endpoints e
  where e.tenant_id = p_tenant and e.active and (p_event = any(e.events) or '*' = any(e.events));
end $$;
revoke all on function public.queue_webhook(uuid, text, jsonb) from public, anon, authenticated;

create or replace function public.webhook_events() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_table_name = 'students' then
    if tg_op = 'INSERT' then
      perform public.queue_webhook(new.tenant_id, 'student.created', jsonb_build_object('student_id', new.id, 'admission_no', new.admission_no,
        'first_name', new.first_name, 'last_name', new.last_name, 'class_group_id', new.class_group_id, 'status', new.status));
    elsif new.status is distinct from old.status or new.class_group_id is distinct from old.class_group_id then
      perform public.queue_webhook(new.tenant_id, 'student.updated', jsonb_build_object('student_id', new.id, 'admission_no', new.admission_no,
        'class_group_id', new.class_group_id, 'status', new.status, 'previous_status', old.status));
    end if;
  elsif tg_table_name = 'applications' then
    if tg_op = 'INSERT' then
      perform public.queue_webhook(new.tenant_id, 'application.created', jsonb_build_object('application_id', new.id, 'application_no', new.application_no,
        'applying_for', new.applying_for, 'status', new.status, 'source', new.source));
    elsif new.status is distinct from old.status then
      perform public.queue_webhook(new.tenant_id, 'application.status_changed', jsonb_build_object('application_id', new.id, 'application_no', new.application_no,
        'status', new.status, 'previous_status', old.status));
    end if;
  elsif tg_table_name = 'fee_payments' then
    if new.status = 'success' and (tg_op = 'INSERT' or old.status is distinct from 'success') then
      perform public.queue_webhook(new.tenant_id, 'payment.received', jsonb_build_object('payment_id', new.id, 'invoice_id', new.invoice_id, 'student_id', new.student_id,
        'amount', new.amount, 'currency', new.currency, 'method', new.method, 'receipt_no', new.receipt_no, 'paid_at', coalesce(new.paid_at, new.created_at)));
    end if;
  elsif tg_table_name = 'fee_invoices' then
    perform public.queue_webhook(new.tenant_id, 'invoice.created', jsonb_build_object('invoice_id', new.id, 'invoice_no', new.invoice_no, 'student_id', new.student_id,
      'term_id', new.term_id, 'total', new.total, 'due_date', new.due_date));
  elsif tg_table_name = 'report_cards' then
    if new.status = 'published' and old.status is distinct from 'published' then
      perform public.queue_webhook(new.tenant_id, 'result.published', jsonb_build_object('report_card_id', new.id, 'student_id', new.student_id, 'term_id', new.term_id,
        'average', new.average, 'position', new.position));
    end if;
  elsif tg_table_name = 'news_posts' then
    if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
      perform public.queue_webhook(new.tenant_id, 'news.published', jsonb_build_object('news_id', new.id, 'title', new.title, 'slug', new.slug, 'published_at', new.published_at));
    end if;
  end if;
  return null;
end $$;

-- ---------- News for the school website ----------
create table if not exists public.news_posts (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  title         text not null check (length(trim(title)) between 2 and 160),
  slug          text not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,80}$'),
  summary       text check (length(summary) <= 400),
  body          text not null default '' check (length(body) <= 50000),
  image_url     text check (image_url is null or image_url ~ '^https://'),
  status        text not null default 'draft' check (status in ('draft','published')),
  published_at  timestamptz,
  author_id     uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (tenant_id, slug)
);
create or replace function public.news_posts_stamp() returns trigger language plpgsql as $$
begin
  if new.status = 'published' and new.published_at is null then new.published_at := now(); end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists news_posts_stamp on public.news_posts;
create trigger news_posts_stamp before insert or update on public.news_posts for each row execute function public.news_posts_stamp();
alter table public.news_posts enable row level security;
drop policy if exists news_posts_read on public.news_posts;
create policy news_posts_read on public.news_posts for select using (tenant_id = public.my_tenant_id());
drop policy if exists news_posts_write on public.news_posts;
create policy news_posts_write on public.news_posts for all
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['admissions_officer'])))
  with check (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['admissions_officer'])));
grant all on public.news_posts to service_role;

alter table public.school_events add column if not exists show_on_website boolean not null default false;

drop trigger if exists webhook_events on public.students;
create trigger webhook_events after insert or update on public.students for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.applications;
create trigger webhook_events after insert or update on public.applications for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.fee_payments;
create trigger webhook_events after insert or update on public.fee_payments for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.fee_invoices;
create trigger webhook_events after insert on public.fee_invoices for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.report_cards;
create trigger webhook_events after update on public.report_cards for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.news_posts;
create trigger webhook_events after insert or update on public.news_posts for each row execute function public.webhook_events();

-- Deliveries are a queue; keys and endpoints hold secrets. None of them belong in the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots',
        'api_keys','webhook_endpoints','webhook_deliveries'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101005300_lti.sql =====
-- =====================================================================
--  Phase 13d: LTI 1.3 (Learning Tools Interoperability).
--
--  The school system acts as the LTI platform: admins register outside
--  learning tools (Khan Academy, Labster, H5P.com, publisher content…);
--  teachers add a tool to a class (optionally tied to homework); students
--  open it signed in, with no extra password. Tools that support Assignment
--  and Grade Services send scores back; scores tied to homework become the
--  homework mark.
-- =====================================================================

-- The platform's signing keys (shared by every school; the private key never leaves the server).
create table if not exists public.lti_platform_keys (
  kid          text primary key,
  public_jwk   jsonb not null,
  private_pem  text not null,
  active       boolean not null default true,
  created_at   timestamptz not null default now()
);
alter table public.lti_platform_keys enable row level security;   -- server only
grant all on public.lti_platform_keys to service_role;

create table if not exists public.lti_tools (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  name             text not null check (length(trim(name)) between 1 and 120),
  description      text,
  client_id        text not null unique default replace(gen_random_uuid()::text, '-', ''),
  deployment_id    text not null default replace(gen_random_uuid()::text, '-', ''),
  oidc_login_url   text not null check (oidc_login_url ~ '^https://'),
  target_link_uri  text not null check (target_link_uri ~ '^https://'),
  redirect_uris    text[] not null default '{}',
  jwks_url         text check (jwks_url is null or jwks_url ~ '^https://'),
  public_key_pem   text,
  custom           jsonb not null default '{}'::jsonb,
  send_name        boolean not null default true,
  send_email       boolean not null default false,
  grades           boolean not null default true,
  active           boolean not null default true,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now(),
  check (jwks_url is not null or public_key_pem is not null or not grades)
);
alter table public.lti_tools enable row level security;
drop policy if exists lti_tools_read on public.lti_tools;
create policy lti_tools_read on public.lti_tools for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists lti_tools_write on public.lti_tools;
create policy lti_tools_write on public.lti_tools for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.lti_tools to service_role;

create table if not exists public.lti_links (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  tool_id         uuid not null references public.lti_tools(id) on delete cascade,
  title           text not null check (length(trim(title)) between 1 and 160),
  class_group_id  uuid references public.class_groups(id) on delete cascade,
  subject_id      uuid references public.subjects(id) on delete set null,
  homework_id     uuid references public.homework(id) on delete set null,
  target_link_uri text check (target_link_uri is null or target_link_uri ~ '^https://'),   -- a deep link inside the tool
  custom          jsonb not null default '{}'::jsonb,
  score_maximum   numeric check (score_maximum is null or score_maximum > 0),
  open_in         text not null default 'window' check (open_in in ('window','frame')),
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists lti_links_class on public.lti_links(class_group_id);

-- A student may see the tools added to their own class (or to everyone).
create or replace function public.in_my_class(p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select p_class is null or exists (select 1 from public.students s where s.user_id = auth.uid() and s.tenant_id = public.my_tenant_id() and s.class_group_id = p_class);
$$;
grant execute on function public.in_my_class(uuid) to authenticated;

alter table public.lti_links enable row level security;
drop policy if exists lti_links_read on public.lti_links;
create policy lti_links_read on public.lti_links for select using (tenant_id = public.my_tenant_id() and (public.is_staff() or public.in_my_class(class_group_id)));
drop policy if exists lti_links_write on public.lti_links;
create policy lti_links_write on public.lti_links for all
  using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff()
    and exists (select 1 from public.lti_tools t where t.id = tool_id and t.tenant_id = public.my_tenant_id() and t.active));
grant all on public.lti_links to service_role;

-- One row per launch: the login hint is single-use and expires after five minutes.
create table if not exists public.lti_launches (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  link_id     uuid not null references public.lti_links(id) on delete cascade,
  user_id     uuid not null references public.users(id) on delete cascade,
  created_at  timestamptz not null default now(),
  used_at     timestamptz
);
alter table public.lti_launches enable row level security;   -- server only
grant all on public.lti_launches to service_role;

create table if not exists public.lti_scores (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  link_id            uuid not null references public.lti_links(id) on delete cascade,
  user_id            uuid not null references public.users(id) on delete cascade,
  score_given        numeric,
  score_maximum      numeric,
  activity_progress  text,
  grading_progress   text,
  comment            text,
  tool_timestamp     timestamptz,
  received_at        timestamptz not null default now(),
  unique (link_id, user_id)
);
alter table public.lti_scores enable row level security;
drop policy if exists lti_scores_read on public.lti_scores;
create policy lti_scores_read on public.lti_scores for select using (tenant_id = public.my_tenant_id() and (public.is_staff() or user_id = auth.uid()));
grant all on public.lti_scores to service_role;

-- Launch records are a short-lived log and keys are secrets: neither belongs in the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots',
        'api_keys','webhook_endpoints','webhook_deliveries',
        'lti_launches','lti_platform_keys'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101005400_classroom_sync.sql =====
-- =====================================================================
--  Phase 13e: Google Classroom and Microsoft Teams / OneNote.
--
--  * Each teacher connects their own Google or Microsoft school account
--    (tokens are kept on the server only).
--  * A class (and subject) is linked to a Classroom course or a Teams class.
--  * Homework is sent across as an assignment, and marks are brought back
--    into the homework, matched by email.
--  * Lesson notes can be sent to the teacher's OneNote.
-- =====================================================================

create table if not exists public.oauth_connections (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  user_id        uuid not null references public.users(id) on delete cascade,
  provider       text not null check (provider in ('google','microsoft')),
  account_email  text,
  access_token   text not null,
  refresh_token  text,
  expires_at     timestamptz,
  scopes         text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (user_id, provider)
);
alter table public.oauth_connections enable row level security;   -- server only: tokens never reach the browser
grant all on public.oauth_connections to service_role;

create table if not exists public.class_links (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_group_id  uuid not null references public.class_groups(id) on delete cascade,
  subject_id      uuid references public.subjects(id) on delete cascade,
  provider        text not null check (provider in ('google','microsoft')),
  external_id     text not null check (length(external_id) between 1 and 200),
  external_name   text,
  external_url    text,
  linked_by       uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create unique index if not exists class_links_once on public.class_links(class_group_id, coalesce(subject_id, '00000000-0000-0000-0000-000000000000'::uuid), provider);
alter table public.class_links enable row level security;
drop policy if exists class_links_read on public.class_links;
create policy class_links_read on public.class_links for select using (tenant_id = public.my_tenant_id() and public.is_staff());
grant all on public.class_links to service_role;   -- written by the server after checking the teacher teaches the class

create table if not exists public.homework_external (
  homework_id     uuid not null references public.homework(id) on delete cascade,
  provider        text not null check (provider in ('google','microsoft')),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_link_id   uuid references public.class_links(id) on delete set null,
  external_id     text not null,
  external_url    text,
  pushed_by       uuid references public.users(id) on delete set null,
  pushed_at       timestamptz not null default now(),
  grades_pulled_at timestamptz,
  primary key (homework_id, provider)
);
alter table public.homework_external enable row level security;
drop policy if exists homework_external_read on public.homework_external;
create policy homework_external_read on public.homework_external for select using (tenant_id = public.my_tenant_id() and public.is_staff());
grant all on public.homework_external to service_role;

alter table public.lesson_notes add column if not exists onenote_url text;

-- Tokens are secrets: keep them out of the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots',
        'api_keys','webhook_endpoints','webhook_deliveries',
        'lti_launches','lti_platform_keys',
        'oauth_connections'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101005500_compliance_docs.sql =====
-- =====================================================================
--  Phase 13f: compliance documents and inspection readiness.
--
--  * A document library for policies, certificates, inspection files,
--    minutes and risk assessments: versions, approval, review dates for
--    policies, expiry dates for certificates, who may see each, and
--    policies staff must read and confirm.
--  * The single central record: pre-employment and safeguarding checks on
--    every member of staff (identity, right to work, qualifications,
--    references, police checks, medical fitness, training) with dates.
--  * Inspection readiness: progress on each requirement of the frameworks
--    the school follows (MoE/SUBEB minimum standards, BSO, COBIS,
--    Cambridge centre), with owners, notes and the documents that show it.
-- =====================================================================

insert into storage.buckets (id, name, public) values ('school-documents', 'school-documents', false) on conflict (id) do nothing;

create table if not exists public.school_documents (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  family_id       uuid not null default gen_random_uuid(),     -- every version of the same document shares this
  version         int not null default 1 check (version >= 1),
  title           text not null check (length(trim(title)) between 2 and 200),
  category        text not null check (category in ('policy','certificate','inspection','minutes','risk_assessment','procedure','report','plan','other')),
  description     text,
  path            text,                                         -- private storage path (null for a link-only record)
  mime            text,
  size_bytes      int,
  visibility      text not null default 'staff' check (visibility in ('leaders','staff','parents')),
  status          text not null default 'draft' check (status in ('draft','approved','superseded','archived')),
  approved_by     uuid references public.users(id) on delete set null,
  approved_at     timestamptz,
  review_due_on   date,                                         -- policies: next review
  expires_on      date,                                         -- certificates: when it runs out
  issued_by       text,                                         -- e.g. Lagos State Fire Service
  reference_no    text,
  tags            text[] not null default '{}',
  requires_ack    boolean not null default false,               -- staff must confirm they have read it
  reminded_at     timestamptz,
  owner_id        uuid references public.users(id) on delete set null,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (family_id, version)
);
create index if not exists school_documents_tenant on public.school_documents(tenant_id, category, status);

-- Approving a new version retires the old one; approval is stamped.
create or replace function public.school_documents_stamp() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if new.status = 'approved' and (tg_op = 'INSERT' or old.status is distinct from 'approved') then
    new.approved_at := coalesce(new.approved_at, now());
    new.approved_by := coalesce(new.approved_by, auth.uid());
    update public.school_documents set status = 'superseded', updated_at = now()
      where family_id = new.family_id and id <> new.id and status = 'approved';
  end if;
  return new;
end $$;
drop trigger if exists school_documents_stamp on public.school_documents;
create trigger school_documents_stamp before insert or update on public.school_documents for each row execute function public.school_documents_stamp();

create or replace function public.can_see_document(p_visibility text, p_status text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])
    or (p_status = 'approved' and (p_visibility = 'staff' and public.is_staff() or p_visibility = 'parents' and (public.is_staff() or public.has_role(array['parent']))));
$$;
grant execute on function public.can_see_document(text, text) to authenticated;

alter table public.school_documents enable row level security;
drop policy if exists school_documents_read on public.school_documents;
create policy school_documents_read on public.school_documents for select using (tenant_id = public.my_tenant_id() and public.can_see_document(visibility, status));
drop policy if exists school_documents_write on public.school_documents;
create policy school_documents_write on public.school_documents for all
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])))
  with check (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])));
grant all on public.school_documents to service_role;

create table if not exists public.document_acknowledgements (
  document_id      uuid not null references public.school_documents(id) on delete cascade,
  user_id          uuid not null references public.users(id) on delete cascade,
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  acknowledged_at  timestamptz not null default now(),
  primary key (document_id, user_id)
);
alter table public.document_acknowledgements enable row level security;
drop policy if exists document_ack_read on public.document_acknowledgements;
create policy document_ack_read on public.document_acknowledgements for select
  using (tenant_id = public.my_tenant_id() and (user_id = auth.uid() or public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])));
drop policy if exists document_ack_insert on public.document_acknowledgements;
create policy document_ack_insert on public.document_acknowledgements for insert
  with check (tenant_id = public.my_tenant_id() and user_id = auth.uid() and public.is_staff()
    and exists (select 1 from public.school_documents d where d.id = document_id and d.tenant_id = public.my_tenant_id() and d.status = 'approved' and d.requires_ack));
grant all on public.document_acknowledgements to service_role;

-- ---------- Single central record ----------
create table if not exists public.staff_checks (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  staff_id      uuid not null references public.staff(id) on delete cascade,
  kind          text not null check (kind in ('identity','right_to_work','qualifications','references','police_check','overseas_police_check',
                                               'prohibition_check','medical_fitness','safeguarding_training','first_aid_training','other')),
  outcome       text not null default 'clear' check (outcome in ('clear','concern','pending','not_required')),
  checked_on    date,
  expires_on    date,
  reference_no  text,
  checked_by    uuid references public.users(id) on delete set null,
  document_id   uuid references public.staff_documents(id) on delete set null,
  notes         text,
  created_at    timestamptz not null default now(),
  check (outcome = 'pending' or outcome = 'not_required' or checked_on is not null)
);
create index if not exists staff_checks_staff on public.staff_checks(staff_id, kind);
alter table public.staff_checks enable row level security;
drop policy if exists staff_checks_rw on public.staff_checks;
create policy staff_checks_rw on public.staff_checks for all
  using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());
drop policy if exists staff_checks_own on public.staff_checks;
create policy staff_checks_own on public.staff_checks for select using (tenant_id = public.my_tenant_id() and staff_id = public.my_staff_id());
grant all on public.staff_checks to service_role;

-- ---------- Inspection readiness ----------
create table if not exists public.inspection_progress (
