-- ---------------------------------------------------------------------------
-- Tenancy
-- ---------------------------------------------------------------------------
create table if not exists live.tenants (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (length(btrim(name)) between 1 and 200),
  slug        text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  plan_code   text not null default 'free_teacher' references live.plans(code),
  country     text,
  timezone    text not null default 'UTC',
  created_at  timestamptz not null default now()
);

-- One row per tenant; every privacy/retention knob from §19/§20 lives here.
create table if not exists live.tenant_settings (
  tenant_id                   uuid primary key references live.tenants(id) on delete cascade,
  allow_spotlight             boolean not null default true,
  allow_group_chat            boolean not null default false,
  allow_screen_capture        boolean not null default true,
  store_event_screenshots     boolean not null default false,
  parent_portal_enabled       boolean not null default false,
  email_alerts_enabled        boolean not null default false,
  nickname_mode               text    not null default 'first_name_initial'
                                check (nickname_mode in ('first_name_initial','approved_nickname','anonymous')),
  learning_retention_days     int     not null default 730 check (learning_retention_days between 30 and 3650),
  telemetry_retention_days    int     not null default 30  check (telemetry_retention_days between 1 and 365),
  default_grace_seconds       int     not null default 15  check (default_grace_seconds between 0 and 600),
  default_idle_seconds        int     not null default 300 check (default_idle_seconds between 30 and 7200),
  thumbnail_interval_seconds  int     not null default 20  check (thumbnail_interval_seconds between 5 and 300),
  monitoring_notice           text    not null default
    'This browser is managed by your school. During an active class session your teacher can see the site you are on and a low-resolution picture of your screen. Nothing is monitored outside class sessions.',
  monitoring_notice_version   int     not null default 1,
  support_access_until        timestamptz,
  updated_at                  timestamptz not null default now()
);

create table if not exists live.schools (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references live.tenants(id) on delete cascade,
  name        text not null check (length(btrim(name)) between 1 and 200),
  created_at  timestamptz not null default now(),
  unique (id, tenant_id)
);

create table if not exists live.departments (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references live.tenants(id) on delete cascade,
  school_id   uuid,
  name        text not null,
  created_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (school_id, tenant_id) references live.schools(id, tenant_id) on delete cascade
);

-- Application profile for every auth.users row that belongs to a tenant.
create table if not exists live.users (
  id            uuid primary key references auth.users(id) on delete cascade,
  tenant_id     uuid not null references live.tenants(id) on delete cascade,
  school_id     uuid,
  email         text not null,
  full_name     text not null check (length(btrim(full_name)) between 1 and 200),
  nickname      text check (nickname is null or length(nickname) between 1 and 40),
  role          text not null references live.roles(code),
  status        text not null default 'active' check (status in ('active','suspended')),
  last_seen_at  timestamptz,
  created_at    timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (school_id, tenant_id) references live.schools(id, tenant_id) on delete set null (school_id)
);
create index if not exists users_tenant_role_idx on live.users(tenant_id, role);
create index if not exists users_tenant_email_idx on live.users(tenant_id, lower(email));

create table if not exists live.student_profiles (
  user_id         uuid primary key,
  tenant_id       uuid not null,
  grade_level     text,
  student_number  text,
  created_at      timestamptz not null default now(),
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

create table if not exists live.teacher_profiles (
  user_id       uuid primary key,
  tenant_id     uuid not null,
  subject_area  text,
  department_id uuid,
  created_at    timestamptz not null default now(),
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (department_id, tenant_id) references live.departments(id, tenant_id) on delete set null (department_id)
);

-- ---------------------------------------------------------------------------
-- Classes & rosters
-- ---------------------------------------------------------------------------
create table if not exists live.classes (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references live.tenants(id) on delete cascade,
  school_id     uuid,
  department_id uuid,
  teacher_id    uuid not null,
  name          text not null check (length(btrim(name)) between 1 and 200),
  subject       text,
  grade_level   text,
  join_code     text not null unique check (join_code ~ '^[A-Z0-9]{6,8}$'),
  archived_at   timestamptz,
  created_at    timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (teacher_id, tenant_id) references live.users(id, tenant_id),
  foreign key (school_id, tenant_id) references live.schools(id, tenant_id) on delete set null (school_id),
  foreign key (department_id, tenant_id) references live.departments(id, tenant_id) on delete set null (department_id)
);
create index if not exists classes_tenant_idx on live.classes(tenant_id);
create index if not exists classes_teacher_idx on live.classes(teacher_id);

create table if not exists live.class_members (
  class_id    uuid not null,
  user_id     uuid not null,
  tenant_id   uuid not null,
  role        text not null check (role in ('teacher','student')),
  joined_at   timestamptz not null default now(),
  primary key (class_id, user_id),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create index if not exists class_members_user_idx on live.class_members(user_id);

-- §3.5 "Student groups" + §23 "auto-start environments".
create table if not exists live.student_groups (
  id                    uuid primary key default gen_random_uuid(),
  tenant_id             uuid not null,
  class_id              uuid not null,
  name                  text not null,
  auto_start_policy_id  uuid,   -- FK added in 0400 once environment_policies exists
  created_at            timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade
);

create table if not exists live.student_group_members (
  group_id    uuid not null,
  user_id     uuid not null,
  tenant_id   uuid not null,
  primary key (group_id, user_id),
  foreign key (group_id, tenant_id) references live.student_groups(id, tenant_id) on delete cascade,
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

-- Invite codes bring staff, students and parents into an existing tenant.
create table if not exists live.invites (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references live.tenants(id) on delete cascade,
  code        text not null unique check (code ~ '^[A-Z0-9]{8,12}$'),
  role        text not null references live.roles(code) check (role <> 'platform_admin'),
  email       text,
  class_id    uuid,
  student_id  uuid,  -- parent invites: the student the parent will be linked to
  created_by  uuid not null,
  max_uses    int  not null default 1 check (max_uses between 1 and 1000),
  uses        int  not null default 0,
  expires_at  timestamptz not null,
  revoked_at  timestamptz,
  created_at  timestamptz not null default now(),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (created_by, tenant_id) references live.users(id, tenant_id) on delete cascade,
  check (role <> 'parent' or student_id is not null)
);

create table if not exists live.parent_links (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  parent_id   uuid not null,
  student_id  uuid not null,
  relation    text not null default 'guardian',
  created_at  timestamptz not null default now(),
  revoked_at  timestamptz,
  unique (parent_id, student_id),
  foreign key (parent_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

-- ---------------------------------------------------------------------------
-- Billing (§25, §26)
-- ---------------------------------------------------------------------------
create table if not exists live.subscriptions (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null references live.tenants(id) on delete cascade,
  plan_code           text not null references live.plans(code),
  status              text not null check (status in ('trialing','active','past_due','canceled')),
  provider            text not null default 'none' check (provider in ('none','stripe','paystack','manual')),
  provider_ref        text,
  current_period_end  timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create unique index if not exists subscriptions_one_live_per_tenant
  on live.subscriptions(tenant_id) where status in ('trialing','active','past_due');

create table if not exists live.invoices (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references live.tenants(id) on delete cascade,
  subscription_id uuid references live.subscriptions(id) on delete set null,
  amount_cents    int  not null check (amount_cents >= 0),
  currency        text not null default 'USD',
  status          text not null check (status in ('draft','open','paid','void','uncollectible')),
  provider_ref    text unique,
  issued_at       timestamptz not null default now(),
  paid_at         timestamptz
);

create table if not exists live.feature_flags (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid references live.tenants(id) on delete cascade,  -- null = platform default
  key         text not null check (key ~ '^[a-z0-9_.]{2,64}$'),
  enabled     boolean not null default false,
  updated_at  timestamptz not null default now(),
  unique nulls not distinct (tenant_id, key)
);

-- ---------------------------------------------------------------------------
-- Audit, notifications, consent (§17, §20)
-- ---------------------------------------------------------------------------
create table if not exists live.audit_logs (
  id           bigint generated always as identity primary key,
  tenant_id    uuid references live.tenants(id) on delete cascade,
  actor_id     uuid,
  action       text not null,
  target_type  text,
  target_id    text,
  meta         jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now()
);
create index if not exists audit_logs_tenant_time_idx on live.audit_logs(tenant_id, created_at desc);

create table if not exists live.notifications (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  user_id     uuid not null,
  kind        text not null,
  title       text not null,
  body        text,
  link        text,
  severity    text not null default 'info' check (severity in ('info','warning','critical')),
  payload     jsonb not null default '{}'::jsonb,
  read_at     timestamptz,
  created_at  timestamptz not null default now(),
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create index if not exists notifications_user_idx on live.notifications(user_id, created_at desc);

create table if not exists live.consents (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  user_id     uuid not null,
  kind        text not null check (kind in ('monitoring_notice','acceptable_use','privacy_notice')),
  version     int  not null,
  accepted_at timestamptz not null default now(),
  unique (user_id, kind, version),
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

-- =============================================================================
-- Helper functions used by RLS policies and RPCs.
-- All are SECURITY DEFINER with an empty search_path (no hijacking), STABLE
-- where possible so the planner can cache them per statement.
-- =============================================================================
create or replace function live_app.tenant_id() returns uuid
language sql stable security definer set search_path = '' as $$
  select u.tenant_id from live.users u where u.id = auth.uid() and u.status = 'active'
$$;

create or replace function live_app.role() returns text
language sql stable security definer set search_path = '' as $$
  select u.role from live.users u where u.id = auth.uid() and u.status = 'active'
$$;

create or replace function live_app.is_staff() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(live_app.role() in ('teacher','school_admin','it_admin','platform_admin'), false)
$$;

-- Can author lessons/activities and run classes.
create or replace function live_app.is_teacher() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(live_app.role() in ('teacher','school_admin','platform_admin'), false)
$$;

create or replace function live_app.is_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(live_app.role() in ('school_admin','platform_admin'), false)
$$;

-- Device & technical-policy administration (IT admins have no academic access).
create or replace function live_app.is_it() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(live_app.role() in ('it_admin','school_admin','platform_admin'), false)
$$;

create or replace function live_app.can_manage_class(p_class uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.classes c
    where c.id = p_class
      and c.tenant_id = live_app.tenant_id()
      and (
        c.teacher_id = auth.uid()
        or live_app.is_admin()
        or exists (select 1 from live.class_members m
                   where m.class_id = c.id and m.user_id = auth.uid() and m.role = 'teacher')
      )
  )
$$;

create or replace function live_app.in_class(p_class uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.class_members m
    where m.class_id = p_class and m.user_id = auth.uid() and m.tenant_id = live_app.tenant_id()
  )
$$;

create or replace function live_app.is_parent_of(p_student uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.parent_links pl
    join live.tenant_settings ts on ts.tenant_id = pl.tenant_id
    where pl.parent_id = auth.uid() and pl.student_id = p_student
      and pl.revoked_at is null and ts.parent_portal_enabled
  )
$$;

-- Does the caller teach/administer a class this student belongs to?
create or replace function live_app.teaches_student(p_student uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.class_members m
    where m.user_id = p_student and m.role = 'student' and live_app.can_manage_class(m.class_id)
  )
$$;

-- Unambiguous, human-friendly codes (no 0/O/1/I/L).
create or replace function live_app.gen_code(p_len int) returns text
language plpgsql volatile set search_path = '' as $$
declare
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_bytes bytea := decode(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'hex');
  v_out text := '';
begin
  for i in 0 .. p_len - 1 loop
    v_out := v_out || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
  end loop;
  return v_out;
end$$;

-- 256-bit random secret, hex encoded. Only its sha256 is ever stored.
create or replace function live_app.gen_secret() returns text
language sql volatile set search_path = '' as $$
  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
$$;

create or replace function live_app.hash_secret(p_secret text) returns text
language sql immutable set search_path = '' as $$
  select encode(sha256(convert_to(coalesce(p_secret, ''), 'UTF8')), 'hex')
$$;

create or replace function live_app.audit(
  p_action text, p_target_type text default null, p_target_id text default null,
  p_meta jsonb default '{}'::jsonb, p_tenant uuid default null, p_actor uuid default null
) returns void
language sql volatile security definer set search_path = '' as $$
  insert into live.audit_logs (tenant_id, actor_id, action, target_type, target_id, meta)
  values (coalesce(p_tenant, live_app.tenant_id()), coalesce(p_actor, auth.uid()),
          p_action, p_target_type, p_target_id, coalesce(p_meta, '{}'::jsonb))
$$;

create or replace function live_app.notify(
  p_user uuid, p_kind text, p_title text, p_body text default null,
  p_link text default null, p_severity text default 'info', p_payload jsonb default '{}'::jsonb
) returns void
language sql volatile security definer set search_path = '' as $$
  insert into live.notifications (tenant_id, user_id, kind, title, body, link, severity, payload)
  select u.tenant_id, u.id, p_kind, p_title, p_body, p_link, p_severity, coalesce(p_payload, '{}'::jsonb)
  from live.users u where u.id = p_user
$$;

-- Plan limit check. Returns true when the tenant may add one more of p_key.
create or replace function live_app.within_limit(p_tenant uuid, p_key text, p_current bigint) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(
    (select case when p.limits -> p_key is null or jsonb_typeof(p.limits -> p_key) = 'null' then true
                 else p_current < (p.limits ->> p_key)::bigint end
     from live.tenants t join live.plans p on p.code = t.plan_code
     where t.id = p_tenant),
    false)
$$;

create or replace function live_app.feature(p_tenant uuid, p_key text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(
    (select ff.enabled from live.feature_flags ff where ff.tenant_id = p_tenant and ff.key = p_key),
    (select (p.features ->> p_key)::boolean from live.tenants t join live.plans p on p.code = t.plan_code
     where t.id = p_tenant),
    (select ff.enabled from live.feature_flags ff where ff.tenant_id is null and ff.key = p_key),
    false)
$$;

-- Generic updated_at trigger.
create or replace function live_app.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end$$;drop trigger if exists tenant_settings_touch on live.tenant_settings;


create trigger tenant_settings_touch before update on live.tenant_settings
  for each row execute function live_app.touch_updated_at();drop trigger if exists subscriptions_touch on live.subscriptions;

create trigger subscriptions_touch before update on live.subscriptions
  for each row execute function live_app.touch_updated_at();drop trigger if exists feature_flags_touch on live.feature_flags;

create trigger feature_flags_touch before update on live.feature_flags
  for each row execute function live_app.touch_updated_at();

-- Role/tenant of a profile are immutable from the client; only definer RPCs
-- (which run as the table owner) may change them.
create or replace function live_app.guard_user_update() returns trigger
language plpgsql set search_path = '' as $$
begin
  if current_user in ('authenticated', 'anon')
     and (new.role is distinct from old.role
          or new.tenant_id is distinct from old.tenant_id
          or new.status is distinct from old.status
          or new.email is distinct from old.email) then
    raise exception 'role, tenant, status and email can only be changed by an administrator'
      using errcode = '42501';
  end if;
  return new;
end$$;drop trigger if exists users_guard on live.users;

create trigger users_guard before update on live.users
  for each row execute function live_app.guard_user_update();

-- ===================== 20260901000200_learning.sql =====================
-- =============================================================================
-- SwiftCipher — 0200 learning engine: Studio (§3.1) + Assess (§3.2)
-- =============================================================================

create table if not exists live.lessons (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references live.tenants(id) on delete cascade,
  owner_id        uuid not null,
  title           text not null check (length(btrim(title)) between 1 and 200),
  description     text,
  subject         text,
  grade_level     text,
  status          text not null default 'draft' check (status in ('draft','published','archived')),
  default_mode    text not null default 'live_participation'
                    check (default_mode in ('live_participation','student_paced','front_of_class')),
  is_template     boolean not null default false,
  current_version int not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id)
);
create index if not exists lessons_tenant_idx on live.lessons(tenant_id, updated_at desc);drop trigger if exists lessons_touch on live.lessons;

create trigger lessons_touch before update on live.lessons
  for each row execute function live_app.touch_updated_at();

-- Immutable snapshot taken on every publish (§3.1 versioning).
create table if not exists live.lesson_versions (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  lesson_id    uuid not null,
  version      int  not null,
  snapshot     jsonb not null,
  published_by uuid,
  created_at   timestamptz not null default now(),
  unique (lesson_id, version),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete cascade
);

-- Activities can live inside a lesson or stand alone (question bank, games, assignments).
create table if not exists live.activities (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  lesson_id     uuid,
  owner_id      uuid not null,
  kind          text not null check (kind in (
                  'multiple_choice','poll','open_ended','quiz','draw','fill_blank','matching',
                  'drag_drop','collab_board','file_upload','short_answer','code')),
  title         text not null check (length(btrim(title)) between 1 and 200),
  instructions  text,
  -- time_limit_seconds, attempts_allowed, shuffle_questions, shuffle_options,
  -- show_feedback ('immediately'|'after_submit'|'never'), rubric_id
  settings      jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete cascade,
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id)
);
create index if not exists activities_lesson_idx on live.activities(lesson_id);drop trigger if exists activities_touch on live.activities;

create trigger activities_touch before update on live.activities
  for each row execute function live_app.touch_updated_at();

-- Blueprint name for a competitive/multi-question assessment is "quiz".
create or replace view live.quizzes with (security_invoker = true) as
  select * from live.activities where kind = 'quiz';

create table if not exists live.lesson_slides (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  lesson_id   uuid not null,
  position    int  not null check (position >= 0),
  kind        text not null check (kind in (
                'title','text','image','video','audio','embed','link','attachment',
                'shapes','whiteboard','activity')),
  -- kind-specific content: heading, body (markdown), media_id, url, alt, captions_url,
  -- shapes[], strokes[] ... Validated in the API layer.
  content     jsonb not null default '{}'::jsonb,
  notes       text,
  activity_id uuid,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete cascade,
  foreign key (activity_id, tenant_id) references live.activities(id, tenant_id) on delete set null (activity_id),
  check (kind <> 'activity' or activity_id is not null)
);
create index if not exists lesson_slides_lesson_idx on live.lesson_slides(lesson_id, position);drop trigger if exists lesson_slides_touch on live.lesson_slides;

create trigger lesson_slides_touch before update on live.lesson_slides
  for each row execute function live_app.touch_updated_at();

-- Media library (§3.1): folders, tags, search.
-- array_to_string is only STABLE, so wrap it for use in a generated column.
create or replace function live_app.media_search_doc(p_title text, p_alt text, p_tags text[]) returns tsvector
language sql immutable set search_path = '' as $$
  select to_tsvector('simple'::regconfig,
    coalesce(p_title, '') || ' ' || coalesce(p_alt, '') || ' ' || coalesce(array_to_string(p_tags, ' '), ''))
$$;

create table if not exists live.media_folders (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  owner_id    uuid not null,
  parent_id   uuid,
  name        text not null check (length(btrim(name)) between 1 and 120),
  created_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (parent_id, tenant_id) references live.media_folders(id, tenant_id) on delete cascade
);

create table if not exists live.lesson_media (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  owner_id      uuid not null,
  folder_id     uuid,
  lesson_id     uuid,
  storage_path  text not null unique,          -- "<tenant_id>/<owner_id>/<uuid>-<name>" in bucket lesson-media
  kind          text not null check (kind in ('image','video','audio','document','other')),
  mime_type     text not null,
  bytes         bigint not null check (bytes >= 0),
  title         text not null,
  alt_text      text,
  captions_path text,
  tags          text[] not null default '{}',
  created_at    timestamptz not null default now(),
  search        tsvector generated always as (live_app.media_search_doc(title, alt_text, tags)) stored,
  unique (id, tenant_id),
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id),
  foreign key (folder_id, tenant_id) references live.media_folders(id, tenant_id) on delete set null (folder_id),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete set null (lesson_id),
  check (storage_path like tenant_id::text || '/%')
);
create index if not exists lesson_media_search_idx on live.lesson_media using gin(search);
create index if not exists lesson_media_tenant_idx on live.lesson_media(tenant_id, created_at desc);

-- Secure share code/link with expiry (§3.1).
create table if not exists live.lesson_shares (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  lesson_id   uuid not null,
  class_id    uuid,
  code        text not null unique check (code ~ '^[A-Z0-9]{8}$'),
  mode        text not null default 'student_paced' check (mode in ('student_paced','front_of_class')),
  created_by  uuid not null,
  expires_at  timestamptz not null,
  revoked_at  timestamptz,
  created_at  timestamptz not null default now(),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete cascade,
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade
);

-- ---------------------------------------------------------------------------
-- Questions. Students never SELECT this table (answer keys live here);
-- they receive sanitised copies through RPCs in 0600.
-- ---------------------------------------------------------------------------
create table if not exists live.questions (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  activity_id  uuid,                 -- null = question-bank only
  owner_id     uuid not null,
  kind         text not null check (kind in (
                 'mcq','multi_select','true_false','poll','open','short','fill_blank',
                 'matching','ordering','categorize','draw','file','code')),
  prompt       text not null check (length(btrim(prompt)) between 1 and 4000),
  media        jsonb not null default '{}'::jsonb,
  -- Public, non-secret structure: blanks, left/right items, categories, items to
  -- order, language/starter code, visible test descriptions.
  config       jsonb not null default '{}'::jsonb,
  -- Secret: accepted answers, pairs, correct order, category map, hidden tests.
  answer_key   jsonb not null default '{}'::jsonb,
  explanation  text,
  points       numeric(8,2) not null default 1 check (points >= 0),
  position     int not null default 0,
  in_bank      boolean not null default false,
  tags         text[] not null default '{}',
  difficulty   smallint check (difficulty between 1 and 5),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (activity_id, tenant_id) references live.activities(id, tenant_id) on delete cascade,
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id)
);
create index if not exists questions_activity_idx on live.questions(activity_id, position);
create index if not exists questions_bank_idx on live.questions(tenant_id) where in_bank;drop trigger if exists questions_touch on live.questions;

create trigger questions_touch before update on live.questions
  for each row execute function live_app.touch_updated_at();

create table if not exists live.question_options (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  question_id  uuid not null,
  label        text not null check (length(label) between 1 and 1000),
  is_correct   boolean not null default false,
  feedback     text,
  position     int not null default 0,
  unique (id, tenant_id),
  foreign key (question_id, tenant_id) references live.questions(id, tenant_id) on delete cascade
);
create index if not exists question_options_question_idx on live.question_options(question_id, position);

-- ---------------------------------------------------------------------------
-- Assignments / rubrics / grading (§3.2, §23)
-- ---------------------------------------------------------------------------
create table if not exists live.rubrics (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  owner_id    uuid not null,
  title       text not null,
  -- [{ "id": "c1", "title": "Accuracy", "levels": [{ "label": "Strong", "points": 4 }] }]
  criteria    jsonb not null check (jsonb_typeof(criteria) = 'array'),
  created_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id)
);

create table if not exists live.assignments (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  class_id          uuid not null,
  activity_id       uuid,
  lesson_id         uuid,
  rubric_id         uuid,
  title             text not null check (length(btrim(title)) between 1 and 200),
  instructions      text,
  due_at            timestamptz,
  allow_late        boolean not null default true,
  max_resubmissions int not null default 0 check (max_resubmissions between 0 and 20),
  points_possible   numeric(8,2) not null default 100,
  status            text not null default 'published' check (status in ('draft','published','closed')),
  created_by        uuid not null,
  created_at        timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (activity_id, tenant_id) references live.activities(id, tenant_id) on delete set null (activity_id),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete set null (lesson_id),
  foreign key (rubric_id, tenant_id) references live.rubrics(id, tenant_id) on delete set null (rubric_id),
  foreign key (created_by, tenant_id) references live.users(id, tenant_id)
);
create index if not exists assignments_class_idx on live.assignments(class_id, due_at);

-- An attempt at any activity: in a live session, from an assignment, or student-paced.
create table if not exists live.quiz_attempts (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  activity_id   uuid not null,
  student_id    uuid not null,
  session_id    uuid,              -- FK added in 0300
  assignment_id uuid,
  attempt_no    int not null default 1 check (attempt_no >= 1),
  seed          int not null,      -- drives reproducible question/option shuffling
  status        text not null default 'in_progress' check (status in ('in_progress','submitted','graded')),
  started_at    timestamptz not null default now(),
  deadline_at   timestamptz,
  submitted_at  timestamptz,
  score         numeric(10,2),
  max_score     numeric(10,2),
  unique (id, tenant_id),
  foreign key (activity_id, tenant_id) references live.activities(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (assignment_id, tenant_id) references live.assignments(id, tenant_id) on delete cascade
);
create unique index if not exists quiz_attempts_unique_no
  on live.quiz_attempts(activity_id, student_id, coalesce(session_id, '00000000-0000-0000-0000-000000000000'::uuid),
                          coalesce(assignment_id, '00000000-0000-0000-0000-000000000000'::uuid), attempt_no);
create index if not exists quiz_attempts_student_idx on live.quiz_attempts(student_id, started_at desc);

create table if not exists live.quiz_answers (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  attempt_id    uuid not null,
  question_id   uuid not null,
  response      jsonb not null,
  is_correct    boolean,                 -- null for polls and manually graded work
  auto_score    numeric(8,2),
  manual_score  numeric(8,2),
  feedback      text,
  status        text not null check (status in ('auto_graded','ungraded','pending_review','reviewed')),
  elapsed_ms    int check (elapsed_ms >= 0),
  answered_at   timestamptz not null default now(),
  reviewed_by   uuid,
  reviewed_at   timestamptz,
  unique (attempt_id, question_id),
  foreign key (attempt_id, tenant_id) references live.quiz_attempts(id, tenant_id) on delete cascade,
  foreign key (question_id, tenant_id) references live.questions(id, tenant_id) on delete cascade
);
create index if not exists quiz_answers_question_idx on live.quiz_answers(question_id);
create index if not exists quiz_answers_review_idx on live.quiz_answers(tenant_id) where status = 'pending_review';

create table if not exists live.submissions (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  assignment_id uuid not null,
  student_id    uuid not null,
  attempt_no    int not null default 1,
  body          text,
  files         jsonb not null default '[]'::jsonb,   -- [{ path, name, bytes }] in bucket "submissions"
  attempt_id    uuid,
  status        text not null default 'submitted' check (status in ('submitted','returned','graded')),
  is_late       boolean not null default false,
  submitted_at  timestamptz not null default now(),
  unique (id, tenant_id),
  unique (assignment_id, student_id, attempt_no),
  foreign key (assignment_id, tenant_id) references live.assignments(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (attempt_id, tenant_id) references live.quiz_attempts(id, tenant_id) on delete set null (attempt_id)
);

create table if not exists live.grades (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null,
  submission_id  uuid not null unique,
  grader_id      uuid not null,
  score          numeric(8,2) not null check (score >= 0),
  rubric_scores  jsonb not null default '{}'::jsonb,
  feedback       text,
  released_at    timestamptz,
  graded_at      timestamptz not null default now(),
  foreign key (submission_id, tenant_id) references live.submissions(id, tenant_id) on delete cascade,
  foreign key (grader_id, tenant_id) references live.users(id, tenant_id)
);

-- Interactive video (§3.1): questions pinned to timestamps of a video slide.
create table if not exists live.video_checkpoints (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  slide_id    uuid not null,
  question_id uuid not null,
  t_seconds   numeric(9,2) not null check (t_seconds >= 0),
  required    boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (slide_id, t_seconds),
  foreign key (slide_id, tenant_id) references live.lesson_slides(id, tenant_id) on delete cascade,
  foreign key (question_id, tenant_id) references live.questions(id, tenant_id) on delete cascade
);

-- Collaborative board (§3.2).
create table if not exists live.collab_boards (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  activity_id uuid,
  session_id  uuid,                 -- FK added in 0300
  owner_id    uuid not null,
  title       text not null,
  locked      boolean not null default false,
  anonymous   boolean not null default false,
  created_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (activity_id, tenant_id) references live.activities(id, tenant_id) on delete cascade,
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id)
);

create table if not exists live.collab_posts (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  board_id    uuid not null,
  author_id   uuid not null,
  body        text not null check (length(body) between 1 and 2000),
  color       text not null default 'yellow' check (color in ('yellow','blue','green','pink','purple')),
  x           int not null default 0,
  y           int not null default 0,
  hidden      boolean not null default false,
  created_at  timestamptz not null default now(),
  foreign key (board_id, tenant_id) references live.collab_boards(id, tenant_id) on delete cascade,
  foreign key (author_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create index if not exists collab_posts_board_idx on live.collab_posts(board_id, created_at);

-- ===================== 20260901000300_classroom_games.sql =====================
-- =============================================================================
-- SwiftCipher — 0300 live classroom (§3.4, §3.7) + game engine (§3.3, §13)
-- =============================================================================

create table if not exists live.class_sessions (
  id                   uuid primary key default gen_random_uuid(),
  tenant_id            uuid not null,
  class_id             uuid not null,
  teacher_id           uuid not null,
  lesson_id            uuid,
  lesson_version       int,
  title                text not null,
  mode                 text not null default 'live_participation'
                         check (mode in ('live_participation','student_paced','front_of_class')),
  join_code            text not null unique check (join_code ~ '^[A-Z0-9]{6}$'),
  status               text not null default 'live' check (status in ('scheduled','live','ended')),
  current_slide        int  not null default 0 check (current_slide >= 0),
  active_activity_id   uuid,
  environment_id       uuid,        -- FK added in 0400
  environment_active   boolean not null default false,
  group_chat_enabled   boolean not null default false,
  responses_visible    boolean not null default false,  -- show anonymised live results to students
  scheduled_for        timestamptz,
  started_at           timestamptz,
  ended_at             timestamptz,
  created_at           timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (teacher_id, tenant_id) references live.users(id, tenant_id),
  foreign key (lesson_id, tenant_id) references live.lessons(id, tenant_id) on delete set null (lesson_id),
  foreign key (active_activity_id, tenant_id) references live.activities(id, tenant_id) on delete set null (active_activity_id)
);
create index if not exists class_sessions_class_idx on live.class_sessions(class_id, created_at desc);
create unique index if not exists class_sessions_one_live_per_class on live.class_sessions(class_id) where status = 'live';

alter table live.quiz_attempts
  add foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete set null (session_id);
alter table live.collab_boards
  add foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade;

-- Web-app presence (§3.4 roster presence + lesson progress per student).
create table if not exists live.session_participants (
  session_id     uuid not null,
  user_id        uuid not null,
  tenant_id      uuid not null,
  current_slide  int  not null default 0,
  status         text not null default 'online' check (status in ('connecting','online','idle','offline')),
  joined_at      timestamptz not null default now(),
  last_seen_at   timestamptz not null default now(),
  left_at        timestamptz,
  primary key (session_id, user_id),
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

-- Blueprint §7 "student_presence": derived, always consistent with the heartbeat clock.
create or replace view live.student_presence with (security_invoker = true) as
  select sp.session_id, sp.user_id as student_id, sp.tenant_id, sp.current_slide,
         case
           when sp.left_at is not null then 'offline'
           when sp.last_seen_at < now() - interval '45 seconds' then 'offline'
           when sp.status = 'idle' then 'idle'
           else sp.status
         end as presence,
         sp.last_seen_at
  from live.session_participants sp;

create table if not exists live.announcements (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  class_id    uuid not null,
  session_id  uuid,
  author_id   uuid not null,
  body        text not null check (length(btrim(body)) between 1 and 2000),
  created_at  timestamptz not null default now(),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (author_id, tenant_id) references live.users(id, tenant_id)
);
create index if not exists announcements_class_idx on live.announcements(class_id, created_at desc);

-- Private 1:1 threads and (policy-permitting) a class group thread.
create table if not exists live.chat_threads (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  class_id    uuid not null,
  kind        text not null check (kind in ('direct','group')),
  student_id  uuid,
  teacher_id  uuid,
  session_id  uuid,
  created_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (teacher_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  check ((kind = 'direct' and student_id is not null and teacher_id is not null)
      or (kind = 'group' and session_id is not null))
);
create unique index if not exists chat_threads_direct_uidx on live.chat_threads(class_id, student_id, teacher_id) where kind = 'direct';
create unique index if not exists chat_threads_group_uidx on live.chat_threads(session_id) where kind = 'group';

create table if not exists live.chat_messages (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  thread_id   uuid not null,
  sender_id   uuid not null,
  body        text not null check (length(btrim(body)) between 1 and 2000),
  hidden      boolean not null default false,
  created_at  timestamptz not null default now(),
  foreign key (thread_id, tenant_id) references live.chat_threads(id, tenant_id) on delete cascade,
  foreign key (sender_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create index if not exists chat_messages_thread_idx on live.chat_messages(thread_id, created_at);

create table if not exists live.raise_hands (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  session_id  uuid not null,
  student_id  uuid not null,
  message     text not null default '' check (length(message) <= 500),
  status      text not null default 'open' check (status in ('open','resolved')),
  resolved_by uuid,
  created_at  timestamptz not null default now(),
  resolved_at timestamptz,
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create unique index if not exists raise_hands_one_open on live.raise_hands(session_id, student_id) where status = 'open';

-- §3.7 spotlight: one student's screen shown to the class/projector.
create table if not exists live.spotlights (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null,
  session_id     uuid not null,
  student_id     uuid not null,
  anonymized     boolean not null default false,
  show_to_class  boolean not null default false,
  started_by     uuid not null,
  started_at     timestamptz not null default now(),
  ended_at       timestamptz,
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create unique index if not exists spotlights_one_active on live.spotlights(session_id) where ended_at is null;

create table if not exists live.attendance (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  class_id    uuid not null,
  session_id  uuid,
  student_id  uuid not null,
  date        date not null,
  status      text not null check (status in ('present','absent','late','excused')),
  source      text not null default 'manual' check (source in ('manual','session')),
  recorded_by uuid,
  created_at  timestamptz not null default now(),
  unique (class_id, student_id, date),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete set null (session_id),
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

-- WebRTC signalling for teacher screen share / optional A/V (§3.4, §15).
create table if not exists live.rtc_rooms (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  session_id  uuid not null,
  host_id     uuid not null,
  purpose     text not null default 'av' check (purpose in ('av','screen_share','spotlight')),
  status      text not null default 'open' check (status in ('open','closed')),
  created_at  timestamptz not null default now(),
  closed_at   timestamptz,
  unique (id, tenant_id),
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (host_id, tenant_id) references live.users(id, tenant_id)
);

create table if not exists live.rtc_peers (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  room_id     uuid not null,
  user_id     uuid not null,
  role        text not null check (role in ('host','participant')),
  joined_at   timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  left_at     timestamptz,
  unique (id, tenant_id),
  unique (room_id, user_id),
  foreign key (room_id, tenant_id) references live.rtc_rooms(id, tenant_id) on delete cascade,
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

create table if not exists live.rtc_signals (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null,
  room_id      uuid not null,
  from_peer_id uuid not null,
  to_peer_id   uuid not null,
  kind         text not null check (kind in ('offer','answer','ice','bye')),
  payload      jsonb not null,
  created_at   timestamptz not null default now(),
  foreign key (room_id, tenant_id) references live.rtc_rooms(id, tenant_id) on delete cascade,
  foreign key (from_peer_id, tenant_id) references live.rtc_peers(id, tenant_id) on delete cascade,
  foreign key (to_peer_id, tenant_id) references live.rtc_peers(id, tenant_id) on delete cascade
);
create index if not exists rtc_signals_to_idx on live.rtc_signals(to_peer_id, id);

-- ---------------------------------------------------------------------------
-- Game engine (§3.3, §13)
-- ---------------------------------------------------------------------------
create table if not exists live.game_sessions (
  id                   uuid primary key default gen_random_uuid(),
  tenant_id            uuid not null,
  class_id             uuid not null,
  host_id              uuid not null,
  activity_id          uuid not null,
  session_id           uuid,           -- optional: launched from a live lesson
  title                text not null,
  join_code            text not null unique check (join_code ~ '^[A-Z0-9]{6}$'),
  status               text not null default 'lobby' check (status in ('lobby','question','review','ended')),
  -- speed_bonus bool, streak_bonus bool, question_seconds int, rank_visibility
  -- ('after_each'|'end_only'|'hidden'), display_mode ('first_name_initial'|'nickname'|'anonymous'),
  -- team_mode bool, team_count int, shuffle_questions bool, shuffle_options bool, podium_size int
  settings             jsonb not null default '{}'::jsonb,
  question_order       uuid[] not null default '{}',
  current_index        int not null default -1,
  question_started_at  timestamptz,
  question_ends_at     timestamptz,
  created_at           timestamptz not null default now(),
  started_at           timestamptz,
  ended_at             timestamptz,
  unique (id, tenant_id),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (host_id, tenant_id) references live.users(id, tenant_id),
  foreign key (activity_id, tenant_id) references live.activities(id, tenant_id) on delete cascade,
  foreign key (session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete set null (session_id)
);

create table if not exists live.game_teams (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  game_id     uuid not null,
  name        text not null,
  color       text not null,
  unique (id, tenant_id),
  foreign key (game_id, tenant_id) references live.game_sessions(id, tenant_id) on delete cascade
);

create table if not exists live.game_players (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  game_id       uuid not null,
  user_id       uuid not null,
  display_name  text not null,
  team_id       uuid,
  score         int not null default 0,
  correct_count int not null default 0,
  streak        int not null default 0,
  best_streak   int not null default 0,
  badges        text[] not null default '{}',
  joined_at     timestamptz not null default now(),
  unique (id, tenant_id),
  unique (game_id, user_id),
  foreign key (game_id, tenant_id) references live.game_sessions(id, tenant_id) on delete cascade,
  foreign key (user_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (team_id, tenant_id) references live.game_teams(id, tenant_id) on delete set null (team_id)
);

create table if not exists live.game_answers (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  game_id           uuid not null,
  player_id         uuid not null,
  question_id       uuid not null,
  question_index    int  not null,
  choice            jsonb not null,
  is_correct        boolean not null,
  base_points       int not null default 0,
  speed_bonus       int not null default 0,
  streak_bonus      int not null default 0,
  server_elapsed_ms int not null,
  scored_elapsed_ms int not null,
  answered_at       timestamptz not null default now(),
  unique (player_id, question_index),        -- answer-window lock: one answer per question
  foreign key (game_id, tenant_id) references live.game_sessions(id, tenant_id) on delete cascade,
  foreign key (player_id, tenant_id) references live.game_players(id, tenant_id) on delete cascade,
  foreign key (question_id, tenant_id) references live.questions(id, tenant_id) on delete cascade
);
create index if not exists game_answers_game_q_idx on live.game_answers(game_id, question_index);

-- Leaderboard snapshot after each question (history analytics, §18).
create table if not exists live.leaderboard_entries (
  id              bigint generated always as identity primary key,
  tenant_id       uuid not null,
  game_id         uuid not null,
  player_id       uuid not null,
  question_index  int not null,
  rank            int not null,
  score           int not null,
  recorded_at     timestamptz not null default now(),
  unique (game_id, question_index, player_id),
  foreign key (game_id, tenant_id) references live.game_sessions(id, tenant_id) on delete cascade,
  foreign key (player_id, tenant_id) references live.game_players(id, tenant_id) on delete cascade
);

-- Suspicious-pattern log (§3.3 anti-cheat). Informational only.
create table if not exists live.game_flags (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null,
  game_id     uuid not null,
  player_id   uuid not null,
  kind        text not null,
  detail      jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  foreign key (game_id, tenant_id) references live.game_sessions(id, tenant_id) on delete cascade,
  foreign key (player_id, tenant_id) references live.game_players(id, tenant_id) on delete cascade
);

-- ===================== 20260901000400_guard.sql =====================
-- =============================================================================
-- SwiftCipher — 0400 classroom control engine
-- Devices (§3.5, §21), environments (§3.6, §14), off-task (§3.8),
-- screen monitoring (§15), teacher commands, scenes.
--
-- Privacy boundary (§36): device telemetry is only accepted while the device's
-- student is in a LIVE class session. Outside a session the agent receives
-- "idle" directives and nothing is stored.
-- =============================================================================

create table if not exists live.environment_policies (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null,
  owner_id           uuid not null,
  name               text not null check (length(btrim(name)) between 1 and 120),
  description        text,
  allowed_domains    text[] not null default '{}',
  blocked_domains    text[] not null default '{}',
  blocked_categories text[] not null default '{}',
  required_urls      text[] not null default '{}',
  lesson_url         text,
  focus_mode         boolean not null default false,  -- anything outside allow/required is a violation
  lock_screen        boolean not null default false,
  tab_limit          int check (tab_limit is null or tab_limit between 1 and 50),
  grace_seconds      int not null default 15 check (grace_seconds between 0 and 600),
  idle_seconds       int not null default 300 check (idle_seconds between 30 and 7200),
  subject            text,                            -- off-task context (§3.8)
  notify             jsonb not null default '{"banner":true,"sound":false,"browser":false,"email":false}'::jsonb,
  is_template        boolean not null default false,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id)
);drop trigger if exists environment_policies_touch on live.environment_policies;

create trigger environment_policies_touch before update on live.environment_policies
  for each row execute function live_app.touch_updated_at();

alter table live.class_sessions
  add foreign key (environment_id, tenant_id) references live.environment_policies(id, tenant_id) on delete set null (environment_id);
alter table live.student_groups
  add foreign key (auto_start_policy_id, tenant_id) references live.environment_policies(id, tenant_id) on delete set null (auto_start_policy_id);

-- Scenes = named, reusable bundles of rules (§3.5, §19 templates).
create table if not exists live.scenes (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  owner_id    uuid not null,
  name        text not null,
  description text,
  policy_id   uuid not null,
  created_at  timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (owner_id, tenant_id) references live.users(id, tenant_id),
  foreign key (policy_id, tenant_id) references live.environment_policies(id, tenant_id) on delete cascade
);

create table if not exists live.scene_rules (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  scene_id    uuid not null,
  -- extra actions executed when a scene is applied to a running session
  rule_type   text not null check (rule_type in ('open_tab','focus','lock','close_other_tabs','message')),
  value       text,
  position    int not null default 0,
  foreign key (scene_id, tenant_id) references live.scenes(id, tenant_id) on delete cascade
);

-- Global domain → category map used by rule-based off-task detection.
create table if not exists live.domain_categories (
  domain    text primary key check (domain ~ '^[a-z0-9.-]+$'),
  category  text not null check (category in ('games','social','video','streaming','shopping','chat','adult','gambling','education','reference','productivity'))
);

