on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Devices (§3.5, §21)
-- ---------------------------------------------------------------------------
create table if not exists live.devices (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null,
  student_id     uuid,                  -- school-authorised mapping (§8)
  label          text not null check (length(btrim(label)) between 1 and 120),
  os             text,
  browser        text,
  agent_version  text,
  secret_hash    text not null,         -- sha256(secret); secret only ever shown to the agent once
  status         text not null default 'active' check (status in ('active','disabled','unenrolled')),
  enrolled_by    uuid,
  enrolled_at    timestamptz not null default now(),
  last_seen_at   timestamptz,
  unique (id, tenant_id),
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete set null (student_id)
);
create index if not exists devices_tenant_idx on live.devices(tenant_id, status);
create index if not exists devices_student_idx on live.devices(student_id) where status = 'active';

create table if not exists live.device_enrollments (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  device_id    uuid not null,
  student_id   uuid,
  enrolled_by  uuid,
  method       text not null check (method in ('student_pairing','admin_pairing')),
  created_at   timestamptz not null default now(),
  revoked_at   timestamptz,
  revoked_by   uuid,
  foreign key (device_id, tenant_id) references live.devices(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete set null (student_id)
);

-- One-time pairing codes: a signed-in student (or IT admin on their behalf)
-- creates one; the extension exchanges it for device credentials.
create table if not exists live.device_pairing_codes (
  code        text primary key check (code ~ '^[A-Z0-9]{8}$'),
  tenant_id   uuid not null,
  student_id  uuid not null,
  created_by  uuid not null,
  method      text not null check (method in ('student_pairing','admin_pairing')),
  expires_at  timestamptz not null,
  used_at     timestamptz,
  device_id   uuid,
  created_at  timestamptz not null default now(),
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);

-- Live per-device state inside one class session (blueprint "browser_sessions").
create table if not exists live.browser_sessions (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null,
  device_id           uuid not null,
  class_session_id    uuid not null,
  student_id          uuid not null,
  started_at          timestamptz not null default now(),
  last_heartbeat_at   timestamptz not null default now(),
  ended_at            timestamptz,
  active_url          text,
  active_domain       text,
  active_title        text,
  tab_count           int,
  idle_state          text not null default 'active' check (idle_state in ('active','idle','locked')),
  idle_since          timestamptz,
  -- Grace-period tracking (§3.6): a violation must persist before it fires.
  violation_kind      text,
  violation_rule      text,
  violation_url       text,
  violation_since     timestamptz,
  snapshot_requested_at timestamptz,
  focus_locked        boolean not null default false,
  connection_lost_at  timestamptz,
  unique (id, tenant_id),
  unique (device_id, class_session_id),
  foreign key (device_id, tenant_id) references live.devices(id, tenant_id) on delete cascade,
  foreign key (class_session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create index if not exists browser_sessions_session_idx on live.browser_sessions(class_session_id);

-- Telemetry log (retention-limited, §18/§20).
create table if not exists live.browser_events (
  id                 bigint generated always as identity primary key,
  tenant_id          uuid not null,
  device_id          uuid not null,
  class_session_id   uuid not null,
  student_id         uuid not null,
  kind               text not null check (kind in ('tab_changed','navigation','idle','active','locked','tab_count')),
  url                text,
  domain             text,
  title              text,
  created_at         timestamptz not null default now(),
  foreign key (device_id, tenant_id) references live.devices(id, tenant_id) on delete cascade,
  foreign key (class_session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade
);
create index if not exists browser_events_session_idx on live.browser_events(class_session_id, created_at desc);
create index if not exists browser_events_tenant_time_idx on live.browser_events(tenant_id, created_at);

-- Only the LATEST thumbnail per device+session is kept, unless the school has
-- enabled event screenshots (§15: never store continuous recordings).
create table if not exists live.screen_snapshots (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  device_id         uuid not null,
  class_session_id  uuid not null,
  student_id        uuid not null,
  image_data        text not null check (image_data like 'data:image/%' and length(image_data) <= 400000),
  width             int,
  height            int,
  quality           text not null default 'thumbnail' check (quality in ('thumbnail','spotlight','event')),
  url               text,
  captured_at       timestamptz not null default now(),
  foreign key (device_id, tenant_id) references live.devices(id, tenant_id) on delete cascade,
  foreign key (class_session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade
);
create unique index if not exists screen_snapshots_latest_uidx
  on live.screen_snapshots(device_id, class_session_id, quality) where quality <> 'event';
create index if not exists screen_snapshots_session_idx on live.screen_snapshots(class_session_id, captured_at desc);

create table if not exists live.environment_events (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  class_session_id  uuid not null,
  class_id          uuid not null,
  student_id        uuid not null,
  device_id         uuid,
  policy_id         uuid,
  kind              text not null check (kind in (
                      'environment_left','domain_blocked','off_task','idle','connection_lost','tab_limit')),
  severity          text not null check (severity in ('info','warning','critical')),
  rule              text not null,          -- human-readable rule that fired
  url               text,
  domain            text,
  confidence        numeric(4,3) check (confidence is null or confidence between 0 and 1),
  status            text not null default 'open'
                      check (status in ('open','acknowledged','dismissed','confirmed','resolved')),
  handled_by        uuid,
  handled_at        timestamptz,
  resolved_at       timestamptz,
  created_at        timestamptz not null default now(),
  unique (id, tenant_id),
  foreign key (class_session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (device_id, tenant_id) references live.devices(id, tenant_id) on delete set null (device_id),
  foreign key (policy_id, tenant_id) references live.environment_policies(id, tenant_id) on delete set null (policy_id)
);
-- Deduplication (§3.6): at most one unresolved event per student+kind per session.
create unique index if not exists environment_events_dedup
  on live.environment_events(class_session_id, student_id, kind) where resolved_at is null;
create index if not exists environment_events_session_idx on live.environment_events(class_session_id, created_at desc);
create index if not exists environment_events_tenant_time_idx on live.environment_events(tenant_id, created_at);

-- Teacher feedback loop for off-task alerts (§3.8).
create table if not exists live.off_task_feedback (
  tenant_id     uuid not null references live.tenants(id) on delete cascade,
  domain        text not null,
  dismissals    int not null default 0,
  confirmations int not null default 0,
  updated_at    timestamptz not null default now(),
  primary key (tenant_id, domain)
);

create table if not exists live.off_task_mutes (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  class_session_id  uuid not null,
  student_id        uuid,            -- null = everyone in the session
  domain            text not null,
  muted_by          uuid not null,
  created_at        timestamptz not null default now(),
  foreign key (class_session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade
);

create table if not exists live.teacher_commands (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  class_session_id  uuid not null,
  student_id        uuid not null,
  device_id         uuid not null,
  issued_by         uuid not null,
  kind              text not null check (kind in (
                      'open_tab','close_tab','redirect','focus','unfocus','lock','unlock',
                      'close_other_tabs','message','screenshot')),
  payload           jsonb not null default '{}'::jsonb,
  status            text not null default 'queued' check (status in ('queued','delivered','acked','failed','expired')),
  error             text,
  created_at        timestamptz not null default now(),
  delivered_at      timestamptz,
  acked_at          timestamptz,
  expires_at        timestamptz not null default now() + interval '2 minutes',
  foreign key (class_session_id, tenant_id) references live.class_sessions(id, tenant_id) on delete cascade,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (device_id, tenant_id) references live.devices(id, tenant_id) on delete cascade,
  foreign key (issued_by, tenant_id) references live.users(id, tenant_id)
);
create index if not exists teacher_commands_device_queue_idx on live.teacher_commands(device_id, created_at) where status = 'queued';
create index if not exists teacher_commands_session_idx on live.teacher_commands(class_session_id, created_at desc);

-- ===================== 20260901000500_rls.sql =====================
-- =============================================================================
-- SwiftCipher — 0500 row-level security
--
-- Rules of thumb:
--   * anon can read nothing but public catalogues; every anon action is an RPC.
--   * Writes that need invariants (codes, limits, grading, audit) are RPC-only:
--     those tables simply have no INSERT/UPDATE policy for clients.
--   * Helper calls are wrapped in (select ...) so Postgres evaluates them once
--     per statement instead of once per row.
-- =============================================================================

-- ---------- Extra helpers that depend on learning/classroom tables ----------
create or replace function live_app.can_edit_lesson(p_lesson uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.lessons l
                 where l.id = p_lesson and l.tenant_id = live_app.tenant_id()
                   and (l.owner_id = auth.uid() or live_app.is_admin()))
$$;

create or replace function live_app.can_view_lesson(p_lesson uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.lessons l
                 where l.id = p_lesson and l.tenant_id = live_app.tenant_id()
                   and (l.owner_id = auth.uid() or live_app.is_admin()
                        or (live_app.is_teacher() and (l.status = 'published' or l.is_template))))
$$;

create or replace function live_app.can_edit_activity(p_activity uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.activities a
                 where a.id = p_activity and a.tenant_id = live_app.tenant_id()
                   and (a.owner_id = auth.uid() or live_app.is_admin()
                        or (a.lesson_id is not null and live_app.can_edit_lesson(a.lesson_id))))
$$;

create or replace function live_app.can_view_activity(p_activity uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.activities a
                 where a.id = p_activity and a.tenant_id = live_app.tenant_id()
                   and (a.owner_id = auth.uid() or live_app.is_admin()
                        or (a.lesson_id is not null and live_app.can_view_lesson(a.lesson_id))
                        or (a.lesson_id is null and live_app.is_teacher())))
$$;

create or replace function live_app.session_class(p_session uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select s.class_id from live.class_sessions s where s.id = p_session
$$;

create or replace function live_app.can_manage_session(p_session uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.can_manage_class(live_app.session_class(p_session))
$$;

create or replace function live_app.in_session(p_session uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.in_class(live_app.session_class(p_session))
$$;

-- ---------- Baseline privileges ----------
-- Supabase grants ALL on public tables to anon/authenticated by default; pull
-- anon back to nothing and give authenticated only what policies can gate.
revoke all on all tables in schema live from anon;
revoke all on all sequences in schema live from anon;
revoke insert, update, delete, truncate, references, trigger on all tables in schema live from authenticated;
grant select on live.roles, live.plans to anon;

-- Enable RLS everywhere.
do $$
declare r record;
begin
  for r in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'live' and c.relkind = 'r'
  loop
    execute format('alter table live.%I enable row level security', r.relname);
  end loop;
end$$;drop policy if exists roles_read on live.roles;


-- ---------- Catalogues ----------
create policy roles_read on live.roles for select using (true);drop policy if exists plans_read on live.plans;

create policy plans_read on live.plans for select using (true);drop policy if exists domain_categories_read on live.domain_categories;

create policy domain_categories_read on live.domain_categories for select to authenticated using (true);drop policy if exists tenants_read on live.tenants;


-- ---------- Tenancy ----------
create policy tenants_read on live.tenants for select to authenticated
  using (id = (select live_app.tenant_id()));
grant update (name, country, timezone) on live.tenants to authenticated;drop policy if exists tenants_admin_update on live.tenants;

create policy tenants_admin_update on live.tenants for update to authenticated
  using (id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (id = (select live_app.tenant_id()));drop policy if exists tenant_settings_read on live.tenant_settings;


create policy tenant_settings_read on live.tenant_settings for select to authenticated
  using (tenant_id = (select live_app.tenant_id()));
grant update (allow_spotlight, allow_group_chat, allow_screen_capture, store_event_screenshots,
              parent_portal_enabled, email_alerts_enabled, nickname_mode, learning_retention_days,
              telemetry_retention_days, default_grace_seconds, default_idle_seconds,
              thumbnail_interval_seconds, monitoring_notice, support_access_until)
  on live.tenant_settings to authenticated;drop policy if exists tenant_settings_admin_update on live.tenant_settings;

create policy tenant_settings_admin_update on live.tenant_settings for update to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (tenant_id = (select live_app.tenant_id()));drop policy if exists schools_read on live.schools;


create policy schools_read on live.schools for select to authenticated
  using (tenant_id = (select live_app.tenant_id()));
grant insert, update, delete on live.schools, live.departments to authenticated;drop policy if exists schools_admin_write on live.schools;

create policy schools_admin_write on live.schools for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists departments_read on live.departments;

create policy departments_read on live.departments for select to authenticated
  using (tenant_id = (select live_app.tenant_id()));drop policy if exists departments_admin_write on live.departments;

create policy departments_admin_write on live.departments for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists users_read on live.users;


-- Users: staff see the tenant directory; students/parents see themselves,
-- staff (to message teachers) and — for parents — their linked students.
create policy users_read on live.users for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and ((select live_app.is_staff())
              or id = (select auth.uid())
              or role in ('teacher','school_admin')
              or live_app.is_parent_of(id)));
grant update (full_name, nickname, last_seen_at) on live.users to authenticated;drop policy if exists users_self_update on live.users;

create policy users_self_update on live.users for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));drop policy if exists student_profiles_read on live.student_profiles;


create policy student_profiles_read on live.student_profiles for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (user_id = (select auth.uid()) or (select live_app.is_staff()) or live_app.is_parent_of(user_id)));
grant insert, update on live.student_profiles, live.teacher_profiles to authenticated;drop policy if exists student_profiles_staff_write on live.student_profiles;

create policy student_profiles_staff_write on live.student_profiles for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and ((select live_app.is_admin()) or live_app.teaches_student(user_id)))
  with check (tenant_id = (select live_app.tenant_id()) and ((select live_app.is_admin()) or live_app.teaches_student(user_id)));drop policy if exists teacher_profiles_read on live.teacher_profiles;

create policy teacher_profiles_read on live.teacher_profiles for select to authenticated
  using (tenant_id = (select live_app.tenant_id()));drop policy if exists teacher_profiles_write on live.teacher_profiles;

create policy teacher_profiles_write on live.teacher_profiles for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (user_id = (select auth.uid()) or (select live_app.is_admin())))
  with check (tenant_id = (select live_app.tenant_id()) and (user_id = (select auth.uid()) or (select live_app.is_admin())));drop policy if exists classes_read on live.classes;


-- ---------- Classes ----------
create policy classes_read on live.classes for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and ((select live_app.is_admin()) or (select live_app.is_it())
              or teacher_id = (select auth.uid()) or live_app.in_class(id)));
grant update (name, subject, grade_level, archived_at, school_id, department_id) on live.classes to authenticated;drop policy if exists classes_manage_update on live.classes;

create policy classes_manage_update on live.classes for update to authenticated
  using (live_app.can_manage_class(id)) with check (tenant_id = (select live_app.tenant_id()));drop policy if exists class_members_read on live.class_members;


create policy class_members_read on live.class_members for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (user_id = (select auth.uid()) or live_app.can_manage_class(class_id) or (select live_app.is_it())
              or (role = 'teacher' and live_app.in_class(class_id))));
grant insert, delete on live.class_members to authenticated;drop policy if exists class_members_manage_insert on live.class_members;

create policy class_members_manage_insert on live.class_members for insert to authenticated
  with check (tenant_id = (select live_app.tenant_id()) and live_app.can_manage_class(class_id)
              and (role = 'student' or (select live_app.is_admin())
                   or exists (select 1 from live.classes c where c.id = class_id and c.teacher_id = (select auth.uid()))));drop policy if exists class_members_manage_delete on live.class_members;

create policy class_members_manage_delete on live.class_members for delete to authenticated
  using (live_app.can_manage_class(class_id));drop policy if exists student_groups_read on live.student_groups;


create policy student_groups_read on live.student_groups for select to authenticated
  using (live_app.can_manage_class(class_id) or (tenant_id = (select live_app.tenant_id()) and (select live_app.is_it())));
grant insert, update, delete on live.student_groups, live.student_group_members to authenticated;drop policy if exists student_groups_write on live.student_groups;

create policy student_groups_write on live.student_groups for all to authenticated
  using (live_app.can_manage_class(class_id))
  with check (tenant_id = (select live_app.tenant_id()) and live_app.can_manage_class(class_id));drop policy if exists student_group_members_read on live.student_group_members;

create policy student_group_members_read on live.student_group_members for select to authenticated
  using (exists (select 1 from live.student_groups g where g.id = group_id));drop policy if exists student_group_members_write on live.student_group_members;

create policy student_group_members_write on live.student_group_members for all to authenticated
  using (exists (select 1 from live.student_groups g where g.id = group_id and live_app.can_manage_class(g.class_id)))
  with check (tenant_id = (select live_app.tenant_id())
              and exists (select 1 from live.student_groups g where g.id = group_id and live_app.can_manage_class(g.class_id))
              and exists (select 1 from live.class_members m join live.student_groups g on g.class_id = m.class_id
                          where g.id = group_id and m.user_id = student_group_members.user_id));drop policy if exists invites_read on live.invites;


create policy invites_read on live.invites for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (created_by = (select auth.uid()) or (select live_app.is_admin())));
grant update (revoked_at) on live.invites to authenticated;drop policy if exists invites_revoke on live.invites;

create policy invites_revoke on live.invites for update to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (created_by = (select auth.uid()) or (select live_app.is_admin())));drop policy if exists parent_links_read on live.parent_links;


create policy parent_links_read on live.parent_links for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (parent_id = (select auth.uid()) or student_id = (select auth.uid())
              or (select live_app.is_admin()) or live_app.teaches_student(student_id)));
grant update (revoked_at) on live.parent_links to authenticated;drop policy if exists parent_links_admin_revoke on live.parent_links;

create policy parent_links_admin_revoke on live.parent_links for update to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists subscriptions_admin_read on live.subscriptions;


-- ---------- Billing / flags / audit / notifications / consents ----------
create policy subscriptions_admin_read on live.subscriptions for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists invoices_admin_read on live.invoices;

create policy invoices_admin_read on live.invoices for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists feature_flags_read on live.feature_flags;


create policy feature_flags_read on live.feature_flags for select to authenticated
  using (tenant_id is null or tenant_id = (select live_app.tenant_id()));
grant insert, update, delete on live.feature_flags to authenticated;drop policy if exists feature_flags_admin_write on live.feature_flags;

create policy feature_flags_admin_write on live.feature_flags for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists audit_logs_admin_read on live.audit_logs;


create policy audit_logs_admin_read on live.audit_logs for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));drop policy if exists notifications_own_read on live.notifications;


create policy notifications_own_read on live.notifications for select to authenticated
  using (user_id = (select auth.uid()));
grant update (read_at) on live.notifications to authenticated;
grant delete on live.notifications to authenticated;drop policy if exists notifications_own_update on live.notifications;

create policy notifications_own_update on live.notifications for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));drop policy if exists notifications_own_delete on live.notifications;

create policy notifications_own_delete on live.notifications for delete to authenticated
  using (user_id = (select auth.uid()));drop policy if exists consents_read on live.consents;


create policy consents_read on live.consents for select to authenticated
  using (user_id = (select auth.uid()) or (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin())));
grant insert on live.consents to authenticated;drop policy if exists consents_own_insert on live.consents;

create policy consents_own_insert on live.consents for insert to authenticated
  with check (user_id = (select auth.uid()) and tenant_id = (select live_app.tenant_id()));drop policy if exists lessons_read on live.lessons;


-- ---------- Studio ----------
-- Row-column checks (not live_app.can_view_lesson(id)) so INSERT ... RETURNING can
-- see the row it just wrote; helper lookups use the pre-statement snapshot.
create policy lessons_read on live.lessons for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (owner_id = (select auth.uid()) or (select live_app.is_admin())
              or ((select live_app.is_teacher()) and (status = 'published' or is_template))));
grant insert, update, delete on live.lessons to authenticated;drop policy if exists lessons_insert on live.lessons;

create policy lessons_insert on live.lessons for insert to authenticated
  with check (tenant_id = (select live_app.tenant_id()) and owner_id = (select auth.uid()) and (select live_app.is_teacher()));drop policy if exists lessons_update on live.lessons;

create policy lessons_update on live.lessons for update to authenticated
  using (live_app.can_edit_lesson(id)) with check (tenant_id = (select live_app.tenant_id()));drop policy if exists lessons_delete on live.lessons;

create policy lessons_delete on live.lessons for delete to authenticated
  using (live_app.can_edit_lesson(id));drop policy if exists lesson_versions_read on live.lesson_versions;


create policy lesson_versions_read on live.lesson_versions for select to authenticated
  using (live_app.can_view_lesson(lesson_id));drop policy if exists lesson_slides_read on live.lesson_slides;


create policy lesson_slides_read on live.lesson_slides for select to authenticated
  using (live_app.can_view_lesson(lesson_id));
grant insert, update, delete on live.lesson_slides to authenticated;drop policy if exists lesson_slides_write on live.lesson_slides;

create policy lesson_slides_write on live.lesson_slides for all to authenticated
  using (live_app.can_edit_lesson(lesson_id))
  with check (tenant_id = (select live_app.tenant_id()) and live_app.can_edit_lesson(lesson_id));drop policy if exists media_folders_read on live.media_folders;


create policy media_folders_read on live.media_folders for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_teacher()));
grant insert, update, delete on live.media_folders, live.lesson_media to authenticated;drop policy if exists media_folders_write on live.media_folders;

create policy media_folders_write on live.media_folders for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (owner_id = (select auth.uid()) or (select live_app.is_admin())))
  with check (tenant_id = (select live_app.tenant_id()) and owner_id = (select auth.uid()) and (select live_app.is_teacher()));drop policy if exists lesson_media_read on live.lesson_media;


create policy lesson_media_read on live.lesson_media for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_teacher()));drop policy if exists lesson_media_write on live.lesson_media;

create policy lesson_media_write on live.lesson_media for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (owner_id = (select auth.uid()) or (select live_app.is_admin())))
  with check (tenant_id = (select live_app.tenant_id()) and owner_id = (select auth.uid()) and (select live_app.is_teacher())
              and storage_path like (select live_app.tenant_id())::text || '/' || (select auth.uid())::text || '/%');drop policy if exists lesson_shares_read on live.lesson_shares;


create policy lesson_shares_read on live.lesson_shares for select to authenticated
  using (live_app.can_edit_lesson(lesson_id));
grant update (revoked_at) on live.lesson_shares to authenticated;drop policy if exists lesson_shares_revoke on live.lesson_shares;

create policy lesson_shares_revoke on live.lesson_shares for update to authenticated
  using (live_app.can_edit_lesson(lesson_id));drop policy if exists activities_read on live.activities;


create policy activities_read on live.activities for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (owner_id = (select auth.uid()) or (select live_app.is_admin())
              or (lesson_id is not null and live_app.can_view_lesson(lesson_id))
              or (lesson_id is null and (select live_app.is_teacher()))));
grant insert, update, delete on live.activities to authenticated;drop policy if exists activities_insert on live.activities;

create policy activities_insert on live.activities for insert to authenticated
  with check (tenant_id = (select live_app.tenant_id()) and owner_id = (select auth.uid()) and (select live_app.is_teacher())
              and (lesson_id is null or live_app.can_edit_lesson(lesson_id)));drop policy if exists activities_update on live.activities;

create policy activities_update on live.activities for update to authenticated
  using (live_app.can_edit_activity(id))
  with check (tenant_id = (select live_app.tenant_id()) and (lesson_id is null or live_app.can_edit_lesson(lesson_id)));drop policy if exists activities_delete on live.activities;

create policy activities_delete on live.activities for delete to authenticated
  using (live_app.can_edit_activity(id));drop policy if exists questions_read on live.questions;


-- Questions/options carry answer keys: staff only. Students use RPCs.
create policy questions_read on live.questions for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_teacher())
         and (owner_id = (select auth.uid()) or in_bank
              or (activity_id is not null and live_app.can_view_activity(activity_id))));
grant insert, update, delete on live.questions, live.question_options to authenticated;drop policy if exists questions_write on live.questions;

create policy questions_write on live.questions for all to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (owner_id = (select auth.uid()) or (activity_id is not null and live_app.can_edit_activity(activity_id))))
  with check (tenant_id = (select live_app.tenant_id()) and (select live_app.is_teacher())
              and (activity_id is null or live_app.can_edit_activity(activity_id)));drop policy if exists question_options_read on live.question_options;


create policy question_options_read on live.question_options for select to authenticated
  using (exists (select 1 from live.questions q where q.id = question_id));drop policy if exists question_options_write on live.question_options;

create policy question_options_write on live.question_options for all to authenticated
  using (exists (select 1 from live.questions q where q.id = question_id
                 and (q.owner_id = (select auth.uid()) or (q.activity_id is not null and live_app.can_edit_activity(q.activity_id)))))
  with check (tenant_id = (select live_app.tenant_id())
              and exists (select 1 from live.questions q where q.id = question_id
                          and (q.owner_id = (select auth.uid()) or (q.activity_id is not null and live_app.can_edit_activity(q.activity_id)))));drop policy if exists video_checkpoints_read on live.video_checkpoints;


create policy video_checkpoints_read on live.video_checkpoints for select to authenticated
  using (exists (select 1 from live.lesson_slides s where s.id = slide_id));
grant insert, update, delete on live.video_checkpoints to authenticated;drop policy if exists video_checkpoints_write on live.video_checkpoints;

create policy video_checkpoints_write on live.video_checkpoints for all to authenticated
  using (exists (select 1 from live.lesson_slides s where s.id = slide_id and live_app.can_edit_lesson(s.lesson_id)))
  with check (tenant_id = (select live_app.tenant_id())
              and exists (select 1 from live.lesson_slides s where s.id = slide_id and live_app.can_edit_lesson(s.lesson_id)));drop policy if exists rubrics_read on live.rubrics;


-- ---------- Assessment ----------
create policy rubrics_read on live.rubrics for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_teacher()));
grant insert, update, delete on live.rubrics to authenticated;drop policy if exists rubrics_write on live.rubrics;

create policy rubrics_write on live.rubrics for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (owner_id = (select auth.uid()) or (select live_app.is_admin())))
  with check (tenant_id = (select live_app.tenant_id()) and owner_id = (select auth.uid()) and (select live_app.is_teacher()));drop policy if exists assignments_read on live.assignments;


create policy assignments_read on live.assignments for select to authenticated
  using (live_app.can_manage_class(class_id) or (status <> 'draft' and live_app.in_class(class_id)));
grant insert, update, delete on live.assignments to authenticated;drop policy if exists assignments_write on live.assignments;

create policy assignments_write on live.assignments for all to authenticated
