revoke execute on function live.parent_report(uuid, text, date), live.parent_alerts(uuid),
  live.set_parent_alerts(uuid, boolean, boolean, int), live.open_parent_thread(uuid, uuid, uuid), live.class_parents(uuid),
  live_app.class_period(uuid, uuid, timestamptz, timestamptz, boolean), live_app.send_parent_digests()
  from public, anon;
grant execute on function live.parent_report(uuid, text, date), live.parent_alerts(uuid),
  live.set_parent_alerts(uuid, boolean, boolean, int), live.open_parent_thread(uuid, uuid, uuid), live.class_parents(uuid)
  to authenticated, service_role;
grant execute on function live_app.send_parent_digests() to service_role;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0820')
$$;

-- ===================== 20260901000830_pentest_fixes.sql =====================
-- =============================================================================
-- SwiftCipher — 0830 fixes from the 2026-09-27 penetration test
--
-- 1. Paid-feature bypass (confirmed live). A school's own feature flag took
--    precedence over its plan, and school admins can write flags for their
--    school, so an admin on a cheaper plan could switch on paid features
--    (e.g. device control). Now a school's own flag can only switch a feature
--    OFF; turning features on comes from the plan (or a platform-wide flag),
--    and the database refuses "enabled" flags for features the plan lacks.
-- 2. Error-log blinding. The anonymous error endpoint shared one hourly quota
--    with signed-in users, so junk reports could use it up and hide real errors
--    for an hour. Anonymous reports now get their own, smaller share.
-- =============================================================================

create or replace function live_app.plan_has(p_tenant uuid, p_key text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(
    (select (p.features ->> p_key)::boolean from live.tenants t join live.plans p on p.code = t.plan_code where t.id = p_tenant),
    (select ff.enabled from live.feature_flags ff where ff.tenant_id is null and ff.key = p_key),
    false)
$$;

create or replace function live_app.feature(p_tenant uuid, p_key text) returns boolean
language sql stable security definer set search_path = '' as $$
  -- The plan decides; the school may only switch a feature off for itself.
  select live_app.plan_has(p_tenant, p_key)
     and coalesce((select ff.enabled from live.feature_flags ff where ff.tenant_id = p_tenant and ff.key = p_key), true)
$$;

drop policy if exists feature_flags_admin_write on live.feature_flags;drop policy if exists feature_flags_admin_write on live.feature_flags;

create policy feature_flags_admin_write on live.feature_flags for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin())
              and (not enabled or live_app.plan_has(tenant_id, key)));

create or replace function live.log_error(
  p_source text, p_message text, p_stack text default null, p_url text default null,
  p_user_agent text default null, p_release text default null
) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v_fp text; v_tenant uuid; v_recent int; v_anon_recent int;
begin
  if p_source not in ('client','server','api') or coalesce(btrim(p_message), '') = '' then return; end if;
  -- Flood guard: at most 600 new rows an hour platform-wide (repeats only bump a counter),
  -- of which anonymous callers may use 150, so they can't crowd out real errors.
  select count(*), count(*) filter (where user_id is null) into v_recent, v_anon_recent
    from live.error_events where first_seen_at > now() - interval '1 hour';
  v_fp := md5(p_source || '|' || left(p_message, 300) || '|' || coalesce(left(split_part(coalesce(p_stack, ''), E'\n', 2), 300), ''));
  begin v_tenant := live_app.tenant_id(); exception when others then v_tenant := null; end;
  update live.error_events set count = count + 1, last_seen_at = now(),
         url = coalesce(left(p_url, 2000), url), tenant_id = coalesce(v_tenant, tenant_id)
   where fingerprint = v_fp and resolved_at is null;
  if found or v_recent >= 600 or (auth.uid() is null and v_anon_recent >= 150) then return; end if;
  insert into live.error_events (fingerprint, source, message, stack, url, user_agent, release, tenant_id, user_id)
    values (v_fp, p_source, left(p_message, 2000), left(p_stack, 8000), left(p_url, 2000), left(p_user_agent, 500),
            left(p_release, 100), v_tenant, auth.uid())
    on conflict (fingerprint) where resolved_at is null do update set count = live.error_events.count + 1, last_seen_at = now();
end$$;

revoke execute on function live_app.plan_has(uuid, text) from public, anon;
grant execute on function live_app.plan_has(uuid, text) to authenticated, service_role;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0830')
$$;

-- ===================== 20260901000840_teacher_not_monitored.sql =====================
-- 0840: only students are monitored.
--
-- start_session records the teacher in session_participants, but the teacher's
-- live room never refreshes that row. Under lockdown the leave sweep treated the
-- teacher like a student whose page had gone silent: about two minutes into every
-- locked-down lesson the teacher was alerted that they had "left the class", and
-- the false alert was counted in the lesson summary. The same could happen to a
-- co-teacher or admin who opened the student view of a lesson.
--
-- Leave alerts are now raised only for the class's students, and the false alerts
-- already stored (about people who are not students) are removed.

create or replace function live_app.raise_web_event(
  p_s live.class_sessions, p_student uuid, p_rule text, p_evidence text default null
) returns boolean
language plpgsql volatile security definer set search_path = '' as $$
declare v_id uuid; v_name text;
begin
  -- Never the teacher, a co-teacher or an admin who opened the lesson.
  if not exists (select 1 from live.class_members m
                 where m.class_id = p_s.class_id and m.user_id = p_student and m.role = 'student') then
    return false;
  end if;
  insert into live.environment_events (tenant_id, class_session_id, class_id, student_id, device_id, policy_id,
                                         kind, severity, rule, evidence_image)
    values (p_s.tenant_id, p_s.id, p_s.class_id, p_student, null, p_s.environment_id,
            'environment_left', 'warning', p_rule, p_evidence)
    on conflict (class_session_id, student_id, kind) where resolved_at is null do nothing
    returning id into v_id;
  if v_id is null then return false; end if;
  select full_name into v_name from live.users where id = p_student;
  perform live_app.notify(p_s.teacher_id, 'environment_left', v_name || ' left the class', p_rule,
                     '/live/teacher/live/' || p_s.id, 'warning',
                     jsonb_build_object('event_id', v_id, 'session_id', p_s.id, 'student_id', p_student));
  return true;
end$$;

create or replace function live_app.web_leave_check(p_s live.class_sessions) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare r record; v_grace int; v_default int; v_keep boolean; v_img text;
begin
  if p_s.status <> 'live' or not p_s.lockdown then return; end if;
  select default_grace_seconds, store_event_screenshots into v_default, v_keep
    from live.tenant_settings where tenant_id = p_s.tenant_id;
  for r in select p.user_id,
                  case when p.away_since is not null then p.away_since
                       when p.left_at is not null then p.left_at
                       else p.last_seen_at + live_app.presence_window() end as since,
                  coalesce(p.away_reason, case when p.left_at is not null then 'Closed the lesson'
                                               else 'Lesson page stopped responding (closed or lost connection)' end) as why
           from live.session_participants p
           where p.session_id = p_s.id
             and (p.away_since is not null or p.left_at is not null or p.last_seen_at < now() - live_app.presence_window())
             -- only the class's students (the teacher has a participant row too)
             and exists (select 1 from live.class_members m
                         where m.class_id = p_s.class_id and m.user_id = p.user_id and m.role = 'student')
             -- a student still setting up (first 2 minutes, never fully in class) hasn't left
             and (p.ready_at is not null or p.joined_at < now() - interval '2 minutes')
             -- students monitored by the extension are covered by its own leave rules
             and not exists (select 1 from live.browser_sessions b where b.class_session_id = p_s.id
                             and b.student_id = p.user_id and b.last_heartbeat_at > now() - interval '45 seconds') loop
    v_grace := coalesce((live_app.effective_policy(p_s, r.user_id)).grace_seconds, v_default, 15);
    if now() - r.since >= make_interval(secs => v_grace) then
      v_img := case when v_keep then (select image_data from live.screen_snapshots
                     where class_session_id = p_s.id and student_id = r.user_id and quality in ('thumbnail','spotlight')
                     order by captured_at desc limit 1) end;
      perform live_app.raise_web_event(p_s, r.user_id, r.why, v_img);
    end if;
  end loop;
end$$;

-- Remove the false alerts already raised about teachers and admins (a student's own
-- history is kept, even if they have since left the class).
delete from live.notifications n
 where n.kind = 'environment_left'
   and exists (select 1 from live.users u where u.id::text = n.payload ->> 'student_id' and u.role <> 'student');
delete from live.environment_events e
 where e.kind = 'environment_left' and e.device_id is null
   and exists (select 1 from live.users u where u.id = e.student_id and u.role <> 'student');

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0840')
$$;

-- ===================== 20260901000850_super_admin_settings.sql =====================
-- 0850: the super admin can change any school's settings.
--
-- Until now the platform console could create, rename, re-plan, suspend, restore
-- and delete a school and appoint its admins, but only read its settings. The
-- super admin can now change the same settings a school admin can, plus the
-- school's time zone. Two things stay with the school:
--   * support_access_until: a school's own consent to support access;
--   * brand_logo_path: logos are uploaded into the school's own storage folder.
--
-- Changes are recorded in the platform audit log, and in the school's audit log as
-- "platform.settings.updated" without the operator's identity (as for every
-- other platform action).

create or replace function live.sa_update_tenant_settings(p_tenant uuid, p_changes jsonb) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  allowed constant text[] := array[
    'allow_spotlight', 'allow_group_chat', 'allow_screen_capture', 'store_event_screenshots',
    'parent_portal_enabled', 'email_alerts_enabled', 'parent_focus_details', 'require_monitoring_consent',
    'nickname_mode', 'learning_retention_days', 'telemetry_retention_days',
    'default_grace_seconds', 'default_idle_seconds', 'thumbnail_interval_seconds', 'monitoring_notice',
    'brand_name', 'brand_primary', 'brand_accent', 'welcome_message', 'timezone'];
  v_bad   text;
  v_old   live.tenant_settings;
  v_new   live.tenant_settings;
  v_tz    text;
begin
  perform live_app.sa_require();
  if not exists (select 1 from live.tenants where id = p_tenant) then
    raise exception 'School not found.' using errcode = 'P0002';
  end if;
  if p_changes is null or jsonb_typeof(p_changes) <> 'object' or p_changes = '{}'::jsonb then
    raise exception 'Nothing to change.' using errcode = '22023';
  end if;
  select k into v_bad from jsonb_object_keys(p_changes) k where k <> all (allowed) limit 1;
  if v_bad is not null then
    raise exception 'This setting can''t be changed here: %.', v_bad using errcode = '22023';
  end if;

  if p_changes ? 'timezone' then
    v_tz := nullif(btrim(p_changes ->> 'timezone'), '');
    if v_tz is null or not exists (select 1 from pg_catalog.pg_timezone_names where name = v_tz) then
      raise exception 'Unknown time zone: %.', coalesce(v_tz, '(empty)') using errcode = '22023';
    end if;
    update live.tenants set timezone = v_tz where id = p_tenant;
  end if;

  select * into v_old from live.tenant_settings where tenant_id = p_tenant;
  v_new := jsonb_populate_record(v_old, p_changes - 'timezone');
  -- Database checks (ranges, colour format, nickname modes) still apply.
  update live.tenant_settings set
    allow_spotlight            = v_new.allow_spotlight,
    allow_group_chat           = v_new.allow_group_chat,
    allow_screen_capture       = v_new.allow_screen_capture,
    store_event_screenshots    = v_new.store_event_screenshots,
    parent_portal_enabled      = v_new.parent_portal_enabled,
    email_alerts_enabled       = v_new.email_alerts_enabled,
    parent_focus_details       = v_new.parent_focus_details,
    require_monitoring_consent = v_new.require_monitoring_consent,
    nickname_mode              = v_new.nickname_mode,
    learning_retention_days    = v_new.learning_retention_days,
    telemetry_retention_days   = v_new.telemetry_retention_days,
    default_grace_seconds      = v_new.default_grace_seconds,
    default_idle_seconds       = v_new.default_idle_seconds,
    thumbnail_interval_seconds = v_new.thumbnail_interval_seconds,
    monitoring_notice          = v_new.monitoring_notice,
    brand_name                 = nullif(btrim(v_new.brand_name), ''),
    brand_primary              = nullif(btrim(v_new.brand_primary), ''),
    brand_accent               = nullif(btrim(v_new.brand_accent), ''),
    welcome_message            = nullif(btrim(v_new.welcome_message), '')
  where tenant_id = p_tenant;

  perform live_app.sa_log('settings.updated', p_tenant, 'tenant_settings', p_tenant::text,
                     jsonb_build_object('changed', (select jsonb_agg(k order by k) from jsonb_object_keys(p_changes) k)));
  return (select to_jsonb(ts) - 'tenant_id' from live.tenant_settings ts where ts.tenant_id = p_tenant)
         || jsonb_build_object('timezone', (select timezone from live.tenants where id = p_tenant));
end$$;

revoke execute on function live.sa_update_tenant_settings(uuid, jsonb) from public, anon;
grant execute on function live.sa_update_tenant_settings(uuid, jsonb) to authenticated, service_role;

-- The settings audit trigger would name the super admin in the school's own log;
-- platform changes are already logged (anonymously for the school) by sa_log above.
create or replace function live_app.audit_settings_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if live_app.is_super_admin() then return new; end if;
  perform live_app.audit('settings.updated', 'tenant_settings', new.tenant_id::text,
                    (to_jsonb(new) - 'updated_at') - coalesce(
                      (select array_agg(k) from jsonb_object_keys(to_jsonb(old)) k
                       where to_jsonb(old) -> k = to_jsonb(new) -> k), '{}'::text[]),
                    new.tenant_id);
  return new;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0850')
$$;

-- ===================== 20260901000860_guests.sql =====================
-- 0860: guests in live lessons (Nearpod-style: the code and a name, no account).
--
-- A guest is a Supabase anonymous sign-in with a "guest" profile in the school,
-- holding a pass for ONE live lesson (session_guests). The pass grants exactly
-- what the lesson needs: its slides and files, answering activities, raising a
-- hand, the teacher's shared screen and the lesson's live boards. It never grants
-- class membership, so guests can't see the class list, assignments, other
-- lessons, chats or files from other lessons.
--
-- The teacher decides per lesson whether guests are monitored (lockdown, screen
-- sharing, leave alerts). Where the school requires parental monitoring consent,
-- a guest's screen is never captured: a guest has no parent on record.
--
-- Anonymous accounts can only ever be guests (enforced by a trigger), and guests
-- can never become class members. Guests are deleted 30 days after their last lesson.
--
-- Supabase: Authentication -> Sign In / Providers -> turn on "Allow anonymous sign-ins".

insert into live.roles (code, label, description, rank) values
  ('guest', 'Guest', 'Joined one live lesson with its code and a name; no account.', 5)
on conflict (code) do nothing;

alter table live.class_sessions
  add column if not exists guest_monitoring boolean not null default false,
  add column if not exists guests_closed   boolean not null default false;

create table if not exists live.session_guests (
  session_id   uuid not null references live.class_sessions(id) on delete cascade,
  user_id      uuid not null references live.users(id) on delete cascade,
  tenant_id    uuid not null references live.tenants(id) on delete cascade,
  display_name text not null check (length(btrim(display_name)) between 2 and 40),
  joined_at    timestamptz not null default now(),
  removed_at   timestamptz,
  primary key (session_id, user_id)
);
create index if not exists session_guests_user_idx on live.session_guests(user_id);
create index if not exists session_guests_tenant_idx on live.session_guests(tenant_id);
alter table live.session_guests enable row level security;
revoke all on live.session_guests from anon, authenticated;
grant select on live.session_guests to authenticated;
drop policy if exists session_guests_read on live.session_guests;drop policy if exists session_guests_read on live.session_guests;

create policy session_guests_read on live.session_guests for select to authenticated
  using (user_id = (select auth.uid()) or live_app.can_manage_session(session_id));

-- Is the caller an anonymous (guest) sign-in?
create or replace function live_app.is_anonymous() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select a.is_anonymous from auth.users a where a.id = auth.uid()), false)
$$;

-- A guest pass for this lesson (kept after the lesson ends so the guest sees "ended").
create or replace function live_app.is_session_guest(p_session uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select auth.uid() is not null and exists (
    select 1 from live.session_guests g
     where g.session_id = p_session and g.user_id = auth.uid() and g.removed_at is null)
$$;

create or replace function live_app.in_session(p_session uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.in_class(live_app.session_class(p_session)) or live_app.is_session_guest(p_session)
$$;

-- Anonymous sign-ins can only ever be guests, a guest is always an anonymous sign-in,
-- and guests never become class members.
create or replace function live_app.guard_guest_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_anon boolean := coalesce((select a.is_anonymous from auth.users a where a.id = new.id), false);
begin
  if v_anon and new.role <> 'guest' then
    raise exception 'Create an account to join a school.' using errcode = '42501';
  end if;
  if new.role = 'guest' and not v_anon then
    raise exception 'Only a guest sign-in can be a guest.' using errcode = '42501';
  end if;
  return new;
end$$;
drop trigger if exists users_guest_guard on live.users;drop trigger if exists users_guest_guard on live.users;

create trigger users_guest_guard before insert or update of role on live.users
  for each row execute function live_app.guard_guest_profile();

create or replace function live_app.guard_guest_membership() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from live.users u where u.id = new.user_id and u.role = 'guest') then
    raise exception 'Guests can''t join a class. Create an account first.' using errcode = '42501';
  end if;
  return new;
end$$;
drop trigger if exists class_members_no_guests on live.class_members;drop trigger if exists class_members_no_guests on live.class_members;

create trigger class_members_no_guests before insert or update of user_id on live.class_members
  for each row execute function live_app.guard_guest_membership();

-- Join a live lesson as a guest. Returns {session_id, title}, or {error, code} so a
-- wrong code still counts towards the 8-per-15-minutes limit.
create or replace function live.join_session_as_guest(p_code text, p_name text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid  uuid := auth.uid();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '\s', '', 'g'));
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_s    live.class_sessions;
  v_user live.users;
  v_pass live.session_guests;
begin
  if v_uid is null or not live_app.is_anonymous() then
    raise exception 'Use the guest sign-in to join as a guest.' using errcode = '42501';
  end if;
  if (select count(*) from live.code_attempts where user_id = v_uid and at > now() - interval '15 minutes') >= 8 then
    raise exception 'Too many wrong codes. Wait 15 minutes, then check the code with your teacher.' using errcode = 'P0001';
  end if;
  if length(v_name) < 2 or length(v_name) > 40 or v_name !~ '^[[:alnum:]][[:alnum:] .''_-]*$' then
    raise exception 'Use 2 to 40 letters or numbers for your name.' using errcode = '22023';
  end if;

  select * into v_s from live.class_sessions where join_code = v_code and status = 'live';
  if v_s.id is null then
    insert into live.code_attempts (user_id) values (v_uid);
    return jsonb_build_object('error', 'No live lesson has that code. Check it with your teacher.', 'code', 'P0002');
  end if;
  if exists (select 1 from live.tenants t where t.id = v_s.tenant_id and t.status <> 'active') then
    raise exception 'This school isn''t available right now.' using errcode = '42501';
  end if;

  select * into v_user from live.users where id = v_uid;
  if v_user.id is not null and v_user.tenant_id <> v_s.tenant_id then
    return jsonb_build_object('error', 'Start a new guest sign-in for this school.', 'code', 'GUEST_OTHER_SCHOOL');
  end if;

  select * into v_pass from live.session_guests where session_id = v_s.id and user_id = v_uid;
  if v_pass.removed_at is not null then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_pass.session_id is null then
    if v_s.guests_closed then
      raise exception 'This lesson isn''t taking new guests. Ask your teacher.' using errcode = 'P0001';
    end if;
    if (select count(*) from live.session_guests where session_id = v_s.id and removed_at is null) >= 300 then
      raise exception 'This lesson is full.' using errcode = 'P0001';
    end if;
    if exists (select 1 from live.session_guests where session_id = v_s.id and removed_at is null
                and lower(display_name) = lower(v_name)) then
      raise exception 'Someone in this lesson already uses that name. Add a surname or a number.' using errcode = 'P0001';
    end if;
  end if;

  if v_user.id is null then
    insert into live.users (id, tenant_id, email, full_name, role)
      values (v_uid, v_s.tenant_id, '', v_name, 'guest');
  else
    update live.users set full_name = v_name where id = v_uid;
  end if;
  -- Joining as a guest means accepting the Terms of Service, as the join page says.
  insert into live.consents (tenant_id, user_id, kind, version)
    values (v_s.tenant_id, v_uid, 'terms_of_service', 1) on conflict (user_id, kind, version) do nothing;

  insert into live.session_guests (session_id, user_id, tenant_id, display_name)
    values (v_s.id, v_uid, v_s.tenant_id, v_name)
    on conflict (session_id, user_id) do update set display_name = excluded.display_name;
  insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
    values (v_s.id, v_uid, v_s.tenant_id, 'online', v_s.current_slide)
    on conflict (session_id, user_id) do update set status = 'online', left_at = null, last_seen_at = now();
  delete from live.code_attempts where user_id = v_uid;
  perform live_app.audit('session.guest_joined', 'class_session', v_s.id::text, jsonb_build_object('name', v_name), v_s.tenant_id);
  return jsonb_build_object('session_id', v_s.id, 'title', v_s.title);
end$$;

-- The teacher's guest controls for one lesson: monitor guests, and stop new guests joining.
create or replace function live.set_session_guests(p_session uuid, p_monitor boolean default null, p_closed boolean default null)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions;
begin
  if not live_app.can_manage_session(p_session) then raise exception 'Not your session.' using errcode = '42501'; end if;
  update live.class_sessions set guest_monitoring = coalesce(p_monitor, guest_monitoring),
                                   guests_closed = coalesce(p_closed, guests_closed),
                                   state_version = state_version + 1
   where id = p_session returning * into v_s;
  perform live_app.audit('session.guests_changed', 'class_session', p_session::text,
                    jsonb_build_object('monitor', v_s.guest_monitoring, 'closed', v_s.guests_closed));
  return jsonb_build_object('guest_monitoring', v_s.guest_monitoring, 'guests_closed', v_s.guests_closed);
end$$;

create or replace function live.remove_session_guest(p_session uuid, p_user uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not live_app.can_manage_session(p_session) then raise exception 'Not your session.' using errcode = '42501'; end if;
  update live.session_guests set removed_at = now() where session_id = p_session and user_id = p_user and removed_at is null;
  if not found then raise exception 'Guest not found.' using errcode = 'P0002'; end if;
  update live.session_participants set left_at = now(), status = 'offline' where session_id = p_session and user_id = p_user;
  update live.raise_hands set status = 'resolved' where session_id = p_session and student_id = p_user and status = 'open';
  perform live_app.audit('session.guest_removed', 'user', p_user::text, jsonb_build_object('session_id', p_session));
end$$;

revoke execute on function live.join_session_as_guest(text, text) from public, anon;
revoke execute on function live.set_session_guests(uuid, boolean, boolean) from public, anon;
revoke execute on function live.remove_session_guest(uuid, uuid) from public, anon;
grant execute on function live.join_session_as_guest(text, text) to authenticated;
grant execute on function live.set_session_guests(uuid, boolean, boolean) to authenticated;
grant execute on function live.remove_session_guest(uuid, uuid) to authenticated;

-- Guests can read the session row of their own lesson.
drop policy if exists class_sessions_read on live.class_sessions;drop policy if exists class_sessions_read on live.class_sessions;

create policy class_sessions_read on live.class_sessions for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (live_app.can_manage_class(class_id) or live_app.in_class(class_id) or (select live_app.is_it()) or live_app.is_session_guest(id)));

-- Files: school members read the school's lesson files; a guest only those of their live lesson.
create or replace function live_app.guest_can_read_media(p_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.session_guests g
      join live.class_sessions s on s.id = g.session_id and s.status = 'live'
     where g.user_id = auth.uid() and g.removed_at is null and s.lesson_id is not null
       and (exists (select 1 from live.lesson_slides sl where sl.lesson_id = s.lesson_id
                    and p_name in (sl.content ->> 'media_path', sl.content ->> 'captions_path'))
            or exists (select 1 from live.lesson_media lm where lm.lesson_id = s.lesson_id and lm.storage_path = p_name)))
$$;
drop policy if exists "lesson media read" on storage.objects;drop policy if exists "live lesson media read" on storage.objects;

create policy "live lesson media read" on storage.objects for select to authenticated
  using (bucket_id = 'live-lesson-media' and (storage.foldername(name))[1] = (select live_app.tenant_id())::text
         and ((select live_app.role()) is distinct from 'guest' or live_app.guest_can_read_media(name)));

-- Guests are removed 30 days after their last lesson (their answers go with them).
create or replace function live_app.purge_guests() returns int
language plpgsql volatile security definer set search_path = '' as $$
declare v_n int;
begin
  delete from auth.users a
   where a.is_anonymous
     and exists (select 1 from live.users u where u.id = a.id and u.role = 'guest')
     and not exists (select 1 from live.session_guests g join live.class_sessions s on s.id = g.session_id
                      where g.user_id = a.id and (s.status = 'live' or coalesce(s.ended_at, s.created_at) > now() - interval '30 days'));
  get diagnostics v_n = row_count;
  return v_n;
end$$;
revoke execute on function live_app.purge_guests() from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('synergy-live-purge-guests', '23 3 * * *', 'select live_app.purge_guests()');
  end if;
end$$;

-- ---------------------------------------------------------------------------
-- Live-lesson functions that now also accept a guest pass for that lesson.
-- (Current definitions, each changed only where noted by "guest".)
-- ---------------------------------------------------------------------------

create or replace function live.session_lesson(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id) or live_app.can_manage_class(v_s.class_id)) then
    raise exception 'Session not found.' using errcode = 'P0002';
  end if;
  if v_s.lesson_id is null then return jsonb_build_object('lesson', null, 'slides', '[]'::jsonb); end if;
  return live_app.lesson_payload(v_s.lesson_id);
end$$;

create or replace function live.session_student_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_s     live.class_sessions;
  v_p     live.session_participants;
  v_spot  live.spotlights;
  v_act   live.activities;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  if v_s.status = 'live' then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
      on conflict (session_id, user_id) do update set last_seen_at = now(), left_at = null,
        status = case when live.session_participants.status = 'offline' then 'online' else live.session_participants.status end
      returning * into v_p;
  end if;
  select * into v_spot from live.spotlights where session_id = p_session and ended_at is null;
  select * into v_act from live.activities where id = v_s.active_activity_id;

  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'mode', v_s.mode,
                                  'current_slide', v_s.current_slide, 'group_chat_enabled', v_s.group_chat_enabled and v_me.role <> 'guest',
                                  'responses_visible', v_s.responses_visible, 'class_id', v_s.class_id,
                                  'teacher', (select full_name from live.users where id = v_s.teacher_id),
                                  'environment_active', v_s.environment_active),
    'my_slide', coalesce(v_p.current_slide, v_s.current_slide),
    'active_activity', case when v_act.id is null then null else jsonb_build_object(
                         'id', v_act.id, 'kind', v_act.kind, 'title', v_act.title) end,
    'spotlight', case when v_spot.id is null then null else jsonb_build_object(
                   'me', v_spot.student_id = v_me.id, 'show_to_class', v_spot.show_to_class, 'anonymized', v_spot.anonymized) end,
    'hand', (select jsonb_build_object('id', h.id, 'created_at', h.created_at) from live.raise_hands h
             where h.session_id = p_session and h.student_id = v_me.id and h.status = 'open'),
    'environment_notice', case when exists (select 1 from live.environment_events e where e.class_session_id = p_session
                                            and e.student_id = v_me.id and e.resolved_at is null
                                            and e.kind in ('environment_left','domain_blocked'))
                               then 'Your class session requires you to return to the lesson.' end,
    'device_monitored', exists (select 1 from live.browser_sessions b where b.class_session_id = p_session
                                and b.student_id = v_me.id and b.last_heartbeat_at > now() - interval '45 seconds'),
    'announcements', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at)
                       order by a.created_at desc), '[]'::jsonb)
                      from (select * from live.announcements where session_id = p_session order by created_at desc limit 5) a),
    'guest', v_me.role = 'guest',
    'server_now', now());
end$$;

create or replace function live.student_report(
  p_session uuid, p_visible boolean, p_fullscreen boolean, p_sharing boolean,
  p_surface text default null, p_unsupported boolean default false,
  p_slide int default null, p_idle boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_p        live.session_participants;
  v_old      live.session_participants;
  v_set      live.tenant_settings;
  v_reason   text;
  v_setup    boolean := false;
  v_status   text := case when p_idle then 'idle' else 'online' end;
  v_slide    int;
  v_changed  boolean;
  v_returned int;
  v_capture  boolean;
  v_guest    boolean;
  v_lock     boolean;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  -- Guests (code and a name, no account) are only monitored when the teacher chose that for this lesson.
  v_guest := not live_app.in_class(v_s.class_id) and live_app.is_session_guest(v_s.id);
  if not (v_guest or live_app.in_class(v_s.class_id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  v_lock := v_s.lockdown and (not v_guest or v_s.guest_monitoring);
  if v_s.status <> 'live' then return jsonb_build_object('status', v_s.status, 'state_version', v_s.state_version); end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  -- Screen sharing is requested only if the school allows it and, where the school
  -- requires it, a parent/guardian monitoring consent is on file for this student.
  -- A guest has no parent on record, so where the school requires consent their screen is never captured.
  v_capture := v_set.allow_screen_capture and case when v_guest then v_s.guest_monitoring and not v_set.require_monitoring_consent
                                                   else not v_set.require_monitoring_consent or live_app.has_monitoring_consent(auth.uid()) end;

  v_reason := case
    when not v_lock then null
    when not coalesce(p_visible, true) then 'Left the lesson (switched tab, app or window)'
    when not coalesce(p_fullscreen, false) and not p_unsupported then 'Left full-screen mode'
    when v_capture and not coalesce(p_sharing, false) and not p_unsupported then 'Stopped sharing their screen'
  end;

  select * into v_old from live.session_participants where session_id = p_session and user_id = auth.uid();
  if v_old.session_id is null then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (p_session, auth.uid(), v_s.tenant_id, v_status, v_s.current_slide)
      on conflict (session_id, user_id) do nothing;
    select * into v_old from live.session_participants where session_id = p_session and user_id = auth.uid();
  end if;

  if v_reason is not null and v_old.ready_at is null then
    if v_old.joined_at > now() - interval '2 minutes' then v_reason := null; v_setup := true;
    else v_reason := 'Did not start the lesson (screen share and full screen are required)'; end if;
  end if;

  v_slide := case when v_s.mode = 'student_paced' then coalesce(case when p_slide >= 0 then p_slide end, v_old.current_slide)
                  else v_s.current_slide end;

  v_changed := v_old.left_at is not null
    or v_old.status is distinct from v_status
    or v_old.current_slide is distinct from v_slide
    or v_old.tab_visible is distinct from coalesce(p_visible, true)
    or v_old.fullscreen is distinct from coalesce(p_fullscreen, false)
    or v_old.screen_sharing is distinct from coalesce(p_sharing, false)
    or v_old.share_unsupported is distinct from coalesce(p_unsupported, false)
    or v_old.screen_surface is distinct from left(p_surface, 20)
    or v_old.away_reason is distinct from v_reason
    or (v_reason is null and not v_setup and v_old.ready_at is null);

  -- Presence only needs a write every 15 s; everything else writes on change.
  if v_changed or v_old.last_seen_at < now() - make_interval(secs => live_app.tick_seconds() * 1.5) then
    update live.session_participants set
      last_seen_at = now(), left_at = null, status = v_status, current_slide = v_slide,
      tab_visible = coalesce(p_visible, true), fullscreen = coalesce(p_fullscreen, false),
      screen_sharing = coalesce(p_sharing, false), share_unsupported = coalesce(p_unsupported, false),
      screen_surface = left(p_surface, 20),
      ready_at = case when v_reason is null and not v_setup then coalesce(ready_at, now()) else ready_at end,
      away_since = case when v_reason is null then null else coalesce(away_since, now()) end,
      away_reason = v_reason
    where session_id = p_session and user_id = auth.uid()
    returning * into v_p;
  else
    v_p := v_old;
  end if;

  if v_setup then
    null;
  elsif v_reason is null then
    -- Only look for alerts to close if the student may have had one.
    if v_old.away_since is not null or v_old.left_at is not null or v_old.last_seen_at < now() - interval '40 seconds' then
      update live.environment_events set resolved_at = now()
       where class_session_id = p_session and student_id = auth.uid() and resolved_at is null
         and kind = 'environment_left' and device_id is null;
      get diagnostics v_returned = row_count;
      if v_returned > 0 then
        perform live_app.notify(v_s.teacher_id, 'student_returned',
          (select full_name from live.users where id = auth.uid()) || ' returned to the class', null,
          '/live/teacher/live/' || p_session, 'info', jsonb_build_object('student_id', auth.uid()));
      end if;
    end if;
  else
    perform live_app.web_leave_check(v_s);
  end if;

  return jsonb_build_object(
    'status', v_s.status,
    'lockdown', v_lock,
    'away', v_reason is not null,
    'reason', v_reason,
    'setting_up', v_setup,
    'tick_seconds', live_app.tick_seconds(),
    'state_version', v_s.state_version,
    'current_slide', v_s.current_slide,
    'active_activity_id', v_s.active_activity_id,
    'capture', jsonb_build_object(
      'enabled', v_capture,
      -- frames are only worth sending while a teacher has the live room open
      'send', v_capture and coalesce(v_s.teacher_seen_at > now() - interval '45 seconds', false),
      'interval_seconds', greatest(v_set.thumbnail_interval_seconds, 5),
      'high_quality', v_p.hq_requested_at is not null and v_p.hq_requested_at > now() - interval '30 seconds'
                      or exists (select 1 from live.spotlights sp where sp.session_id = p_session
                                 and sp.student_id = auth.uid() and sp.ended_at is null)));
end$$;

create or replace function live.student_screen_frame(
  p_session uuid, p_image text, p_width int default null, p_height int default null, p_quality text default 'thumbnail'
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions; v_set live.tenant_settings; v_last timestamptz;
begin
  if p_quality not in ('thumbnail','spotlight') then raise exception 'Unknown quality.' using errcode = '22023'; end if;
  if p_image is null or p_image not like 'data:image/%' or length(p_image) > 400000 then
    raise exception 'Frame must be a data:image URL under 400 KB.' using errcode = '22023';
  end if;
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or v_s.status <> 'live'
     or not (live_app.in_class(v_s.class_id) or (v_s.guest_monitoring and live_app.is_session_guest(v_s.id))) then
    return jsonb_build_object('stored', false, 'reason', 'no live session');
  end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  if not v_set.allow_screen_capture then return jsonb_build_object('stored', false, 'reason', 'screen capture disabled by school'); end if;

  select captured_at into v_last from live.screen_snapshots
   where class_session_id = p_session and student_id = auth.uid() and quality = p_quality and source = 'web';
  if v_last is not null and now() - v_last < interval '1500 milliseconds' then
    return jsonb_build_object('stored', false, 'reason', 'rate limited');
  end if;

  insert into live.screen_snapshots (tenant_id, device_id, class_session_id, student_id, image_data, width, height, quality, source)
    values (v_s.tenant_id, null, p_session, auth.uid(), p_image, p_width, p_height, p_quality, 'web')
    on conflict (class_session_id, student_id, quality, source) where quality <> 'event'
    do update set image_data = excluded.image_data, width = excluded.width, height = excluded.height, captured_at = now();

  -- Attach "what they switched to" to a fresh leave alert (school setting).
  if v_set.store_event_screenshots then
    update live.environment_events set evidence_image = p_image
     where class_session_id = p_session and student_id = auth.uid() and resolved_at is null
       and kind = 'environment_left' and device_id is null
       and created_at > now() - interval '60 seconds';
  end if;
  if p_quality = 'spotlight' then
    update live.session_participants set hq_requested_at = null where session_id = p_session and user_id = auth.uid();
  end if;
  return jsonb_build_object('stored', true);
end$$;

create or replace function live_app.attempt_context_ok(
  p_activity live.activities, p_session uuid, p_assignment uuid, p_share text
) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions; v_a live.assignments;
begin
  if p_session is not null then
    select * into v_s from live.class_sessions where id = p_session;
    -- coalesce: a NULL active_activity_id must mean "no", never "unknown".
    return coalesce(v_s.id is not null and v_s.status = 'live' and (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id))
       and (v_s.active_activity_id = p_activity.id
            or (p_activity.lesson_id is not null and p_activity.lesson_id = v_s.lesson_id
                and (v_s.mode = 'student_paced'
                     or exists (select 1 from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id
                                and sl.activity_id = p_activity.id and sl.position = v_s.current_slide)
                     or exists (select 1 from live.video_checkpoints vc
                                join live.questions q on q.id = vc.question_id
                                join live.lesson_slides sl on sl.id = vc.slide_id
                                where q.activity_id = p_activity.id and sl.lesson_id = v_s.lesson_id)))), false);
  elsif p_assignment is not null then
    select * into v_a from live.assignments where id = p_assignment;
    return coalesce(v_a.id is not null and v_a.status = 'published' and v_a.activity_id = p_activity.id
       and live_app.in_class(v_a.class_id)
       and (v_a.due_at is null or v_a.due_at > now() or v_a.allow_late), false);
  elsif p_share is not null then
    return coalesce(p_activity.lesson_id = (live_app.valid_share(p_share)).lesson_id, false);
  end if;
  return false;
end$$;

create or replace function live_app.raise_web_event(
  p_s live.class_sessions, p_student uuid, p_rule text, p_evidence text default null
) returns boolean
language plpgsql volatile security definer set search_path = '' as $$
declare v_id uuid; v_name text;
begin
  -- Never the teacher, a co-teacher or an admin who opened the lesson.
  if not exists (select 1 from live.class_members m
                 where m.class_id = p_s.class_id and m.user_id = p_student and m.role = 'student')
     and not (p_s.guest_monitoring and exists (select 1 from live.session_guests g
                                               where g.session_id = p_s.id and g.user_id = p_student and g.removed_at is null)) then
    return false;
  end if;
  insert into live.environment_events (tenant_id, class_session_id, class_id, student_id, device_id, policy_id,
                                         kind, severity, rule, evidence_image)
    values (p_s.tenant_id, p_s.id, p_s.class_id, p_student, null, p_s.environment_id,
            'environment_left', 'warning', p_rule, p_evidence)
    on conflict (class_session_id, student_id, kind) where resolved_at is null do nothing
    returning id into v_id;
  if v_id is null then return false; end if;
  select full_name into v_name from live.users where id = p_student;
  perform live_app.notify(p_s.teacher_id, 'environment_left', v_name || ' left the class', p_rule,
                     '/live/teacher/live/' || p_s.id, 'warning',
                     jsonb_build_object('event_id', v_id, 'session_id', p_s.id, 'student_id', p_student));
  return true;
end$$;

create or replace function live_app.web_leave_check(p_s live.class_sessions) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare r record; v_grace int; v_default int; v_keep boolean; v_img text;
begin
  if p_s.status <> 'live' or not p_s.lockdown then return; end if;
  select default_grace_seconds, store_event_screenshots into v_default, v_keep
    from live.tenant_settings where tenant_id = p_s.tenant_id;
  for r in select p.user_id,
                  case when p.away_since is not null then p.away_since
                       when p.left_at is not null then p.left_at
                       else p.last_seen_at + live_app.presence_window() end as since,
                  coalesce(p.away_reason, case when p.left_at is not null then 'Closed the lesson'
                                               else 'Lesson page stopped responding (closed or lost connection)' end) as why
           from live.session_participants p
           where p.session_id = p_s.id
             and (p.away_since is not null or p.left_at is not null or p.last_seen_at < now() - live_app.presence_window())
             -- only the class's students (the teacher has a participant row too)
             and (exists (select 1 from live.class_members m
                          where m.class_id = p_s.class_id and m.user_id = p.user_id and m.role = 'student')
                  or (p_s.guest_monitoring and exists (select 1 from live.session_guests g
                                                       where g.session_id = p_s.id and g.user_id = p.user_id and g.removed_at is null)))
             -- a student still setting up (first 2 minutes, never fully in class) hasn't left
             and (p.ready_at is not null or p.joined_at < now() - interval '2 minutes')
             -- students monitored by the extension are covered by its own leave rules
             and not exists (select 1 from live.browser_sessions b where b.class_session_id = p_s.id
                             and b.student_id = p.user_id and b.last_heartbeat_at > now() - interval '45 seconds') loop
    v_grace := coalesce((live_app.effective_policy(p_s, r.user_id)).grace_seconds, v_default, 15);
    if now() - r.since >= make_interval(secs => v_grace) then
      v_img := case when v_keep then (select image_data from live.screen_snapshots
                     where class_session_id = p_s.id and student_id = r.user_id and quality in ('thumbnail','spotlight')
                     order by captured_at desc limit 1) end;
      perform live_app.raise_web_event(p_s, r.user_id, r.why, v_img);
    end if;
  end loop;
end$$;

create or replace function live.teacher_session_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_settings live.tenant_settings;
  r          live.browser_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_class(v_s.class_id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_settings from live.tenant_settings where tenant_id = v_s.tenant_id;

  if v_s.status = 'live' then
    -- Students only send screen frames while a teacher is watching (throttled write).
    if v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '20 seconds' then
      update live.class_sessions set teacher_seen_at = now() where id = p_session;
    end if;
    for r in update live.browser_sessions set connection_lost_at = now()
             where class_session_id = p_session and ended_at is null and connection_lost_at is null
               and last_heartbeat_at < now() - interval '45 seconds'
             returning * loop
      perform live_app.raise_event(r, v_s, v_s.environment_id, 'connection_lost', 'info',
                              'Extension stopped reporting — connection lost, not a rule violation', null, null);
    end loop;
    perform live_app.web_leave_check(v_s);
    update live.teacher_commands set status = 'expired'
     where class_session_id = p_session and status in ('queued','delivered') and expires_at < now();
  end if;

  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object(
      'class_name', (select name from live.classes where id = v_s.class_id),
      'lesson_title', (select title from live.lessons where id = v_s.lesson_id),
      'environment_name', (select name from live.environment_policies where id = v_s.environment_id)),
    'settings', jsonb_build_object('allow_spotlight', v_settings.allow_spotlight, 'allow_group_chat', v_settings.allow_group_chat,
                                   'allow_screen_capture', v_settings.allow_screen_capture,
                                   'store_event_screenshots', v_settings.store_event_screenshots,
                                   'thumbnail_interval_seconds', v_settings.thumbnail_interval_seconds),
    'server_now', now(),
    'roster', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name, 'guest', m.guest,
        'presence', case when p.user_id is null then 'not_joined'
                         when p.left_at is not null or p.last_seen_at < now() - live_app.presence_window() then 'offline'
                         else p.status end,
        'last_seen_at', p.last_seen_at, 'current_slide', p.current_slide,
        'web', case when p.user_id is null then null else jsonb_build_object(
                 'sharing', p.screen_sharing and p.last_seen_at > now() - live_app.presence_window(),
                 'unsupported', p.share_unsupported, 'surface', p.screen_surface,
                 'visible', p.tab_visible, 'fullscreen', p.fullscreen,
                 'away_since', p.away_since, 'away_reason', p.away_reason) end,
        'device', (select jsonb_build_object('device_id', b.device_id, 'url', b.active_url, 'domain', b.active_domain,
                     'title', b.active_title, 'tab_count', b.tab_count, 'idle_state', b.idle_state,
                     'online', b.connection_lost_at is null and b.last_heartbeat_at > now() - interval '45 seconds',
                     'last_heartbeat_at', b.last_heartbeat_at, 'focus_locked', b.focus_locked,
                     'violation', b.violation_rule, 'violation_since', b.violation_since,
                     'snapshot_at', (select max(sn.captured_at) from live.screen_snapshots sn
                                     where sn.student_id = u.id and sn.class_session_id = p_session and sn.quality = 'thumbnail'))
                   from live.browser_sessions b where b.class_session_id = p_session and b.student_id = u.id
                   order by b.last_heartbeat_at desc limit 1),
        'open_alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session
                        and e.student_id = u.id and e.status = 'open'),
        'hand_raised', exists (select 1 from live.raise_hands h where h.session_id = p_session and h.student_id = u.id and h.status = 'open'))
        order by u.full_name), '[]'::jsonb)
      from (select cm.user_id, false as guest from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, true from live.session_guests g where g.session_id = p_session and g.removed_at is null) m
      join live.users u on u.id = m.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = u.id),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'severity', e.severity, 'rule', e.rule,
                 'domain', e.domain, 'confidence', e.confidence, 'status', e.status, 'student_id', e.student_id,
                 'student', u.full_name, 'created_at', e.created_at, 'resolved_at', e.resolved_at,
                 'has_evidence', e.evidence_image is not null)
                 order by e.created_at desc), '[]'::jsonb)
               from (select * from live.environment_events where class_session_id = p_session
                     and (status = 'open' or created_at > now() - interval '10 minutes') order by created_at desc limit 50) e
               join live.users u on u.id = e.student_id),
    'hands', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'student_id', h.student_id, 'student', u.full_name,
                'message', h.message, 'created_at', h.created_at) order by h.created_at), '[]'::jsonb)
              from live.raise_hands h join live.users u on u.id = h.student_id
              where h.session_id = p_session and h.status = 'open'),
    'commands', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'status', c.status, 'error', c.error,
                   'student', u.full_name, 'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
                 from (select * from live.teacher_commands where class_session_id = p_session order by created_at desc limit 20) c
                 join live.users u on u.id = c.student_id),
    'spotlight', (select jsonb_build_object('id', s.id, 'student_id', s.student_id, 'anonymized', s.anonymized,
                    'show_to_class', s.show_to_class, 'started_at', s.started_at)
                  from live.spotlights s where s.session_id = p_session and s.ended_at is null),
    'activity', case when v_s.active_activity_id is null then null
                     else live.activity_results(v_s.active_activity_id, p_session) end);
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0860')
$$;

-- ===================== 20260901000870_monitoring_addon.sql =====================
-- 0870: classroom monitoring becomes an optional add-on per school.
--
-- SwiftCipher is now a live presentation and engagement engine (docs/LIVE_ENGINE.md).
-- Monitoring (lockdown, screen capture, leave alerts, blocked-site environments) is an
-- add-on a school switches on. New schools start with it off; schools that already
-- exist keep it on, so nothing changes for them. When it is off the database refuses
-- lockdown and screen capture outright: the switch is not just hidden in the interface.

alter table live.tenant_settings add column if not exists monitoring_enabled boolean;
update live.tenant_settings set monitoring_enabled = true where monitoring_enabled is null;
-- Run the deferred checks for the rows just changed now: a table with checks still
-- pending can't be altered later in the same run ("pending trigger events", 55006).
set constraints all immediate;
set constraints all deferred;
alter table live.tenant_settings alter column monitoring_enabled set default false;
alter table live.tenant_settings alter column monitoring_enabled set not null;
grant update (monitoring_enabled) on live.tenant_settings to authenticated;

-- Sessions already running in a school without monitoring stop locking down.
update live.class_sessions s set lockdown = false
  from live.tenant_settings t
 where t.tenant_id = s.tenant_id and not t.monitoring_enabled and s.status = 'live' and s.lockdown;
-- Run the deferred checks for the rows just changed now: a table with checks still
-- pending can't be altered later in the same run ("pending trigger events", 55006).
set constraints all immediate;
set constraints all deferred;

create or replace function live.start_session(
  p_class uuid, p_lesson uuid default null, p_mode text default 'live_participation',
  p_title text default null, p_environment uuid default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_class live.classes;
  v_s     live.class_sessions;
  v_mon   boolean;
begin
  if not live_app.can_manage_class(p_class) then raise exception 'Not your class.' using errcode = '42501'; end if;
  select * into v_class from live.classes where id = p_class;
  if p_mode not in ('live_participation','student_paced','front_of_class') then
    raise exception 'Unknown delivery mode.' using errcode = '22023';
  end if;
  if p_lesson is not null and not live_app.can_view_lesson(p_lesson) then
    raise exception 'Lesson not found.' using errcode = 'P0002';
  end if;
  if p_environment is not null and not exists (select 1 from live.environment_policies
                                               where id = p_environment and tenant_id = v_me.tenant_id) then
    raise exception 'Environment not found.' using errcode = 'P0002';
  end if;
  -- Monitoring is an add-on: without it, no lockdown and no blocked-site environment.
  v_mon := coalesce((select monitoring_enabled from live.tenant_settings where tenant_id = v_me.tenant_id), false);
  if not v_mon then p_environment := null; end if;
  if exists (select 1 from live.class_sessions where class_id = p_class and status = 'live') then
    raise exception 'This class already has a live session. End it first.' using errcode = 'P0001';
  end if;

  insert into live.class_sessions (tenant_id, class_id, teacher_id, lesson_id, lesson_version, title, mode, join_code,
                                     status, environment_id, environment_active, started_at, lockdown)
    values (v_me.tenant_id, p_class, v_me.id, p_lesson,
            (select current_version from live.lessons where id = p_lesson),
            coalesce(nullif(btrim(p_title), ''), (select title from live.lessons where id = p_lesson), v_class.name || ' live'),
            p_mode, live_app.unique_code(6, 'class_sessions'), 'live', p_environment, p_environment is not null, now(), v_mon)
    returning * into v_s;

  insert into live.session_participants (session_id, user_id, tenant_id, status)
    values (v_s.id, v_me.id, v_me.tenant_id, 'online');
  perform live_app.audit('session.started', 'class_session', v_s.id::text,
                    jsonb_build_object('class_id', p_class, 'lesson_id', p_lesson, 'environment_id', p_environment));
  perform live_app.notify(m.user_id, 'session_started', 'Live class started: ' || v_s.title, 'Join code ' || v_s.join_code,
                     '/live/student/live/' || v_s.id, 'info', jsonb_build_object('session_id', v_s.id))
  from live.class_members m where m.class_id = p_class and m.role = 'student';
  return to_jsonb(v_s);
end$$;

create or replace function live.set_session_lockdown(p_session uuid, p_on boolean) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions := live_app.require_live_session(p_session);
begin
  if p_on and not coalesce((select ts.monitoring_enabled from live.tenant_settings ts
                             join live.class_sessions cs on cs.tenant_id = ts.tenant_id where cs.id = p_session), false) then
    raise exception 'Classroom monitoring is switched off for this school.' using errcode = 'P0001';
  end if;
  update live.class_sessions set lockdown = p_on where id = p_session;
  if not p_on then
    update live.session_participants set away_since = null, away_reason = null where session_id = p_session;
    update live.environment_events set resolved_at = now()
     where class_session_id = p_session and resolved_at is null and kind = 'environment_left' and device_id is null;
  end if;
  perform live_app.audit('session.lockdown_' || case when p_on then 'on' else 'off' end, 'class_session', p_session::text);
end$$;

create or replace function live.student_report(
  p_session uuid, p_visible boolean, p_fullscreen boolean, p_sharing boolean,
  p_surface text default null, p_unsupported boolean default false,
  p_slide int default null, p_idle boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_p        live.session_participants;
  v_old      live.session_participants;
  v_set      live.tenant_settings;
  v_reason   text;
  v_setup    boolean := false;
  v_status   text := case when p_idle then 'idle' else 'online' end;
  v_slide    int;
  v_changed  boolean;
  v_returned int;
  v_capture  boolean;
  v_guest    boolean;
  v_lock     boolean;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  -- Guests (code and a name, no account) are only monitored when the teacher chose that for this lesson.
  v_guest := not live_app.in_class(v_s.class_id) and live_app.is_session_guest(v_s.id);
  if not (v_guest or live_app.in_class(v_s.class_id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  -- Monitoring is an add-on: when the school has it off, nothing is locked or captured.
  v_lock := v_set.monitoring_enabled and v_s.lockdown and (not v_guest or v_s.guest_monitoring);
  if v_s.status <> 'live' then return jsonb_build_object('status', v_s.status, 'state_version', v_s.state_version); end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  -- Screen sharing is requested only if the school allows it and, where the school
  -- requires it, a parent/guardian monitoring consent is on file for this student.
  -- A guest has no parent on record, so where the school requires consent their screen is never captured.
  v_capture := v_set.monitoring_enabled and v_set.allow_screen_capture and case when v_guest then v_s.guest_monitoring and not v_set.require_monitoring_consent
                                                   else not v_set.require_monitoring_consent or live_app.has_monitoring_consent(auth.uid()) end;

  v_reason := case
    when not v_lock then null
    when not coalesce(p_visible, true) then 'Left the lesson (switched tab, app or window)'
    when not coalesce(p_fullscreen, false) and not p_unsupported then 'Left full-screen mode'
    when v_capture and not coalesce(p_sharing, false) and not p_unsupported then 'Stopped sharing their screen'
  end;

  select * into v_old from live.session_participants where session_id = p_session and user_id = auth.uid();
  if v_old.session_id is null then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (p_session, auth.uid(), v_s.tenant_id, v_status, v_s.current_slide)
      on conflict (session_id, user_id) do nothing;
    select * into v_old from live.session_participants where session_id = p_session and user_id = auth.uid();
  end if;

  if v_reason is not null and v_old.ready_at is null then
    if v_old.joined_at > now() - interval '2 minutes' then v_reason := null; v_setup := true;
    else v_reason := 'Did not start the lesson (screen share and full screen are required)'; end if;
  end if;

  v_slide := case when v_s.mode = 'student_paced' then coalesce(case when p_slide >= 0 then p_slide end, v_old.current_slide)
                  else v_s.current_slide end;

  v_changed := v_old.left_at is not null
    or v_old.status is distinct from v_status
    or v_old.current_slide is distinct from v_slide
    or v_old.tab_visible is distinct from coalesce(p_visible, true)
    or v_old.fullscreen is distinct from coalesce(p_fullscreen, false)
    or v_old.screen_sharing is distinct from coalesce(p_sharing, false)
    or v_old.share_unsupported is distinct from coalesce(p_unsupported, false)
    or v_old.screen_surface is distinct from left(p_surface, 20)
    or v_old.away_reason is distinct from v_reason
    or (v_reason is null and not v_setup and v_old.ready_at is null);

  -- Presence only needs a write every 15 s; everything else writes on change.
  if v_changed or v_old.last_seen_at < now() - make_interval(secs => live_app.tick_seconds() * 1.5) then
    update live.session_participants set
      last_seen_at = now(), left_at = null, status = v_status, current_slide = v_slide,
      tab_visible = coalesce(p_visible, true), fullscreen = coalesce(p_fullscreen, false),
      screen_sharing = coalesce(p_sharing, false), share_unsupported = coalesce(p_unsupported, false),
      screen_surface = left(p_surface, 20),
      ready_at = case when v_reason is null and not v_setup then coalesce(ready_at, now()) else ready_at end,
      away_since = case when v_reason is null then null else coalesce(away_since, now()) end,
      away_reason = v_reason
    where session_id = p_session and user_id = auth.uid()
    returning * into v_p;
  else
    v_p := v_old;
  end if;

  if v_setup then
    null;
  elsif v_reason is null then
    -- Only look for alerts to close if the student may have had one.
    if v_old.away_since is not null or v_old.left_at is not null or v_old.last_seen_at < now() - interval '40 seconds' then
      update live.environment_events set resolved_at = now()
       where class_session_id = p_session and student_id = auth.uid() and resolved_at is null
         and kind = 'environment_left' and device_id is null;
      get diagnostics v_returned = row_count;
      if v_returned > 0 then
        perform live_app.notify(v_s.teacher_id, 'student_returned',
          (select full_name from live.users where id = auth.uid()) || ' returned to the class', null,
          '/live/teacher/live/' || p_session, 'info', jsonb_build_object('student_id', auth.uid()));
      end if;
    end if;
  else
    perform live_app.web_leave_check(v_s);
  end if;

  return jsonb_build_object(
    'status', v_s.status,
    'lockdown', v_lock,
    'away', v_reason is not null,
    'reason', v_reason,
    'setting_up', v_setup,
    'tick_seconds', live_app.tick_seconds(),
    'state_version', v_s.state_version,
    'current_slide', v_s.current_slide,
    'active_activity_id', v_s.active_activity_id,
    'capture', jsonb_build_object(
      'enabled', v_capture,
      -- frames are only worth sending while a teacher has the live room open
      'send', v_capture and coalesce(v_s.teacher_seen_at > now() - interval '45 seconds', false),
      'interval_seconds', greatest(v_set.thumbnail_interval_seconds, 5),
      'high_quality', v_p.hq_requested_at is not null and v_p.hq_requested_at > now() - interval '30 seconds'
                      or exists (select 1 from live.spotlights sp where sp.session_id = p_session
                                 and sp.student_id = auth.uid() and sp.ended_at is null)));
end$$;

create or replace function live.student_screen_frame(
  p_session uuid, p_image text, p_width int default null, p_height int default null, p_quality text default 'thumbnail'
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions; v_set live.tenant_settings; v_last timestamptz;
begin
  if p_quality not in ('thumbnail','spotlight') then raise exception 'Unknown quality.' using errcode = '22023'; end if;
  if p_image is null or p_image not like 'data:image/%' or length(p_image) > 400000 then
    raise exception 'Frame must be a data:image URL under 400 KB.' using errcode = '22023';
  end if;
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or v_s.status <> 'live'
     or not (live_app.in_class(v_s.class_id) or (v_s.guest_monitoring and live_app.is_session_guest(v_s.id))) then
    return jsonb_build_object('stored', false, 'reason', 'no live session');
  end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  if not (v_set.allow_screen_capture and v_set.monitoring_enabled) then return jsonb_build_object('stored', false, 'reason', 'screen capture disabled by school'); end if;

  select captured_at into v_last from live.screen_snapshots
   where class_session_id = p_session and student_id = auth.uid() and quality = p_quality and source = 'web';
  if v_last is not null and now() - v_last < interval '1500 milliseconds' then
    return jsonb_build_object('stored', false, 'reason', 'rate limited');
  end if;

  insert into live.screen_snapshots (tenant_id, device_id, class_session_id, student_id, image_data, width, height, quality, source)
    values (v_s.tenant_id, null, p_session, auth.uid(), p_image, p_width, p_height, p_quality, 'web')
    on conflict (class_session_id, student_id, quality, source) where quality <> 'event'
    do update set image_data = excluded.image_data, width = excluded.width, height = excluded.height, captured_at = now();

  -- Attach "what they switched to" to a fresh leave alert (school setting).
  if v_set.store_event_screenshots then
    update live.environment_events set evidence_image = p_image
     where class_session_id = p_session and student_id = auth.uid() and resolved_at is null
       and kind = 'environment_left' and device_id is null
       and created_at > now() - interval '60 seconds';
  end if;
  if p_quality = 'spotlight' then
    update live.session_participants set hq_requested_at = null where session_id = p_session and user_id = auth.uid();
  end if;
  return jsonb_build_object('stored', true);
end$$;

create or replace function live.teacher_session_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_settings live.tenant_settings;
  r          live.browser_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_class(v_s.class_id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_settings from live.tenant_settings where tenant_id = v_s.tenant_id;

  if v_s.status = 'live' then
    -- Students only send screen frames while a teacher is watching (throttled write).
    if v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '20 seconds' then
      update live.class_sessions set teacher_seen_at = now() where id = p_session;
    end if;
    for r in update live.browser_sessions set connection_lost_at = now()
             where class_session_id = p_session and ended_at is null and connection_lost_at is null
               and last_heartbeat_at < now() - interval '45 seconds'
             returning * loop
      perform live_app.raise_event(r, v_s, v_s.environment_id, 'connection_lost', 'info',
                              'Extension stopped reporting — connection lost, not a rule violation', null, null);
    end loop;
    perform live_app.web_leave_check(v_s);
    update live.teacher_commands set status = 'expired'
     where class_session_id = p_session and status in ('queued','delivered') and expires_at < now();
  end if;

  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object(
      'class_name', (select name from live.classes where id = v_s.class_id),
      'lesson_title', (select title from live.lessons where id = v_s.lesson_id),
      'environment_name', (select name from live.environment_policies where id = v_s.environment_id)),
    'settings', jsonb_build_object('monitoring_enabled', v_settings.monitoring_enabled, 'allow_spotlight', v_settings.allow_spotlight, 'allow_group_chat', v_settings.allow_group_chat,
                                   'allow_screen_capture', v_settings.allow_screen_capture,
                                   'store_event_screenshots', v_settings.store_event_screenshots,
                                   'thumbnail_interval_seconds', v_settings.thumbnail_interval_seconds),
    'server_now', now(),
    'roster', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name, 'guest', m.guest,
        'presence', case when p.user_id is null then 'not_joined'
                         when p.left_at is not null or p.last_seen_at < now() - live_app.presence_window() then 'offline'
                         else p.status end,
        'last_seen_at', p.last_seen_at, 'current_slide', p.current_slide,
        'web', case when p.user_id is null then null else jsonb_build_object(
                 'sharing', p.screen_sharing and p.last_seen_at > now() - live_app.presence_window(),
                 'unsupported', p.share_unsupported, 'surface', p.screen_surface,
                 'visible', p.tab_visible, 'fullscreen', p.fullscreen,
                 'away_since', p.away_since, 'away_reason', p.away_reason) end,
        'device', (select jsonb_build_object('device_id', b.device_id, 'url', b.active_url, 'domain', b.active_domain,
                     'title', b.active_title, 'tab_count', b.tab_count, 'idle_state', b.idle_state,
                     'online', b.connection_lost_at is null and b.last_heartbeat_at > now() - interval '45 seconds',
                     'last_heartbeat_at', b.last_heartbeat_at, 'focus_locked', b.focus_locked,
                     'violation', b.violation_rule, 'violation_since', b.violation_since,
                     'snapshot_at', (select max(sn.captured_at) from live.screen_snapshots sn
                                     where sn.student_id = u.id and sn.class_session_id = p_session and sn.quality = 'thumbnail'))
                   from live.browser_sessions b where b.class_session_id = p_session and b.student_id = u.id
                   order by b.last_heartbeat_at desc limit 1),
        'open_alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session
                        and e.student_id = u.id and e.status = 'open'),
        'hand_raised', exists (select 1 from live.raise_hands h where h.session_id = p_session and h.student_id = u.id and h.status = 'open'))
        order by u.full_name), '[]'::jsonb)
      from (select cm.user_id, false as guest from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, true from live.session_guests g where g.session_id = p_session and g.removed_at is null) m
      join live.users u on u.id = m.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = u.id),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'severity', e.severity, 'rule', e.rule,
                 'domain', e.domain, 'confidence', e.confidence, 'status', e.status, 'student_id', e.student_id,
                 'student', u.full_name, 'created_at', e.created_at, 'resolved_at', e.resolved_at,
                 'has_evidence', e.evidence_image is not null)
                 order by e.created_at desc), '[]'::jsonb)
               from (select * from live.environment_events where class_session_id = p_session
                     and (status = 'open' or created_at > now() - interval '10 minutes') order by created_at desc limit 50) e
               join live.users u on u.id = e.student_id),
    'hands', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'student_id', h.student_id, 'student', u.full_name,
                'message', h.message, 'created_at', h.created_at) order by h.created_at), '[]'::jsonb)
              from live.raise_hands h join live.users u on u.id = h.student_id
              where h.session_id = p_session and h.status = 'open'),
    'commands', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'status', c.status, 'error', c.error,
                   'student', u.full_name, 'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
                 from (select * from live.teacher_commands where class_session_id = p_session order by created_at desc limit 20) c
                 join live.users u on u.id = c.student_id),
    'spotlight', (select jsonb_build_object('id', s.id, 'student_id', s.student_id, 'anonymized', s.anonymized,
                    'show_to_class', s.show_to_class, 'started_at', s.started_at)
                  from live.spotlights s where s.session_id = p_session and s.ended_at is null),
    'activity', case when v_s.active_activity_id is null then null
                     else live.activity_results(v_s.active_activity_id, p_session) end);
end$$;

create or replace function live.sa_update_tenant_settings(p_tenant uuid, p_changes jsonb) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  allowed constant text[] := array[
    'allow_spotlight', 'allow_group_chat', 'allow_screen_capture', 'store_event_screenshots',
    'parent_portal_enabled', 'email_alerts_enabled', 'parent_focus_details', 'require_monitoring_consent',
    'nickname_mode', 'learning_retention_days', 'telemetry_retention_days',
    'default_grace_seconds', 'default_idle_seconds', 'thumbnail_interval_seconds', 'monitoring_notice',
    'brand_name', 'brand_primary', 'brand_accent', 'welcome_message', 'timezone', 'monitoring_enabled'];
  v_bad   text;
  v_old   live.tenant_settings;
  v_new   live.tenant_settings;
  v_tz    text;
begin
  perform live_app.sa_require();
  if not exists (select 1 from live.tenants where id = p_tenant) then
    raise exception 'School not found.' using errcode = 'P0002';
  end if;
  if p_changes is null or jsonb_typeof(p_changes) <> 'object' or p_changes = '{}'::jsonb then
    raise exception 'Nothing to change.' using errcode = '22023';
  end if;
  select k into v_bad from jsonb_object_keys(p_changes) k where k <> all (allowed) limit 1;
  if v_bad is not null then
    raise exception 'This setting can''t be changed here: %.', v_bad using errcode = '22023';
  end if;

  if p_changes ? 'timezone' then
    v_tz := nullif(btrim(p_changes ->> 'timezone'), '');
    if v_tz is null or not exists (select 1 from pg_catalog.pg_timezone_names where name = v_tz) then
      raise exception 'Unknown time zone: %.', coalesce(v_tz, '(empty)') using errcode = '22023';
    end if;
    update live.tenants set timezone = v_tz where id = p_tenant;
  end if;

  select * into v_old from live.tenant_settings where tenant_id = p_tenant;
  v_new := jsonb_populate_record(v_old, p_changes - 'timezone');
  -- Database checks (ranges, colour format, nickname modes) still apply.
  update live.tenant_settings set
    monitoring_enabled         = v_new.monitoring_enabled,
    allow_spotlight            = v_new.allow_spotlight,
    allow_group_chat           = v_new.allow_group_chat,
    allow_screen_capture       = v_new.allow_screen_capture,
    store_event_screenshots    = v_new.store_event_screenshots,
    parent_portal_enabled      = v_new.parent_portal_enabled,
    email_alerts_enabled       = v_new.email_alerts_enabled,
    parent_focus_details       = v_new.parent_focus_details,
    require_monitoring_consent = v_new.require_monitoring_consent,
    nickname_mode              = v_new.nickname_mode,
    learning_retention_days    = v_new.learning_retention_days,
    telemetry_retention_days   = v_new.telemetry_retention_days,
    default_grace_seconds      = v_new.default_grace_seconds,
    default_idle_seconds       = v_new.default_idle_seconds,
    thumbnail_interval_seconds = v_new.thumbnail_interval_seconds,
    monitoring_notice          = v_new.monitoring_notice,
    brand_name                 = nullif(btrim(v_new.brand_name), ''),
    brand_primary              = nullif(btrim(v_new.brand_primary), ''),
    brand_accent               = nullif(btrim(v_new.brand_accent), ''),
    welcome_message            = nullif(btrim(v_new.welcome_message), '')
  where tenant_id = p_tenant;

  perform live_app.sa_log('settings.updated', p_tenant, 'tenant_settings', p_tenant::text,
                     jsonb_build_object('changed', (select jsonb_agg(k order by k) from jsonb_object_keys(p_changes) k)));
  return (select to_jsonb(ts) - 'tenant_id' from live.tenant_settings ts where ts.tenant_id = p_tenant)
         || jsonb_build_object('timezone', (select timezone from live.tenants where id = p_tenant));
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0870')
$$;

-- ===================== 20260901000880_live_engine_core.sql =====================
-- 0880: live engine core (docs/LIVE_ENGINE.md, increment 2).
--
-- * Session phases: lobby -> active <-> paused -> ended. New sessions open in the
--   lobby; answers are accepted only while the lesson is active.
-- * One teacher control path, live.session_control(session, action, args): start,
--   pause, resume, next, prev, goto, kick, settings, end. It checks the caller and the
--   transition, writes the state, and the existing trigger broadcasts it, now with the
--   compact state in the payload.
-- * A class is optional. Anyone with the code joins: guests (0860) and, new here,
--   signed-in students of the same school who aren't in a class, by a session pass.
-- * Per-session settings (leaderboard, anonymous names, late join, speed bonus) and a
--   participant avatar for the lobby.

alter table live.class_sessions
  add column if not exists phase text not null default 'active'
    check (phase in ('lobby','active','paused','ended')),
  add column if not exists settings jsonb not null
    default '{"leaderboard": true, "anonymous_names": false, "late_join": true, "speed_bonus": true}'::jsonb;
update live.class_sessions set phase = 'ended' where status = 'ended' and phase <> 'ended';
-- Run the deferred checks for the rows just changed now: a table with checks still
-- pending can't be altered later in the same run ("pending trigger events", 55006).
set constraints all immediate;
set constraints all deferred;
alter table live.class_sessions alter column phase set default 'lobby';
alter table live.class_sessions alter column class_id drop not null;

alter table live.session_participants
  add column if not exists avatar text check (avatar is null or avatar ~ '^[a-z]{2,16}$'),
  add column if not exists removed_at timestamptz;

-- Session passes: guests (is_guest) and signed-in students without a class.
alter table live.session_guests add column if not exists is_guest boolean not null default true;

alter table live.announcements alter column class_id drop not null;

-- Who runs a session: its own teacher, a school admin, or a teacher of its class.
create or replace function live_app.can_manage_session(p_session uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.class_sessions s
                  where s.id = p_session and s.tenant_id = live_app.tenant_id()
                    and (s.teacher_id = auth.uid() or live_app.is_admin()
                         or (s.class_id is not null and live_app.can_manage_class(s.class_id))))
$$;

-- A pass held by a real guest (an anonymous sign-in), as opposed to a student's pass.
create or replace function live_app.is_true_guest(p_session uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select auth.uid() is not null and exists (
    select 1 from live.session_guests g
     where g.session_id = p_session and g.user_id = auth.uid() and g.removed_at is null and g.is_guest)
$$;

drop policy if exists class_sessions_read on live.class_sessions;drop policy if exists class_sessions_read on live.class_sessions;

create policy class_sessions_read on live.class_sessions for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (teacher_id = (select auth.uid()) or (select live_app.is_admin()) or (select live_app.is_it())
              or live_app.can_manage_class(class_id) or live_app.in_class(class_id) or live_app.is_session_guest(id)));

drop policy if exists announcements_insert on live.announcements;drop policy if exists announcements_insert on live.announcements;

create policy announcements_insert on live.announcements for insert to authenticated
  with check (tenant_id = (select live_app.tenant_id()) and author_id = (select auth.uid())
              and (case when session_id is not null then live_app.can_manage_session(session_id)
                        and (class_id is null or live_app.session_class(session_id) = class_id)
                        else live_app.can_manage_class(class_id) end));
drop policy if exists announcements_read on live.announcements;drop policy if exists announcements_read on live.announcements;

create policy announcements_read on live.announcements for select to authenticated
  using (live_app.can_manage_class(class_id) or live_app.in_class(class_id)
         or (session_id is not null and (live_app.can_manage_session(session_id) or live_app.in_session(session_id))));

-- Signed-in students join by code: their class's lessons as before, and any other
-- live lesson in their school by a session pass.
create or replace function live.join_session(p_code text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me   live.users := live_app.me();
  v_s    live.class_sessions;
  v_pass live.session_guests;
begin
  select * into v_s from live.class_sessions
   where join_code = upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')) and status = 'live';
  if v_s.id is null then raise exception 'No live lesson has that code.' using errcode = 'P0002'; end if;
  if v_s.tenant_id <> v_me.tenant_id then
    raise exception 'This lesson belongs to another school. Sign out, then join as a guest.' using errcode = '42501';
  end if;
  if exists (select 1 from live.session_participants where session_id = v_s.id and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if not live_app.in_class(v_s.class_id) and not live_app.can_manage_session(v_s.id) then
    if v_me.role <> 'student' then raise exception 'Only students can join a lesson with a code.' using errcode = '42501'; end if;
    select * into v_pass from live.session_guests where session_id = v_s.id and user_id = v_me.id;
    if v_pass.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
    if v_pass.session_id is null then
      if v_s.phase <> 'lobby' and not coalesce((v_s.settings ->> 'late_join')::boolean, true) then
        raise exception 'This lesson has already started and isn''t taking late joiners.' using errcode = 'P0001';
      end if;
      if v_s.guests_closed then raise exception 'This lesson isn''t taking new joiners. Ask your teacher.' using errcode = 'P0001'; end if;
      insert into live.session_guests (session_id, user_id, tenant_id, display_name, is_guest)
        values (v_s.id, v_me.id, v_s.tenant_id,
                case when length(btrim(v_me.full_name)) < 2 then rpad(btrim(v_me.full_name), 2, '.')
                     else left(btrim(v_me.full_name), 40) end, false);
    end if;
  end if;
  insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
    values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
    on conflict (session_id, user_id) do update set status = 'online', left_at = null, last_seen_at = now();
  return jsonb_build_object('session_id', v_s.id, 'title', v_s.title);
end$$;

-- The one teacher control path (state machine in docs/LIVE_ENGINE.md §2).
create or replace function live.session_control(p_session uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions := live_app.require_live_session(p_session);
  v_n      int;
  v_target int;
  v_user   uuid;
  v_bad    text;
begin
  p_args := coalesce(p_args, '{}'::jsonb);
  case p_action
    when 'start' then
      if v_s.phase <> 'lobby' then raise exception 'The lesson has already started.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active', started_at = now() where id = p_session;
    when 'pause' then
      if v_s.phase <> 'active' then raise exception 'Only a running lesson can be paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'paused' where id = p_session;
    when 'resume' then
      if v_s.phase <> 'paused' then raise exception 'The lesson isn''t paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active' where id = p_session;
    when 'next', 'prev', 'goto' then
      if v_s.phase <> 'active' then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      select count(*) into v_n from live.lesson_slides where lesson_id = v_s.lesson_id;
      v_target := case p_action when 'next' then v_s.current_slide + 1 when 'prev' then v_s.current_slide - 1
                                else (p_args ->> 'slide')::int end;
      if v_target is null then raise exception 'Which slide?' using errcode = '22023'; end if;
      perform live.set_session_state(p_session, greatest(0, least(v_target, greatest(v_n - 1, 0))));
    when 'kick' then
      v_user := nullif(p_args ->> 'user_id', '')::uuid;
      if v_user is null or v_user = v_s.teacher_id then raise exception 'Who should be removed?' using errcode = '22023'; end if;
      update live.session_participants set removed_at = now(), left_at = now(), status = 'offline'
       where session_id = p_session and user_id = v_user and removed_at is null;
      if not found then raise exception 'That person isn''t in this lesson.' using errcode = 'P0002'; end if;
      update live.session_guests set removed_at = now() where session_id = p_session and user_id = v_user and removed_at is null;
      update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and student_id = v_user and status = 'open';
      perform live_app.audit('session.participant_removed', 'user', v_user::text, jsonb_build_object('session_id', p_session));
    when 'settings' then
      select k into v_bad from jsonb_object_keys(p_args) k
       where k <> all (array['leaderboard', 'anonymous_names', 'late_join', 'speed_bonus'])
          or jsonb_typeof(p_args -> k) <> 'boolean' limit 1;
      if v_bad is not null then raise exception 'Unknown or invalid setting: %.', v_bad using errcode = '22023'; end if;
      update live.class_sessions set settings = settings || p_args where id = p_session;
    when 'end' then
      return live.end_session(p_session);
    else
      raise exception 'Unknown action: %.', p_action using errcode = '22023';
  end case;
  select * into v_s from live.class_sessions where id = p_session;
  return jsonb_build_object('phase', v_s.phase, 'slide', v_s.current_slide, 'settings', v_s.settings, 'v', v_s.state_version);
end$$;

-- A participant picks their lobby avatar (a word from the app's avatar set).
create or replace function live.set_avatar(p_session uuid, p_avatar text) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if p_avatar !~ '^[a-z]{2,16}$' then raise exception 'Unknown avatar.' using errcode = '22023'; end if;
  update live.session_participants set avatar = p_avatar
   where session_id = p_session and user_id = auth.uid() and removed_at is null;
  if not found then raise exception 'Join the lesson first.' using errcode = 'P0002'; end if;
end$$;

revoke execute on function live.session_control(uuid, text, jsonb) from public, anon;
revoke execute on function live.set_avatar(uuid, text) from public, anon;
grant execute on function live.session_control(uuid, text, jsonb) to authenticated;
grant execute on function live.set_avatar(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Existing functions, changed only where noted (session-based management instead of
-- class-based, phases, passes for students).
-- ---------------------------------------------------------------------------

create or replace function live_app.require_live_session(p_session uuid) returns live.class_sessions
language plpgsql stable security definer set search_path = '' as $$
declare v live.class_sessions;
begin
  select * into v from live.class_sessions where id = p_session;
  if v.id is null then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  if not live_app.can_manage_session(v.id) then raise exception 'Not your session.' using errcode = '42501'; end if;
  if v.status <> 'live' then raise exception 'The session is not live.' using errcode = 'P0001'; end if;
  return v;
end$$;

create or replace function live.session_lesson(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id) or live_app.can_manage_session(v_s.id)) then
    raise exception 'Session not found.' using errcode = 'P0002';
  end if;
  if v_s.lesson_id is null then return jsonb_build_object('lesson', null, 'slides', '[]'::jsonb); end if;
  return live_app.lesson_payload(v_s.lesson_id);
end$$;

create or replace function live.session_screens(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions; v_interval int;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select thumbnail_interval_seconds into v_interval from live.tenant_settings where tenant_id = v_s.tenant_id;
  return (select coalesce(jsonb_agg(jsonb_build_object('student_id', sn.student_id, 'device_id', sn.device_id,
            'image', sn.image_data, 'captured_at', sn.captured_at, 'url', sn.url, 'source', sn.source,
            'stale', sn.captured_at < now() - make_interval(secs => greatest(v_interval * 3, 30)))), '[]'::jsonb)
          from (select distinct on (student_id) * from live.screen_snapshots
                where class_session_id = p_session and quality = 'thumbnail'
                order by student_id, captured_at desc) sn);
end$$;

create or replace function live.session_screen(p_session uuid, p_student uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions; v_interval int;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select thumbnail_interval_seconds into v_interval from live.tenant_settings where tenant_id = v_s.tenant_id;
  return (select jsonb_build_object('image', sn.image_data, 'captured_at', sn.captured_at, 'url', sn.url, 'quality', sn.quality,
                   'stale', sn.captured_at < now() - make_interval(secs => greatest(v_interval * 3, 60)))
          from live.screen_snapshots sn
          where sn.class_session_id = p_session and sn.student_id = p_student and sn.quality in ('spotlight','thumbnail')
          order by sn.captured_at desc limit 1);
end$$;

create or replace function live.session_report(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'mode', v_s.mode, 'started_at', v_s.started_at,
                                  'ended_at', v_s.ended_at,
                                  'minutes', round(extract(epoch from coalesce(v_s.ended_at, now()) - coalesce(v_s.started_at, v_s.created_at)) / 60)),
    'class', (select jsonb_build_object('id', c.id, 'name', c.name) from live.classes c where c.id = v_s.class_id),
    'enrolled', (select count(*) from live.class_members where class_id = v_s.class_id and role = 'student'),
    'joined', (select count(*) from live.session_participants p join live.class_members m
               on m.class_id = v_s.class_id and m.user_id = p.user_id and m.role = 'student' where p.session_id = p_session),
    'activities', (select coalesce(jsonb_agg(jsonb_build_object('activity_id', a.id, 'title', a.title, 'kind', a.kind,
                     'attempts', (select count(*) from live.quiz_attempts t where t.activity_id = a.id and t.session_id = p_session),
                     'avg_percent', (select round(avg(100.0 * t.score / nullif(t.max_score, 0))) from live.quiz_attempts t
                                     where t.activity_id = a.id and t.session_id = p_session and t.status <> 'in_progress'))), '[]'::jsonb)
                   from live.activities a where exists (select 1 from live.quiz_attempts t where t.activity_id = a.id and t.session_id = p_session)),
    'alerts', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from
                (select kind, count(*) n from live.environment_events where class_session_id = p_session group by kind) x),
    'commands', (select count(*) from live.teacher_commands where class_session_id = p_session),
    'hands', (select count(*) from live.raise_hands where session_id = p_session),
    'students', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name,
        'joined', exists (select 1 from live.session_participants p where p.session_id = p_session and p.user_id = u.id),
        'answers', (select count(*) from live.quiz_answers qa join live.quiz_attempts t on t.id = qa.attempt_id
                    where t.session_id = p_session and t.student_id = u.id),
        'correct', (select count(*) from live.quiz_answers qa join live.quiz_attempts t on t.id = qa.attempt_id
                    where t.session_id = p_session and t.student_id = u.id and qa.is_correct),
        'alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session and e.student_id = u.id
                   and e.kind <> 'connection_lost'))
        order by u.full_name), '[]'::jsonb)
      from live.class_members m join live.users u on u.id = m.user_id
      where m.class_id = v_s.class_id and m.role = 'student'));
end$$;

create or replace function live.teacher_session_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_settings live.tenant_settings;
  r          live.browser_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_settings from live.tenant_settings where tenant_id = v_s.tenant_id;

  if v_s.status = 'live' then
    -- Students only send screen frames while a teacher is watching (throttled write).
    if v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '20 seconds' then
      update live.class_sessions set teacher_seen_at = now() where id = p_session;
    end if;
    for r in update live.browser_sessions set connection_lost_at = now()
             where class_session_id = p_session and ended_at is null and connection_lost_at is null
               and last_heartbeat_at < now() - interval '45 seconds'
             returning * loop
      perform live_app.raise_event(r, v_s, v_s.environment_id, 'connection_lost', 'info',
                              'Extension stopped reporting — connection lost, not a rule violation', null, null);
    end loop;
    perform live_app.web_leave_check(v_s);
    update live.teacher_commands set status = 'expired'
     where class_session_id = p_session and status in ('queued','delivered') and expires_at < now();
  end if;

  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object(
      'class_name', (select name from live.classes where id = v_s.class_id),
      'lesson_title', (select title from live.lessons where id = v_s.lesson_id),
      'environment_name', (select name from live.environment_policies where id = v_s.environment_id)),
    'settings', jsonb_build_object('monitoring_enabled', v_settings.monitoring_enabled, 'allow_spotlight', v_settings.allow_spotlight, 'allow_group_chat', v_settings.allow_group_chat,
                                   'allow_screen_capture', v_settings.allow_screen_capture,
                                   'store_event_screenshots', v_settings.store_event_screenshots,
                                   'thumbnail_interval_seconds', v_settings.thumbnail_interval_seconds),
    'server_now', now(),
    'roster', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name, 'guest', m.guest, 'avatar', p.avatar,
        'presence', case when p.user_id is null then 'not_joined'
                         when p.left_at is not null or p.last_seen_at < now() - live_app.presence_window() then 'offline'
                         else p.status end,
        'last_seen_at', p.last_seen_at, 'current_slide', p.current_slide,
        'web', case when p.user_id is null then null else jsonb_build_object(
                 'sharing', p.screen_sharing and p.last_seen_at > now() - live_app.presence_window(),
                 'unsupported', p.share_unsupported, 'surface', p.screen_surface,
                 'visible', p.tab_visible, 'fullscreen', p.fullscreen,
                 'away_since', p.away_since, 'away_reason', p.away_reason) end,
        'device', (select jsonb_build_object('device_id', b.device_id, 'url', b.active_url, 'domain', b.active_domain,
                     'title', b.active_title, 'tab_count', b.tab_count, 'idle_state', b.idle_state,
                     'online', b.connection_lost_at is null and b.last_heartbeat_at > now() - interval '45 seconds',
                     'last_heartbeat_at', b.last_heartbeat_at, 'focus_locked', b.focus_locked,
                     'violation', b.violation_rule, 'violation_since', b.violation_since,
                     'snapshot_at', (select max(sn.captured_at) from live.screen_snapshots sn
                                     where sn.student_id = u.id and sn.class_session_id = p_session and sn.quality = 'thumbnail'))
                   from live.browser_sessions b where b.class_session_id = p_session and b.student_id = u.id
                   order by b.last_heartbeat_at desc limit 1),
        'open_alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session
                        and e.student_id = u.id and e.status = 'open'),
        'hand_raised', exists (select 1 from live.raise_hands h where h.session_id = p_session and h.student_id = u.id and h.status = 'open'))
        order by u.full_name), '[]'::jsonb)
      from (select cm.user_id, false as guest from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, g.is_guest from live.session_guests g where g.session_id = p_session and g.removed_at is null) m
      join live.users u on u.id = m.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = u.id),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'severity', e.severity, 'rule', e.rule,
                 'domain', e.domain, 'confidence', e.confidence, 'status', e.status, 'student_id', e.student_id,
                 'student', u.full_name, 'created_at', e.created_at, 'resolved_at', e.resolved_at,
                 'has_evidence', e.evidence_image is not null)
                 order by e.created_at desc), '[]'::jsonb)
               from (select * from live.environment_events where class_session_id = p_session
                     and (status = 'open' or created_at > now() - interval '10 minutes') order by created_at desc limit 50) e
               join live.users u on u.id = e.student_id),
    'hands', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'student_id', h.student_id, 'student', u.full_name,
                'message', h.message, 'created_at', h.created_at) order by h.created_at), '[]'::jsonb)
              from live.raise_hands h join live.users u on u.id = h.student_id
              where h.session_id = p_session and h.status = 'open'),
    'commands', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'status', c.status, 'error', c.error,
                   'student', u.full_name, 'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
                 from (select * from live.teacher_commands where class_session_id = p_session order by created_at desc limit 20) c
                 join live.users u on u.id = c.student_id),
    'spotlight', (select jsonb_build_object('id', s.id, 'student_id', s.student_id, 'anonymized', s.anonymized,
                    'show_to_class', s.show_to_class, 'started_at', s.started_at)
                  from live.spotlights s where s.session_id = p_session and s.ended_at is null),
    'activity', case when v_s.active_activity_id is null then null
                     else live.activity_results(v_s.active_activity_id, p_session) end);
end$$;

create or replace function live.start_session(
  p_class uuid, p_lesson uuid default null, p_mode text default 'live_participation',
  p_title text default null, p_environment uuid default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_class live.classes;
  v_s     live.class_sessions;
  v_mon   boolean;
begin
  -- A class is optional: without one, anyone with the code joins (live engine, 0880).
  if p_class is not null and not live_app.can_manage_class(p_class) then raise exception 'Not your class.' using errcode = '42501'; end if;
  if p_class is null and not live_app.is_teacher() then raise exception 'Only teachers can start a live lesson.' using errcode = '42501'; end if;
  select * into v_class from live.classes where id = p_class;
  if p_mode not in ('live_participation','student_paced','front_of_class') then
    raise exception 'Unknown delivery mode.' using errcode = '22023';
  end if;
  if p_lesson is not null and not live_app.can_view_lesson(p_lesson) then
    raise exception 'Lesson not found.' using errcode = 'P0002';
  end if;
  if p_environment is not null and not exists (select 1 from live.environment_policies
                                               where id = p_environment and tenant_id = v_me.tenant_id) then
    raise exception 'Environment not found.' using errcode = 'P0002';
  end if;
  -- Monitoring is an add-on: without it, no lockdown and no blocked-site environment.
  v_mon := coalesce((select monitoring_enabled from live.tenant_settings where tenant_id = v_me.tenant_id), false);
  if not v_mon then p_environment := null; end if;
  if p_class is not null and exists (select 1 from live.class_sessions where class_id = p_class and status = 'live') then
    raise exception 'This class already has a live session. End it first.' using errcode = 'P0001';
  end if;

  insert into live.class_sessions (tenant_id, class_id, teacher_id, lesson_id, lesson_version, title, mode, join_code,
                                     status, environment_id, environment_active, started_at, lockdown)
    values (v_me.tenant_id, p_class, v_me.id, p_lesson,
            (select current_version from live.lessons where id = p_lesson),
            coalesce(nullif(btrim(p_title), ''), (select title from live.lessons where id = p_lesson), coalesce(v_class.name || ' live', 'Live lesson')),
            p_mode, live_app.unique_code(6, 'class_sessions'), 'live', p_environment, p_environment is not null, now(), v_mon)
    returning * into v_s;

  insert into live.session_participants (session_id, user_id, tenant_id, status)
    values (v_s.id, v_me.id, v_me.tenant_id, 'online');
  perform live_app.audit('session.started', 'class_session', v_s.id::text,
                    jsonb_build_object('class_id', p_class, 'lesson_id', p_lesson, 'environment_id', p_environment));
  perform live_app.notify(m.user_id, 'session_started', 'Live class started: ' || v_s.title, 'Join code ' || v_s.join_code,
                     '/live/student/live/' || v_s.id, 'info', jsonb_build_object('session_id', v_s.id))
  from live.class_members m where m.class_id = p_class and m.role = 'student';
  return to_jsonb(v_s);
end$$;

create or replace function live.end_session(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions := live_app.require_live_session(p_session);
  v_report uuid;
begin
  update live.class_sessions set status = 'ended', phase = 'ended', ended_at = now(), environment_active = false where id = p_session;
  update live.session_participants set left_at = coalesce(left_at, now()), status = 'offline' where session_id = p_session;
  update live.browser_sessions set ended_at = now() where class_session_id = p_session and ended_at is null;
  update live.environment_events set resolved_at = now() where class_session_id = p_session and resolved_at is null;
  update live.spotlights set ended_at = now() where session_id = p_session and ended_at is null;
  update live.teacher_commands set status = 'expired' where class_session_id = p_session and status in ('queued','delivered');
  update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and status = 'open';
  update live.rtc_rooms set status = 'closed', closed_at = now() where session_id = p_session and status = 'open';
  update live.quiz_attempts set status = 'submitted', submitted_at = now() where session_id = p_session and status = 'in_progress';
  perform live_app.recompute_attempt(id) from live.quiz_attempts where session_id = p_session;

  insert into live.reports (tenant_id, kind, title, scope_type, scope_id, payload, created_by)
    values (v_s.tenant_id, 'session_summary', 'Session report: ' || v_s.title, 'class_session', p_session,
            live.session_report(p_session), auth.uid())
    returning id into v_report;
  perform live_app.audit('session.ended', 'class_session', p_session::text, jsonb_build_object('report_id', v_report));
  return jsonb_build_object('ended', true, 'report_id', v_report);
end$$;

create or replace function live.join_session_as_guest(p_code text, p_name text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid  uuid := auth.uid();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '\s', '', 'g'));
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_s    live.class_sessions;
  v_user live.users;
  v_pass live.session_guests;
begin
  if v_uid is null or not live_app.is_anonymous() then
    raise exception 'Use the guest sign-in to join as a guest.' using errcode = '42501';
  end if;
  if (select count(*) from live.code_attempts where user_id = v_uid and at > now() - interval '15 minutes') >= 8 then
    raise exception 'Too many wrong codes. Wait 15 minutes, then check the code with your teacher.' using errcode = 'P0001';
  end if;
  if length(v_name) < 2 or length(v_name) > 40 or v_name !~ '^[[:alnum:]][[:alnum:] .''_-]*$' then
    raise exception 'Use 2 to 40 letters or numbers for your name.' using errcode = '22023';
  end if;

  select * into v_s from live.class_sessions where join_code = v_code and status = 'live';
  if v_s.id is null then
    insert into live.code_attempts (user_id) values (v_uid);
    return jsonb_build_object('error', 'No live lesson has that code. Check it with your teacher.', 'code', 'P0002');
  end if;
  if exists (select 1 from live.tenants t where t.id = v_s.tenant_id and t.status <> 'active') then
    raise exception 'This school isn''t available right now.' using errcode = '42501';
  end if;

  select * into v_user from live.users where id = v_uid;
  if v_user.id is not null and v_user.tenant_id <> v_s.tenant_id then
    return jsonb_build_object('error', 'Start a new guest sign-in for this school.', 'code', 'GUEST_OTHER_SCHOOL');
  end if;

  select * into v_pass from live.session_guests where session_id = v_s.id and user_id = v_uid;
  if v_pass.removed_at is not null then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_pass.session_id is null then
    if v_s.phase <> 'lobby' and not coalesce((v_s.settings ->> 'late_join')::boolean, true) then
      raise exception 'This lesson has already started and isn''t taking late joiners.' using errcode = 'P0001';
    end if;
    if v_s.guests_closed then
      raise exception 'This lesson isn''t taking new guests. Ask your teacher.' using errcode = 'P0001';
    end if;
    if (select count(*) from live.session_guests where session_id = v_s.id and removed_at is null) >= 300 then
      raise exception 'This lesson is full.' using errcode = 'P0001';
    end if;
    if exists (select 1 from live.session_guests where session_id = v_s.id and removed_at is null
                and lower(display_name) = lower(v_name)) then
      raise exception 'Someone in this lesson already uses that name. Add a surname or a number.' using errcode = 'P0001';
    end if;
  end if;

  if v_user.id is null then
    insert into live.users (id, tenant_id, email, full_name, role)
      values (v_uid, v_s.tenant_id, '', v_name, 'guest');
  else
    update live.users set full_name = v_name where id = v_uid;
  end if;
  -- Joining as a guest means accepting the Terms of Service, as the join page says.
  insert into live.consents (tenant_id, user_id, kind, version)
    values (v_s.tenant_id, v_uid, 'terms_of_service', 1) on conflict (user_id, kind, version) do nothing;

  insert into live.session_guests (session_id, user_id, tenant_id, display_name)
    values (v_s.id, v_uid, v_s.tenant_id, v_name)
    on conflict (session_id, user_id) do update set display_name = excluded.display_name;
  insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
    values (v_s.id, v_uid, v_s.tenant_id, 'online', v_s.current_slide)
    on conflict (session_id, user_id) do update set status = 'online', left_at = null, last_seen_at = now();
  delete from live.code_attempts where user_id = v_uid;
  perform live_app.audit('session.guest_joined', 'class_session', v_s.id::text, jsonb_build_object('name', v_name), v_s.tenant_id);
  return jsonb_build_object('session_id', v_s.id, 'title', v_s.title);
end$$;

create or replace function live.student_report(
  p_session uuid, p_visible boolean, p_fullscreen boolean, p_sharing boolean,
  p_surface text default null, p_unsupported boolean default false,
  p_slide int default null, p_idle boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_p        live.session_participants;
  v_old      live.session_participants;
  v_set      live.tenant_settings;
  v_reason   text;
  v_setup    boolean := false;
  v_status   text := case when p_idle then 'idle' else 'online' end;
  v_slide    int;
  v_changed  boolean;
  v_returned int;
  v_capture  boolean;
  v_guest    boolean;
  v_lock     boolean;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  -- Guests (code and a name, no account) are only monitored when the teacher chose that for this lesson.
  v_guest := not live_app.in_class(v_s.class_id) and live_app.is_true_guest(v_s.id);
  if not (v_guest or live_app.in_class(v_s.class_id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  -- Monitoring is an add-on: when the school has it off, nothing is locked or captured.
  v_lock := v_set.monitoring_enabled and v_s.lockdown and (not v_guest or v_s.guest_monitoring);
  if v_s.status <> 'live' then return jsonb_build_object('status', v_s.status, 'state_version', v_s.state_version); end if;
  select * into v_set from live.tenant_settings where tenant_id = v_s.tenant_id;
  -- Screen sharing is requested only if the school allows it and, where the school
  -- requires it, a parent/guardian monitoring consent is on file for this student.
  -- A guest has no parent on record, so where the school requires consent their screen is never captured.
  v_capture := v_set.monitoring_enabled and v_set.allow_screen_capture and case when v_guest then v_s.guest_monitoring and not v_set.require_monitoring_consent
                                                   else not v_set.require_monitoring_consent or live_app.has_monitoring_consent(auth.uid()) end;

  v_reason := case
    when not v_lock then null
    when not coalesce(p_visible, true) then 'Left the lesson (switched tab, app or window)'
    when not coalesce(p_fullscreen, false) and not p_unsupported then 'Left full-screen mode'
    when v_capture and not coalesce(p_sharing, false) and not p_unsupported then 'Stopped sharing their screen'
  end;

  select * into v_old from live.session_participants where session_id = p_session and user_id = auth.uid();
  if v_old.session_id is null then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (p_session, auth.uid(), v_s.tenant_id, v_status, v_s.current_slide)
      on conflict (session_id, user_id) do nothing;
    select * into v_old from live.session_participants where session_id = p_session and user_id = auth.uid();
  end if;

  if v_reason is not null and v_old.ready_at is null then
    if v_old.joined_at > now() - interval '2 minutes' then v_reason := null; v_setup := true;
    else v_reason := 'Did not start the lesson (screen share and full screen are required)'; end if;
  end if;

  v_slide := case when v_s.mode = 'student_paced' then coalesce(case when p_slide >= 0 then p_slide end, v_old.current_slide)
                  else v_s.current_slide end;

  v_changed := v_old.left_at is not null
    or v_old.status is distinct from v_status
    or v_old.current_slide is distinct from v_slide
    or v_old.tab_visible is distinct from coalesce(p_visible, true)
    or v_old.fullscreen is distinct from coalesce(p_fullscreen, false)
    or v_old.screen_sharing is distinct from coalesce(p_sharing, false)
    or v_old.share_unsupported is distinct from coalesce(p_unsupported, false)
    or v_old.screen_surface is distinct from left(p_surface, 20)
    or v_old.away_reason is distinct from v_reason
    or (v_reason is null and not v_setup and v_old.ready_at is null);

  -- Presence only needs a write every 15 s; everything else writes on change.
  if v_changed or v_old.last_seen_at < now() - make_interval(secs => live_app.tick_seconds() * 1.5) then
    update live.session_participants set
      last_seen_at = now(), left_at = null, status = v_status, current_slide = v_slide,
      tab_visible = coalesce(p_visible, true), fullscreen = coalesce(p_fullscreen, false),
      screen_sharing = coalesce(p_sharing, false), share_unsupported = coalesce(p_unsupported, false),
      screen_surface = left(p_surface, 20),
      ready_at = case when v_reason is null and not v_setup then coalesce(ready_at, now()) else ready_at end,
      away_since = case when v_reason is null then null else coalesce(away_since, now()) end,
      away_reason = v_reason
    where session_id = p_session and user_id = auth.uid()
    returning * into v_p;
  else
    v_p := v_old;
  end if;

  if v_setup then
    null;
  elsif v_reason is null then
    -- Only look for alerts to close if the student may have had one.
    if v_old.away_since is not null or v_old.left_at is not null or v_old.last_seen_at < now() - interval '40 seconds' then
      update live.environment_events set resolved_at = now()
       where class_session_id = p_session and student_id = auth.uid() and resolved_at is null
         and kind = 'environment_left' and device_id is null;
      get diagnostics v_returned = row_count;
      if v_returned > 0 then
        perform live_app.notify(v_s.teacher_id, 'student_returned',
          (select full_name from live.users where id = auth.uid()) || ' returned to the class', null,
          '/live/teacher/live/' || p_session, 'info', jsonb_build_object('student_id', auth.uid()));
      end if;
    end if;
  else
    perform live_app.web_leave_check(v_s);
  end if;

  return jsonb_build_object(
    'status', v_s.status,
    'lockdown', v_lock,
    'away', v_reason is not null,
    'reason', v_reason,
    'setting_up', v_setup,
    'tick_seconds', live_app.tick_seconds(),
    'state_version', v_s.state_version,
    'current_slide', v_s.current_slide,
    'active_activity_id', v_s.active_activity_id,
    'capture', jsonb_build_object(
      'enabled', v_capture,
      -- frames are only worth sending while a teacher has the live room open
      'send', v_capture and coalesce(v_s.teacher_seen_at > now() - interval '45 seconds', false),
      'interval_seconds', greatest(v_set.thumbnail_interval_seconds, 5),
      'high_quality', v_p.hq_requested_at is not null and v_p.hq_requested_at > now() - interval '30 seconds'
                      or exists (select 1 from live.spotlights sp where sp.session_id = p_session
                                 and sp.student_id = auth.uid() and sp.ended_at is null)));
end$$;

create or replace function live_app.raise_web_event(
  p_s live.class_sessions, p_student uuid, p_rule text, p_evidence text default null
) returns boolean
language plpgsql volatile security definer set search_path = '' as $$
declare v_id uuid; v_name text;
begin
  -- Never the teacher, a co-teacher or an admin who opened the lesson.
  if not exists (select 1 from live.class_members m
                 where m.class_id = p_s.class_id and m.user_id = p_student and m.role = 'student')
     and not exists (select 1 from live.session_guests g
                      where g.session_id = p_s.id and g.user_id = p_student and g.removed_at is null
                        and (not g.is_guest or p_s.guest_monitoring)) then
    return false;
  end if;
  insert into live.environment_events (tenant_id, class_session_id, class_id, student_id, device_id, policy_id,
                                         kind, severity, rule, evidence_image)
    values (p_s.tenant_id, p_s.id, p_s.class_id, p_student, null, p_s.environment_id,
            'environment_left', 'warning', p_rule, p_evidence)
    on conflict (class_session_id, student_id, kind) where resolved_at is null do nothing
    returning id into v_id;
  if v_id is null then return false; end if;
  select full_name into v_name from live.users where id = p_student;
  perform live_app.notify(p_s.teacher_id, 'environment_left', v_name || ' left the class', p_rule,
                     '/live/teacher/live/' || p_s.id, 'warning',
                     jsonb_build_object('event_id', v_id, 'session_id', p_s.id, 'student_id', p_student));
  return true;
end$$;

create or replace function live_app.web_leave_check(p_s live.class_sessions) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare r record; v_grace int; v_default int; v_keep boolean; v_img text;
begin
  if p_s.status <> 'live' or not p_s.lockdown then return; end if;
  select default_grace_seconds, store_event_screenshots into v_default, v_keep
    from live.tenant_settings where tenant_id = p_s.tenant_id;
  for r in select p.user_id,
                  case when p.away_since is not null then p.away_since
                       when p.left_at is not null then p.left_at
                       else p.last_seen_at + live_app.presence_window() end as since,
                  coalesce(p.away_reason, case when p.left_at is not null then 'Closed the lesson'
                                               else 'Lesson page stopped responding (closed or lost connection)' end) as why
           from live.session_participants p
           where p.session_id = p_s.id
             and (p.away_since is not null or p.left_at is not null or p.last_seen_at < now() - live_app.presence_window())
             -- only the class's students (the teacher has a participant row too)
             and (exists (select 1 from live.class_members m
                          where m.class_id = p_s.class_id and m.user_id = p.user_id and m.role = 'student')
                  or exists (select 1 from live.session_guests g
                              where g.session_id = p_s.id and g.user_id = p.user_id and g.removed_at is null
                                and (not g.is_guest or p_s.guest_monitoring)))
             -- a student still setting up (first 2 minutes, never fully in class) hasn't left
             and (p.ready_at is not null or p.joined_at < now() - interval '2 minutes')
             -- students monitored by the extension are covered by its own leave rules
             and not exists (select 1 from live.browser_sessions b where b.class_session_id = p_s.id
                             and b.student_id = p.user_id and b.last_heartbeat_at > now() - interval '45 seconds') loop
    v_grace := coalesce((live_app.effective_policy(p_s, r.user_id)).grace_seconds, v_default, 15);
    if now() - r.since >= make_interval(secs => v_grace) then
      v_img := case when v_keep then (select image_data from live.screen_snapshots
                     where class_session_id = p_s.id and student_id = r.user_id and quality in ('thumbnail','spotlight')
                     order by captured_at desc limit 1) end;
      perform live_app.raise_web_event(p_s, r.user_id, r.why, v_img);
    end if;
  end loop;
end$$;

create or replace function live_app.attempt_context_ok(
  p_activity live.activities, p_session uuid, p_assignment uuid, p_share text
) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions; v_a live.assignments;
begin
  if p_session is not null then
    select * into v_s from live.class_sessions where id = p_session;
    -- coalesce: a NULL active_activity_id must mean "no", never "unknown".
    return coalesce(v_s.id is not null and v_s.status = 'live' and v_s.phase = 'active' and (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id))
       and (v_s.active_activity_id = p_activity.id
            or (p_activity.lesson_id is not null and p_activity.lesson_id = v_s.lesson_id
                and (v_s.mode = 'student_paced'
                     or exists (select 1 from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id
                                and sl.activity_id = p_activity.id and sl.position = v_s.current_slide)
                     or exists (select 1 from live.video_checkpoints vc
                                join live.questions q on q.id = vc.question_id
                                join live.lesson_slides sl on sl.id = vc.slide_id
                                where q.activity_id = p_activity.id and sl.lesson_id = v_s.lesson_id)))), false);
  elsif p_assignment is not null then
    select * into v_a from live.assignments where id = p_assignment;
    return coalesce(v_a.id is not null and v_a.status = 'published' and v_a.activity_id = p_activity.id
       and live_app.in_class(v_a.class_id)
       and (v_a.due_at is null or v_a.due_at > now() or v_a.allow_late), false);
  elsif p_share is not null then
    return coalesce(p_activity.lesson_id = (live_app.valid_share(p_share)).lesson_id, false);
  end if;
  return false;
end$$;

create or replace function live.session_student_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_s     live.class_sessions;
  v_p     live.session_participants;
  v_spot  live.spotlights;
  v_act   live.activities;
  v_pass  live.session_guests;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if exists (select 1 from live.session_participants where session_id = p_session and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_p from live.session_participants where session_id = p_session and user_id = v_me.id;
  if v_p.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
  select * into v_pass from live.session_guests where session_id = p_session and user_id = v_me.id;
  if v_s.status = 'live' then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
      on conflict (session_id, user_id) do update set last_seen_at = now(), left_at = null,
        status = case when live.session_participants.status = 'offline' then 'online' else live.session_participants.status end
      returning * into v_p;
  end if;
  select * into v_spot from live.spotlights where session_id = p_session and ended_at is null;
  select * into v_act from live.activities where id = v_s.active_activity_id;

  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'phase', v_s.phase, 'mode', v_s.mode,
                                  'join_code', v_s.join_code, 'settings', v_s.settings,
                                  'current_slide', v_s.current_slide, 'group_chat_enabled', v_s.group_chat_enabled and v_me.role <> 'guest',
                                  'responses_visible', v_s.responses_visible, 'class_id', v_s.class_id,
                                  'teacher', (select full_name from live.users where id = v_s.teacher_id),
                                  'environment_active', v_s.environment_active),
    'my_slide', coalesce(v_p.current_slide, v_s.current_slide),
    'active_activity', case when v_act.id is null then null else jsonb_build_object(
                         'id', v_act.id, 'kind', v_act.kind, 'title', v_act.title) end,
    'spotlight', case when v_spot.id is null then null else jsonb_build_object(
                   'me', v_spot.student_id = v_me.id, 'show_to_class', v_spot.show_to_class, 'anonymized', v_spot.anonymized) end,
    'hand', (select jsonb_build_object('id', h.id, 'created_at', h.created_at) from live.raise_hands h
             where h.session_id = p_session and h.student_id = v_me.id and h.status = 'open'),
    'environment_notice', case when exists (select 1 from live.environment_events e where e.class_session_id = p_session
                                            and e.student_id = v_me.id and e.resolved_at is null
                                            and e.kind in ('environment_left','domain_blocked'))
                               then 'Your class session requires you to return to the lesson.' end,
    'device_monitored', exists (select 1 from live.browser_sessions b where b.class_session_id = p_session
                                and b.student_id = v_me.id and b.last_heartbeat_at > now() - interval '45 seconds'),
    'announcements', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at)
                       order by a.created_at desc), '[]'::jsonb)
                      from (select * from live.announcements where session_id = p_session order by created_at desc limit 5) a),
    'guest', v_me.role = 'guest',
    'me', jsonb_build_object('name', coalesce(v_pass.display_name, v_me.full_name), 'avatar', v_p.avatar),
    'participants', (select count(*) from live.session_participants sp
                      where sp.session_id = p_session and sp.user_id <> v_s.teacher_id and sp.left_at is null and sp.removed_at is null
                        and sp.last_seen_at > now() - live_app.presence_window()),
    'summary', case when v_s.status = 'ended' then (
       select jsonb_build_object('answered', count(*), 'correct', count(*) filter (where a.is_correct))
         from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        where t.session_id = p_session and t.student_id = v_me.id) end,
    'server_now', now());
end$$;

create or replace function live_app.session_changed() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.state_version is distinct from old.state_version then
    -- The compact state travels with the signal, so screens can change without refetching.
    perform live_app.broadcast('session:' || new.id, 'state', jsonb_build_object('v', new.state_version, 'phase', new.phase, 'status', new.status,
      'slide', new.current_slide, 'activity', new.active_activity_id, 'mode', new.mode));
    perform live_app.broadcast('staff:' || new.id, 'state', '{}'::jsonb);
  end if;
  return null;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0880')
$$;

-- ===================== 20260901000890_scoring.sql =====================
-- 0890: points and the leaderboard (docs/LIVE_ENGINE.md, increment 3).
--
-- Scoring is server-side, inside submit_answer, for answers given in a live lesson:
--   correct:       1000 (a second-chance correct: 500)
--                  + speed bonus up to +500, if the lesson's speed_bonus setting is on
--                    and it isn't student-paced: 500 x (1 - elapsed / window), where
--                    elapsed runs from when the question appeared (server clock) and the
--                    window is the activity's time limit, or 20 s
--                  + streak bonus: +100 for each correct answer in a row before this
--                    one, up to +500
--   wrong:         0, and the streak resets
--   poll, open, draw, file (no right answer): 100 for taking part
-- A changed answer replaces its points; totals live on session_participants and
-- are updated under the participant's row lock, so concurrent answers count once.
--
-- The leaderboard: the teacher shows it (session_control 'leaderboard'); the top 10
-- and each one's rank movement since it was last shown are frozen in a snapshot so
-- every screen sees the same board. Students see the top 5 and only their own rank;
-- lower ranks are never shown to the class.

alter table live.session_participants
  add column if not exists total_score   int not null default 0,
  add column if not exists streak        int not null default 0,
  add column if not exists best_streak   int not null default 0,
  add column if not exists correct_count int not null default 0,
  add column if not exists last_rank     int;

alter table live.quiz_answers
  add column if not exists points      int,
  add column if not exists response_ms int;

alter table live.class_sessions
  add column if not exists activity_opened_at timestamptz,
  add column if not exists slide_changed_at   timestamptz,
  add column if not exists show_leaderboard   boolean not null default false,
  add column if not exists leaderboard        jsonb;

create index if not exists session_participants_score_idx on live.session_participants(session_id, total_score desc);

-- When a question appears: the slide changes, an activity is opened, or the lesson starts.
create or replace function live_app.session_timing() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.current_slide is distinct from old.current_slide or (new.phase = 'active' and old.phase = 'lobby') then
    new.slide_changed_at := now();
  end if;
  if new.active_activity_id is not null and new.active_activity_id is distinct from old.active_activity_id then
    new.activity_opened_at := now();
  end if;
  return new;
end$$;
drop trigger if exists class_sessions_timing on live.class_sessions;drop trigger if exists class_sessions_timing on live.class_sessions;

create trigger class_sessions_timing before update on live.class_sessions
  for each row execute function live_app.session_timing();

-- Points for one answer in a live lesson; updates the participant's totals. Returns the breakdown.
create or replace function live_app.score_live_answer(
  p_attempt live.quiz_attempts, p_question live.questions, p_activity live.activities,
  p_is_correct boolean, p_tries smallint, p_prev_points int
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s       live.class_sessions;
  v_base    int := 0;
  v_speed   int := 0;
  v_bonus   int := 0;
  v_prior   int := 0;
  v_streak  int;
  v_start   timestamptz;
  v_window  numeric;
  v_elapsed numeric;
  v_points  int;
  v_p       live.session_participants;
begin
  select * into v_s from live.class_sessions where id = p_attempt.session_id;
  if v_s.id is null then return null; end if;
  v_start := greatest(p_attempt.started_at, coalesce(v_s.slide_changed_at, v_s.started_at),
                      case when v_s.active_activity_id = p_activity.id then v_s.activity_opened_at end);
  v_elapsed := greatest(extract(epoch from now() - v_start), 0);

  if p_question.kind in ('poll', 'open', 'draw', 'file') or p_is_correct is null then
    v_base := 100;
  elsif p_is_correct then
    v_base := case when p_tries = 2 then 500 else 1000 end;
    if p_tries = 1 and v_s.mode <> 'student_paced' and coalesce((v_s.settings ->> 'speed_bonus')::boolean, true) then
      v_window := coalesce(nullif((p_activity.settings ->> 'time_limit_seconds')::int, 0), 20);
      v_speed := round(500 * greatest(0, 1 - v_elapsed / v_window));
    end if;
    -- Correct answers in a row just before this one (questions with a right answer only).
    select count(*) into v_prior from (
      select a.is_correct, sum(case when a.is_correct then 0 else 1 end) over (order by a.answered_at desc) as broken
        from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        join live.questions q on q.id = a.question_id
       where t.session_id = v_s.id and t.student_id = p_attempt.student_id and a.question_id <> p_question.id
         and a.is_correct is not null and q.kind not in ('poll', 'open', 'draw', 'file')) x
     where broken = 0;
    if p_tries = 1 then v_bonus := least(100 * v_prior, 500); end if;
  end if;
  v_points := v_base + v_speed + v_bonus;
  v_streak := case when p_is_correct then v_prior + 1 when p_is_correct is false then 0 end;

  update live.session_participants set
      total_score   = total_score - coalesce(p_prev_points, 0) + v_points,
      streak        = coalesce(v_streak, streak),
      best_streak   = greatest(best_streak, coalesce(v_streak, 0)),
      correct_count = (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                        where t.session_id = v_s.id and t.student_id = p_attempt.student_id and a.is_correct
                          and a.question_id <> p_question.id) + case when p_is_correct then 1 else 0 end
   where session_id = v_s.id and user_id = p_attempt.student_id
   returning * into v_p;

  return jsonb_build_object('points', v_points, 'base', v_base, 'speed', v_speed, 'streak_bonus', v_bonus,
                            'streak', coalesce(v_p.streak, 0), 'total', coalesce(v_p.total_score, v_points),
                            'response_ms', round(v_elapsed * 1000));
end$$;
revoke execute on function live_app.score_live_answer(live.quiz_attempts, live.questions, live.activities, boolean, smallint, int) from public, anon, authenticated;

-- Ranks for a session: participants only (never the teacher or removed people).
create or replace function live_app.session_ranks(p_session uuid)
returns table (user_id uuid, name text, avatar text, score int, rank bigint, last_rank int, streak int)
language sql stable security definer set search_path = '' as $$
  select p.user_id,
         case when coalesce((s.settings ->> 'anonymous_names')::boolean, false)
              then 'Player ' || row_number() over (order by p.joined_at)
              else coalesce(g.display_name, u.full_name) end,
         p.avatar, p.total_score, rank() over (order by p.total_score desc), p.last_rank, p.streak
    from live.session_participants p
    join live.class_sessions s on s.id = p.session_id
    join live.users u on u.id = p.user_id
    left join live.session_guests g on g.session_id = p.session_id and g.user_id = p.user_id
   where p.session_id = p_session and p.user_id <> s.teacher_id and p.removed_at is null
$$;
revoke execute on function live_app.session_ranks(uuid) from public, anon, authenticated;

-- Freeze the current top 10 (with movement since the last board) for everyone to see.
create or replace function live_app.snapshot_leaderboard(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_board jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('name', r.name, 'avatar', r.avatar, 'score', r.score, 'rank', r.rank,
                                               'delta', coalesce(r.last_rank, r.rank) - r.rank) order by r.rank, r.name), '[]'::jsonb)
    into v_board
    from (select * from live_app.session_ranks(p_session) order by rank, name limit 10) r;
  update live.session_participants p set last_rank = r.rank
    from live_app.session_ranks(p_session) r where p.session_id = p_session and p.user_id = r.user_id;
  update live.class_sessions set show_leaderboard = true, leaderboard = jsonb_build_object('at', now(), 'top', v_board)
   where id = p_session;
  return v_board;
end$$;
revoke execute on function live_app.snapshot_leaderboard(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Existing functions, changed only where noted (scoring, leaderboard).
-- ---------------------------------------------------------------------------

create or replace function live.submit_answer(
  p_attempt uuid, p_question uuid, p_response jsonb, p_elapsed_ms int default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me       live.users := live_app.me();
  v_attempt  live.quiz_attempts;
  v_act      live.activities;
  v_q        live.questions;
  v_prev     live.quiz_answers;
  v_grade    jsonb;
  v_feedback text;
  v_instant  boolean;
  v_second   boolean;
  v_tries    smallint := 1;
  v_score    numeric;
  v_reveal   boolean;
  v_points   jsonb;
begin
  select * into v_attempt from live.quiz_attempts where id = p_attempt and student_id = v_me.id for update;
  if v_attempt.id is null then raise exception 'Attempt not found.' using errcode = 'P0002'; end if;
  if v_attempt.status <> 'in_progress' then raise exception 'This attempt has already been submitted.' using errcode = 'P0001'; end if;
  if v_attempt.deadline_at is not null and now() > v_attempt.deadline_at + interval '5 seconds' then
    perform live.finish_attempt(p_attempt);
    raise exception 'Time is up — your attempt was submitted.' using errcode = 'P0001';
  end if;
  if length(p_response::text) > 200000 then raise exception 'Response is too large.' using errcode = '22023'; end if;

  select * into v_q from live.questions where id = p_question and activity_id = v_attempt.activity_id;
  if v_q.id is null then raise exception 'Question not in this activity.' using errcode = 'P0002'; end if;
  select * into v_act from live.activities where id = v_attempt.activity_id;
  v_feedback := coalesce(v_act.settings ->> 'show_feedback', 'after_submit');
  v_second := coalesce((v_act.settings ->> 'redemption')::boolean, false);
  v_grade := live_app.grade_response(v_q, p_response);
  v_instant := v_feedback = 'immediately' and v_grade ->> 'status' = 'auto_graded';
  v_score := (v_grade ->> 'score')::numeric;

  select * into v_prev from live.quiz_answers where attempt_id = p_attempt and question_id = p_question;
  if v_prev.id is not null then
    -- Once the correct answer has been shown, the answer is final.
    if v_prev.revealed then
      raise exception 'You have already answered this question. Move on to the next one.' using errcode = 'P0001';
    end if;
    -- Second chance: only after a wrong first try with instant feedback. Worth half,
    -- but never less than any partial credit the first try already earned.
    if v_instant and v_second and v_prev.is_correct is false and v_prev.tries = 1 then
      v_tries := 2;
      v_score := greatest(round(coalesce(v_score, 0) * 0.5, 2), coalesce(v_prev.auto_score, 0));
    end if;
  end if;

  -- With a second chance on, a wrong first try says "not quite" without showing the answer.
  v_reveal := v_instant and not (v_second and v_tries = 1 and (v_grade ->> 'is_correct')::boolean is false);

  insert into live.quiz_answers (tenant_id, attempt_id, question_id, response, is_correct, auto_score, status, elapsed_ms, tries, revealed)
    values (v_me.tenant_id, p_attempt, p_question, p_response, (v_grade ->> 'is_correct')::boolean,
            v_score, v_grade ->> 'status', greatest(coalesce(p_elapsed_ms, 0), 0), v_tries, v_reveal)
    on conflict (attempt_id, question_id) do update
      set response = excluded.response, is_correct = excluded.is_correct, auto_score = excluded.auto_score,
          status = excluded.status, elapsed_ms = excluded.elapsed_ms, answered_at = now(),
          tries = excluded.tries, revealed = excluded.revealed;

  -- Live lessons: points, streak and totals, decided here on the server (0890).
  if v_attempt.session_id is not null then
    v_points := live_app.score_live_answer(v_attempt, v_q, v_act, (v_grade ->> 'is_correct')::boolean, v_tries, v_prev.points);
    update live.quiz_answers set points = (v_points ->> 'points')::int, response_ms = (v_points ->> 'response_ms')::int
     where attempt_id = p_attempt and question_id = p_question;
  end if;

  if v_instant and v_reveal then
    return jsonb_build_object('saved', true, 'status', v_grade ->> 'status', 'tries', v_tries,
                              'is_correct', (v_grade ->> 'is_correct')::boolean, 'score', v_score)
           || live_app.reveal_answer(v_q) || case when v_points is not null and v_feedback <> 'never' then jsonb_build_object('points', v_points) else '{}'::jsonb end;
  elsif v_instant then
    return jsonb_build_object('saved', true, 'status', v_grade ->> 'status', 'tries', v_tries,
                              'is_correct', false, 'second_chance', true);
  end if;
  -- No right answer (poll, open...): the participation points can be shown straight away.
  return jsonb_build_object('saved', true, 'status', v_grade ->> 'status')
         || case when (v_grade ->> 'is_correct') is null then case when v_points is not null and v_feedback <> 'never' then jsonb_build_object('points', v_points) else '{}'::jsonb end else '{}'::jsonb end;
end$$;

create or replace function live.finish_attempt(p_attempt uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_attempt live.quiz_attempts;
  v_act     live.activities;
  v_asg     live.assignments;
  v_no      int;
begin
  select * into v_attempt from live.quiz_attempts where id = p_attempt and student_id = auth.uid() for update;
  if v_attempt.id is null then raise exception 'Attempt not found.' using errcode = 'P0002'; end if;
  if v_attempt.status = 'in_progress' then
    update live.quiz_attempts set status = 'submitted', submitted_at = now() where id = p_attempt;
    perform live_app.recompute_attempt(p_attempt);
    if v_attempt.assignment_id is not null then
      select * into v_asg from live.assignments where id = v_attempt.assignment_id;
      select coalesce(max(attempt_no), 0) + 1 into v_no from live.submissions
       where assignment_id = v_asg.id and student_id = v_attempt.student_id;
      insert into live.submissions (tenant_id, assignment_id, student_id, attempt_no, attempt_id, is_late)
        values (v_attempt.tenant_id, v_asg.id, v_attempt.student_id, v_no, p_attempt,
                v_asg.due_at is not null and now() > v_asg.due_at);
    end if;
  end if;
  select * into v_attempt from live.quiz_attempts where id = p_attempt;
  select * into v_act from live.activities where id = v_attempt.activity_id;

  return jsonb_build_object(
    'attempt', jsonb_build_object('id', v_attempt.id, 'status', v_attempt.status, 'score', v_attempt.score,
                                  'max_score', v_attempt.max_score, 'submitted_at', v_attempt.submitted_at,
                                  'points', case when coalesce(v_act.settings ->> 'show_feedback', 'after_submit') = 'never' then null
                                                 else (select sum(points) from live.quiz_answers where attempt_id = p_attempt) end),
    'results', case when coalesce(v_act.settings ->> 'show_feedback', 'after_submit') = 'never' then null else (
       select coalesce(jsonb_agg(jsonb_build_object('question_id', a.question_id, 'is_correct', a.is_correct,
                        'score', coalesce(a.manual_score, a.auto_score), 'status', a.status, 'feedback', a.feedback)
                        || live_app.reveal_answer(q)), '[]'::jsonb)
       from live.quiz_answers a join live.questions q on q.id = a.question_id where a.attempt_id = p_attempt) end);
end$$;

create or replace function live.session_control(p_session uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions := live_app.require_live_session(p_session);
  v_n      int;
  v_target int;
  v_user   uuid;
  v_bad    text;
begin
  p_args := coalesce(p_args, '{}'::jsonb);
  case p_action
    when 'start' then
      if v_s.phase <> 'lobby' then raise exception 'The lesson has already started.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active', started_at = now() where id = p_session;
    when 'pause' then
      if v_s.phase <> 'active' then raise exception 'Only a running lesson can be paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'paused' where id = p_session;
    when 'resume' then
      if v_s.phase <> 'paused' then raise exception 'The lesson isn''t paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active' where id = p_session;
    when 'next', 'prev', 'goto' then
      if v_s.phase <> 'active' then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      select count(*) into v_n from live.lesson_slides where lesson_id = v_s.lesson_id;
      v_target := case p_action when 'next' then v_s.current_slide + 1 when 'prev' then v_s.current_slide - 1
                                else (p_args ->> 'slide')::int end;
      if v_target is null then raise exception 'Which slide?' using errcode = '22023'; end if;
      perform live.set_session_state(p_session, greatest(0, least(v_target, greatest(v_n - 1, 0))));
    when 'kick' then
      v_user := nullif(p_args ->> 'user_id', '')::uuid;
      if v_user is null or v_user = v_s.teacher_id then raise exception 'Who should be removed?' using errcode = '22023'; end if;
      update live.session_participants set removed_at = now(), left_at = now(), status = 'offline'
       where session_id = p_session and user_id = v_user and removed_at is null;
      if not found then raise exception 'That person isn''t in this lesson.' using errcode = 'P0002'; end if;
      update live.session_guests set removed_at = now() where session_id = p_session and user_id = v_user and removed_at is null;
      update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and student_id = v_user and status = 'open';
      perform live_app.audit('session.participant_removed', 'user', v_user::text, jsonb_build_object('session_id', p_session));
    when 'settings' then
      select k into v_bad from jsonb_object_keys(p_args) k
       where k <> all (array['leaderboard', 'anonymous_names', 'late_join', 'speed_bonus'])
          or jsonb_typeof(p_args -> k) <> 'boolean' limit 1;
      if v_bad is not null then raise exception 'Unknown or invalid setting: %.', v_bad using errcode = '22023'; end if;
      update live.class_sessions set settings = settings || p_args where id = p_session;
    when 'leaderboard' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      if coalesce((p_args ->> 'show')::boolean, true) then perform live_app.snapshot_leaderboard(p_session);
      else update live.class_sessions set show_leaderboard = false where id = p_session; end if;
    when 'end' then
      return live.end_session(p_session);
    else
      raise exception 'Unknown action: %.', p_action using errcode = '22023';
  end case;
  select * into v_s from live.class_sessions where id = p_session;
  return jsonb_build_object('phase', v_s.phase, 'slide', v_s.current_slide, 'settings', v_s.settings, 'v', v_s.state_version);
end$$;

create or replace function live.session_student_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_s     live.class_sessions;
  v_p     live.session_participants;
  v_spot  live.spotlights;
  v_act   live.activities;
  v_pass  live.session_guests;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if exists (select 1 from live.session_participants where session_id = p_session and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_p from live.session_participants where session_id = p_session and user_id = v_me.id;
  if v_p.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
  select * into v_pass from live.session_guests where session_id = p_session and user_id = v_me.id;
  if v_s.status = 'live' then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
      on conflict (session_id, user_id) do update set last_seen_at = now(), left_at = null,
        status = case when live.session_participants.status = 'offline' then 'online' else live.session_participants.status end
      returning * into v_p;
  end if;
  select * into v_spot from live.spotlights where session_id = p_session and ended_at is null;
  select * into v_act from live.activities where id = v_s.active_activity_id;

  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'phase', v_s.phase, 'mode', v_s.mode,
                                  'join_code', v_s.join_code, 'settings', v_s.settings,
                                  'current_slide', v_s.current_slide, 'group_chat_enabled', v_s.group_chat_enabled and v_me.role <> 'guest',
                                  'responses_visible', v_s.responses_visible, 'class_id', v_s.class_id,
                                  'teacher', (select full_name from live.users where id = v_s.teacher_id),
                                  'environment_active', v_s.environment_active),
    'my_slide', coalesce(v_p.current_slide, v_s.current_slide),
    'active_activity', case when v_act.id is null then null else jsonb_build_object(
                         'id', v_act.id, 'kind', v_act.kind, 'title', v_act.title) end,
    'spotlight', case when v_spot.id is null then null else jsonb_build_object(
                   'me', v_spot.student_id = v_me.id, 'show_to_class', v_spot.show_to_class, 'anonymized', v_spot.anonymized) end,
    'hand', (select jsonb_build_object('id', h.id, 'created_at', h.created_at) from live.raise_hands h
             where h.session_id = p_session and h.student_id = v_me.id and h.status = 'open'),
    'environment_notice', case when exists (select 1 from live.environment_events e where e.class_session_id = p_session
                                            and e.student_id = v_me.id and e.resolved_at is null
                                            and e.kind in ('environment_left','domain_blocked'))
                               then 'Your class session requires you to return to the lesson.' end,
    'device_monitored', exists (select 1 from live.browser_sessions b where b.class_session_id = p_session
                                and b.student_id = v_me.id and b.last_heartbeat_at > now() - interval '45 seconds'),
    'announcements', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at)
                       order by a.created_at desc), '[]'::jsonb)
                      from (select * from live.announcements where session_id = p_session order by created_at desc limit 5) a),
    'guest', v_me.role = 'guest',
    -- Own score and rank only; the class sees the top 5 when the teacher shows the board.
    'my', (select jsonb_build_object('score', r.score, 'rank', r.rank, 'streak', r.streak,
                                     'of', (select count(*) from live_app.session_ranks(p_session)))
             from live_app.session_ranks(p_session) r where r.user_id = v_me.id),
    'leaderboard', case when v_s.show_leaderboard and coalesce((v_s.settings ->> 'leaderboard')::boolean, true) then
      (select coalesce(jsonb_agg(e order by (e ->> 'rank')::int), '[]'::jsonb) from jsonb_array_elements(v_s.leaderboard -> 'top') e
        where (e ->> 'rank')::int <= 5) end,
    'me', jsonb_build_object('name', coalesce(v_pass.display_name, v_me.full_name), 'avatar', v_p.avatar),
    'participants', (select count(*) from live.session_participants sp
                      where sp.session_id = p_session and sp.user_id <> v_s.teacher_id and sp.left_at is null and sp.removed_at is null
                        and sp.last_seen_at > now() - live_app.presence_window()),
    'summary', case when v_s.status = 'ended' then (
       select jsonb_build_object('answered', count(*), 'correct', count(*) filter (where a.is_correct))
         from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        where t.session_id = p_session and t.student_id = v_me.id) end,
    'server_now', now());
end$$;

create or replace function live.teacher_session_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_settings live.tenant_settings;
  r          live.browser_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_settings from live.tenant_settings where tenant_id = v_s.tenant_id;

  if v_s.status = 'live' then
    -- Students only send screen frames while a teacher is watching (throttled write).
    if v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '20 seconds' then
      update live.class_sessions set teacher_seen_at = now() where id = p_session;
    end if;
    for r in update live.browser_sessions set connection_lost_at = now()
             where class_session_id = p_session and ended_at is null and connection_lost_at is null
               and last_heartbeat_at < now() - interval '45 seconds'
             returning * loop
      perform live_app.raise_event(r, v_s, v_s.environment_id, 'connection_lost', 'info',
                              'Extension stopped reporting — connection lost, not a rule violation', null, null);
    end loop;
    perform live_app.web_leave_check(v_s);
    update live.teacher_commands set status = 'expired'
     where class_session_id = p_session and status in ('queued','delivered') and expires_at < now();
  end if;

  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object(
      'class_name', (select name from live.classes where id = v_s.class_id),
      'lesson_title', (select title from live.lessons where id = v_s.lesson_id),
      'environment_name', (select name from live.environment_policies where id = v_s.environment_id)),
    'settings', jsonb_build_object('monitoring_enabled', v_settings.monitoring_enabled, 'allow_spotlight', v_settings.allow_spotlight, 'allow_group_chat', v_settings.allow_group_chat,
                                   'allow_screen_capture', v_settings.allow_screen_capture,
                                   'store_event_screenshots', v_settings.store_event_screenshots,
                                   'thumbnail_interval_seconds', v_settings.thumbnail_interval_seconds),
    'server_now', now(),
    'roster', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name, 'guest', m.guest, 'avatar', p.avatar,
        'score', coalesce(p.total_score, 0), 'streak', coalesce(p.streak, 0),
        'presence', case when p.user_id is null then 'not_joined'
                         when p.left_at is not null or p.last_seen_at < now() - live_app.presence_window() then 'offline'
                         else p.status end,
        'last_seen_at', p.last_seen_at, 'current_slide', p.current_slide,
        'web', case when p.user_id is null then null else jsonb_build_object(
                 'sharing', p.screen_sharing and p.last_seen_at > now() - live_app.presence_window(),
                 'unsupported', p.share_unsupported, 'surface', p.screen_surface,
                 'visible', p.tab_visible, 'fullscreen', p.fullscreen,
                 'away_since', p.away_since, 'away_reason', p.away_reason) end,
        'device', (select jsonb_build_object('device_id', b.device_id, 'url', b.active_url, 'domain', b.active_domain,
                     'title', b.active_title, 'tab_count', b.tab_count, 'idle_state', b.idle_state,
                     'online', b.connection_lost_at is null and b.last_heartbeat_at > now() - interval '45 seconds',
                     'last_heartbeat_at', b.last_heartbeat_at, 'focus_locked', b.focus_locked,
                     'violation', b.violation_rule, 'violation_since', b.violation_since,
                     'snapshot_at', (select max(sn.captured_at) from live.screen_snapshots sn
                                     where sn.student_id = u.id and sn.class_session_id = p_session and sn.quality = 'thumbnail'))
                   from live.browser_sessions b where b.class_session_id = p_session and b.student_id = u.id
                   order by b.last_heartbeat_at desc limit 1),
        'open_alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session
                        and e.student_id = u.id and e.status = 'open'),
        'hand_raised', exists (select 1 from live.raise_hands h where h.session_id = p_session and h.student_id = u.id and h.status = 'open'))
        order by u.full_name), '[]'::jsonb)
      from (select cm.user_id, false as guest from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, g.is_guest from live.session_guests g where g.session_id = p_session and g.removed_at is null) m
      join live.users u on u.id = m.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = u.id),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'severity', e.severity, 'rule', e.rule,
                 'domain', e.domain, 'confidence', e.confidence, 'status', e.status, 'student_id', e.student_id,
                 'student', u.full_name, 'created_at', e.created_at, 'resolved_at', e.resolved_at,
                 'has_evidence', e.evidence_image is not null)
                 order by e.created_at desc), '[]'::jsonb)
               from (select * from live.environment_events where class_session_id = p_session
                     and (status = 'open' or created_at > now() - interval '10 minutes') order by created_at desc limit 50) e
               join live.users u on u.id = e.student_id),
    'hands', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'student_id', h.student_id, 'student', u.full_name,
                'message', h.message, 'created_at', h.created_at) order by h.created_at), '[]'::jsonb)
              from live.raise_hands h join live.users u on u.id = h.student_id
              where h.session_id = p_session and h.status = 'open'),
    'commands', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'status', c.status, 'error', c.error,
                   'student', u.full_name, 'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
                 from (select * from live.teacher_commands where class_session_id = p_session order by created_at desc limit 20) c
                 join live.users u on u.id = c.student_id),
    'spotlight', (select jsonb_build_object('id', s.id, 'student_id', s.student_id, 'anonymized', s.anonymized,
                    'show_to_class', s.show_to_class, 'started_at', s.started_at)
                  from live.spotlights s where s.session_id = p_session and s.ended_at is null),
    'ranking', (select coalesce(jsonb_agg(jsonb_build_object('user_id', rk.user_id, 'name', rk.name, 'avatar', rk.avatar,
                   'score', rk.score, 'rank', rk.rank, 'streak', rk.streak) order by rk.rank, rk.name), '[]'::jsonb)
                from (select * from live_app.session_ranks(p_session) order by rank, name limit 10) rk),
    'activity', case when v_s.active_activity_id is null then null
                     else live.activity_results(v_s.active_activity_id, p_session) end);
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0890')
$$;

-- ===================== 20260901000900_reveal.sql =====================
-- 0900: reveal and live answer counts (docs/LIVE_ENGINE.md, increment 4).
--
-- * session_control 'reveal' closes the activity on screen: unfinished attempts are
--   submitted as they stand, no further answers are accepted, and everyone sees the
--   right answers with the distribution (responses_visible).
-- * Students see which options were right only after the reveal.
-- * Fix: changing results sharing, chat or mode no longer resets the slide to 1.
-- * The teacher's state reports the activity on screen (launched, or on the current
--   slide) with answered / joined counts and whether it has been revealed.

alter table live.class_sessions add column if not exists revealed_activity_id uuid;

create or replace function live.session_control(p_session uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions := live_app.require_live_session(p_session);
  v_n      int;
  v_target int;
  v_user   uuid;
  v_bad    text;
  v_act    uuid;
  v_att    uuid;
begin
  p_args := coalesce(p_args, '{}'::jsonb);
  case p_action
    when 'start' then
      if v_s.phase <> 'lobby' then raise exception 'The lesson has already started.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active', started_at = now() where id = p_session;
    when 'pause' then
      if v_s.phase <> 'active' then raise exception 'Only a running lesson can be paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'paused' where id = p_session;
    when 'resume' then
      if v_s.phase <> 'paused' then raise exception 'The lesson isn''t paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active' where id = p_session;
    when 'next', 'prev', 'goto' then
      if v_s.phase <> 'active' then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      select count(*) into v_n from live.lesson_slides where lesson_id = v_s.lesson_id;
      v_target := case p_action when 'next' then v_s.current_slide + 1 when 'prev' then v_s.current_slide - 1
                                else (p_args ->> 'slide')::int end;
      if v_target is null then raise exception 'Which slide?' using errcode = '22023'; end if;
      perform live.set_session_state(p_session, greatest(0, least(v_target, greatest(v_n - 1, 0))));
    when 'kick' then
      v_user := nullif(p_args ->> 'user_id', '')::uuid;
      if v_user is null or v_user = v_s.teacher_id then raise exception 'Who should be removed?' using errcode = '22023'; end if;
      update live.session_participants set removed_at = now(), left_at = now(), status = 'offline'
       where session_id = p_session and user_id = v_user and removed_at is null;
      if not found then raise exception 'That person isn''t in this lesson.' using errcode = 'P0002'; end if;
      update live.session_guests set removed_at = now() where session_id = p_session and user_id = v_user and removed_at is null;
      update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and student_id = v_user and status = 'open';
      perform live_app.audit('session.participant_removed', 'user', v_user::text, jsonb_build_object('session_id', p_session));
    when 'settings' then
      select k into v_bad from jsonb_object_keys(p_args) k
       where k <> all (array['leaderboard', 'anonymous_names', 'late_join', 'speed_bonus'])
          or jsonb_typeof(p_args -> k) <> 'boolean' limit 1;
      if v_bad is not null then raise exception 'Unknown or invalid setting: %.', v_bad using errcode = '22023'; end if;
      update live.class_sessions set settings = settings || p_args where id = p_session;
    when 'leaderboard' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      if coalesce((p_args ->> 'show')::boolean, true) then perform live_app.snapshot_leaderboard(p_session);
      else update live.class_sessions set show_leaderboard = false where id = p_session; end if;
    when 'reveal' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      v_act := coalesce(nullif(p_args ->> 'activity_id', '')::uuid, v_s.active_activity_id,
                        (select sl.activity_id from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id and sl.position = v_s.current_slide));
      if v_act is null then raise exception 'There is no activity on this slide to reveal.' using errcode = 'P0001'; end if;
      -- Answers close: unfinished attempts are submitted as they stand, then everyone sees the result.
      for v_att in select id from live.quiz_attempts where session_id = p_session and activity_id = v_act and status = 'in_progress' loop
        update live.quiz_attempts set status = 'submitted', submitted_at = now() where id = v_att;
        perform live_app.recompute_attempt(v_att);
      end loop;
      update live.class_sessions set revealed_activity_id = v_act, responses_visible = true where id = p_session;
    when 'end' then
      return live.end_session(p_session);
    else
      raise exception 'Unknown action: %.', p_action using errcode = '22023';
  end case;
  select * into v_s from live.class_sessions where id = p_session;
  return jsonb_build_object('phase', v_s.phase, 'slide', v_s.current_slide, 'settings', v_s.settings, 'v', v_s.state_version);
end$$;

create or replace function live_app.attempt_context_ok(
  p_activity live.activities, p_session uuid, p_assignment uuid, p_share text
) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare v_s live.class_sessions; v_a live.assignments;
begin
  if p_session is not null then
    select * into v_s from live.class_sessions where id = p_session;
    -- coalesce: a NULL active_activity_id must mean "no", never "unknown".
    return coalesce(v_s.id is not null and v_s.status = 'live' and v_s.phase = 'active'
       and v_s.revealed_activity_id is distinct from p_activity.id and (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id))
       and (v_s.active_activity_id = p_activity.id
            or (p_activity.lesson_id is not null and p_activity.lesson_id = v_s.lesson_id
                and (v_s.mode = 'student_paced'
                     or exists (select 1 from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id
                                and sl.activity_id = p_activity.id and sl.position = v_s.current_slide)
                     or exists (select 1 from live.video_checkpoints vc
                                join live.questions q on q.id = vc.question_id
                                join live.lesson_slides sl on sl.id = vc.slide_id
                                where q.activity_id = p_activity.id and sl.lesson_id = v_s.lesson_id)))), false);
  elsif p_assignment is not null then
    select * into v_a from live.assignments where id = p_assignment;
    return coalesce(v_a.id is not null and v_a.status = 'published' and v_a.activity_id = p_activity.id
       and live_app.in_class(v_a.class_id)
       and (v_a.due_at is null or v_a.due_at > now() or v_a.allow_late), false);
  elsif p_share is not null then
    return coalesce(p_activity.lesson_id = (live_app.valid_share(p_share)).lesson_id, false);
  end if;
  return false;
end$$;

create or replace function live.submit_answer(
  p_attempt uuid, p_question uuid, p_response jsonb, p_elapsed_ms int default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me       live.users := live_app.me();
  v_attempt  live.quiz_attempts;
  v_act      live.activities;
  v_q        live.questions;
  v_prev     live.quiz_answers;
  v_grade    jsonb;
  v_feedback text;
  v_instant  boolean;
  v_second   boolean;
  v_tries    smallint := 1;
  v_score    numeric;
  v_reveal   boolean;
  v_points   jsonb;
begin
  select * into v_attempt from live.quiz_attempts where id = p_attempt and student_id = v_me.id for update;
  if v_attempt.id is null then raise exception 'Attempt not found.' using errcode = 'P0002'; end if;
  if v_attempt.status <> 'in_progress' then raise exception 'This attempt has already been submitted.' using errcode = 'P0001'; end if;
  if v_attempt.session_id is not null and exists (select 1 from live.class_sessions cs where cs.id = v_attempt.session_id
                                                   and cs.revealed_activity_id = v_attempt.activity_id) then
    raise exception 'The answers have been revealed: this activity is closed.' using errcode = 'P0001';
  end if;
  if v_attempt.deadline_at is not null and now() > v_attempt.deadline_at + interval '5 seconds' then
    perform live.finish_attempt(p_attempt);
    raise exception 'Time is up — your attempt was submitted.' using errcode = 'P0001';
  end if;
  if length(p_response::text) > 200000 then raise exception 'Response is too large.' using errcode = '22023'; end if;

  select * into v_q from live.questions where id = p_question and activity_id = v_attempt.activity_id;
  if v_q.id is null then raise exception 'Question not in this activity.' using errcode = 'P0002'; end if;
  select * into v_act from live.activities where id = v_attempt.activity_id;
  v_feedback := coalesce(v_act.settings ->> 'show_feedback', 'after_submit');
  v_second := coalesce((v_act.settings ->> 'redemption')::boolean, false);
  v_grade := live_app.grade_response(v_q, p_response);
  v_instant := v_feedback = 'immediately' and v_grade ->> 'status' = 'auto_graded';
  v_score := (v_grade ->> 'score')::numeric;

  select * into v_prev from live.quiz_answers where attempt_id = p_attempt and question_id = p_question;
  if v_prev.id is not null then
    -- Once the correct answer has been shown, the answer is final.
    if v_prev.revealed then
      raise exception 'You have already answered this question. Move on to the next one.' using errcode = 'P0001';
    end if;
    -- Second chance: only after a wrong first try with instant feedback. Worth half,
    -- but never less than any partial credit the first try already earned.
    if v_instant and v_second and v_prev.is_correct is false and v_prev.tries = 1 then
      v_tries := 2;
      v_score := greatest(round(coalesce(v_score, 0) * 0.5, 2), coalesce(v_prev.auto_score, 0));
    end if;
  end if;

  -- With a second chance on, a wrong first try says "not quite" without showing the answer.
  v_reveal := v_instant and not (v_second and v_tries = 1 and (v_grade ->> 'is_correct')::boolean is false);

  insert into live.quiz_answers (tenant_id, attempt_id, question_id, response, is_correct, auto_score, status, elapsed_ms, tries, revealed)
    values (v_me.tenant_id, p_attempt, p_question, p_response, (v_grade ->> 'is_correct')::boolean,
            v_score, v_grade ->> 'status', greatest(coalesce(p_elapsed_ms, 0), 0), v_tries, v_reveal)
    on conflict (attempt_id, question_id) do update
      set response = excluded.response, is_correct = excluded.is_correct, auto_score = excluded.auto_score,
          status = excluded.status, elapsed_ms = excluded.elapsed_ms, answered_at = now(),
          tries = excluded.tries, revealed = excluded.revealed;

  -- Live lessons: points, streak and totals, decided here on the server (0890).
  if v_attempt.session_id is not null then
    v_points := live_app.score_live_answer(v_attempt, v_q, v_act, (v_grade ->> 'is_correct')::boolean, v_tries, v_prev.points);
    update live.quiz_answers set points = (v_points ->> 'points')::int, response_ms = (v_points ->> 'response_ms')::int
     where attempt_id = p_attempt and question_id = p_question;
  end if;

  if v_instant and v_reveal then
    return jsonb_build_object('saved', true, 'status', v_grade ->> 'status', 'tries', v_tries,
                              'is_correct', (v_grade ->> 'is_correct')::boolean, 'score', v_score)
           || live_app.reveal_answer(v_q) || case when v_points is not null and v_feedback <> 'never' then jsonb_build_object('points', v_points) else '{}'::jsonb end;
  elsif v_instant then
    return jsonb_build_object('saved', true, 'status', v_grade ->> 'status', 'tries', v_tries,
                              'is_correct', false, 'second_chance', true);
  end if;
  -- No right answer (poll, open...): the participation points can be shown straight away.
  return jsonb_build_object('saved', true, 'status', v_grade ->> 'status')
         || case when (v_grade ->> 'is_correct') is null then case when v_points is not null and v_feedback <> 'never' then jsonb_build_object('points', v_points) else '{}'::jsonb end else '{}'::jsonb end;
end$$;

create or replace function live.session_student_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_s     live.class_sessions;
  v_p     live.session_participants;
  v_spot  live.spotlights;
  v_act   live.activities;
  v_pass  live.session_guests;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if exists (select 1 from live.session_participants where session_id = p_session and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_p from live.session_participants where session_id = p_session and user_id = v_me.id;
  if v_p.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
  select * into v_pass from live.session_guests where session_id = p_session and user_id = v_me.id;
  if v_s.status = 'live' then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
      on conflict (session_id, user_id) do update set last_seen_at = now(), left_at = null,
        status = case when live.session_participants.status = 'offline' then 'online' else live.session_participants.status end
      returning * into v_p;
  end if;
  select * into v_spot from live.spotlights where session_id = p_session and ended_at is null;
  select * into v_act from live.activities where id = v_s.active_activity_id;

  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'phase', v_s.phase, 'mode', v_s.mode,
                                  'join_code', v_s.join_code, 'settings', v_s.settings,
                                  'current_slide', v_s.current_slide, 'group_chat_enabled', v_s.group_chat_enabled and v_me.role <> 'guest',
                                  'responses_visible', v_s.responses_visible, 'class_id', v_s.class_id,
                                  'teacher', (select full_name from live.users where id = v_s.teacher_id),
                                  'environment_active', v_s.environment_active),
    'my_slide', coalesce(v_p.current_slide, v_s.current_slide),
    'active_activity', case when v_act.id is null then null else jsonb_build_object(
                         'id', v_act.id, 'kind', v_act.kind, 'title', v_act.title) end,
    'spotlight', case when v_spot.id is null then null else jsonb_build_object(
                   'me', v_spot.student_id = v_me.id, 'show_to_class', v_spot.show_to_class, 'anonymized', v_spot.anonymized) end,
    'hand', (select jsonb_build_object('id', h.id, 'created_at', h.created_at) from live.raise_hands h
             where h.session_id = p_session and h.student_id = v_me.id and h.status = 'open'),
    'environment_notice', case when exists (select 1 from live.environment_events e where e.class_session_id = p_session
                                            and e.student_id = v_me.id and e.resolved_at is null
                                            and e.kind in ('environment_left','domain_blocked'))
                               then 'Your class session requires you to return to the lesson.' end,
    'device_monitored', exists (select 1 from live.browser_sessions b where b.class_session_id = p_session
                                and b.student_id = v_me.id and b.last_heartbeat_at > now() - interval '45 seconds'),
    'announcements', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at)
                       order by a.created_at desc), '[]'::jsonb)
                      from (select * from live.announcements where session_id = p_session order by created_at desc limit 5) a),
    'guest', v_me.role = 'guest',
    'revealed_activity_id', v_s.revealed_activity_id,
    -- Own score and rank only; the class sees the top 5 when the teacher shows the board.
    'my', (select jsonb_build_object('score', r.score, 'rank', r.rank, 'streak', r.streak,
                                     'of', (select count(*) from live_app.session_ranks(p_session)))
             from live_app.session_ranks(p_session) r where r.user_id = v_me.id),
    'leaderboard', case when v_s.show_leaderboard and coalesce((v_s.settings ->> 'leaderboard')::boolean, true) then
      (select coalesce(jsonb_agg(e order by (e ->> 'rank')::int), '[]'::jsonb) from jsonb_array_elements(v_s.leaderboard -> 'top') e
        where (e ->> 'rank')::int <= 5) end,
    'me', jsonb_build_object('name', coalesce(v_pass.display_name, v_me.full_name), 'avatar', v_p.avatar),
    'participants', (select count(*) from live.session_participants sp
                      where sp.session_id = p_session and sp.user_id <> v_s.teacher_id and sp.left_at is null and sp.removed_at is null
                        and sp.last_seen_at > now() - live_app.presence_window()),
    'summary', case when v_s.status = 'ended' then (
       select jsonb_build_object('answered', count(*), 'correct', count(*) filter (where a.is_correct))
         from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        where t.session_id = p_session and t.student_id = v_me.id) end,
    'server_now', now());
end$$;

create or replace function live.activity_results(p_activity uuid, p_session uuid default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_act live.activities;
begin
  select * into v_act from live.activities where id = p_activity;
  if v_act.id is null then raise exception 'Activity not found.' using errcode = 'P0002'; end if;
  if p_session is not null then
    if not live_app.can_manage_session(p_session) then
      -- Students may see anonymised aggregates when the teacher shares results.
      if not (live_app.in_session(p_session) and exists (select 1 from live.class_sessions s
              where s.id = p_session and s.responses_visible)) then
        raise exception 'Not your session.' using errcode = '42501';
      end if;
      return (select jsonb_build_object('questions', coalesce(jsonb_agg(jsonb_build_object(
                'question_id', q.id, 'prompt', q.prompt, 'kind', q.kind,
                'options', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'label', o.label,
                              -- Right answers only once the teacher has revealed them (0900).
                              'is_correct', case when exists (select 1 from live.class_sessions cs where cs.id = p_session
                                                               and cs.revealed_activity_id = p_activity) then o.is_correct end,
                              'count', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                                        where a.question_id = q.id and t.session_id = p_session and a.response ->> 'option_id' = o.id::text))
                              order by o.position), '[]'::jsonb) from live.question_options o where o.question_id = q.id))
              order by q.position), '[]'::jsonb))
              from live.questions q where q.activity_id = p_activity);
    end if;
  elsif not live_app.can_view_activity(p_activity) then
    raise exception 'Not visible to you.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'activity', jsonb_build_object('id', v_act.id, 'title', v_act.title, 'kind', v_act.kind),
    'attempts', (select count(*) from live.quiz_attempts t where t.activity_id = p_activity
                 and (p_session is null or t.session_id = p_session)),
    'submitted', (select count(*) from live.quiz_attempts t where t.activity_id = p_activity and t.status <> 'in_progress'
                  and (p_session is null or t.session_id = p_session)),
    'questions', (select coalesce(jsonb_agg(jsonb_build_object(
        'question_id', q.id, 'prompt', q.prompt, 'kind', q.kind, 'points', q.points,
        'responses', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                      where a.question_id = q.id and (p_session is null or t.session_id = p_session)),
        'correct', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                    where a.question_id = q.id and a.is_correct and (p_session is null or t.session_id = p_session)),
        'avg_elapsed_ms', (select round(avg(a.elapsed_ms)) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                           where a.question_id = q.id and (p_session is null or t.session_id = p_session)),
        'options', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'label', o.label, 'is_correct', o.is_correct,
                      'count', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                                where a.question_id = q.id and (p_session is null or t.session_id = p_session)
                                  and (a.response ->> 'option_id' = o.id::text or a.response -> 'option_ids' ? o.id::text)))
                      order by o.position), '[]'::jsonb) from live.question_options o where o.question_id = q.id),
        'text_responses', (select coalesce(jsonb_agg(jsonb_build_object('student', u.full_name, 'response', a.response,
                             'status', a.status, 'answer_id', a.id) order by a.answered_at), '[]'::jsonb)
                           from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                           join live.users u on u.id = t.student_id
                           where a.question_id = q.id and q.kind in ('open','short','fill_blank','draw','code','file')
                             and (p_session is null or t.session_id = p_session)))
        order by q.position, q.created_at), '[]'::jsonb)
      from live.questions q where q.activity_id = p_activity));
end$$;

create or replace function live.teacher_session_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_settings live.tenant_settings;
  r          live.browser_sessions;
  v_cur      uuid;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_settings from live.tenant_settings where tenant_id = v_s.tenant_id;

  if v_s.status = 'live' then
    -- Students only send screen frames while a teacher is watching (throttled write).
    if v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '20 seconds' then
      update live.class_sessions set teacher_seen_at = now() where id = p_session;
    end if;
    for r in update live.browser_sessions set connection_lost_at = now()
             where class_session_id = p_session and ended_at is null and connection_lost_at is null
               and last_heartbeat_at < now() - interval '45 seconds'
             returning * loop
      perform live_app.raise_event(r, v_s, v_s.environment_id, 'connection_lost', 'info',
                              'Extension stopped reporting — connection lost, not a rule violation', null, null);
    end loop;
    perform live_app.web_leave_check(v_s);
    update live.teacher_commands set status = 'expired'
     where class_session_id = p_session and status in ('queued','delivered') and expires_at < now();
  end if;

  -- The activity on screen: the one launched, or the one on the current slide.
  v_cur := coalesce(v_s.active_activity_id,
                    (select sl.activity_id from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id and sl.position = v_s.current_slide));
  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object(
      'class_name', (select name from live.classes where id = v_s.class_id),
      'lesson_title', (select title from live.lessons where id = v_s.lesson_id),
      'environment_name', (select name from live.environment_policies where id = v_s.environment_id)),
    'settings', jsonb_build_object('monitoring_enabled', v_settings.monitoring_enabled, 'allow_spotlight', v_settings.allow_spotlight, 'allow_group_chat', v_settings.allow_group_chat,
                                   'allow_screen_capture', v_settings.allow_screen_capture,
                                   'store_event_screenshots', v_settings.store_event_screenshots,
                                   'thumbnail_interval_seconds', v_settings.thumbnail_interval_seconds),
    'server_now', now(),
    'roster', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name, 'guest', m.guest, 'avatar', p.avatar,
        'score', coalesce(p.total_score, 0), 'streak', coalesce(p.streak, 0),
        'presence', case when p.user_id is null then 'not_joined'
                         when p.left_at is not null or p.last_seen_at < now() - live_app.presence_window() then 'offline'
                         else p.status end,
        'last_seen_at', p.last_seen_at, 'current_slide', p.current_slide,
        'web', case when p.user_id is null then null else jsonb_build_object(
                 'sharing', p.screen_sharing and p.last_seen_at > now() - live_app.presence_window(),
                 'unsupported', p.share_unsupported, 'surface', p.screen_surface,
                 'visible', p.tab_visible, 'fullscreen', p.fullscreen,
                 'away_since', p.away_since, 'away_reason', p.away_reason) end,
        'device', (select jsonb_build_object('device_id', b.device_id, 'url', b.active_url, 'domain', b.active_domain,
                     'title', b.active_title, 'tab_count', b.tab_count, 'idle_state', b.idle_state,
                     'online', b.connection_lost_at is null and b.last_heartbeat_at > now() - interval '45 seconds',
                     'last_heartbeat_at', b.last_heartbeat_at, 'focus_locked', b.focus_locked,
                     'violation', b.violation_rule, 'violation_since', b.violation_since,
                     'snapshot_at', (select max(sn.captured_at) from live.screen_snapshots sn
                                     where sn.student_id = u.id and sn.class_session_id = p_session and sn.quality = 'thumbnail'))
                   from live.browser_sessions b where b.class_session_id = p_session and b.student_id = u.id
                   order by b.last_heartbeat_at desc limit 1),
        'open_alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session
                        and e.student_id = u.id and e.status = 'open'),
        'hand_raised', exists (select 1 from live.raise_hands h where h.session_id = p_session and h.student_id = u.id and h.status = 'open'))
        order by u.full_name), '[]'::jsonb)
      from (select cm.user_id, false as guest from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, g.is_guest from live.session_guests g where g.session_id = p_session and g.removed_at is null) m
      join live.users u on u.id = m.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = u.id),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'severity', e.severity, 'rule', e.rule,
                 'domain', e.domain, 'confidence', e.confidence, 'status', e.status, 'student_id', e.student_id,
                 'student', u.full_name, 'created_at', e.created_at, 'resolved_at', e.resolved_at,
                 'has_evidence', e.evidence_image is not null)
                 order by e.created_at desc), '[]'::jsonb)
               from (select * from live.environment_events where class_session_id = p_session
                     and (status = 'open' or created_at > now() - interval '10 minutes') order by created_at desc limit 50) e
               join live.users u on u.id = e.student_id),
    'hands', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'student_id', h.student_id, 'student', u.full_name,
                'message', h.message, 'created_at', h.created_at) order by h.created_at), '[]'::jsonb)
              from live.raise_hands h join live.users u on u.id = h.student_id
              where h.session_id = p_session and h.status = 'open'),
    'commands', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'status', c.status, 'error', c.error,
                   'student', u.full_name, 'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
                 from (select * from live.teacher_commands where class_session_id = p_session order by created_at desc limit 20) c
                 join live.users u on u.id = c.student_id),
    'spotlight', (select jsonb_build_object('id', s.id, 'student_id', s.student_id, 'anonymized', s.anonymized,
                    'show_to_class', s.show_to_class, 'started_at', s.started_at)
                  from live.spotlights s where s.session_id = p_session and s.ended_at is null),
    'ranking', (select coalesce(jsonb_agg(jsonb_build_object('user_id', rk.user_id, 'name', rk.name, 'avatar', rk.avatar,
                   'score', rk.score, 'rank', rk.rank, 'streak', rk.streak) order by rk.rank, rk.name), '[]'::jsonb)
                from (select * from live_app.session_ranks(p_session) order by rank, name limit 10) rk),
    'activity', case when v_cur is null then null
                     else live.activity_results(v_cur, p_session) || jsonb_build_object(
                       'answered', (select count(distinct t.student_id) from live.quiz_attempts t
                                     where t.session_id = p_session and t.activity_id = v_cur
                                       and exists (select 1 from live.quiz_answers a where a.attempt_id = t.id)),
                       'joined', (select count(*) from live.session_participants sp where sp.session_id = p_session
                                   and sp.user_id <> v_s.teacher_id and sp.removed_at is null and sp.left_at is null),
                       'revealed', v_s.revealed_activity_id is not distinct from v_cur) end);
end$$;

create or replace function live.set_session_state(
  p_session uuid, p_slide int default null, p_activity uuid default null, p_clear_activity boolean default false,
  p_group_chat boolean default null, p_responses_visible boolean default null, p_mode text default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions := live_app.require_live_session(p_session); v_allow boolean;
begin
  if p_activity is not null and not exists (select 1 from live.activities where id = p_activity and tenant_id = v_s.tenant_id) then
    raise exception 'Activity not found.' using errcode = 'P0002';
  end if;
  if p_group_chat then
    select allow_group_chat into v_allow from live.tenant_settings where tenant_id = v_s.tenant_id;
    if not v_allow then raise exception 'Group chat is disabled by your school.' using errcode = 'P0001'; end if;
  end if;
  if p_mode is not null and p_mode not in ('live_participation','student_paced','front_of_class') then
    raise exception 'Unknown delivery mode.' using errcode = '22023';
  end if;
  update live.class_sessions set
    -- greatest(NULL, 0) is 0 in Postgres: without this, any change that didn't name a slide
    -- (sharing results, chat, mode) sent the whole class back to the first slide.
    current_slide = case when p_slide is null then current_slide else greatest(p_slide, 0) end,
    active_activity_id = case when p_clear_activity then null else coalesce(p_activity, active_activity_id) end,
    group_chat_enabled = coalesce(p_group_chat, group_chat_enabled),
    responses_visible = coalesce(p_responses_visible, responses_visible),
    mode = coalesce(p_mode, mode)
  where id = p_session returning * into v_s;
  if p_slide is not null and v_s.mode <> 'student_paced' then
    update live.session_participants set current_slide = v_s.current_slide where session_id = p_session;
  end if;
  if p_activity is not null then
    perform live_app.audit('activity.launched', 'activity', p_activity::text, jsonb_build_object('session_id', p_session));
  end if;
  return to_jsonb(v_s);
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0900')
$$;

-- ===================== 20260901000910_canvas_slides.sql =====================
-- 0910: designed slides (docs/LIVE_ENGINE.md, deck builder).
--
-- * A new slide kind, 'canvas': a 16:9 slide laid out freely with text boxes,
--   pictures and shapes, like a PowerPoint slide. Its content is
--   { background: {color, media_path}, elements: [...] } in a 1600 x 900 grid.
-- * Slide content is capped at 256 KB so one slide can't bloat a lesson
--   (existing slides are not checked).
-- * Guests in a live lesson can see the pictures on its designed slides.

alter table live.lesson_slides drop constraint if exists lesson_slides_kind_check;alter table live.lesson_slides drop constraint if exists lesson_slides_kind_check;

alter table live.lesson_slides add constraint lesson_slides_kind_check check (kind in (
  'title','text','image','video','audio','embed','link','attachment',
  'shapes','whiteboard','activity','canvas'));

alter table live.lesson_slides drop constraint if exists lesson_slides_content_size;alter table live.lesson_slides drop constraint if exists lesson_slides_content_size;

alter table live.lesson_slides add constraint lesson_slides_content_size
  check (octet_length(content::text) <= 262144) not valid;

-- Guests may read the pictures placed on designed slides (and their background) in their live lesson.
create or replace function live_app.guest_can_read_media(p_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.session_guests g
      join live.class_sessions s on s.id = g.session_id and s.status = 'live'
     where g.user_id = auth.uid() and g.removed_at is null and s.lesson_id is not null
       and (exists (select 1 from live.lesson_slides sl where sl.lesson_id = s.lesson_id
                    and (p_name in (sl.content ->> 'media_path', sl.content ->> 'captions_path', sl.content -> 'background' ->> 'media_path')
                         or sl.content @> jsonb_build_object('elements', jsonb_build_array(jsonb_build_object('media_path', p_name)))))
            or exists (select 1 from live.lesson_media lm where lm.lesson_id = s.lesson_id and lm.storage_path = p_name)))
$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0910')
$$;

-- ===================== 20260901000920_session_report.sql =====================
-- 0920: the session report (docs/LIVE_ENGINE.md, report and proof).
--
-- * Everyone who took part is in the report: the class's students and anyone
--   who joined with the code (guests and students without the class). Before,
--   only the class was listed, so code-only lessons had an empty report.
-- * Each participant: joined, final score and rank, best streak, questions
--   answered, correct, accuracy and average answer time.
-- * Each question, in slide order: how many answered, accuracy, average time,
--   how many chose each option (the most chosen wrong option shows a common
--   misconception), who got it wrong, and the written answers.
-- * Monitoring numbers (alerts, commands) appear only when the school has it on.
-- * The report saved when a lesson ends uses this shape ('version' 2).

create or replace function live.session_report(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_s      live.class_sessions;
  v_mon    boolean;
  v_people jsonb;
  v_qs     jsonb;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select coalesce(monitoring_enabled, false) into v_mon from live.tenant_settings where tenant_id = v_s.tenant_id;

  -- "ans": everyone's answers in this lesson, one row per question answered.
  with ans as (select t.student_id as user_id, qa.question_id, qa.is_correct, qa.response, qa.response_ms
                from live.quiz_attempts t join live.quiz_answers qa on qa.attempt_id = t.id where t.session_id = p_session),
  per as (select user_id, count(*) as answered, count(*) filter (where is_correct) as correct, count(is_correct) as graded,
                 round(avg(response_ms) / 1000.0, 1) as avg_seconds from ans group by user_id),
  people as (
    select distinct on (x.user_id) x.user_id, x.guest, x.removed, x.display_name
      from (select cm.user_id, false as guest, false as removed, null::text as display_name, 1 as pref
              from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, g.is_guest, g.removed_at is not null, g.display_name, 2
              from live.session_guests g where g.session_id = p_session) x
     order by x.user_id, x.pref),
  scored as (
    select pe.user_id, coalesce(pe.display_name, u.full_name) as name, pe.guest, pe.removed,
           p.user_id is not null as joined, coalesce(p.total_score, 0) as score, coalesce(p.best_streak, 0) as best_streak,
           coalesce(pr.answered, 0) as answered, coalesce(pr.correct, 0) as correct, coalesce(pr.graded, 0) as graded, pr.avg_seconds,
           case when v_mon then (select count(*) from live.environment_events e
                                 where e.class_session_id = p_session and e.student_id = pe.user_id and e.kind <> 'connection_lost') end as alerts
      from people pe
      join live.users u on u.id = pe.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = pe.user_id
      left join per pr on pr.user_id = pe.user_id)
  select coalesce(jsonb_agg(jsonb_build_object(
           'student_id', s.user_id, 'name', s.name, 'guest', s.guest, 'removed', s.removed, 'joined', s.joined,
           'score', s.score, 'rank', case when s.joined then s.rk end, 'best_streak', s.best_streak,
           'answers', s.answered, 'correct', s.correct, 'graded', s.graded,
           'accuracy', case when s.graded > 0 then round(100.0 * s.correct / s.graded) end,
           'avg_seconds', s.avg_seconds, 'alerts', s.alerts)
         order by s.joined desc, s.rk nulls last, s.name), '[]'::jsonb)
    into v_people
    from (select sc.*, rank() over (partition by sc.joined order by sc.score desc) as rk from scored sc) s;

  with ans as (select t.student_id as user_id, qa.question_id, qa.is_correct, qa.response, qa.response_ms
                from live.quiz_attempts t join live.quiz_answers qa on qa.attempt_id = t.id where t.session_id = p_session),
  names as (select (x ->> 'student_id')::uuid as id, x ->> 'name' as name from jsonb_array_elements(v_people) x)
  select coalesce(jsonb_agg(q.j order by q.slide_pos, q.act_title, q.q_pos), '[]'::jsonb) into v_qs from (
    select coalesce((select min(sl.position) from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id and sl.activity_id = act.id), 100000) as slide_pos,
           act.title as act_title, q.position as q_pos,
           jsonb_build_object(
             'question_id', q.id, 'activity_id', act.id, 'activity', act.title, 'prompt', q.prompt, 'kind', q.kind,
             'answered', (select count(*) from ans a where a.question_id = q.id),
             'correct', (select count(*) from ans a where a.question_id = q.id and a.is_correct),
             'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0))
                          from ans a where a.question_id = q.id),
             'avg_seconds', (select round(avg(a.response_ms) / 1000.0, 1) from ans a where a.question_id = q.id),
             'options', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'label', o.label, 'is_correct', o.is_correct,
                            'count', (select count(*) from ans a where a.question_id = q.id
                                      and (a.response ->> 'option_id' = o.id::text or coalesce(a.response -> 'option_ids', '[]'::jsonb) ? o.id::text)))
                          order by o.position), '[]'::jsonb)
                         from live.question_options o where o.question_id = q.id),
             'missed_by', (select coalesce(jsonb_agg(p.name order by p.name), '[]'::jsonb)
                           from ans a
                           join names p on p.id = a.user_id
                           where a.question_id = q.id and a.is_correct = false),
             'written', case when q.kind in ('open', 'short', 'fill_blank') then
                          (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'text', left(a.response ->> 'text', 500), 'is_correct', a.is_correct)
                                   order by p.name), '[]'::jsonb)
                             from ans a
                             join names p on p.id = a.user_id
                            where a.question_id = q.id and coalesce(a.response ->> 'text', '') <> '') end) as j
      from live.activities act
      join live.questions q on q.activity_id = act.id
     where exists (select 1 from live.quiz_attempts t where t.activity_id = act.id and t.session_id = p_session)) q;

  return jsonb_build_object(
    'version', 2,
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'mode', v_s.mode, 'started_at', v_s.started_at, 'ended_at', v_s.ended_at,
                                  'minutes', round(extract(epoch from coalesce(v_s.ended_at, now()) - coalesce(v_s.started_at, v_s.created_at)) / 60),
                                  'lesson_title', (select title from live.lessons where id = v_s.lesson_id)),
    'class', (select jsonb_build_object('id', c.id, 'name', c.name) from live.classes c where c.id = v_s.class_id),
    'monitoring', v_mon,
    'enrolled', (select count(*) from live.class_members where class_id = v_s.class_id and role = 'student'),
    'joined', (select count(*) from jsonb_array_elements(v_people) x where (x ->> 'joined')::boolean),
    'guests', (select count(*) from jsonb_array_elements(v_people) x where (x ->> 'guest')::boolean),
    'accuracy', (select round(100.0 * sum((x ->> 'correct')::int) / nullif(sum((x ->> 'graded')::int), 0)) from jsonb_array_elements(v_people) x),
    'answers', (select coalesce(sum((x ->> 'answers')::int), 0) from jsonb_array_elements(v_people) x),
    'hands', (select count(*) from live.raise_hands where session_id = p_session),
    'commands', case when v_mon then (select count(*) from live.teacher_commands where class_session_id = p_session) end,
    'alerts', case when v_mon then (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from
                (select kind, count(*) n from live.environment_events where class_session_id = p_session group by kind) x) else '{}'::jsonb end,
    'activities', (select coalesce(jsonb_agg(jsonb_build_object('activity_id', a.id, 'title', a.title, 'kind', a.kind,
                     'attempts', (select count(*) from live.quiz_attempts t where t.activity_id = a.id and t.session_id = p_session),
                     'avg_percent', (select round(avg(100.0 * t.score / nullif(t.max_score, 0))) from live.quiz_attempts t
                                     where t.activity_id = a.id and t.session_id = p_session and t.status <> 'in_progress'))), '[]'::jsonb)
                   from live.activities a where exists (select 1 from live.quiz_attempts t where t.activity_id = a.id and t.session_id = p_session)),
    'questions', v_qs,
    'students', v_people);
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0920')
$$;

-- ===================== 20260901000930_progress.sql =====================
-- 0930: progress for students and parents (docs/LIVE_ENGINE.md, progress dashboards).
--
-- * Questions get a topic (e.g. "Fractions"), typed by the teacher. Results are
--   grouped by subject and topic; untagged questions count under the lesson title.
-- * School terms: the school admin enters the school year and each term's dates.
-- * progress_report(student, period, date): day, week, month, term or year.
--   Lessons held and attended, answers and accuracy (with the previous period),
--   a trend inside the period, each subject with its topics, strongest topics
--   and topics that need practice, and the lessons themselves.
--   Seen by the student, their linked parents (when the school has the parent
--   portal on), their teachers and the school's admins.
-- * Copying a lesson keeps each question's topic.

alter table live.questions add column if not exists topic text;
alter table live.questions drop constraint if exists questions_topic_check;alter table live.questions drop constraint if exists questions_topic_check;

alter table live.questions add constraint questions_topic_check check (topic is null or length(btrim(topic)) between 1 and 60);

-- ---------------------------------------------------------------------------
-- School terms
-- ---------------------------------------------------------------------------
create table if not exists live.school_terms (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references live.tenants(id) on delete cascade,
  school_year text not null check (length(btrim(school_year)) between 4 and 20),
  name        text not null check (length(btrim(name)) between 1 and 40),
  starts_on   date not null,
  ends_on     date not null,
  created_at  timestamptz not null default now(),
  check (ends_on >= starts_on and ends_on <= starts_on + 200),
  unique (tenant_id, starts_on)
);
create index if not exists school_terms_tenant_idx on live.school_terms(tenant_id, starts_on);
alter table live.school_terms enable row level security;
revoke all on live.school_terms from anon;
grant select, insert, update, delete on live.school_terms to authenticated;
drop policy if exists school_terms_read on live.school_terms;drop policy if exists school_terms_read on live.school_terms;

create policy school_terms_read on live.school_terms for select to authenticated
  using (tenant_id = (select live_app.tenant_id()));
drop policy if exists school_terms_admin on live.school_terms;drop policy if exists school_terms_admin on live.school_terms;

create policy school_terms_admin on live.school_terms for all to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()))
  with check (tenant_id = (select live_app.tenant_id()) and (select live_app.is_admin()));

create or replace function live_app.school_terms_no_overlap() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from live.school_terms t where t.tenant_id = new.tenant_id and t.id <> new.id
             and t.starts_on <= new.ends_on and new.starts_on <= t.ends_on) then
    raise exception 'Terms can''t overlap. Check the start and end dates.' using errcode = '23P01';
  end if;
  return new;
end$$;
drop trigger if exists school_terms_no_overlap on live.school_terms;drop trigger if exists school_terms_no_overlap on live.school_terms;

create trigger school_terms_no_overlap before insert or update on live.school_terms
  for each row execute function live_app.school_terms_no_overlap();

-- ---------------------------------------------------------------------------
-- Periods and the rows a report is built from
-- ---------------------------------------------------------------------------

/** [starts, ends) of the day, week, month, term or school year that contains p_date. */
create or replace function live_app.period_bounds(p_tenant uuid, p_period text, p_date date)
returns table (starts date, ends date, label text, term_id uuid)
language plpgsql stable security definer set search_path = '' as $$
declare v_t live.school_terms; v_mon date; v_y int;
begin
  if p_period = 'day' then
    return query select p_date, p_date + 1, to_char(p_date, 'FMDay FMDD FMMonth YYYY'), null::uuid;
  elsif p_period = 'week' then
    v_mon := p_date - (extract(isodow from p_date)::int - 1);
    return query select v_mon, v_mon + 7, 'Week of ' || to_char(v_mon, 'FMDD FMMonth YYYY'), null::uuid;
  elsif p_period = 'month' then
    return query select date_trunc('month', p_date)::date, (date_trunc('month', p_date) + interval '1 month')::date,
                        to_char(p_date, 'FMMonth YYYY'), null::uuid;
  elsif p_period in ('term', 'year') then
    -- The term in progress (or, in a holiday, the one just finished; before any, the first).
    select * into v_t from live.school_terms where tenant_id = p_tenant and starts_on <= p_date order by starts_on desc limit 1;
    if v_t.id is null then select * into v_t from live.school_terms where tenant_id = p_tenant order by starts_on limit 1; end if;
    if p_period = 'term' then
      if v_t.id is null then return; end if;
      return query select v_t.starts_on, v_t.ends_on + 1, v_t.name || ', ' || v_t.school_year, v_t.id;
    elsif v_t.id is not null then
      return query select min(t.starts_on), max(t.ends_on) + 1, 'School year ' || v_t.school_year, null::uuid
                     from live.school_terms t where t.tenant_id = p_tenant and t.school_year = v_t.school_year;
    else
      -- No terms entered: September to August.
      v_y := extract(year from p_date)::int - case when extract(month from p_date) >= 9 then 0 else 1 end;
      return query select make_date(v_y, 9, 1), make_date(v_y + 1, 9, 1), 'School year ' || v_y || '/' || (v_y + 1), null::uuid;
    end if;
  else
    raise exception 'Period is day, week, month, term or year.' using errcode = '22023';
  end if;
end$$;

/** Every answer the student gave in [p_from, p_to), with its subject and topic. */
create or replace function live_app.progress_answers(p_student uuid, p_from timestamptz, p_to timestamptz)
returns table (at timestamptz, session_id uuid, subject text, topic text, is_correct boolean)
language sql stable security definer set search_path = '' as $$
  select qa.answered_at, t.session_id,
         coalesce(nullif(btrim(l.subject), ''), nullif(btrim(c.subject), ''), c.name, 'Other lessons'),
         coalesce(nullif(btrim(q.topic), ''), l.title, a.title),
         qa.is_correct
    from live.quiz_attempts t
    join live.quiz_answers qa on qa.attempt_id = t.id
    join live.questions q on q.id = qa.question_id
    join live.activities a on a.id = t.activity_id
    left join live.lessons l on l.id = a.lesson_id
    left join live.class_sessions s on s.id = t.session_id
    left join live.classes c on c.id = s.class_id
   where t.student_id = p_student and qa.answered_at >= p_from and qa.answered_at < p_to
$$;

/** Live lessons in [p_from, p_to) for the student's classes, plus any they joined with a code. */
create or replace function live_app.progress_lessons(p_student uuid, p_from timestamptz, p_to timestamptz)
returns table (session_id uuid, title text, subject text, started_at timestamptz, attended boolean, points int)
language sql stable security definer set search_path = '' as $$
  select s.id, s.title,
         coalesce(nullif(btrim(l.subject), ''), nullif(btrim(c.subject), ''), c.name, 'Other lessons'),
         s.started_at, p.user_id is not null, coalesce(p.total_score, 0)
    from live.class_sessions s
    left join live.lessons l on l.id = s.lesson_id
    left join live.classes c on c.id = s.class_id
    left join live.session_participants p on p.session_id = s.id and p.user_id = p_student
   where s.tenant_id = (select u.tenant_id from live.users u where u.id = p_student)
     and s.started_at >= p_from and s.started_at < p_to
     and (p.user_id is not null
          or exists (select 1 from live.class_members m where m.class_id = s.class_id and m.user_id = p_student and m.role = 'student'))
$$;

create or replace function live_app.can_see_student(p_student uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select auth.uid() = p_student or live_app.is_parent_of(p_student) or live_app.teaches_student(p_student)
      or (live_app.is_admin() and exists (select 1 from live.users u where u.id = p_student and u.tenant_id = live_app.tenant_id()))
$$;

revoke execute on function live_app.period_bounds(uuid, text, date), live_app.progress_answers(uuid, timestamptz, timestamptz),
  live_app.progress_lessons(uuid, timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function live_app.can_see_student(uuid) from public, anon;

-- ---------------------------------------------------------------------------
-- The report
-- ---------------------------------------------------------------------------
create or replace function live.progress_report(p_student uuid, p_period text default 'week', p_date date default null)
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_st    live.users;
  v_tz    text;
  v_today date;
  v_day   date;
  v_b     record;
  v_pb    record;
  v_ps    date;    -- previous period, null when there is none
  v_pe    date;
  v_from  timestamptz; v_to timestamptz; v_pfrom timestamptz; v_pto timestamptz;
  v_step  interval;
  v_unit  text;
  v_terms jsonb;
begin
  select * into v_st from live.users where id = p_student and role = 'student';
  if v_st.id is null or not live_app.can_see_student(p_student) then raise exception 'Report not found.' using errcode = 'P0002'; end if;
  if p_period not in ('day', 'week', 'month', 'term', 'year') then
    raise exception 'Period is day, week, month, term or year.' using errcode = '22023';
  end if;
  select coalesce(t.timezone, 'UTC') into v_tz from live.tenants t where t.id = v_st.tenant_id;
  v_today := (now() at time zone v_tz)::date;
  v_day := coalesce(p_date, v_today);
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'school_year', t.school_year,
                                               'starts_on', t.starts_on, 'ends_on', t.ends_on) order by t.starts_on), '[]'::jsonb)
    into v_terms from live.school_terms t where t.tenant_id = v_st.tenant_id;

  select * into v_b from live_app.period_bounds(v_st.tenant_id, p_period, v_day);
  if v_b.starts is null then
    return jsonb_build_object('student', jsonb_build_object('id', v_st.id, 'name', v_st.full_name), 'period', p_period,
                              'date', v_day, 'today', v_today, 'needs_terms', true, 'terms', v_terms);
  end if;
  select * into v_pb from live_app.period_bounds(v_st.tenant_id, p_period, v_b.starts - 1);
  if v_pb.starts is distinct from v_b.starts then v_ps := v_pb.starts; v_pe := v_pb.ends; end if;   -- else: no earlier term
  v_from := v_b.starts::timestamp at time zone v_tz;
  v_to := v_b.ends::timestamp at time zone v_tz;
  v_pfrom := v_ps::timestamp at time zone v_tz;
  v_pto := v_pe::timestamp at time zone v_tz;
  v_unit := case p_period when 'week' then 'day' when 'month' then 'week' when 'term' then 'week' when 'year' then 'month' end;
  v_step := case v_unit when 'day' then interval '1 day' when 'week' then interval '7 days' when 'month' then interval '1 month' end;

  return (
    with ans as (select * from live_app.progress_answers(p_student, v_from, v_to)),
    les as (select * from live_app.progress_lessons(p_student, v_from, v_to)),
    pans as (select * from live_app.progress_answers(p_student, v_pfrom, v_pto)),
    ples as (select * from live_app.progress_lessons(p_student, v_pfrom, v_pto)),
    topics as (
      select a.subject, a.topic, count(*) as answers, count(a.is_correct) as graded,
             round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) as accuracy
        from ans a group by a.subject, a.topic),
    subjects as (select x.subject from ans x union select y.subject from les y)
    select jsonb_build_object(
      'student', jsonb_build_object('id', v_st.id, 'name', v_st.full_name),
      'period', p_period, 'date', v_day, 'today', v_today, 'timezone', v_tz, 'needs_terms', false, 'terms', v_terms,
      'from', v_b.starts, 'to', v_b.ends - 1, 'label', v_b.label, 'unit', v_unit,
      'prev_date', case when v_ps is not null then v_b.starts - 1 end,
      'next_date', case when v_b.ends <= v_today then v_b.ends end,
      'summary', jsonb_build_object(
        'held', (select count(*) from les), 'attended', (select count(*) from les where attended),
        'answers', (select count(*) from ans), 'correct', (select count(*) from ans where is_correct),
        'accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from ans),
        'points', (select coalesce(sum(points), 0) from les where attended),
        'prev_held', case when v_ps is not null then (select count(*) from ples) end,
        'prev_attended', case when v_ps is not null then (select count(*) from ples where attended) end,
        'prev_answers', case when v_ps is not null then (select count(*) from pans) end,
        'prev_accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from pans)),
      'trend', case when v_step is null then '[]'::jsonb else (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'start', greatest(b::date, v_b.starts),
                 'answers', (select count(*) from ans a where (a.at at time zone v_tz) >= b and (a.at at time zone v_tz) < b + v_step),
                 'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from ans a
                              where (a.at at time zone v_tz) >= b and (a.at at time zone v_tz) < b + v_step),
                 'held', (select count(*) from les l where (l.started_at at time zone v_tz) >= b and (l.started_at at time zone v_tz) < b + v_step),
                 'attended', (select count(*) from les l where l.attended and (l.started_at at time zone v_tz) >= b and (l.started_at at time zone v_tz) < b + v_step))
               order by b), '[]'::jsonb)
          from generate_series(date_trunc(v_unit, v_b.starts::timestamp), (v_b.ends - 1)::timestamp, v_step) b) end,
      'subjects', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'subject', s.subject,
                 'held', (select count(*) from les l where l.subject = s.subject),
                 'attended', (select count(*) from les l where l.subject = s.subject and l.attended),
                 'answers', (select count(*) from ans a where a.subject = s.subject),
                 'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from ans a where a.subject = s.subject),
                 'prev_accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from pans a where a.subject = s.subject),
                 'topics', (select coalesce(jsonb_agg(jsonb_build_object('topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy)
                                     order by t.accuracy asc nulls last, t.answers desc), '[]'::jsonb)
                              from topics t where t.subject = s.subject))
               order by (select count(*) from ans a where a.subject = s.subject) desc, s.subject), '[]'::jsonb)
          from subjects s),
      'strengths', (select coalesce(jsonb_agg(jsonb_build_object('subject', t.subject, 'topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy)
                                     order by t.accuracy desc, t.graded desc), '[]'::jsonb)
                      from (select * from topics where graded >= 3 and accuracy >= 80 order by accuracy desc, graded desc limit 5) t),
      'needs_help', (select coalesce(jsonb_agg(jsonb_build_object('subject', t.subject, 'topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy)
                                      order by t.accuracy asc, t.graded desc), '[]'::jsonb)
                       from (select * from topics where graded >= 3 and accuracy < 60 order by accuracy asc, graded desc limit 5) t),
      'lessons', (select coalesce(jsonb_agg(jsonb_build_object(
                   'session_id', l.session_id, 'title', l.title, 'subject', l.subject, 'started_at', l.started_at,
                   'attended', l.attended, 'points', l.points,
                   'answers', (select count(*) from ans a where a.session_id = l.session_id),
                   'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from ans a where a.session_id = l.session_id))
                 order by l.started_at desc), '[]'::jsonb)
                    from (select * from les order by started_at desc limit 60) l))
  );
end$$;

revoke execute on function live.progress_report(uuid, text, date) from public, anon;
grant execute on function live.progress_report(uuid, text, date) to authenticated;

-- Copying a lesson keeps each question's topic (otherwise unchanged).
create or replace function live.duplicate_lesson(p_lesson uuid, p_title text default null, p_as_template boolean default false)
returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me     live.users := live_app.me();
  v_src    live.lessons;
  v_new    uuid;
  v_map_a  jsonb := '{}'::jsonb;   -- old activity id -> new
  v_map_q  jsonb := '{}'::jsonb;   -- old question id -> new
  v_map_s  jsonb := '{}'::jsonb;   -- old slide id -> new
  r        record;
  v_id     uuid;
begin
  if not live_app.is_teacher() or not live_app.can_view_lesson(p_lesson) then
    raise exception 'You cannot copy this lesson.' using errcode = '42501';
  end if;
  select * into v_src from live.lessons where id = p_lesson;
  insert into live.lessons (tenant_id, owner_id, title, description, subject, grade_level, default_mode, is_template)
    values (v_me.tenant_id, v_me.id, coalesce(nullif(btrim(p_title), ''), left(v_src.title || ' (copy)', 200)),
            v_src.description, v_src.subject, v_src.grade_level, v_src.default_mode, p_as_template)
    returning id into v_new;

  for r in select * from live.activities where lesson_id = p_lesson loop
    insert into live.activities (tenant_id, lesson_id, owner_id, kind, title, instructions, settings)
      values (v_me.tenant_id, v_new, v_me.id, r.kind, r.title, r.instructions, r.settings) returning id into v_id;
    v_map_a := v_map_a || jsonb_build_object(r.id::text, v_id);
  end loop;

  for r in select q.* from live.questions q join live.activities a on a.id = q.activity_id where a.lesson_id = p_lesson loop
    insert into live.questions (tenant_id, activity_id, owner_id, kind, prompt, media, config, answer_key,
                                  explanation, points, position, tags, difficulty, topic)
      values (v_me.tenant_id, (v_map_a ->> r.activity_id::text)::uuid, v_me.id, r.kind, r.prompt, r.media, r.config,
              r.answer_key, r.explanation, r.points, r.position, r.tags, r.difficulty, r.topic)
      returning id into v_id;
    v_map_q := v_map_q || jsonb_build_object(r.id::text, v_id);
    insert into live.question_options (tenant_id, question_id, label, is_correct, feedback, position)
      select v_me.tenant_id, v_id, o.label, o.is_correct, o.feedback, o.position
      from live.question_options o where o.question_id = r.id;
  end loop;

  for r in select * from live.lesson_slides where lesson_id = p_lesson order by position loop
    insert into live.lesson_slides (tenant_id, lesson_id, position, kind, content, notes, activity_id)
      values (v_me.tenant_id, v_new, r.position, r.kind, r.content, r.notes, (v_map_a ->> r.activity_id::text)::uuid)
      returning id into v_id;
    v_map_s := v_map_s || jsonb_build_object(r.id::text, v_id);
  end loop;

  insert into live.video_checkpoints (tenant_id, slide_id, question_id, t_seconds, required)
    select v_me.tenant_id, (v_map_s ->> vc.slide_id::text)::uuid, (v_map_q ->> vc.question_id::text)::uuid,
           vc.t_seconds, vc.required
    from live.video_checkpoints vc join live.lesson_slides s on s.id = vc.slide_id
    where s.lesson_id = p_lesson and v_map_q ? vc.question_id::text;

  perform live_app.audit('lesson.duplicated', 'lesson', v_new::text, jsonb_build_object('source', p_lesson));
  return v_new;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0930')
$$;

-- ===================== 20260901000940_game_timer.sql =====================
-- 0940: the game look's rules (docs/LIVE_ENGINE.md).
--
-- * A countdown on each activity in a teacher-paced live lesson (game setting
--   "timer", on unless the teacher turns it off). The time is the activity's
--   time limit, or per question: 20 s for choices, 45 s fill in the blank,
--   90 s written answers, 60 s anything else.
-- * The class shares one clock, from when the question appeared. Once it runs
--   out (plus 2 s for the network) the server refuses answers.
-- * Pausing stops the clock: resuming moves the question's start (and with it
--   the speed bonus) forward by the length of the pause.
-- * Student and teacher states carry the timer; "auto_reveal" is a new game
--   setting (the teacher's screen reveals answers when time is up).

alter table live.class_sessions add column if not exists paused_at timestamptz;

/** The countdown for the activity on screen, or null when there is none. */
create or replace function live_app.live_timer(p_s live.class_sessions) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_act live.activities; v_start timestamptz; v_secs int;
begin
  if p_s.status <> 'live' or p_s.phase is distinct from 'active' or p_s.mode = 'student_paced'
     or not coalesce((p_s.settings ->> 'timer')::boolean, true) then
    return null;
  end if;
  select a.* into v_act from live.activities a
   where a.id = coalesce(p_s.active_activity_id,
                         (select sl.activity_id from live.lesson_slides sl where sl.lesson_id = p_s.lesson_id and sl.position = p_s.current_slide));
  if v_act.id is null or v_act.kind = 'collab_board' or p_s.revealed_activity_id is not distinct from v_act.id then return null; end if;
  v_secs := nullif((v_act.settings ->> 'time_limit_seconds')::int, 0);
  if v_secs is null then
    select sum(case when q.kind in ('mcq', 'true_false', 'poll', 'multi_select') then 20 when q.kind = 'fill_blank' then 45
                    when q.kind in ('open', 'short') then 90 else 60 end)::int
      into v_secs from live.questions q where q.activity_id = v_act.id;
  end if;
  if coalesce(v_secs, 0) <= 0 then return null; end if;
  v_secs := least(v_secs, 3600);
  v_start := greatest(coalesce(p_s.slide_changed_at, p_s.started_at),
                      case when p_s.active_activity_id = v_act.id then p_s.activity_opened_at end);
  if v_start is null then return null; end if;
  return jsonb_build_object('activity_id', v_act.id, 'started_at', v_start, 'seconds', v_secs,
                            'ends_at', v_start + make_interval(secs => v_secs));
end$$;
revoke execute on function live_app.live_timer(live.class_sessions) from public, anon, authenticated;

create or replace function live.session_control(p_session uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions := live_app.require_live_session(p_session);
  v_n      int;
  v_target int;
  v_user   uuid;
  v_bad    text;
  v_act    uuid;
  v_att    uuid;
begin
  p_args := coalesce(p_args, '{}'::jsonb);
  case p_action
    when 'start' then
      if v_s.phase <> 'lobby' then raise exception 'The lesson has already started.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active', started_at = now() where id = p_session;
    when 'pause' then
      if v_s.phase <> 'active' then raise exception 'Only a running lesson can be paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'paused', paused_at = now() where id = p_session;
    when 'resume' then
      if v_s.phase <> 'paused' then raise exception 'The lesson isn''t paused.' using errcode = 'P0001'; end if;
      -- The question clock (and the speed bonus) stand still while paused.
      update live.class_sessions set phase = 'active', paused_at = null,
             slide_changed_at = slide_changed_at + (now() - coalesce(paused_at, now())),
             activity_opened_at = activity_opened_at + (now() - coalesce(paused_at, now()))
       where id = p_session;
    when 'next', 'prev', 'goto' then
      if v_s.phase <> 'active' then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      select count(*) into v_n from live.lesson_slides where lesson_id = v_s.lesson_id;
      v_target := case p_action when 'next' then v_s.current_slide + 1 when 'prev' then v_s.current_slide - 1
                                else (p_args ->> 'slide')::int end;
      if v_target is null then raise exception 'Which slide?' using errcode = '22023'; end if;
      perform live.set_session_state(p_session, greatest(0, least(v_target, greatest(v_n - 1, 0))));
    when 'kick' then
      v_user := nullif(p_args ->> 'user_id', '')::uuid;
      if v_user is null or v_user = v_s.teacher_id then raise exception 'Who should be removed?' using errcode = '22023'; end if;
      update live.session_participants set removed_at = now(), left_at = now(), status = 'offline'
       where session_id = p_session and user_id = v_user and removed_at is null;
      if not found then raise exception 'That person isn''t in this lesson.' using errcode = 'P0002'; end if;
      update live.session_guests set removed_at = now() where session_id = p_session and user_id = v_user and removed_at is null;
      update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and student_id = v_user and status = 'open';
      perform live_app.audit('session.participant_removed', 'user', v_user::text, jsonb_build_object('session_id', p_session));
    when 'settings' then
      select k into v_bad from jsonb_object_keys(p_args) k
       where k <> all (array['leaderboard', 'anonymous_names', 'late_join', 'speed_bonus', 'timer', 'auto_reveal'])
          or jsonb_typeof(p_args -> k) <> 'boolean' limit 1;
      if v_bad is not null then raise exception 'Unknown or invalid setting: %.', v_bad using errcode = '22023'; end if;
      update live.class_sessions set settings = settings || p_args where id = p_session;
    when 'leaderboard' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      if coalesce((p_args ->> 'show')::boolean, true) then perform live_app.snapshot_leaderboard(p_session);
      else update live.class_sessions set show_leaderboard = false where id = p_session; end if;
    when 'reveal' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      v_act := coalesce(nullif(p_args ->> 'activity_id', '')::uuid, v_s.active_activity_id,
                        (select sl.activity_id from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id and sl.position = v_s.current_slide));
      if v_act is null then raise exception 'There is no activity on this slide to reveal.' using errcode = 'P0001'; end if;
      -- Answers close: unfinished attempts are submitted as they stand, then everyone sees the result.
      for v_att in select id from live.quiz_attempts where session_id = p_session and activity_id = v_act and status = 'in_progress' loop
        update live.quiz_attempts set status = 'submitted', submitted_at = now() where id = v_att;
        perform live_app.recompute_attempt(v_att);
      end loop;
      update live.class_sessions set revealed_activity_id = v_act, responses_visible = true where id = p_session;
    when 'end' then
      return live.end_session(p_session);
    else
      raise exception 'Unknown action: %.', p_action using errcode = '22023';
  end case;
  select * into v_s from live.class_sessions where id = p_session;
  return jsonb_build_object('phase', v_s.phase, 'slide', v_s.current_slide, 'settings', v_s.settings, 'v', v_s.state_version);
end$$;

create or replace function live_app.score_live_answer(
  p_attempt live.quiz_attempts, p_question live.questions, p_activity live.activities,
  p_is_correct boolean, p_tries smallint, p_prev_points int
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s       live.class_sessions;
  v_base    int := 0;
  v_speed   int := 0;
  v_bonus   int := 0;
  v_prior   int := 0;
  v_streak  int;
  v_start   timestamptz;
  v_window  numeric;
  v_elapsed numeric;
  v_points  int;
  v_p       live.session_participants;
  v_timer   jsonb;
begin
  select * into v_s from live.class_sessions where id = p_attempt.session_id;
  if v_s.id is null then return null; end if;
  v_start := greatest(p_attempt.started_at, coalesce(v_s.slide_changed_at, v_s.started_at),
                      case when v_s.active_activity_id = p_activity.id then v_s.activity_opened_at end);
  v_elapsed := greatest(extract(epoch from now() - v_start), 0);
  -- Countdown (0940): once the class's time is up, no more answers (2 s grace for the network).
  v_timer := live_app.live_timer(v_s);
  if v_timer is not null and (v_timer ->> 'activity_id')::uuid = p_activity.id
     and now() > (v_timer ->> 'ends_at')::timestamptz + interval '2 seconds' then
    raise exception 'Time''s up for this question.' using errcode = 'P0001';
  end if;

  if p_question.kind in ('poll', 'open', 'draw', 'file') or p_is_correct is null then
    v_base := 100;
  elsif p_is_correct then
    v_base := case when p_tries = 2 then 500 else 1000 end;
    if p_tries = 1 and v_s.mode <> 'student_paced' and coalesce((v_s.settings ->> 'speed_bonus')::boolean, true) then
      v_window := coalesce(nullif((p_activity.settings ->> 'time_limit_seconds')::int, 0), 20);
      v_speed := round(500 * greatest(0, 1 - v_elapsed / v_window));
    end if;
    -- Correct answers in a row just before this one (questions with a right answer only).
    select count(*) into v_prior from (
      select a.is_correct, sum(case when a.is_correct then 0 else 1 end) over (order by a.answered_at desc) as broken
        from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        join live.questions q on q.id = a.question_id
       where t.session_id = v_s.id and t.student_id = p_attempt.student_id and a.question_id <> p_question.id
         and a.is_correct is not null and q.kind not in ('poll', 'open', 'draw', 'file')) x
     where broken = 0;
    if p_tries = 1 then v_bonus := least(100 * v_prior, 500); end if;
  end if;
  v_points := v_base + v_speed + v_bonus;
  v_streak := case when p_is_correct then v_prior + 1 when p_is_correct is false then 0 end;

  update live.session_participants set
      total_score   = total_score - coalesce(p_prev_points, 0) + v_points,
      streak        = coalesce(v_streak, streak),
      best_streak   = greatest(best_streak, coalesce(v_streak, 0)),
      correct_count = (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                        where t.session_id = v_s.id and t.student_id = p_attempt.student_id and a.is_correct
                          and a.question_id <> p_question.id) + case when p_is_correct then 1 else 0 end
   where session_id = v_s.id and user_id = p_attempt.student_id
   returning * into v_p;

  return jsonb_build_object('points', v_points, 'base', v_base, 'speed', v_speed, 'streak_bonus', v_bonus,
                            'streak', coalesce(v_p.streak, 0), 'total', coalesce(v_p.total_score, v_points),
                            'response_ms', round(v_elapsed * 1000));
end$$;

create or replace function live.session_student_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_s     live.class_sessions;
  v_p     live.session_participants;
  v_spot  live.spotlights;
  v_act   live.activities;
  v_pass  live.session_guests;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if exists (select 1 from live.session_participants where session_id = p_session and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_p from live.session_participants where session_id = p_session and user_id = v_me.id;
  if v_p.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
  select * into v_pass from live.session_guests where session_id = p_session and user_id = v_me.id;
  if v_s.status = 'live' then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
      on conflict (session_id, user_id) do update set last_seen_at = now(), left_at = null,
        status = case when live.session_participants.status = 'offline' then 'online' else live.session_participants.status end
      returning * into v_p;
  end if;
  select * into v_spot from live.spotlights where session_id = p_session and ended_at is null;
  select * into v_act from live.activities where id = v_s.active_activity_id;

  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'phase', v_s.phase, 'mode', v_s.mode,
                                  'join_code', v_s.join_code, 'settings', v_s.settings,
                                  'current_slide', v_s.current_slide, 'group_chat_enabled', v_s.group_chat_enabled and v_me.role <> 'guest',
                                  'responses_visible', v_s.responses_visible, 'class_id', v_s.class_id,
                                  'teacher', (select full_name from live.users where id = v_s.teacher_id),
                                  'environment_active', v_s.environment_active),
    'my_slide', coalesce(v_p.current_slide, v_s.current_slide),
    'active_activity', case when v_act.id is null then null else jsonb_build_object(
                         'id', v_act.id, 'kind', v_act.kind, 'title', v_act.title) end,
    'spotlight', case when v_spot.id is null then null else jsonb_build_object(
                   'me', v_spot.student_id = v_me.id, 'show_to_class', v_spot.show_to_class, 'anonymized', v_spot.anonymized) end,
    'hand', (select jsonb_build_object('id', h.id, 'created_at', h.created_at) from live.raise_hands h
             where h.session_id = p_session and h.student_id = v_me.id and h.status = 'open'),
    'environment_notice', case when exists (select 1 from live.environment_events e where e.class_session_id = p_session
                                            and e.student_id = v_me.id and e.resolved_at is null
                                            and e.kind in ('environment_left','domain_blocked'))
                               then 'Your class session requires you to return to the lesson.' end,
    'device_monitored', exists (select 1 from live.browser_sessions b where b.class_session_id = p_session
                                and b.student_id = v_me.id and b.last_heartbeat_at > now() - interval '45 seconds'),
    'announcements', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at)
                       order by a.created_at desc), '[]'::jsonb)
                      from (select * from live.announcements where session_id = p_session order by created_at desc limit 5) a),
    'guest', v_me.role = 'guest',
    'revealed_activity_id', v_s.revealed_activity_id,
    -- Own score and rank only; the class sees the top 5 when the teacher shows the board.
    'my', (select jsonb_build_object('score', r.score, 'rank', r.rank, 'streak', r.streak,
                                     'of', (select count(*) from live_app.session_ranks(p_session)))
             from live_app.session_ranks(p_session) r where r.user_id = v_me.id),
    'leaderboard', case when v_s.show_leaderboard and coalesce((v_s.settings ->> 'leaderboard')::boolean, true) then
      (select coalesce(jsonb_agg(e order by (e ->> 'rank')::int), '[]'::jsonb) from jsonb_array_elements(v_s.leaderboard -> 'top') e
        where (e ->> 'rank')::int <= 5) end,
    'me', jsonb_build_object('name', coalesce(v_pass.display_name, v_me.full_name), 'avatar', v_p.avatar),
    'participants', (select count(*) from live.session_participants sp
                      where sp.session_id = p_session and sp.user_id <> v_s.teacher_id and sp.left_at is null and sp.removed_at is null
                        and sp.last_seen_at > now() - live_app.presence_window()),
    'summary', case when v_s.status = 'ended' then (
       select jsonb_build_object('answered', count(*), 'correct', count(*) filter (where a.is_correct))
         from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        where t.session_id = p_session and t.student_id = v_me.id) end,
    'server_now', now(),
    'timer', live_app.live_timer(v_s));
end$$;

create or replace function live.teacher_session_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s        live.class_sessions;
  v_settings live.tenant_settings;
  r          live.browser_sessions;
  v_cur      uuid;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_settings from live.tenant_settings where tenant_id = v_s.tenant_id;

  if v_s.status = 'live' then
    -- Students only send screen frames while a teacher is watching (throttled write).
    if v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '20 seconds' then
      update live.class_sessions set teacher_seen_at = now() where id = p_session;
    end if;
    for r in update live.browser_sessions set connection_lost_at = now()
             where class_session_id = p_session and ended_at is null and connection_lost_at is null
               and last_heartbeat_at < now() - interval '45 seconds'
             returning * loop
      perform live_app.raise_event(r, v_s, v_s.environment_id, 'connection_lost', 'info',
                              'Extension stopped reporting — connection lost, not a rule violation', null, null);
    end loop;
    perform live_app.web_leave_check(v_s);
    update live.teacher_commands set status = 'expired'
     where class_session_id = p_session and status in ('queued','delivered') and expires_at < now();
  end if;

  -- The activity on screen: the one launched, or the one on the current slide.
  v_cur := coalesce(v_s.active_activity_id,
                    (select sl.activity_id from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id and sl.position = v_s.current_slide));
  return jsonb_build_object(
    'session', to_jsonb(v_s) || jsonb_build_object(
      'class_name', (select name from live.classes where id = v_s.class_id),
      'lesson_title', (select title from live.lessons where id = v_s.lesson_id),
      'environment_name', (select name from live.environment_policies where id = v_s.environment_id)),
    'settings', jsonb_build_object('monitoring_enabled', v_settings.monitoring_enabled, 'allow_spotlight', v_settings.allow_spotlight, 'allow_group_chat', v_settings.allow_group_chat,
                                   'allow_screen_capture', v_settings.allow_screen_capture,
                                   'store_event_screenshots', v_settings.store_event_screenshots,
                                   'thumbnail_interval_seconds', v_settings.thumbnail_interval_seconds),
    'server_now', now(),
    'roster', (select coalesce(jsonb_agg(jsonb_build_object(
        'student_id', u.id, 'name', u.full_name, 'guest', m.guest, 'avatar', p.avatar,
        'score', coalesce(p.total_score, 0), 'streak', coalesce(p.streak, 0),
        'presence', case when p.user_id is null then 'not_joined'
                         when p.left_at is not null or p.last_seen_at < now() - live_app.presence_window() then 'offline'
                         else p.status end,
        'last_seen_at', p.last_seen_at, 'current_slide', p.current_slide,
        'web', case when p.user_id is null then null else jsonb_build_object(
                 'sharing', p.screen_sharing and p.last_seen_at > now() - live_app.presence_window(),
                 'unsupported', p.share_unsupported, 'surface', p.screen_surface,
                 'visible', p.tab_visible, 'fullscreen', p.fullscreen,
                 'away_since', p.away_since, 'away_reason', p.away_reason) end,
        'device', (select jsonb_build_object('device_id', b.device_id, 'url', b.active_url, 'domain', b.active_domain,
                     'title', b.active_title, 'tab_count', b.tab_count, 'idle_state', b.idle_state,
                     'online', b.connection_lost_at is null and b.last_heartbeat_at > now() - interval '45 seconds',
                     'last_heartbeat_at', b.last_heartbeat_at, 'focus_locked', b.focus_locked,
                     'violation', b.violation_rule, 'violation_since', b.violation_since,
                     'snapshot_at', (select max(sn.captured_at) from live.screen_snapshots sn
                                     where sn.student_id = u.id and sn.class_session_id = p_session and sn.quality = 'thumbnail'))
                   from live.browser_sessions b where b.class_session_id = p_session and b.student_id = u.id
                   order by b.last_heartbeat_at desc limit 1),
        'open_alerts', (select count(*) from live.environment_events e where e.class_session_id = p_session
                        and e.student_id = u.id and e.status = 'open'),
        'hand_raised', exists (select 1 from live.raise_hands h where h.session_id = p_session and h.student_id = u.id and h.status = 'open'))
        order by u.full_name), '[]'::jsonb)
      from (select cm.user_id, false as guest from live.class_members cm where cm.class_id = v_s.class_id and cm.role = 'student'
            union all
            select g.user_id, g.is_guest from live.session_guests g where g.session_id = p_session and g.removed_at is null) m
      join live.users u on u.id = m.user_id
      left join live.session_participants p on p.session_id = p_session and p.user_id = u.id),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'severity', e.severity, 'rule', e.rule,
                 'domain', e.domain, 'confidence', e.confidence, 'status', e.status, 'student_id', e.student_id,
                 'student', u.full_name, 'created_at', e.created_at, 'resolved_at', e.resolved_at,
                 'has_evidence', e.evidence_image is not null)
                 order by e.created_at desc), '[]'::jsonb)
               from (select * from live.environment_events where class_session_id = p_session
                     and (status = 'open' or created_at > now() - interval '10 minutes') order by created_at desc limit 50) e
               join live.users u on u.id = e.student_id),
    'hands', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'student_id', h.student_id, 'student', u.full_name,
                'message', h.message, 'created_at', h.created_at) order by h.created_at), '[]'::jsonb)
              from live.raise_hands h join live.users u on u.id = h.student_id
              where h.session_id = p_session and h.status = 'open'),
    'commands', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'status', c.status, 'error', c.error,
                   'student', u.full_name, 'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
                 from (select * from live.teacher_commands where class_session_id = p_session order by created_at desc limit 20) c
                 join live.users u on u.id = c.student_id),
    'spotlight', (select jsonb_build_object('id', s.id, 'student_id', s.student_id, 'anonymized', s.anonymized,
                    'show_to_class', s.show_to_class, 'started_at', s.started_at)
                  from live.spotlights s where s.session_id = p_session and s.ended_at is null),
    'ranking', (select coalesce(jsonb_agg(jsonb_build_object('user_id', rk.user_id, 'name', rk.name, 'avatar', rk.avatar,
                   'score', rk.score, 'rank', rk.rank, 'streak', rk.streak) order by rk.rank, rk.name), '[]'::jsonb)
                from (select * from live_app.session_ranks(p_session) order by rank, name limit 10) rk),
    'timer', live_app.live_timer(v_s),
    'activity', case when v_cur is null then null
                     else live.activity_results(v_cur, p_session) || jsonb_build_object(
                       'answered', (select count(distinct t.student_id) from live.quiz_attempts t
                                     where t.session_id = p_session and t.activity_id = v_cur
                                       and exists (select 1 from live.quiz_answers a where a.attempt_id = t.id)),
                       'joined', (select count(*) from live.session_participants sp where sp.session_id = p_session
                                   and sp.user_id <> v_s.teacher_id and sp.removed_at is null and sp.left_at is null),
                       'revealed', v_s.revealed_activity_id is not distinct from v_cur) end);
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0940')
$$;

-- ===================== 20260901000950_roles_progress.sql =====================
-- 0950: roles and the school's view of progress.
--
-- * Schools never learn that other schools exist: a code from another school
--   gets the same answer as a code that doesn't exist (joining a lesson,
--   redeeming a class or invite code).
-- * Teachers see a student's progress only for their own lessons and classes;
--   the student, their parents and the school's admins see everything.
-- * Parent codes: each student has a standing code (up to 4 parents), seen by
--   staff only (parent_codes for a class, new_parent_code to replace one).
--   A parent signs up with it, or adds another child with it.
-- * Parent feedback to the teacher of each of the child's classes, with one
--   reply; teachers see their own, school admins see all.
-- * school_progress: for admins, where pupils struggle by subject and topic,
--   and the pupils who need help (whole school or one class, any period).
-- * users.is_support: the platform's support account inside a school.

drop function if exists live_app.progress_answers(uuid, timestamptz, timestamptz);
drop function if exists live_app.progress_lessons(uuid, timestamptz, timestamptz);

create or replace function live.redeem_code(p_code text, p_full_name text default null)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid     uuid := auth.uid();
  v_code    text := upper(btrim(coalesce(p_code, '')));
  v_email   text;
  v_meta    jsonb;
  v_user    live.users;
  v_class   live.classes;
  v_invite  live.invites;
  v_name    text;
  v_count   bigint;
begin
  if v_uid is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  -- Guessing protection: class codes are short enough to type, so wrong guesses are limited.
  if (select count(*) from live.code_attempts where user_id = v_uid and at > now() - interval '15 minutes') >= 8 then
    raise exception 'Too many wrong codes. Wait 15 minutes, then check the code with your teacher.' using errcode = 'P0001';
  end if;
  if v_code !~ '^[A-Z0-9]{6,12}$' then raise exception 'That code is not valid.' using errcode = '22023'; end if;

  select email, raw_user_meta_data into v_email, v_meta from auth.users where id = v_uid;
  select * into v_user from live.users where id = v_uid;
  v_name := coalesce(nullif(btrim(p_full_name), ''), nullif(btrim(v_meta ->> 'full_name'), ''),
                     split_part(coalesce(v_email, 'user'), '@', 1));

  -- Invite codes take precedence (8-12 chars); class codes are 6-8.
  select * into v_invite from live.invites
   where code = v_code and revoked_at is null and expires_at > now() and uses < max_uses
   for update;

  if v_invite.id is not null then
    if v_invite.email is not null and lower(v_invite.email) <> lower(coalesce(v_email, '')) then
      raise exception 'This invite was issued for a different email address.' using errcode = '42501';
    end if;

    if v_user.id is null then
      insert into live.users (id, tenant_id, email, full_name, role)
        values (v_uid, v_invite.tenant_id, coalesce(v_email, ''), v_name, v_invite.role)
        returning * into v_user;
      if v_invite.role = 'student' then
        insert into live.student_profiles (user_id, tenant_id) values (v_uid, v_invite.tenant_id);
      elsif v_invite.role in ('teacher','school_admin','it_admin') then
        insert into live.teacher_profiles (user_id, tenant_id) values (v_uid, v_invite.tenant_id);
      end if;
    elsif v_user.tenant_id <> v_invite.tenant_id then
      raise exception 'No class or invite matches that code.' using errcode = 'P0002';
    elsif v_user.role <> v_invite.role then
      raise exception 'This invite is for a % account.', v_invite.role using errcode = 'P0001';
    end if;

    if v_invite.class_id is not null then
      insert into live.class_members (class_id, user_id, tenant_id, role)
        values (v_invite.class_id, v_uid, v_invite.tenant_id,
                case when v_invite.role = 'student' then 'student' else 'teacher' end)
        on conflict (class_id, user_id) do nothing;
    end if;
    if v_invite.role = 'parent' then
      insert into live.parent_links (tenant_id, parent_id, student_id)
        values (v_invite.tenant_id, v_uid, v_invite.student_id)
        on conflict (parent_id, student_id) do update set revoked_at = null;
    end if;

    update live.invites set uses = uses + 1 where id = v_invite.id;
    perform live_app.audit('invite.redeemed', 'invite', v_invite.id::text,
                      jsonb_build_object('role', v_invite.role), v_invite.tenant_id, v_uid);
    return jsonb_build_object('tenant_id', v_invite.tenant_id, 'role', v_user.role,
                              'class_id', v_invite.class_id, 'kind', 'invite');
  end if;

  select * into v_class from live.classes where join_code = v_code and archived_at is null;
  if v_class.id is null then
    -- Returned, not raised: raising would roll back the attempt we need to count.
    delete from live.code_attempts where user_id = v_uid and at < now() - interval '1 day';
    insert into live.code_attempts (user_id) values (v_uid);
    return jsonb_build_object('error', 'No class or invite matches that code.', 'code', 'P0002');
  end if;

  if v_user.id is null then
    insert into live.users (id, tenant_id, email, full_name, role)
      values (v_uid, v_class.tenant_id, coalesce(v_email, ''), v_name, 'student')
      returning * into v_user;
    insert into live.student_profiles (user_id, tenant_id) values (v_uid, v_class.tenant_id);
  elsif v_user.tenant_id <> v_class.tenant_id then
    raise exception 'No class or invite matches that code.' using errcode = 'P0002';
  elsif v_user.role <> 'student' then
    raise exception 'Class codes are for students. Ask an administrator to add you as a teacher.' using errcode = 'P0001';
  end if;

  if not exists (select 1 from live.class_members where class_id = v_class.id and user_id = v_uid) then
    select count(*) into v_count from live.class_members where class_id = v_class.id and role = 'student';
    if not live_app.within_limit(v_class.tenant_id, 'students_per_class', v_count) then
      raise exception 'This class is full on the current plan.' using errcode = 'P0001';
    end if;
    insert into live.class_members (class_id, user_id, tenant_id, role)
      values (v_class.id, v_uid, v_class.tenant_id, 'student');
    perform live_app.notify(v_class.teacher_id, 'student_joined', v_name || ' joined ' || v_class.name,
                       null, '/school/classroom?class=' || v_class.id, 'info',
                       jsonb_build_object('class_id', v_class.id, 'student_id', v_uid));
  end if;

  return jsonb_build_object('tenant_id', v_class.tenant_id, 'role', 'student',
                            'class_id', v_class.id, 'class_name', v_class.name, 'kind', 'class');
end$$;

create or replace function live.join_session(p_code text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me   live.users := live_app.me();
  v_s    live.class_sessions;
  v_pass live.session_guests;
begin
  select * into v_s from live.class_sessions
   where join_code = upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')) and status = 'live';
  if v_s.id is null then raise exception 'No live lesson has that code.' using errcode = 'P0002'; end if;
  if v_s.tenant_id <> v_me.tenant_id then
    -- Same answer as an unknown code: a school never learns that another school exists.
    raise exception 'No live lesson has that code.' using errcode = 'P0002';
  end if;
  if exists (select 1 from live.session_participants where session_id = v_s.id and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if not live_app.in_class(v_s.class_id) and not live_app.can_manage_session(v_s.id) then
    if v_me.role <> 'student' then raise exception 'Only students can join a lesson with a code.' using errcode = '42501'; end if;
    select * into v_pass from live.session_guests where session_id = v_s.id and user_id = v_me.id;
    if v_pass.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
    if v_pass.session_id is null then
      if v_s.phase <> 'lobby' and not coalesce((v_s.settings ->> 'late_join')::boolean, true) then
        raise exception 'This lesson has already started and isn''t taking late joiners.' using errcode = 'P0001';
      end if;
      if v_s.guests_closed then raise exception 'This lesson isn''t taking new joiners. Ask your teacher.' using errcode = 'P0001'; end if;
      insert into live.session_guests (session_id, user_id, tenant_id, display_name, is_guest)
        values (v_s.id, v_me.id, v_s.tenant_id,
                case when length(btrim(v_me.full_name)) < 2 then rpad(btrim(v_me.full_name), 2, '.')
                     else left(btrim(v_me.full_name), 40) end, false);
    end if;
  end if;
  insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
    values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
    on conflict (session_id, user_id) do update set status = 'online', left_at = null, last_seen_at = now();
  return jsonb_build_object('session_id', v_s.id, 'title', v_s.title);
end$$;

create or replace function live_app.progress_answers(p_student uuid, p_from timestamptz, p_to timestamptz, p_teacher uuid default null)
returns table (at timestamptz, session_id uuid, subject text, topic text, is_correct boolean)
language sql stable security definer set search_path = '' as $$
  select qa.answered_at, t.session_id,
         coalesce(nullif(btrim(l.subject), ''), nullif(btrim(c.subject), ''), c.name, 'Other lessons'),
         coalesce(nullif(btrim(q.topic), ''), l.title, a.title),
         qa.is_correct
    from live.quiz_attempts t
    join live.quiz_answers qa on qa.attempt_id = t.id
    join live.questions q on q.id = qa.question_id
    join live.activities a on a.id = t.activity_id
    left join live.lessons l on l.id = a.lesson_id
    left join live.class_sessions s on s.id = t.session_id
    left join live.classes c on c.id = s.class_id
   where t.student_id = p_student and qa.answered_at >= p_from and qa.answered_at < p_to
     -- A teacher sees only their own lessons and classes.
     and (p_teacher is null or s.teacher_id = p_teacher or live_app.can_manage_class(s.class_id)
          or (t.session_id is null and a.owner_id = p_teacher))
$$;

create or replace function live_app.progress_lessons(p_student uuid, p_from timestamptz, p_to timestamptz, p_teacher uuid default null)
returns table (session_id uuid, title text, subject text, started_at timestamptz, attended boolean, points int)
language sql stable security definer set search_path = '' as $$
  select s.id, s.title,
         coalesce(nullif(btrim(l.subject), ''), nullif(btrim(c.subject), ''), c.name, 'Other lessons'),
         s.started_at, p.user_id is not null, coalesce(p.total_score, 0)
    from live.class_sessions s
    left join live.lessons l on l.id = s.lesson_id
    left join live.classes c on c.id = s.class_id
    left join live.session_participants p on p.session_id = s.id and p.user_id = p_student
   where s.tenant_id = (select u.tenant_id from live.users u where u.id = p_student)
     and s.started_at >= p_from and s.started_at < p_to
     and (p_teacher is null or s.teacher_id = p_teacher or live_app.can_manage_class(s.class_id))
     and (p.user_id is not null
          or exists (select 1 from live.class_members m where m.class_id = s.class_id and m.user_id = p_student and m.role = 'student'))
$$;

create or replace function live.progress_report(p_student uuid, p_period text default 'week', p_date date default null)
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_st    live.users;
  v_tz    text;
  v_today date;
  v_day   date;
  v_b     record;
  v_pb    record;
  v_ps    date;    -- previous period, null when there is none
  v_pe    date;
  v_from  timestamptz; v_to timestamptz; v_pfrom timestamptz; v_pto timestamptz;
  v_step  interval;
  v_unit  text;
  v_terms jsonb;
  v_scope uuid;   -- a teacher: only their own lessons and classes
begin
  select * into v_st from live.users where id = p_student and role = 'student';
  if v_st.id is null or not live_app.can_see_student(p_student) then raise exception 'Report not found.' using errcode = 'P0002'; end if;
  v_scope := case when auth.uid() = p_student or live_app.is_parent_of(p_student)
                       or (live_app.is_admin() and v_st.tenant_id = live_app.tenant_id()) then null else auth.uid() end;
  if p_period not in ('day', 'week', 'month', 'term', 'year') then
    raise exception 'Period is day, week, month, term or year.' using errcode = '22023';
  end if;
  select coalesce(t.timezone, 'UTC') into v_tz from live.tenants t where t.id = v_st.tenant_id;
  v_today := (now() at time zone v_tz)::date;
  v_day := coalesce(p_date, v_today);
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'school_year', t.school_year,
                                               'starts_on', t.starts_on, 'ends_on', t.ends_on) order by t.starts_on), '[]'::jsonb)
    into v_terms from live.school_terms t where t.tenant_id = v_st.tenant_id;

  select * into v_b from live_app.period_bounds(v_st.tenant_id, p_period, v_day);
  if v_b.starts is null then
    return jsonb_build_object('student', jsonb_build_object('id', v_st.id, 'name', v_st.full_name), 'period', p_period,
                              'date', v_day, 'today', v_today, 'needs_terms', true, 'terms', v_terms);
  end if;
  select * into v_pb from live_app.period_bounds(v_st.tenant_id, p_period, v_b.starts - 1);
  if v_pb.starts is distinct from v_b.starts then v_ps := v_pb.starts; v_pe := v_pb.ends; end if;   -- else: no earlier term
  v_from := v_b.starts::timestamp at time zone v_tz;
  v_to := v_b.ends::timestamp at time zone v_tz;
  v_pfrom := v_ps::timestamp at time zone v_tz;
  v_pto := v_pe::timestamp at time zone v_tz;
  v_unit := case p_period when 'week' then 'day' when 'month' then 'week' when 'term' then 'week' when 'year' then 'month' end;
  v_step := case v_unit when 'day' then interval '1 day' when 'week' then interval '7 days' when 'month' then interval '1 month' end;

  return (
    with ans as (select * from live_app.progress_answers(p_student, v_from, v_to, v_scope)),
    les as (select * from live_app.progress_lessons(p_student, v_from, v_to, v_scope)),
    pans as (select * from live_app.progress_answers(p_student, v_pfrom, v_pto, v_scope)),
    ples as (select * from live_app.progress_lessons(p_student, v_pfrom, v_pto, v_scope)),
    topics as (
      select a.subject, a.topic, count(*) as answers, count(a.is_correct) as graded,
             round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) as accuracy
        from ans a group by a.subject, a.topic),
    subjects as (select x.subject from ans x union select y.subject from les y)
    select jsonb_build_object(
      'student', jsonb_build_object('id', v_st.id, 'name', v_st.full_name),
      'period', p_period, 'date', v_day, 'today', v_today, 'timezone', v_tz, 'needs_terms', false, 'terms', v_terms, 'scope', case when v_scope is null then 'all' else 'teacher' end,
      'from', v_b.starts, 'to', v_b.ends - 1, 'label', v_b.label, 'unit', v_unit,
      'prev_date', case when v_ps is not null then v_b.starts - 1 end,
      'next_date', case when v_b.ends <= v_today then v_b.ends end,
      'summary', jsonb_build_object(
        'held', (select count(*) from les), 'attended', (select count(*) from les where attended),
        'answers', (select count(*) from ans), 'correct', (select count(*) from ans where is_correct),
        'accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from ans),
        'points', (select coalesce(sum(points), 0) from les where attended),
        'prev_held', case when v_ps is not null then (select count(*) from ples) end,
        'prev_attended', case when v_ps is not null then (select count(*) from ples where attended) end,
        'prev_answers', case when v_ps is not null then (select count(*) from pans) end,
        'prev_accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from pans)),
      'trend', case when v_step is null then '[]'::jsonb else (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'start', greatest(b::date, v_b.starts),
                 'answers', (select count(*) from ans a where (a.at at time zone v_tz) >= b and (a.at at time zone v_tz) < b + v_step),
                 'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from ans a
                              where (a.at at time zone v_tz) >= b and (a.at at time zone v_tz) < b + v_step),
                 'held', (select count(*) from les l where (l.started_at at time zone v_tz) >= b and (l.started_at at time zone v_tz) < b + v_step),
                 'attended', (select count(*) from les l where l.attended and (l.started_at at time zone v_tz) >= b and (l.started_at at time zone v_tz) < b + v_step))
               order by b), '[]'::jsonb)
          from generate_series(date_trunc(v_unit, v_b.starts::timestamp), (v_b.ends - 1)::timestamp, v_step) b) end,
      'subjects', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'subject', s.subject,
                 'held', (select count(*) from les l where l.subject = s.subject),
                 'attended', (select count(*) from les l where l.subject = s.subject and l.attended),
                 'answers', (select count(*) from ans a where a.subject = s.subject),
                 'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from ans a where a.subject = s.subject),
                 'prev_accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from pans a where a.subject = s.subject),
                 'topics', (select coalesce(jsonb_agg(jsonb_build_object('topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy)
                                     order by t.accuracy asc nulls last, t.answers desc), '[]'::jsonb)
                              from topics t where t.subject = s.subject))
               order by (select count(*) from ans a where a.subject = s.subject) desc, s.subject), '[]'::jsonb)
          from subjects s),
      'strengths', (select coalesce(jsonb_agg(jsonb_build_object('subject', t.subject, 'topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy)
                                     order by t.accuracy desc, t.graded desc), '[]'::jsonb)
                      from (select * from topics where graded >= 3 and accuracy >= 80 order by accuracy desc, graded desc limit 5) t),
      'needs_help', (select coalesce(jsonb_agg(jsonb_build_object('subject', t.subject, 'topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy)
                                      order by t.accuracy asc, t.graded desc), '[]'::jsonb)
                       from (select * from topics where graded >= 3 and accuracy < 60 order by accuracy asc, graded desc limit 5) t),
      'lessons', (select coalesce(jsonb_agg(jsonb_build_object(
                   'session_id', l.session_id, 'title', l.title, 'subject', l.subject, 'started_at', l.started_at,
                   'attended', l.attended, 'points', l.points,
                   'answers', (select count(*) from ans a where a.session_id = l.session_id),
                   'accuracy', (select round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) from ans a where a.session_id = l.session_id))
                 order by l.started_at desc), '[]'::jsonb)
                    from (select * from les order by started_at desc limit 60) l))
  );
end$$;

-- ---------------------------------------------------------------------------
-- Parent codes: one standing code per student, seen by staff only
-- ---------------------------------------------------------------------------
alter table live.invites add column if not exists standing boolean not null default false;
create unique index if not exists invites_standing_parent_uidx on live.invites(student_id)
  where standing and revoked_at is null;

/** The student's parent code, made when first needed (up to 4 parents per code). */
create or replace function live_app.parent_code_for(p_student uuid) returns live.invites
language plpgsql volatile security definer set search_path = '' as $$
declare v_i live.invites; v_st live.users;
begin
  select * into v_i from live.invites
   where student_id = p_student and standing and revoked_at is null and expires_at > now() and uses < max_uses;
  if v_i.id is not null then return v_i; end if;
  -- Used up or expired: retire it and make a fresh one.
  update live.invites set revoked_at = now() where student_id = p_student and standing and revoked_at is null;
  select * into v_st from live.users where id = p_student;
  loop
    begin
      insert into live.invites (tenant_id, code, role, student_id, created_by, max_uses, expires_at, standing)
        values (v_st.tenant_id, live_app.gen_code(10), 'parent', p_student, auth.uid(), 4, now() + interval '5 years', true)
        returning * into v_i;
      exit;
    exception when unique_violation then null;  -- the random code was taken: try another
    end;
  end loop;
  return v_i;
end$$;
revoke execute on function live_app.parent_code_for(uuid) from public, anon, authenticated;

/** Parent codes for every student in a class: for its teachers and the school's admins. */
create or replace function live.parent_codes(p_class uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_c live.classes; v_out jsonb := '[]'::jsonb; r record; v_i live.invites;
begin
  select * into v_c from live.classes where id = p_class;
  if v_c.id is null or not (live_app.can_manage_class(p_class) or (live_app.is_admin() and v_c.tenant_id = live_app.tenant_id())) then
    raise exception 'Class not found.' using errcode = 'P0002';
  end if;
  for r in select u.id, u.full_name from live.class_members m join live.users u on u.id = m.user_id
            where m.class_id = p_class and m.role = 'student' order by u.full_name loop
    v_i := live_app.parent_code_for(r.id);
    v_out := v_out || jsonb_build_object('student_id', r.id, 'name', r.full_name, 'code', v_i.code, 'uses', v_i.uses, 'max_uses', v_i.max_uses,
      'parents', (select coalesce(jsonb_agg(p.full_name order by p.full_name), '[]'::jsonb) from live.parent_links pl
                    join live.users p on p.id = pl.parent_id where pl.student_id = r.id and pl.revoked_at is null));
  end loop;
  return jsonb_build_object('class', jsonb_build_object('id', v_c.id, 'name', v_c.name),
                            'school', (select name from live.tenants where id = v_c.tenant_id), 'students', v_out);
end$$;

/** A new parent code for one student (the old one stops working; linked parents stay linked). */
create or replace function live.new_parent_code(p_student uuid) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare v_i live.invites;
begin
  if not (live_app.teaches_student(p_student)
          or (live_app.is_admin() and exists (select 1 from live.users where id = p_student and role = 'student' and tenant_id = live_app.tenant_id()))) then
    raise exception 'Student not found.' using errcode = 'P0002';
  end if;
  update live.invites set revoked_at = now() where student_id = p_student and standing and revoked_at is null;
  v_i := live_app.parent_code_for(p_student);
  perform live_app.audit('parent_code.renewed', 'user', p_student::text, '{}'::jsonb);
  return v_i.code;
end$$;

revoke execute on function live.parent_codes(uuid), live.new_parent_code(uuid) from public, anon;
grant execute on function live.parent_codes(uuid), live.new_parent_code(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Parent feedback to subject teachers (with one reply)
-- ---------------------------------------------------------------------------
create table if not exists live.parent_feedback (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references live.tenants(id) on delete cascade,
  student_id  uuid not null,
  parent_id   uuid not null,
  teacher_id  uuid not null,
  class_id    uuid,
  subject     text not null,
  body        text not null check (length(btrim(body)) between 2 and 2000),
  created_at  timestamptz not null default now(),
  read_at     timestamptz,
  reply       text check (reply is null or length(btrim(reply)) between 1 and 2000),
  replied_at  timestamptz,
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (parent_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (teacher_id, tenant_id) references live.users(id, tenant_id) on delete cascade,
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete set null (class_id)
);
create index if not exists parent_feedback_teacher_idx on live.parent_feedback(teacher_id, created_at desc);
create index if not exists parent_feedback_parent_idx on live.parent_feedback(parent_id, created_at desc);
create index if not exists parent_feedback_tenant_idx on live.parent_feedback(tenant_id, created_at desc);
create index if not exists parent_feedback_student_idx on live.parent_feedback(student_id);
create index if not exists parent_feedback_class_idx on live.parent_feedback(class_id) where class_id is not null;
alter table live.parent_feedback enable row level security;
revoke all on live.parent_feedback from anon;
revoke insert, update, delete on live.parent_feedback from authenticated;
grant select on live.parent_feedback to authenticated;
drop policy if exists parent_feedback_read on live.parent_feedback;drop policy if exists parent_feedback_read on live.parent_feedback;

create policy parent_feedback_read on live.parent_feedback for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (parent_id = (select auth.uid()) or teacher_id = (select auth.uid()) or (select live_app.is_admin())));

/** Who a parent can write to about a child: the teacher of each of the child's classes. */
create or replace function live.feedback_targets(p_student uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('class_id', c.id, 'subject', coalesce(nullif(btrim(c.subject), ''), c.name),
                                               'class', c.name, 'teacher_id', t.id, 'teacher', t.full_name)
                            order by coalesce(nullif(btrim(c.subject), ''), c.name)), '[]'::jsonb)
    from live.class_members m join live.classes c on c.id = m.class_id join live.users t on t.id = c.teacher_id
   where m.user_id = p_student and m.role = 'student' and c.archived_at is null and live_app.is_parent_of(p_student)
$$;

create or replace function live.send_parent_feedback(p_student uuid, p_class uuid, p_body text) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_me live.users := live_app.me(); v_c live.classes; v_id uuid; v_child text;
begin
  if v_me.role <> 'parent' or not live_app.is_parent_of(p_student) then raise exception 'Not your child.' using errcode = '42501'; end if;
  select c.* into v_c from live.classes c join live.class_members m on m.class_id = c.id
   where c.id = p_class and m.user_id = p_student and m.role = 'student';
  if v_c.id is null then raise exception 'That class isn''t one of your child''s.' using errcode = 'P0002'; end if;
  if (select count(*) from live.parent_feedback where parent_id = v_me.id and created_at > now() - interval '1 day') >= 20 then
    raise exception 'You''ve sent a lot of feedback today. Please try again tomorrow.' using errcode = 'P0001';
  end if;
  insert into live.parent_feedback (tenant_id, student_id, parent_id, teacher_id, class_id, subject, body)
    values (v_me.tenant_id, p_student, v_me.id, v_c.teacher_id, v_c.id, coalesce(nullif(btrim(v_c.subject), ''), v_c.name), btrim(p_body))
    returning id into v_id;
  select full_name into v_child from live.users where id = p_student;
  perform live_app.notify(v_c.teacher_id, 'parent_feedback', 'Feedback from ' || v_me.full_name, 'About ' || v_child || ' in ' || v_c.name,
                     '/school/inbox', 'info', jsonb_build_object('feedback_id', v_id));
  return v_id;
end$$;

create or replace function live.reply_parent_feedback(p_feedback uuid, p_reply text) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v_f live.parent_feedback;
begin
  select * into v_f from live.parent_feedback where id = p_feedback and teacher_id = auth.uid() for update;
  if v_f.id is null then raise exception 'Feedback not found.' using errcode = 'P0002'; end if;
  update live.parent_feedback set reply = btrim(p_reply), replied_at = now(), read_at = coalesce(read_at, now()) where id = p_feedback;
  perform live_app.notify(v_f.parent_id, 'feedback_reply', 'Your ' || v_f.subject || ' teacher replied', left(btrim(p_reply), 140),
                     '/parent?child=' || v_f.student_id, 'info', jsonb_build_object('feedback_id', v_f.id));
end$$;

/** Feedback the caller may see: a parent's own, a teacher's inbox, or the whole school for admins. */
create or replace function live.parent_feedback_list(p_student uuid default null, p_unread_only boolean default false) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_me live.users := live_app.me(); v_out jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'student_id', f.student_id, 'student', s.full_name, 'parent', p.full_name,
           'teacher_id', f.teacher_id, 'teacher', t.full_name, 'class_id', f.class_id, 'subject', f.subject, 'body', f.body,
           'created_at', f.created_at, 'read_at', f.read_at, 'reply', f.reply, 'replied_at', f.replied_at,
           'mine', f.teacher_id = v_me.id) order by f.created_at desc), '[]'::jsonb)
    into v_out
    from (select * from live.parent_feedback x
           where x.tenant_id = v_me.tenant_id
             and (x.parent_id = v_me.id or x.teacher_id = v_me.id or live_app.is_admin())
             and (p_student is null or x.student_id = p_student)
             and (not p_unread_only or x.read_at is null)
           order by x.created_at desc limit 300) f
    join live.users s on s.id = f.student_id join live.users p on p.id = f.parent_id join live.users t on t.id = f.teacher_id;
  -- A teacher opening their inbox has read what was sent to them.
  update live.parent_feedback set read_at = now() where teacher_id = v_me.id and read_at is null
     and (p_student is null or student_id = p_student);
  return v_out;
end$$;

revoke execute on function live.feedback_targets(uuid), live.send_parent_feedback(uuid, uuid, text),
  live.reply_parent_feedback(uuid, text), live.parent_feedback_list(uuid, boolean) from public, anon;
grant execute on function live.feedback_targets(uuid), live.send_parent_feedback(uuid, uuid, text),
  live.reply_parent_feedback(uuid, text), live.parent_feedback_list(uuid, boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- School-wide progress for admins: where pupils struggle
-- ---------------------------------------------------------------------------
create or replace function live.school_progress(p_period text default 'term', p_date date default null, p_class uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_tenant uuid := live_app.tenant_id();
  v_tz text; v_today date; v_day date; v_b record; v_from timestamptz; v_to timestamptz;
begin
  if v_tenant is null or not live_app.is_admin() then raise exception 'Only school admins can see this.' using errcode = '42501'; end if;
  if p_class is not null and not exists (select 1 from live.classes where id = p_class and tenant_id = v_tenant) then
    raise exception 'Class not found.' using errcode = 'P0002';
  end if;
  select coalesce(timezone, 'UTC') into v_tz from live.tenants where id = v_tenant;
  v_today := (now() at time zone v_tz)::date;
  v_day := coalesce(p_date, v_today);
  select * into v_b from live_app.period_bounds(v_tenant, p_period, v_day);
  if v_b.starts is null then
    return jsonb_build_object('period', p_period, 'date', v_day, 'needs_terms', true);
  end if;
  v_from := v_b.starts::timestamp at time zone v_tz;
  v_to := v_b.ends::timestamp at time zone v_tz;

  return (
    with pupils as (
      select u.id, u.full_name from live.users u
       where u.tenant_id = v_tenant and u.role = 'student' and u.status = 'active'
         and (p_class is null or exists (select 1 from live.class_members m where m.class_id = p_class and m.user_id = u.id and m.role = 'student'))),
    ans as (
      select t.student_id, qa.is_correct,
             coalesce(nullif(btrim(l.subject), ''), nullif(btrim(c.subject), ''), c.name, 'Other lessons') as subject,
             coalesce(nullif(btrim(q.topic), ''), l.title, a.title) as topic
        from live.quiz_attempts t
        join pupils pu on pu.id = t.student_id
        join live.quiz_answers qa on qa.attempt_id = t.id
        join live.questions q on q.id = qa.question_id
        join live.activities a on a.id = t.activity_id
        left join live.lessons l on l.id = a.lesson_id
        left join live.class_sessions s on s.id = t.session_id
        left join live.classes c on c.id = s.class_id
       where t.tenant_id = v_tenant and qa.answered_at >= v_from and qa.answered_at < v_to),
    per_topic as (
      select subject, topic, count(*) as answers, count(is_correct) as graded,
             round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy,
             count(distinct student_id) as pupils
        from ans group by subject, topic),
    per_pupil_topic as (
      select student_id, subject, topic, round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy
        from ans group by student_id, subject, topic having count(is_correct) >= 2),
    per_pupil as (
      select a.student_id, count(*) as answers, round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) as accuracy
        from ans a group by a.student_id)
    select jsonb_build_object(
      'period', p_period, 'date', v_day, 'today', v_today, 'needs_terms', false, 'label', v_b.label, 'from', v_b.starts, 'to', v_b.ends - 1,
      'prev_date', v_b.starts - 1, 'next_date', case when v_b.ends <= v_today then v_b.ends end,
      'classes', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name), '[]'::jsonb)
                    from live.classes c where c.tenant_id = v_tenant and c.archived_at is null),
      'summary', jsonb_build_object(
        'pupils', (select count(*) from pupils), 'active', (select count(distinct student_id) from ans),
        'answers', (select count(*) from ans),
        'accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from ans)),
      'subjects', (select coalesce(jsonb_agg(jsonb_build_object(
          'subject', sb.subject, 'answers', sb.answers, 'accuracy', sb.accuracy, 'pupils', sb.pupils,
          'topics', (select coalesce(jsonb_agg(jsonb_build_object('topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy, 'pupils', t.pupils,
                       'struggling', (select count(*) from per_pupil_topic x where x.subject = t.subject and x.topic = t.topic and x.accuracy < 50))
                       order by t.accuracy asc nulls last, t.answers desc), '[]'::jsonb)
                     from per_topic t where t.subject = sb.subject))
          order by sb.answers desc), '[]'::jsonb)
        from (select subject, count(*) as answers, count(distinct student_id) as pupils,
                     round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy
                from ans group by subject) sb),
      'hardest', (select coalesce(jsonb_agg(jsonb_build_object('subject', t.subject, 'topic', t.topic, 'answers', t.answers,
                     'accuracy', t.accuracy, 'pupils', t.pupils,
                     'struggling', (select count(*) from per_pupil_topic x where x.subject = t.subject and x.topic = t.topic and x.accuracy < 50))
                     order by t.accuracy asc, t.answers desc), '[]'::jsonb)
                    from (select * from per_topic where graded >= 5 and accuracy < 60 order by accuracy asc, answers desc limit 10) t),
      'pupils_needing_help', (select coalesce(jsonb_agg(jsonb_build_object('student_id', pp.student_id, 'name', u.full_name,
                     'answers', pp.answers, 'accuracy', pp.accuracy,
                     'weakest', (select jsonb_build_object('subject', x.subject, 'topic', x.topic, 'accuracy', x.accuracy)
                                   from per_pupil_topic x where x.student_id = pp.student_id order by x.accuracy asc limit 1),
                     'classes', (select coalesce(jsonb_agg(c.name order by c.name), '[]'::jsonb) from live.class_members m
                                   join live.classes c on c.id = m.class_id where m.user_id = pp.student_id and m.role = 'student'))
                     order by pp.accuracy asc, pp.answers desc), '[]'::jsonb)
                    from (select * from per_pupil where answers >= 5 and accuracy < 50 order by accuracy asc limit 30) pp
                    join live.users u on u.id = pp.student_id),
      'feedback', (select jsonb_build_object('total', count(*), 'unanswered', count(*) filter (where reply is null))
                     from live.parent_feedback where tenant_id = v_tenant and created_at >= v_from and created_at < v_to))
  );
end$$;
revoke execute on function live.school_progress(text, date, uuid) from public, anon;
grant execute on function live.school_progress(text, date, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Platform support accounts ("Open as admin" from the platform console)
-- ---------------------------------------------------------------------------
alter table live.users add column if not exists is_support boolean not null default false;

revoke execute on function live_app.progress_answers(uuid, timestamptz, timestamptz, uuid), live_app.progress_lessons(uuid, timestamptz, timestamptz, uuid)
  from public, anon, authenticated;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0950')
$$;

-- ===================== 20260901000960_signup_support.sql =====================
-- 0960: who is signing up, and the platform's support account in a school.
--
-- * redeem_code takes who is joining (p_as: student, parent or staff) and
--   refuses a code meant for someone else before creating anything.
-- * "Open as admin" from the platform console: each school gets one support
--   account ("SwiftCipher support", a school admin, marked is_support). The
--   console signs the super admin into it; the school's audit log shows
--   "SwiftCipher support", the platform audit log shows who. It never counts
--   towards the school's staff limit.

drop function if exists live.redeem_code(text, text);

create or replace function live.redeem_code(p_code text, p_full_name text default null, p_as text default null)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid     uuid := auth.uid();
  v_code    text := upper(btrim(coalesce(p_code, '')));
  v_email   text;
  v_meta    jsonb;
  v_user    live.users;
  v_class   live.classes;
  v_invite  live.invites;
  v_name    text;
  v_count   bigint;
begin
  if v_uid is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  -- Guessing protection: class codes are short enough to type, so wrong guesses are limited.
  if (select count(*) from live.code_attempts where user_id = v_uid and at > now() - interval '15 minutes') >= 8 then
    raise exception 'Too many wrong codes. Wait 15 minutes, then check the code with your teacher.' using errcode = 'P0001';
  end if;
  if v_code !~ '^[A-Z0-9]{6,12}$' then raise exception 'That code is not valid.' using errcode = '22023'; end if;

  select email, raw_user_meta_data into v_email, v_meta from auth.users where id = v_uid;
  select * into v_user from live.users where id = v_uid;
  v_name := coalesce(nullif(btrim(p_full_name), ''), nullif(btrim(v_meta ->> 'full_name'), ''),
                     split_part(coalesce(v_email, 'user'), '@', 1));

  -- Invite codes take precedence (8-12 chars); class codes are 6-8.
  select * into v_invite from live.invites
   where code = v_code and revoked_at is null and expires_at > now() and uses < max_uses
   for update;

  if v_invite.id is not null then
    -- The sign-up form says who is joining (student, parent or staff): a code for someone else is refused
    -- before anything is created, so a parent can't become a student by typing the wrong code.
    if p_as is not null and not (case when p_as = 'staff' then v_invite.role in ('teacher', 'school_admin', 'it_admin')
                                      else v_invite.role = p_as end) then
      raise exception '%', case v_invite.role when 'parent' then 'That is a parent code. Choose "Parent" to use it.'
                                              when 'student' then 'That code is for a student. Choose "Student" to use it.'
                                              else 'That is a staff invite. Choose "Staff" to use it.' end using errcode = 'P0001';
    end if;
    if v_invite.email is not null and lower(v_invite.email) <> lower(coalesce(v_email, '')) then
      raise exception 'This invite was issued for a different email address.' using errcode = '42501';
    end if;

    if v_user.id is null then
      insert into live.users (id, tenant_id, email, full_name, role)
        values (v_uid, v_invite.tenant_id, coalesce(v_email, ''), v_name, v_invite.role)
        returning * into v_user;
      if v_invite.role = 'student' then
        insert into live.student_profiles (user_id, tenant_id) values (v_uid, v_invite.tenant_id);
      elsif v_invite.role in ('teacher','school_admin','it_admin') then
        insert into live.teacher_profiles (user_id, tenant_id) values (v_uid, v_invite.tenant_id);
      end if;
    elsif v_user.tenant_id <> v_invite.tenant_id then
      raise exception 'No class or invite matches that code.' using errcode = 'P0002';
    elsif v_user.role <> v_invite.role then
      raise exception 'This invite is for a % account.', v_invite.role using errcode = 'P0001';
    end if;

    if v_invite.class_id is not null then
      insert into live.class_members (class_id, user_id, tenant_id, role)
        values (v_invite.class_id, v_uid, v_invite.tenant_id,
                case when v_invite.role = 'student' then 'student' else 'teacher' end)
        on conflict (class_id, user_id) do nothing;
    end if;
    if v_invite.role = 'parent' then
      insert into live.parent_links (tenant_id, parent_id, student_id)
        values (v_invite.tenant_id, v_uid, v_invite.student_id)
        on conflict (parent_id, student_id) do update set revoked_at = null;
    end if;

    update live.invites set uses = uses + 1 where id = v_invite.id;
    perform live_app.audit('invite.redeemed', 'invite', v_invite.id::text,
                      jsonb_build_object('role', v_invite.role), v_invite.tenant_id, v_uid);
    return jsonb_build_object('tenant_id', v_invite.tenant_id, 'role', v_user.role,
                              'class_id', v_invite.class_id, 'kind', 'invite');
  end if;

  select * into v_class from live.classes where join_code = v_code and archived_at is null;
  if v_class.id is null then
    -- Returned, not raised: raising would roll back the attempt we need to count.
    delete from live.code_attempts where user_id = v_uid and at < now() - interval '1 day';
    insert into live.code_attempts (user_id) values (v_uid);
    return jsonb_build_object('error', 'No class or invite matches that code.', 'code', 'P0002');
  end if;

  if p_as is not null and p_as <> 'student' then
    raise exception '%', case p_as when 'parent' then 'That is a class code for students. Parents use the parent code from the school, not the class code.'
                                   else 'That is a class code for students. Staff join with an invite from the school admin.' end using errcode = 'P0001';
  end if;
  if v_user.id is null then
    insert into live.users (id, tenant_id, email, full_name, role)
      values (v_uid, v_class.tenant_id, coalesce(v_email, ''), v_name, 'student')
      returning * into v_user;
    insert into live.student_profiles (user_id, tenant_id) values (v_uid, v_class.tenant_id);
  elsif v_user.tenant_id <> v_class.tenant_id then
    raise exception 'No class or invite matches that code.' using errcode = 'P0002';
  elsif v_user.role <> 'student' then
    raise exception 'Class codes are for students. Ask an administrator to add you as a teacher.' using errcode = 'P0001';
  end if;

  if not exists (select 1 from live.class_members where class_id = v_class.id and user_id = v_uid) then
    select count(*) into v_count from live.class_members where class_id = v_class.id and role = 'student';
    if not live_app.within_limit(v_class.tenant_id, 'students_per_class', v_count) then
      raise exception 'This class is full on the current plan.' using errcode = 'P0001';
    end if;
    insert into live.class_members (class_id, user_id, tenant_id, role)
      values (v_class.id, v_uid, v_class.tenant_id, 'student');
    perform live_app.notify(v_class.teacher_id, 'student_joined', v_name || ' joined ' || v_class.name,
                       null, '/school/classroom?class=' || v_class.id, 'info',
                       jsonb_build_object('class_id', v_class.id, 'student_id', v_uid));
  end if;

  return jsonb_build_object('tenant_id', v_class.tenant_id, 'role', 'student',
                            'class_id', v_class.id, 'class_name', v_class.name, 'kind', 'class');
end$$;

create or replace function live.create_invite(
  p_role text, p_email text default null, p_class uuid default null, p_student uuid default null,
  p_days int default 14, p_max_uses int default 1
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me     live.users := live_app.me();
  v_invite live.invites;
begin
  if p_role not in ('student','teacher','it_admin','school_admin','parent') then
    raise exception 'Unknown role.' using errcode = '22023';
  end if;
  if p_days not between 1 and 90 or p_max_uses not between 1 and 1000 then
    raise exception 'Invites last 1-90 days and allow 1-1000 uses.' using errcode = '22023';
  end if;

  if p_role in ('teacher','it_admin','school_admin') then
    if not live_app.is_admin() then raise exception 'Only administrators can invite staff.' using errcode = '42501'; end if;
    if p_role in ('teacher','school_admin') and not live_app.within_limit(v_me.tenant_id, 'teachers',
         (select count(*) from live.users where tenant_id = v_me.tenant_id and role in ('teacher','school_admin') and not is_support)) then
      raise exception 'Your plan''s teacher limit has been reached.' using errcode = 'P0001';
    end if;
  elsif p_role = 'student' then
    if p_class is null then raise exception 'Student invites need a class.' using errcode = '22023'; end if;
    if not live_app.can_manage_class(p_class) then raise exception 'Not your class.' using errcode = '42501'; end if;
  elsif p_role = 'parent' then
    if p_student is null then raise exception 'Parent invites need a student.' using errcode = '22023'; end if;
    if not (live_app.is_admin() or live_app.teaches_student(p_student)) then
      raise exception 'You can only invite parents of your own students.' using errcode = '42501';
    end if;
    if not exists (select 1 from live.users where id = p_student and tenant_id = v_me.tenant_id and role = 'student') then
      raise exception 'Student not found.' using errcode = 'P0002';
    end if;
  end if;

  if p_class is not null and not exists (select 1 from live.classes where id = p_class and tenant_id = v_me.tenant_id) then
    raise exception 'Class not found.' using errcode = 'P0002';
  end if;

  insert into live.invites (tenant_id, code, role, email, class_id, student_id, created_by, max_uses, expires_at)
    values (v_me.tenant_id, live_app.unique_code(10, 'invites'), p_role, nullif(lower(btrim(p_email)), ''),
            p_class, p_student, v_me.id, p_max_uses, now() + make_interval(days => p_days))
    returning * into v_invite;
  perform live_app.audit('invite.created', 'invite', v_invite.id::text,
                    jsonb_build_object('role', p_role, 'class_id', p_class, 'student_id', p_student));
  return to_jsonb(v_invite);
end$$;

create table if not exists live.support_accounts (
  tenant_id  uuid primary key references live.tenants(id) on delete cascade,
  user_id    uuid not null unique references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table live.support_accounts enable row level security;
revoke all on live.support_accounts from anon, authenticated;

/** The address of a school's support account (never sent to; it has no password). */
create or replace function live_app.support_email(p_tenant uuid) returns text
language sql immutable set search_path = '' as $$
  select 'support-' || left(replace(p_tenant::text, '-', ''), 16) || '@support.swiftcipher.invalid'
$$;

/**
 * Super admin: the school's support account (its auth user id, or null when it
 * still has to be created) and the address to sign it in with. Records the visit.
 */
create or replace function live.sa_support_account(p_tenant uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_t live.tenants; v_user uuid;
begin
  perform live_app.sa_require();
  select * into v_t from live.tenants where id = p_tenant;
  if v_t.id is null then raise exception 'School not found.' using errcode = 'P0002'; end if;
  select user_id into v_user from live.support_accounts where tenant_id = p_tenant;
  if v_user is not null then
    -- The super admin's authority: the account is always an active admin of this school.
    update live.users set status = 'active', role = 'school_admin', is_support = true where id = v_user and tenant_id = p_tenant;
    if not found then v_user := null; end if;
  end if;
  insert into live.platform_audit (actor_id, action, tenant_id, target_type, target_id)
    values (auth.uid(), 'support.enter', p_tenant, 'tenant', p_tenant::text);
  return jsonb_build_object('user_id', v_user, 'email', live_app.support_email(p_tenant), 'school', v_t.name, 'status', v_t.status);
end$$;

/** Super admin: makes the auth user just created for the school its support account. */
create or replace function live.sa_register_support(p_tenant uuid, p_user uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  perform live_app.sa_require();
  if not exists (select 1 from auth.users where id = p_user and lower(email) = live_app.support_email(p_tenant)) then
    raise exception 'Not a support account.' using errcode = '22023';
  end if;
  if exists (select 1 from live.users where id = p_user and tenant_id <> p_tenant) then
    raise exception 'Not a support account.' using errcode = '22023';
  end if;
  insert into live.users (id, tenant_id, email, full_name, role, is_support)
    values (p_user, p_tenant, live_app.support_email(p_tenant), 'SwiftCipher support', 'school_admin', true)
    on conflict (id) do update set status = 'active', role = 'school_admin', is_support = true;
  insert into live.teacher_profiles (user_id, tenant_id) values (p_user, p_tenant) on conflict do nothing;
  insert into live.support_accounts (tenant_id, user_id) values (p_tenant, p_user)
    on conflict (tenant_id) do update set user_id = excluded.user_id;
  perform live_app.audit('support.account_created', 'user', p_user::text, '{}'::jsonb, p_tenant, p_user);
end$$;

revoke execute on function live.sa_support_account(uuid), live.sa_register_support(uuid, uuid) from public, anon;
grant execute on function live.sa_support_account(uuid), live.sa_register_support(uuid, uuid) to authenticated;
revoke execute on function live.redeem_code(text, text, text) from public, anon;
grant execute on function live.redeem_code(text, text, text) to authenticated;

-- The profile says when it is the platform's support account (for the "Return to console" bar).
create or replace function live.me() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_user live.users;
  v_out  jsonb;
begin
  if auth.uid() is null then return null; end if;
  select * into v_user from live.users where id = auth.uid();
  if v_user.id is null then
    return jsonb_build_object('profile', null, 'super_admin', live_app.is_super_admin(),
      'email', (select email from auth.users where id = auth.uid()));
  end if;
  select jsonb_build_object(
    'profile', jsonb_build_object('id', v_user.id, 'tenant_id', v_user.tenant_id, 'email', v_user.email,
                                  'full_name', v_user.full_name, 'nickname', v_user.nickname,
                                  'role', v_user.role, 'status', v_user.status, 'is_support', v_user.is_support),
    'tenant', jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug, 'plan_code', t.plan_code,
                                 'timezone', t.timezone, 'status', t.status),
    'plan', jsonb_build_object('code', p.code, 'name', p.name, 'limits', p.limits, 'features', p.features),
    'settings', to_jsonb(ts) - 'tenant_id',
    'monitoring_consent', exists (select 1 from live.consents c where c.user_id = v_user.id
                                  and c.kind = 'monitoring_notice' and c.version = ts.monitoring_notice_version),
    'unread_notifications', (select count(*) from live.notifications n
                             where n.user_id = v_user.id and n.read_at is null),
    'super_admin', live_app.is_super_admin()
  ) into v_out
  from live.tenants t
  join live.plans p on p.code = t.plan_code
  join live.tenant_settings ts on ts.tenant_id = t.id
  where t.id = v_user.tenant_id;
  return v_out;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0960')
$$;

-- ===================== 20260901000970_rosters.sql =====================
-- 0970: class rosters run by staff, promotion, and each student's own classes.
--
-- * Staff add students themselves (one by one, or from a CSV or Excel file).
--   The server creates each login (a username, or the student's email) with a
--   starting password; the student must choose a new one at first sign-in.
--   Usernames live in users.login_name; the admission number in
--   student_profiles.student_number.
-- * Staff edit a student's name and admission number, and reset the password
--   of school-made logins. School admins can delete a student's account.
-- * Promotion: a class's students (all or some) move to another class of the
--   school; admins can promote every class at once at the end of the year.
-- * my_classes: the classes a student is in, each with their own results this
--   term (or school year), for the student's home page.

alter table live.users add column if not exists login_name text;
alter table live.users add column if not exists must_change_password boolean not null default false;
alter table live.users drop constraint if exists users_login_name_check;alter table live.users drop constraint if exists users_login_name_check;

alter table live.users add constraint users_login_name_check check (login_name is null or login_name ~ '^[a-z0-9][a-z0-9.]{2,40}$');
create unique index if not exists users_login_name_uidx on live.users(login_name) where login_name is not null;

/** Staff who may look after this student: their teachers, or the school's admins. */
create or replace function live_app.can_manage_student(p_student uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.teaches_student(p_student)
      or (live_app.is_admin() and exists (select 1 from live.users u where u.id = p_student and u.role = 'student' and u.tenant_id = live_app.tenant_id()))
$$;
revoke execute on function live_app.can_manage_student(uuid) from public, anon;

/** A student who already has an account in this school joins the class (matched by email). */
create or replace function live.add_existing_student(p_class uuid, p_email text) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_c live.classes; v_id uuid;
begin
  select * into v_c from live.classes where id = p_class;
  if v_c.id is null or not live_app.can_manage_class(p_class) then raise exception 'Class not found.' using errcode = 'P0002'; end if;
  select id into v_id from live.users
   where tenant_id = v_c.tenant_id and role = 'student' and lower(email) = lower(btrim(p_email));
  if v_id is null then return null; end if;
  insert into live.class_members (class_id, user_id, tenant_id, role) values (p_class, v_id, v_c.tenant_id, 'student')
    on conflict (class_id, user_id) do nothing;
  return v_id;
end$$;

/**
 * Makes the login the server has just created (p_user, with address p_email) a
 * student of this class's school. Only a brand-new login with no school yet qualifies.
 */
create or replace function live.add_managed_student(
  p_class uuid, p_user uuid, p_email text, p_name text, p_login text default null, p_admission text default null
) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_c live.classes; v_count bigint;
begin
  select * into v_c from live.classes where id = p_class;
  if v_c.id is null or not live_app.can_manage_class(p_class) then raise exception 'Class not found.' using errcode = 'P0002'; end if;
  if v_c.archived_at is not null then raise exception 'This class is archived.' using errcode = 'P0001'; end if;
  if not exists (select 1 from auth.users where id = p_user and lower(email) = lower(p_email) and created_at > now() - interval '15 minutes')
     or exists (select 1 from live.users where id = p_user) then
    raise exception 'That login is not new.' using errcode = '22023';
  end if;
  select count(*) into v_count from live.class_members where class_id = p_class and role = 'student';
  if not live_app.within_limit(v_c.tenant_id, 'students_per_class', v_count) then
    raise exception 'This class is full on the current plan.' using errcode = 'P0001';
  end if;
  insert into live.users (id, tenant_id, email, full_name, role, login_name, must_change_password)
    values (p_user, v_c.tenant_id, lower(p_email), btrim(p_name), 'student', nullif(lower(btrim(p_login)), ''), true);
  insert into live.student_profiles (user_id, tenant_id, student_number) values (p_user, v_c.tenant_id, nullif(btrim(p_admission), ''));
  insert into live.class_members (class_id, user_id, tenant_id, role) values (p_class, p_user, v_c.tenant_id, 'student');
  perform live_app.audit('student.added', 'user', p_user::text, jsonb_build_object('class_id', p_class));
  return p_user;
end$$;

create or replace function live.update_student(p_student uuid, p_name text, p_admission text default null) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not live_app.can_manage_student(p_student) then raise exception 'Student not found.' using errcode = 'P0002'; end if;
  update live.users set full_name = btrim(p_name) where id = p_student and role = 'student';
  insert into live.student_profiles (user_id, tenant_id, student_number)
    select id, tenant_id, nullif(btrim(p_admission), '') from live.users where id = p_student
    on conflict (user_id) do update set student_number = excluded.student_number;
  perform live_app.audit('student.updated', 'user', p_student::text, '{}'::jsonb);
end$$;

/** Before the server sets a new starting password: only for school-made logins. */
create or replace function live.prepare_password_reset(p_student uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v live.users;
begin
  if not live_app.can_manage_student(p_student) then raise exception 'Student not found.' using errcode = 'P0002'; end if;
  select * into v from live.users where id = p_student;
  if v.login_name is null then
    raise exception 'This student signs in with their own email. They can use "Forgot password" on the sign-in page.' using errcode = 'P0001';
  end if;
  update live.users set must_change_password = true where id = p_student;
  perform live_app.audit('student.password_reset', 'user', p_student::text, '{}'::jsonb);
  return jsonb_build_object('login_name', v.login_name);
end$$;

/** The signed-in user has chosen their own password. */
create or replace function live.password_changed() returns void
language sql volatile security definer set search_path = '' as $$
  update live.users set must_change_password = false where id = auth.uid()
$$;

/** School admins only, typing the student's name: then the server deletes the login (and everything with it). */
create or replace function live.delete_student_check(p_student uuid, p_confirm_name text) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v live.users;
begin
  select * into v from live.users where id = p_student and role = 'student';
  if v.id is null or not live_app.is_admin() or v.tenant_id <> live_app.tenant_id() then raise exception 'Student not found.' using errcode = 'P0002'; end if;
  if lower(btrim(coalesce(p_confirm_name, ''))) <> lower(btrim(v.full_name)) then
    raise exception 'Type the student''s full name exactly to confirm.' using errcode = '22023';
  end if;
  perform live_app.audit('student.deleted', 'user', p_student::text, jsonb_build_object('name', v.full_name));
end$$;

-- ---------------------------------------------------------------------------
-- Promotion
-- ---------------------------------------------------------------------------

/** Classes a class can be promoted into: the school's other open classes. */
create or replace function live.promotion_targets(p_class uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'subject', c.subject, 'teacher', t.full_name,
           'students', (select count(*) from live.class_members m where m.class_id = c.id and m.role = 'student')) order by c.name), '[]'::jsonb)
    from live.classes c left join live.users t on t.id = c.teacher_id
   where live_app.can_manage_class(p_class) and c.id <> p_class and c.archived_at is null
     and c.tenant_id = (select tenant_id from live.classes where id = p_class)
$$;

/** Moves students (all, or those listed) from one class to another. Their results stay with them. */
create or replace function live.promote_students(p_from uuid, p_to uuid, p_students uuid[] default null) returns int
language plpgsql volatile security definer set search_path = '' as $$
declare v_f live.classes; v_t live.classes; v_n int; v_after bigint;
begin
  select * into v_f from live.classes where id = p_from;
  select * into v_t from live.classes where id = p_to;
  if v_f.id is null or not live_app.can_manage_class(p_from) then raise exception 'Class not found.' using errcode = 'P0002'; end if;
  if v_t.id is null or v_t.tenant_id <> v_f.tenant_id or v_t.archived_at is not null or p_to = p_from then
    raise exception 'Choose another open class of your school.' using errcode = '22023';
  end if;
  select count(distinct user_id) into v_after from live.class_members
   where role = 'student' and (class_id = p_to or (class_id = p_from and (p_students is null or user_id = any(p_students))));
  if not live_app.within_limit(v_t.tenant_id, 'students_per_class', v_after - 1) then
    raise exception 'The next class would be over the plan''s class size.' using errcode = 'P0001';
  end if;
  with moving as (
         select user_id from live.class_members
          where class_id = p_from and role = 'student' and (p_students is null or user_id = any(p_students))),
       ins as (
         insert into live.class_members (class_id, user_id, tenant_id, role)
           select p_to, user_id, v_t.tenant_id, 'student' from moving
           on conflict (class_id, user_id) do nothing returning user_id),
       del as (
         delete from live.class_members m using moving
          where m.class_id = p_from and m.user_id = moving.user_id returning m.user_id)
  select count(*) into v_n from del;
  perform live_app.audit('class.promoted', 'class', p_from::text, jsonb_build_object('to', p_to, 'students', v_n));
  return v_n;
end$$;

/**
 * End of year, school admins: every class to its next class at once, e.g.
 * [{from: JSS 1, to: JSS 2}, {from: JSS 2, to: JSS 3}, {from: SS 3, to: null}].
 * "to": null means the students leave that class (finished school). Everyone
 * moves from where they were before the promotion, so chains work.
 */
create or replace function live.promote_school(p_moves jsonb) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_tenant uuid := live_app.tenant_id(); v_moved int; v_left int;
begin
  if v_tenant is null or not live_app.is_admin() then raise exception 'Only school admins can promote the whole school.' using errcode = '42501'; end if;
  if jsonb_typeof(p_moves) <> 'array' then raise exception 'Moves must be a list.' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_array_elements(p_moves) e
              where not exists (select 1 from live.classes c where c.id = (e ->> 'from')::uuid and c.tenant_id = v_tenant)
                 or (nullif(e ->> 'to', '') is not null
                     and not exists (select 1 from live.classes c where c.id = (e ->> 'to')::uuid and c.tenant_id = v_tenant and c.archived_at is null))) then
    raise exception 'A class in the list is not one of your school''s open classes.' using errcode = '22023';
  end if;
  if (select count(*) from jsonb_array_elements(p_moves)) <> (select count(distinct e ->> 'from') from jsonb_array_elements(p_moves) e) then
    raise exception 'Each class can appear once.' using errcode = '22023';
  end if;
  with moves as (select (e ->> 'from')::uuid as f, nullif(e ->> 'to', '')::uuid as t from jsonb_array_elements(p_moves) e),
       cur as (select m.user_id, mv.f, mv.t from moves mv join live.class_members m on m.class_id = mv.f and m.role = 'student'),
       del as (delete from live.class_members m using cur where m.class_id = cur.f and m.user_id = cur.user_id returning 1),
       ins as (insert into live.class_members (class_id, user_id, tenant_id, role)
                 select cur.t, cur.user_id, v_tenant, 'student' from cur where cur.t is not null
                 on conflict (class_id, user_id) do nothing returning 1)
  select (select count(*) from ins), (select count(*) from cur where t is null) into v_moved, v_left;
  perform live_app.audit('school.promoted', 'tenant', v_tenant::text, jsonb_build_object('moved', v_moved, 'left', v_left, 'classes', jsonb_array_length(p_moves)));
  return jsonb_build_object('moved', v_moved, 'left', v_left);
end$$;

-- ---------------------------------------------------------------------------
-- A student's own classes, each with their results
-- ---------------------------------------------------------------------------
create or replace function live.my_classes() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_me live.users := live_app.me(); v_tz text; v_b record; v_from timestamptz; v_to timestamptz;
begin
  if v_me.id is null or v_me.role <> 'student' then return '[]'::jsonb; end if;
  select coalesce(timezone, 'UTC') into v_tz from live.tenants where id = v_me.tenant_id;
  select * into v_b from live_app.period_bounds(v_me.tenant_id, 'term', (now() at time zone v_tz)::date);
  if v_b.starts is null then select * into v_b from live_app.period_bounds(v_me.tenant_id, 'year', (now() at time zone v_tz)::date); end if;
  v_from := v_b.starts::timestamp at time zone v_tz;
  v_to := v_b.ends::timestamp at time zone v_tz;
  return (
    with mine as (
      select c.id, c.name, c.subject, t.full_name as teacher
        from live.class_members m join live.classes c on c.id = m.class_id left join live.users t on t.id = c.teacher_id
       where m.user_id = v_me.id and m.role = 'student' and c.archived_at is null),
    ans as (
      select s.class_id, qa.is_correct, coalesce(nullif(btrim(q.topic), ''), l.title, a.title) as topic
        from live.quiz_attempts qt
        join live.quiz_answers qa on qa.attempt_id = qt.id
        join live.questions q on q.id = qa.question_id
        join live.activities a on a.id = qt.activity_id
        left join live.lessons l on l.id = a.lesson_id
        join live.class_sessions s on s.id = qt.session_id
       where qt.student_id = v_me.id and qa.answered_at >= v_from and qa.answered_at < v_to
         and s.class_id in (select id from mine)),
    topics as (
      select class_id, topic, count(is_correct) as graded,
             round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy
        from ans group by class_id, topic having count(is_correct) >= 3)
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', c.id, 'name', c.name, 'subject', c.subject, 'teacher', c.teacher, 'period', v_b.label,
             'held', (select count(*) from live.class_sessions s where s.class_id = c.id and s.started_at >= v_from and s.started_at < v_to),
             'attended', (select count(*) from live.class_sessions s join live.session_participants p on p.session_id = s.id and p.user_id = v_me.id
                           where s.class_id = c.id and s.started_at >= v_from and s.started_at < v_to),
             'answers', (select count(*) from ans where ans.class_id = c.id),
             'accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from ans where ans.class_id = c.id),
             'strongest', (select jsonb_build_object('topic', topic, 'accuracy', accuracy) from topics t
                            where t.class_id = c.id and t.accuracy >= 70 order by accuracy desc, graded desc limit 1),
             'weakest', (select jsonb_build_object('topic', topic, 'accuracy', accuracy) from topics t
                          where t.class_id = c.id and t.accuracy < 60 order by accuracy asc, graded desc limit 1))
             order by c.name), '[]'::jsonb)
      from mine c
  );
end$$;

revoke execute on function live.add_existing_student(uuid, text), live.add_managed_student(uuid, uuid, text, text, text, text),
  live.update_student(uuid, text, text), live.prepare_password_reset(uuid), live.password_changed(),
  live.delete_student_check(uuid, text), live.promotion_targets(uuid), live.promote_students(uuid, uuid, uuid[]),
  live.promote_school(jsonb), live.my_classes() from public, anon;
grant execute on function live.add_existing_student(uuid, text), live.add_managed_student(uuid, uuid, text, text, text, text),
  live.update_student(uuid, text, text), live.prepare_password_reset(uuid), live.password_changed(),
  live.delete_student_check(uuid, text), live.promotion_targets(uuid), live.promote_students(uuid, uuid, uuid[]),
  live.promote_school(jsonb), live.my_classes() to authenticated;

-- The profile says when the student must choose their own password (first sign-in, or after a reset).
create or replace function live.me() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_user live.users;
  v_out  jsonb;
begin
  if auth.uid() is null then return null; end if;
  select * into v_user from live.users where id = auth.uid();
  if v_user.id is null then
    return jsonb_build_object('profile', null, 'super_admin', live_app.is_super_admin(),
      'email', (select email from auth.users where id = auth.uid()));
  end if;
  select jsonb_build_object(
    'profile', jsonb_build_object('id', v_user.id, 'tenant_id', v_user.tenant_id, 'email', v_user.email,
                                  'full_name', v_user.full_name, 'nickname', v_user.nickname,
                                  'role', v_user.role, 'status', v_user.status, 'is_support', v_user.is_support, 'must_change_password', v_user.must_change_password),
    'tenant', jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug, 'plan_code', t.plan_code,
                                 'timezone', t.timezone, 'status', t.status),
    'plan', jsonb_build_object('code', p.code, 'name', p.name, 'limits', p.limits, 'features', p.features),
    'settings', to_jsonb(ts) - 'tenant_id',
    'monitoring_consent', exists (select 1 from live.consents c where c.user_id = v_user.id
                                  and c.kind = 'monitoring_notice' and c.version = ts.monitoring_notice_version),
    'unread_notifications', (select count(*) from live.notifications n
                             where n.user_id = v_user.id and n.read_at is null),
    'super_admin', live_app.is_super_admin()
  ) into v_out
  from live.tenants t
  join live.plans p on p.code = t.plan_code
  join live.tenant_settings ts on ts.tenant_id = t.id
  where t.id = v_user.tenant_id;
  return v_out;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0970')
$$;

-- ===================== 20260901000980_results_privacy.sql =====================
-- 0980: results with names stay with the activity's own teacher.
--
-- Outside a live lesson, activity_results returned every answer with the
-- student's name to any teacher who could view a published lesson, so a
-- colleague could read another teacher's students' answers. Now only the
-- activity's own teacher (or whoever may edit it) and the school's admins get
-- them. Students and parents never could, and a test now proves it for every
-- route to another child's data.

create or replace function live.activity_results(p_activity uuid, p_session uuid default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_act live.activities;
begin
  select * into v_act from live.activities where id = p_activity;
  if v_act.id is null then raise exception 'Activity not found.' using errcode = 'P0002'; end if;
  if p_session is not null then
    if not live_app.can_manage_session(p_session) then
      -- Students may see anonymised aggregates when the teacher shares results.
      if not (live_app.in_session(p_session) and exists (select 1 from live.class_sessions s
              where s.id = p_session and s.responses_visible)) then
        raise exception 'Not your session.' using errcode = '42501';
      end if;
      return (select jsonb_build_object('questions', coalesce(jsonb_agg(jsonb_build_object(
                'question_id', q.id, 'prompt', q.prompt, 'kind', q.kind,
                'options', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'label', o.label,
                              -- Right answers only once the teacher has revealed them (0900).
                              'is_correct', case when exists (select 1 from live.class_sessions cs where cs.id = p_session
                                                               and cs.revealed_activity_id = p_activity) then o.is_correct end,
                              'count', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                                        where a.question_id = q.id and t.session_id = p_session and a.response ->> 'option_id' = o.id::text))
                              order by o.position), '[]'::jsonb) from live.question_options o where o.question_id = q.id))
              order by q.position), '[]'::jsonb))
              from live.questions q where q.activity_id = p_activity);
    end if;
  -- Outside a live lesson, the full results (with names and written answers) are for the
  -- activity's own teacher and the school's admins only, not for colleagues browsing it.
  elsif not live_app.can_edit_activity(p_activity) then
    raise exception 'Not visible to you.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'activity', jsonb_build_object('id', v_act.id, 'title', v_act.title, 'kind', v_act.kind),
    'attempts', (select count(*) from live.quiz_attempts t where t.activity_id = p_activity
                 and (p_session is null or t.session_id = p_session)),
    'submitted', (select count(*) from live.quiz_attempts t where t.activity_id = p_activity and t.status <> 'in_progress'
                  and (p_session is null or t.session_id = p_session)),
    'questions', (select coalesce(jsonb_agg(jsonb_build_object(
        'question_id', q.id, 'prompt', q.prompt, 'kind', q.kind, 'points', q.points,
        'responses', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                      where a.question_id = q.id and (p_session is null or t.session_id = p_session)),
        'correct', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                    where a.question_id = q.id and a.is_correct and (p_session is null or t.session_id = p_session)),
        'avg_elapsed_ms', (select round(avg(a.elapsed_ms)) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                           where a.question_id = q.id and (p_session is null or t.session_id = p_session)),
        'options', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'label', o.label, 'is_correct', o.is_correct,
                      'count', (select count(*) from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                                where a.question_id = q.id and (p_session is null or t.session_id = p_session)
                                  and (a.response ->> 'option_id' = o.id::text or a.response -> 'option_ids' ? o.id::text)))
                      order by o.position), '[]'::jsonb) from live.question_options o where o.question_id = q.id),
        'text_responses', (select coalesce(jsonb_agg(jsonb_build_object('student', u.full_name, 'response', a.response,
                             'status', a.status, 'answer_id', a.id) order by a.answered_at), '[]'::jsonb)
                           from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
                           join live.users u on u.id = t.student_id
                           where a.question_id = q.id and q.kind in ('open','short','fill_blank','draw','code','file')
                             and (p_session is null or t.session_id = p_session)))
        order by q.position, q.created_at), '[]'::jsonb)
      from live.questions q where q.activity_id = p_activity));
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0980')
$$;

-- ===================== 20260901000990_subject_teachers.sql =====================
-- 0990: class teachers and subject teachers.
--
-- * A class has one class teacher (classes.teacher_id, plus any co-teachers)
--   and subject teachers (class_subjects: Mathematics -> Mr Bello). The class
--   teacher or a school admin assigns them.
-- * A subject teacher sees the class and its students, teaches live lessons to
--   it, and sees results for their own subject only. Looking after accounts,
--   parent codes and promotion stay with the class teacher and admins.
-- * A class teacher sees every subject for their class's students; school
--   admins see every class.
-- * A result's subject: the lesson's subject, else the subject the session's
--   teacher teaches in that class, else the class's subject or name.
-- * Parents can write to each subject teacher as well as the class teacher.

create table if not exists live.class_subjects (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null,
  class_id    uuid not null,
  teacher_id  uuid not null,
  subject     text not null check (length(btrim(subject)) between 1 and 60),
  created_at  timestamptz not null default now(),
  foreign key (class_id, tenant_id) references live.classes(id, tenant_id) on delete cascade,
  foreign key (teacher_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
create unique index if not exists class_subjects_uidx on live.class_subjects(class_id, lower(subject));
create index if not exists class_subjects_teacher_idx on live.class_subjects(teacher_id);
create index if not exists class_subjects_tenant_idx on live.class_subjects(tenant_id);
alter table live.class_subjects enable row level security;
revoke all on live.class_subjects from anon;
revoke insert, update, delete on live.class_subjects from authenticated;
grant select on live.class_subjects to authenticated;
drop policy if exists class_subjects_read on live.class_subjects;drop policy if exists class_subjects_read on live.class_subjects;

create policy class_subjects_read on live.class_subjects for select to authenticated
  using (tenant_id = (select live_app.tenant_id()) and (teacher_id = (select auth.uid()) or live_app.can_manage_class(class_id) or live_app.in_class(class_id)));

create or replace function live_app.is_subject_teacher(p_class uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.class_subjects where class_id = p_class and teacher_id = auth.uid())
$$;

/** Teaches this class at all: class teacher, co-teacher, school admin, or subject teacher. */
create or replace function live_app.can_teach_class(p_class uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.can_manage_class(p_class) or live_app.is_subject_teacher(p_class)
$$;

/** The subject a result counts under (see the header). */
create or replace function live_app.row_subject(p_class uuid, p_teacher uuid, p_lesson_subject text, p_class_subject text, p_class_name text)
returns text
language sql stable security definer set search_path = '' as $$
  select coalesce(
    (select cs.subject from live.class_subjects cs
      where cs.class_id = p_class and cs.teacher_id = p_teacher and lower(cs.subject) = lower(btrim(p_lesson_subject)) limit 1),
    nullif(btrim(p_lesson_subject), ''),
    (select cs.subject from live.class_subjects cs where cs.class_id = p_class and cs.teacher_id = p_teacher order by cs.subject limit 1),
    nullif(btrim(p_class_subject), ''), p_class_name, 'Other lessons')
$$;

/** Is this subject, in this class, one the teacher teaches there? */
create or replace function live_app.subject_visible(p_class uuid, p_subject text, p_teacher uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.class_subjects cs
                  where cs.class_id = p_class and cs.teacher_id = p_teacher and lower(cs.subject) = lower(p_subject))
$$;
revoke execute on function live_app.row_subject(uuid, uuid, text, text, text), live_app.subject_visible(uuid, text, uuid) from public, anon;

-- Subject teachers see the classes they teach, and their students.
drop policy if exists classes_read on live.classes;drop policy if exists classes_read on live.classes;

create policy classes_read on live.classes for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and ((select live_app.is_admin()) or (select live_app.is_it())
              or teacher_id = (select auth.uid()) or live_app.in_class(id) or live_app.is_subject_teacher(id)));
drop policy if exists class_members_read on live.class_members;drop policy if exists class_members_read on live.class_members;

create policy class_members_read on live.class_members for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (user_id = (select auth.uid()) or live_app.can_manage_class(class_id) or live_app.is_subject_teacher(class_id) or (select live_app.is_it())
              or (role = 'teacher' and live_app.in_class(class_id))));

/** Class teacher or school admin: who teaches which subject in this class. */
create or replace function live.set_class_subject(p_class uuid, p_subject text, p_teacher uuid) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_c live.classes; v_id uuid;
begin
  select * into v_c from live.classes where id = p_class;
  if v_c.id is null or not live_app.can_manage_class(p_class) then raise exception 'Class not found.' using errcode = 'P0002'; end if;
  if not exists (select 1 from live.users where id = p_teacher and tenant_id = v_c.tenant_id and role in ('teacher', 'school_admin') and status = 'active') then
    raise exception 'Choose a teacher of your school.' using errcode = '22023';
  end if;
  insert into live.class_subjects (tenant_id, class_id, teacher_id, subject) values (v_c.tenant_id, p_class, p_teacher, btrim(p_subject))
    on conflict (class_id, lower(subject)) do update set teacher_id = excluded.teacher_id
    returning id into v_id;
  perform live_app.audit('class.subject_teacher', 'class', p_class::text, jsonb_build_object('subject', btrim(p_subject), 'teacher', p_teacher));
  return v_id;
end$$;

create or replace function live.remove_class_subject(p_id uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v live.class_subjects;
begin
  select * into v from live.class_subjects where id = p_id;
  if v.id is null or not live_app.can_manage_class(v.class_id) then raise exception 'Not found.' using errcode = 'P0002'; end if;
  delete from live.class_subjects where id = p_id;
  perform live_app.audit('class.subject_teacher_removed', 'class', v.class_id::text, jsonb_build_object('subject', v.subject));
end$$;

/** The subject teachers of a class, for the class page. */
create or replace function live.class_subject_teachers(p_class uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', cs.id, 'subject', cs.subject, 'teacher_id', cs.teacher_id, 'teacher', u.full_name)
           order by cs.subject), '[]'::jsonb)
    from live.class_subjects cs join live.users u on u.id = cs.teacher_id
   where cs.class_id = p_class and live_app.can_teach_class(p_class)
$$;

drop function if exists live.send_parent_feedback(uuid, uuid, text);

create or replace function live_app.progress_answers(p_student uuid, p_from timestamptz, p_to timestamptz, p_teacher uuid default null)
returns table (at timestamptz, session_id uuid, subject text, topic text, is_correct boolean)
language sql stable security definer set search_path = '' as $$
  select qa.answered_at, t.session_id,
         live_app.row_subject(c.id, s.teacher_id, l.subject, c.subject, c.name),
         coalesce(nullif(btrim(q.topic), ''), l.title, a.title),
         qa.is_correct
    from live.quiz_attempts t
    join live.quiz_answers qa on qa.attempt_id = t.id
    join live.questions q on q.id = qa.question_id
    join live.activities a on a.id = t.activity_id
    left join live.lessons l on l.id = a.lesson_id
    left join live.class_sessions s on s.id = t.session_id
    left join live.classes c on c.id = s.class_id
   where t.student_id = p_student and qa.answered_at >= p_from and qa.answered_at < p_to
     -- A teacher sees their own lessons, every subject of a class they are class teacher of,
     -- and their own subject in a class they teach as a subject teacher.
     and (p_teacher is null or s.teacher_id = p_teacher or live_app.can_manage_class(s.class_id)
          or live_app.subject_visible(s.class_id, live_app.row_subject(c.id, s.teacher_id, l.subject, c.subject, c.name), p_teacher)
          or (t.session_id is null and a.owner_id = p_teacher))
$$;

create or replace function live_app.progress_lessons(p_student uuid, p_from timestamptz, p_to timestamptz, p_teacher uuid default null)
returns table (session_id uuid, title text, subject text, started_at timestamptz, attended boolean, points int)
language sql stable security definer set search_path = '' as $$
  select s.id, s.title,
         live_app.row_subject(c.id, s.teacher_id, l.subject, c.subject, c.name),
         s.started_at, p.user_id is not null, coalesce(p.total_score, 0)
    from live.class_sessions s
    left join live.lessons l on l.id = s.lesson_id
    left join live.classes c on c.id = s.class_id
    left join live.session_participants p on p.session_id = s.id and p.user_id = p_student
   where s.tenant_id = (select u.tenant_id from live.users u where u.id = p_student)
     and s.started_at >= p_from and s.started_at < p_to
     and (p_teacher is null or s.teacher_id = p_teacher or live_app.can_manage_class(s.class_id)
          or live_app.subject_visible(s.class_id, live_app.row_subject(c.id, s.teacher_id, l.subject, c.subject, c.name), p_teacher))
     and (p.user_id is not null
          or exists (select 1 from live.class_members m where m.class_id = s.class_id and m.user_id = p_student and m.role = 'student'))
$$;

create or replace function live.school_progress(p_period text default 'term', p_date date default null, p_class uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_tenant uuid := live_app.tenant_id();
  v_tz text; v_today date; v_day date; v_b record; v_from timestamptz; v_to timestamptz;
  v_admin boolean := live_app.is_admin();
  v_scope uuid;   -- a subject teacher: only their own subjects in this class
begin
  -- School admins: the whole school or any class. A class teacher: their class, every subject.
  -- A subject teacher: their class, their own subjects only.
  if v_tenant is null or not (v_admin or (p_class is not null and live_app.can_teach_class(p_class))) then
    raise exception 'Only school admins can see this.' using errcode = '42501';
  end if;
  if not v_admin and not live_app.can_manage_class(p_class) then v_scope := auth.uid(); end if;
  if p_class is not null and not exists (select 1 from live.classes where id = p_class and tenant_id = v_tenant) then
    raise exception 'Class not found.' using errcode = 'P0002';
  end if;
  select coalesce(timezone, 'UTC') into v_tz from live.tenants where id = v_tenant;
  v_today := (now() at time zone v_tz)::date;
  v_day := coalesce(p_date, v_today);
  select * into v_b from live_app.period_bounds(v_tenant, p_period, v_day);
  if v_b.starts is null then
    return jsonb_build_object('period', p_period, 'date', v_day, 'needs_terms', true);
  end if;
  v_from := v_b.starts::timestamp at time zone v_tz;
  v_to := v_b.ends::timestamp at time zone v_tz;

  return (
    with pupils as (
      select u.id, u.full_name from live.users u
       where u.tenant_id = v_tenant and u.role = 'student' and u.status = 'active'
         and (p_class is null or exists (select 1 from live.class_members m where m.class_id = p_class and m.user_id = u.id and m.role = 'student'))),
    ans as (
      select t.student_id, qa.is_correct,
             live_app.row_subject(c.id, s.teacher_id, l.subject, c.subject, c.name) as subject,
             coalesce(nullif(btrim(q.topic), ''), l.title, a.title) as topic
        from live.quiz_attempts t
        join pupils pu on pu.id = t.student_id
        join live.quiz_answers qa on qa.attempt_id = t.id
        join live.questions q on q.id = qa.question_id
        join live.activities a on a.id = t.activity_id
        left join live.lessons l on l.id = a.lesson_id
        left join live.class_sessions s on s.id = t.session_id
        left join live.classes c on c.id = s.class_id
       where t.tenant_id = v_tenant and qa.answered_at >= v_from and qa.answered_at < v_to
         and (v_scope is null or s.teacher_id = v_scope
              or live_app.subject_visible(s.class_id, live_app.row_subject(c.id, s.teacher_id, l.subject, c.subject, c.name), v_scope))),
    per_topic as (
      select subject, topic, count(*) as answers, count(is_correct) as graded,
             round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy,
             count(distinct student_id) as pupils
        from ans group by subject, topic),
    per_pupil_topic as (
      select student_id, subject, topic, round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy
        from ans group by student_id, subject, topic having count(is_correct) >= 2),
    per_pupil as (
      select a.student_id, count(*) as answers, round(100.0 * count(*) filter (where a.is_correct) / nullif(count(a.is_correct), 0)) as accuracy
        from ans a group by a.student_id)
    select jsonb_build_object(
      'period', p_period, 'date', v_day, 'today', v_today, 'needs_terms', false, 'label', v_b.label, 'from', v_b.starts, 'to', v_b.ends - 1,
      'prev_date', v_b.starts - 1, 'next_date', case when v_b.ends <= v_today then v_b.ends end,
      'classes', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name), '[]'::jsonb)
                    from live.classes c where c.tenant_id = v_tenant and c.archived_at is null and (v_admin or c.id = p_class)),
      'scope', case when v_admin then 'school' when v_scope is null then 'class' else 'subject' end,
      'summary', jsonb_build_object(
        'pupils', (select count(*) from pupils), 'active', (select count(distinct student_id) from ans),
        'answers', (select count(*) from ans),
        'accuracy', (select round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) from ans)),
      'subjects', (select coalesce(jsonb_agg(jsonb_build_object(
          'subject', sb.subject, 'answers', sb.answers, 'accuracy', sb.accuracy, 'pupils', sb.pupils,
          'topics', (select coalesce(jsonb_agg(jsonb_build_object('topic', t.topic, 'answers', t.answers, 'accuracy', t.accuracy, 'pupils', t.pupils,
                       'struggling', (select count(*) from per_pupil_topic x where x.subject = t.subject and x.topic = t.topic and x.accuracy < 50))
                       order by t.accuracy asc nulls last, t.answers desc), '[]'::jsonb)
                     from per_topic t where t.subject = sb.subject))
          order by sb.answers desc), '[]'::jsonb)
        from (select subject, count(*) as answers, count(distinct student_id) as pupils,
                     round(100.0 * count(*) filter (where is_correct) / nullif(count(is_correct), 0)) as accuracy
                from ans group by subject) sb),
      'hardest', (select coalesce(jsonb_agg(jsonb_build_object('subject', t.subject, 'topic', t.topic, 'answers', t.answers,
                     'accuracy', t.accuracy, 'pupils', t.pupils,
                     'struggling', (select count(*) from per_pupil_topic x where x.subject = t.subject and x.topic = t.topic and x.accuracy < 50))
                     order by t.accuracy asc, t.answers desc), '[]'::jsonb)
                    from (select * from per_topic where graded >= 5 and accuracy < 60 order by accuracy asc, answers desc limit 10) t),
      'pupils_needing_help', (select coalesce(jsonb_agg(jsonb_build_object('student_id', pp.student_id, 'name', u.full_name,
                     'answers', pp.answers, 'accuracy', pp.accuracy,
                     'weakest', (select jsonb_build_object('subject', x.subject, 'topic', x.topic, 'accuracy', x.accuracy)
                                   from per_pupil_topic x where x.student_id = pp.student_id order by x.accuracy asc limit 1),
                     'classes', (select coalesce(jsonb_agg(c.name order by c.name), '[]'::jsonb) from live.class_members m
                                   join live.classes c on c.id = m.class_id where m.user_id = pp.student_id and m.role = 'student'))
                     order by pp.accuracy asc, pp.answers desc), '[]'::jsonb)
                    from (select * from per_pupil where answers >= 5 and accuracy < 50 order by accuracy asc limit 30) pp
                    join live.users u on u.id = pp.student_id),
      'feedback', (select jsonb_build_object('total', count(*), 'unanswered', count(*) filter (where reply is null))
                     from live.parent_feedback where tenant_id = v_tenant and created_at >= v_from and created_at < v_to
                       and (v_admin or teacher_id = auth.uid())))
  );
end$$;

create or replace function live.start_session(
  p_class uuid, p_lesson uuid default null, p_mode text default 'live_participation',
  p_title text default null, p_environment uuid default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_class live.classes;
  v_s     live.class_sessions;
  v_mon   boolean;
begin
  -- A class is optional: without one, anyone with the code joins (live engine, 0880).
  if p_class is not null and not live_app.can_teach_class(p_class) then raise exception 'Not your class.' using errcode = '42501'; end if;
  if p_class is null and not live_app.is_teacher() then raise exception 'Only teachers can start a live lesson.' using errcode = '42501'; end if;
  select * into v_class from live.classes where id = p_class;
  if p_mode not in ('live_participation','student_paced','front_of_class') then
    raise exception 'Unknown delivery mode.' using errcode = '22023';
  end if;
  if p_lesson is not null and not live_app.can_view_lesson(p_lesson) then
    raise exception 'Lesson not found.' using errcode = 'P0002';
  end if;
  if p_environment is not null and not exists (select 1 from live.environment_policies
                                               where id = p_environment and tenant_id = v_me.tenant_id) then
    raise exception 'Environment not found.' using errcode = 'P0002';
  end if;
  -- Monitoring is an add-on: without it, no lockdown and no blocked-site environment.
  v_mon := coalesce((select monitoring_enabled from live.tenant_settings where tenant_id = v_me.tenant_id), false);
  if not v_mon then p_environment := null; end if;
  if p_class is not null and exists (select 1 from live.class_sessions where class_id = p_class and status = 'live') then
    raise exception 'This class already has a live session. End it first.' using errcode = 'P0001';
  end if;

  insert into live.class_sessions (tenant_id, class_id, teacher_id, lesson_id, lesson_version, title, mode, join_code,
                                     status, environment_id, environment_active, started_at, lockdown)
    values (v_me.tenant_id, p_class, v_me.id, p_lesson,
            (select current_version from live.lessons where id = p_lesson),
            coalesce(nullif(btrim(p_title), ''), (select title from live.lessons where id = p_lesson), coalesce(v_class.name || ' live', 'Live lesson')),
            p_mode, live_app.unique_code(6, 'class_sessions'), 'live', p_environment, p_environment is not null, now(), v_mon)
    returning * into v_s;

  insert into live.session_participants (session_id, user_id, tenant_id, status)
    values (v_s.id, v_me.id, v_me.tenant_id, 'online');
  perform live_app.audit('session.started', 'class_session', v_s.id::text,
                    jsonb_build_object('class_id', p_class, 'lesson_id', p_lesson, 'environment_id', p_environment));
  perform live_app.notify(m.user_id, 'session_started', 'Live class started: ' || v_s.title, 'Join code ' || v_s.join_code,
                     '/live/student/live/' || v_s.id, 'info', jsonb_build_object('session_id', v_s.id))
  from live.class_members m where m.class_id = p_class and m.role = 'student';
  return to_jsonb(v_s);
end$$;

create or replace function live.my_teaching_classes() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'subject', c.subject,
           'students', (select count(*) from live.class_members m where m.class_id = c.id and m.role = 'student'))
         order by c.name), '[]'::jsonb)
  from live.classes c where c.archived_at is null and live_app.can_teach_class(c.id)
$$;

create or replace function live.class_access(p_class uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('manage', live_app.can_manage_class(p_class), 'member', live_app.in_class(p_class),
                            'teach', live_app.can_teach_class(p_class),
                            'subjects', (select coalesce(jsonb_agg(cs.subject order by cs.subject), '[]'::jsonb) from live.class_subjects cs
                                          where cs.class_id = p_class and cs.teacher_id = auth.uid()))
$$;

create or replace function live_app.teaches_student(p_student uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from live.class_members m
    where m.user_id = p_student and m.role = 'student' and live_app.can_teach_class(m.class_id)
  )
$$;

create or replace function live_app.can_manage_student(p_student uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from live.class_members m
                 where m.user_id = p_student and m.role = 'student' and live_app.can_manage_class(m.class_id))
      or (live_app.is_admin() and exists (select 1 from live.users u where u.id = p_student and u.role = 'student' and u.tenant_id = live_app.tenant_id()))
$$;

create or replace function live.new_parent_code(p_student uuid) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare v_i live.invites;
begin
  if not (live_app.can_manage_student(p_student)
          or (live_app.is_admin() and exists (select 1 from live.users where id = p_student and role = 'student' and tenant_id = live_app.tenant_id()))) then
    raise exception 'Student not found.' using errcode = 'P0002';
  end if;
  update live.invites set revoked_at = now() where student_id = p_student and standing and revoked_at is null;
  v_i := live_app.parent_code_for(p_student);
  perform live_app.audit('parent_code.renewed', 'user', p_student::text, '{}'::jsonb);
  return v_i.code;
end$$;

create or replace function live.feedback_targets(p_student uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  -- The class teacher of each of the child's classes, and each subject teacher there.
  select coalesce(jsonb_agg(jsonb_build_object('class_id', x.class_id, 'subject', x.subject, 'class', x.class, 'teacher_id', x.teacher_id, 'teacher', x.teacher)
                            order by x.class, x.subject), '[]'::jsonb)
    from (
      select c.id as class_id, coalesce(nullif(btrim(c.subject), ''), 'Class teacher') as subject, c.name as class, t.id as teacher_id, t.full_name as teacher
        from live.class_members m join live.classes c on c.id = m.class_id join live.users t on t.id = c.teacher_id
       where m.user_id = p_student and m.role = 'student' and c.archived_at is null
      union all
      select c.id, cs.subject, c.name, t.id, t.full_name
        from live.class_members m join live.classes c on c.id = m.class_id
        join live.class_subjects cs on cs.class_id = c.id join live.users t on t.id = cs.teacher_id
       where m.user_id = p_student and m.role = 'student' and c.archived_at is null) x
   where live_app.is_parent_of(p_student)
$$;

create or replace function live.send_parent_feedback(p_student uuid, p_class uuid, p_body text, p_teacher uuid default null) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_me live.users := live_app.me(); v_c live.classes; v_id uuid; v_child text; v_teacher uuid; v_subject text;
begin
  if v_me.role <> 'parent' or not live_app.is_parent_of(p_student) then raise exception 'Not your child.' using errcode = '42501'; end if;
  select c.* into v_c from live.classes c join live.class_members m on m.class_id = c.id
   where c.id = p_class and m.user_id = p_student and m.role = 'student';
  if v_c.id is null then raise exception 'That class isn''t one of your child''s.' using errcode = 'P0002'; end if;
  -- To the class teacher, or to one of the class's subject teachers.
  v_teacher := coalesce(p_teacher, v_c.teacher_id);
  if v_teacher = v_c.teacher_id then
    v_subject := coalesce(nullif(btrim(v_c.subject), ''), v_c.name);
  else
    select cs.subject into v_subject from live.class_subjects cs where cs.class_id = v_c.id and cs.teacher_id = v_teacher order by cs.subject limit 1;
    if v_subject is null then raise exception 'That teacher doesn''t teach this class.' using errcode = 'P0002'; end if;
  end if;
  if (select count(*) from live.parent_feedback where parent_id = v_me.id and created_at > now() - interval '1 day') >= 20 then
    raise exception 'You''ve sent a lot of feedback today. Please try again tomorrow.' using errcode = 'P0001';
  end if;
  insert into live.parent_feedback (tenant_id, student_id, parent_id, teacher_id, class_id, subject, body)
    values (v_me.tenant_id, p_student, v_me.id, v_teacher, v_c.id, v_subject, btrim(p_body))
    returning id into v_id;
  select full_name into v_child from live.users where id = p_student;
  perform live_app.notify(v_teacher, 'parent_feedback', 'Feedback from ' || v_me.full_name, 'About ' || v_child || ' in ' || v_c.name,
                     '/school/inbox', 'info', jsonb_build_object('feedback_id', v_id));
  return v_id;
end$$;

revoke execute on function live.set_class_subject(uuid, text, uuid), live.remove_class_subject(uuid), live.class_subject_teachers(uuid),
  live.send_parent_feedback(uuid, uuid, text, uuid) from public, anon;
grant execute on function live.set_class_subject(uuid, text, uuid), live.remove_class_subject(uuid), live.class_subject_teachers(uuid),
  live.send_parent_feedback(uuid, uuid, text, uuid) to authenticated;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '0990')
$$;

-- ===================== 20260901001000_guest_accounts.sql =====================
-- 1000: guests join with just the code and a name, whatever Supabase's settings.
--
-- Until now a guest had to be a Supabase anonymous sign-in, which works only
-- while "Allow anonymous sign-ins" is on, and then only about 30 an hour from
-- one internet address (a whole school). When that fails, the server now makes
-- the guest's account itself (POST /api/live/guest, with the service key): an
-- account marked app_metadata.guest = true. Only the service key can set
-- app_metadata, so nobody can mark their own account. A marked account is
-- treated exactly like an anonymous sign-in: it can only ever be a guest.

/** A guest account: an anonymous sign-in, or one the server made for a guest. */
create or replace function live_app.is_guest_account(p_user uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select a.is_anonymous or coalesce(a.raw_app_meta_data ->> 'guest', '') = 'true'
                     from auth.users a where a.id = p_user), false)
$$;
revoke execute on function live_app.is_guest_account(uuid) from public, anon, authenticated;

create or replace function live_app.is_anonymous() returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.is_guest_account(auth.uid())
$$;

create or replace function live_app.guard_guest_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_anon boolean := live_app.is_guest_account(new.id);
begin
  if v_anon and new.role <> 'guest' then
    raise exception 'Create an account to join a school.' using errcode = '42501';
  end if;
  if new.role = 'guest' and not v_anon then
    raise exception 'Only a guest sign-in can be a guest.' using errcode = '42501';
  end if;
  return new;
end$$;

-- Guests are removed 30 days after their last lesson, and guest sign-ins that
-- never joined a lesson (a wrong code, a closed lesson) after a day.
create or replace function live_app.purge_guests() returns int
language plpgsql volatile security definer set search_path = '' as $$
declare v_n int;
begin
  delete from auth.users a
   where (a.is_anonymous or coalesce(a.raw_app_meta_data ->> 'guest', '') = 'true')
     and (exists (select 1 from live.users u where u.id = a.id and u.role = 'guest')
          or (not exists (select 1 from live.users u where u.id = a.id) and a.created_at < now() - interval '1 day'))
     and not exists (select 1 from live.session_guests g join live.class_sessions s on s.id = g.session_id
                      where g.user_id = a.id and (s.status = 'live' or coalesce(s.ended_at, s.created_at) > now() - interval '30 days'));
  get diagnostics v_n = row_count;
  return v_n;
end$$;
revoke execute on function live_app.purge_guests() from public, anon, authenticated;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1000')
$$;

-- ===================== 20260901001010_slide_moves_on.sql =====================
-- 1010: moving to another slide moves the class on.
--
-- A launched activity (and "Share results", which Reveal turns on) used to stay
-- on after the teacher moved to another slide, so the projector and students'
-- screens kept showing that question or its results: the slides seemed stuck.
-- Now changing slide closes the launched activity and hides results, unless the
-- same change launches one or shares results itself. The new slide's own
-- activity, if it has one, shows as usual.

create or replace function live_app.session_timing() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.current_slide is distinct from old.current_slide or (new.phase = 'active' and old.phase = 'lobby') then
    new.slide_changed_at := now();
  end if;
  if new.current_slide is distinct from old.current_slide then
    if new.active_activity_id is not distinct from old.active_activity_id then new.active_activity_id := null; end if;
    if new.responses_visible is not distinct from old.responses_visible then new.responses_visible := false; end if;
  end if;
  if new.active_activity_id is not null and new.active_activity_id is distinct from old.active_activity_id then
    new.activity_opened_at := now();
  end if;
  return new;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1010')
$$;

-- ===================== 20260901001020_teacher_closes_lesson.sql =====================
-- 1020: when the teacher closes the lesson, it ends, even without "End session".
--
-- The teacher's pages (control room, Present, a game hosted from the lesson) say
-- "here" every 20 seconds (teacher_here), and "left" the moment the tab or
-- browser is closed. A live lesson ends for everyone:
--   * 45 seconds after the teacher closed it (a page refresh comes back sooner), or
--   * 3 minutes after the teacher's pages last said "here" (crash, no internet,
--     laptop shut).
-- It is checked on every student's tick (no scheduler needed) and every minute
-- by pg_cron where it is on, for lessons nobody is in. Its report is saved like
-- any other; the teacher sees it under Reports.

alter table live.class_sessions add column if not exists teacher_left_at timestamptz;

-- The teacher's comings and goings are not lesson state: students don't refetch for them.
create or replace function live_app.session_version_bump() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (to_jsonb(new) - 'teacher_seen_at' - 'teacher_left_at' - 'state_version' - 'updated_at')
     is distinct from (to_jsonb(old) - 'teacher_seen_at' - 'teacher_left_at' - 'state_version' - 'updated_at')
     and new.state_version = old.state_version then
    new.state_version := old.state_version + 1;
  end if;
  return new;
end$$;

/** Ends a live lesson for everyone and saves its report. Callers check who may do this. */
create or replace function live_app.finish_session(p_session uuid, p_reason text default 'teacher') returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions;
  v_report uuid;
  v_by_teacher boolean := p_reason = 'teacher';
begin
  select * into v_s from live.class_sessions where id = p_session for update;
  if v_s.id is null or v_s.status <> 'live' then return null; end if;
  update live.class_sessions set status = 'ended', phase = 'ended', ended_at = now(), environment_active = false where id = p_session;
  update live.session_participants set left_at = coalesce(left_at, now()), status = 'offline' where session_id = p_session;
  update live.browser_sessions set ended_at = now() where class_session_id = p_session and ended_at is null;
  update live.environment_events set resolved_at = now() where class_session_id = p_session and resolved_at is null;
  update live.spotlights set ended_at = now() where session_id = p_session and ended_at is null;
  update live.teacher_commands set status = 'expired' where class_session_id = p_session and status in ('queued','delivered');
  update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and status = 'open';
  update live.rtc_rooms set status = 'closed', closed_at = now() where session_id = p_session and status = 'open';
  update live.quiz_attempts set status = 'submitted', submitted_at = now() where session_id = p_session and status = 'in_progress';
  perform live_app.recompute_attempt(id) from live.quiz_attempts where session_id = p_session;

  -- The full report needs the teacher's view (session_report checks it). Ended any
  -- other way, a placeholder is saved and Reports builds it when the teacher opens it.
  insert into live.reports (tenant_id, kind, title, scope_type, scope_id, payload, created_by)
    values (v_s.tenant_id, 'session_summary', 'Session report: ' || v_s.title, 'class_session', p_session,
            case when v_by_teacher then live.session_report(p_session) else jsonb_build_object('ended_because', p_reason) end,
            case when v_by_teacher then auth.uid() else v_s.teacher_id end)
    returning id into v_report;
  if v_by_teacher then
    perform live_app.audit('session.ended', 'class_session', p_session::text, jsonb_build_object('report_id', v_report));
  else
    perform live_app.audit('session.auto_ended', 'class_session', p_session::text,
                      jsonb_build_object('report_id', v_report, 'reason', p_reason), v_s.tenant_id, null);
  end if;
  return v_report;
end$$;
revoke execute on function live_app.finish_session(uuid, text) from public, anon, authenticated;

create or replace function live.end_session(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions := live_app.require_live_session(p_session);
begin
  return jsonb_build_object('ended', true, 'report_id', live_app.finish_session(v_s.id, 'teacher'));
end$$;

/** Has the teacher closed this live lesson (see the header)? */
create or replace function live_app.teacher_gone(p_s live.class_sessions) returns boolean
language sql stable set search_path = '' as $$
  select p_s.status = 'live'
     and ((p_s.teacher_left_at is not null and p_s.teacher_left_at < now() - interval '45 seconds')
          or coalesce(p_s.teacher_seen_at, p_s.started_at, p_s.created_at) < now() - interval '3 minutes')
$$;

/** The teacher's pages: "here" every 20 seconds, "left" when the tab is closed. */
create or replace function live.teacher_here(p_session uuid, p_here boolean default true) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_s live.class_sessions;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not live_app.can_manage_session(v_s.id) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  if v_s.status = 'live' and live_app.teacher_gone(v_s) then
    perform live_app.finish_session(v_s.id, 'teacher_left');
  elsif v_s.status = 'live' and p_here then
    if v_s.teacher_left_at is not null or v_s.teacher_seen_at is null or v_s.teacher_seen_at < now() - interval '10 seconds' then
      update live.class_sessions set teacher_seen_at = now(), teacher_left_at = null where id = p_session;
    end if;
  elsif v_s.status = 'live' then
    update live.class_sessions set teacher_left_at = now() where id = p_session;
  end if;
  return jsonb_build_object('status', (select status from live.class_sessions where id = p_session));
end$$;
revoke execute on function live.teacher_here(uuid, boolean) from public, anon;
grant execute on function live.teacher_here(uuid, boolean) to authenticated;

-- Checked on every student's tick (student_report refreshes last_seen_at).
create or replace function live_app.end_if_teacher_gone() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_s live.class_sessions;
begin
  select * into v_s from live.class_sessions where id = new.session_id;
  if v_s.id is not null and live_app.teacher_gone(v_s) then perform live_app.finish_session(v_s.id, 'teacher_left'); end if;
  return null;
end$$;
drop trigger if exists session_participants_teacher_gone on live.session_participants;drop trigger if exists session_participants_teacher_gone on live.session_participants;

create trigger session_participants_teacher_gone after update of last_seen_at on live.session_participants
  for each row when (new.last_seen_at is distinct from old.last_seen_at and new.left_at is null)
  execute function live_app.end_if_teacher_gone();

/** For pg_cron (every minute) and hourly maintenance: lessons nobody is in. */
create or replace function live_app.end_teacherless_sessions() returns int
language plpgsql volatile security definer set search_path = '' as $$
declare r live.class_sessions; v_n int := 0;
begin
  for r in select * from live.class_sessions s where s.status = 'live' loop
    if live_app.teacher_gone(r) then perform live_app.finish_session(r.id, 'teacher_left'); v_n := v_n + 1; end if;
  end loop;
  return v_n;
end$$;
revoke execute on function live_app.end_teacherless_sessions() from public, anon, authenticated;

create or replace function live_app.run_maintenance() returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_ended int;
begin
  v_ended := live_app.end_abandoned_sessions() + live_app.end_teacherless_sessions();
  perform live_app.apply_retention_all();
  delete from live.invites where expires_at < now() - interval '30 days';
  delete from live.error_events where last_seen_at < now() - interval '30 days';
  perform live_app.refresh_platform_stats();
  return jsonb_build_object('ok', true, 'ran_at', now(), 'sessions_auto_ended', v_ended);
end$$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('synergy-live-teacherless', '* * * * *', 'select live_app.end_teacherless_sessions()');
  end if;
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1020')
$$;

-- ===================== 20260901001030_lobby_players.sql =====================
-- 1030: students see who else is in the lobby.
--
-- Before the teacher starts, everyone in the lesson sees the others who have
-- joined: their avatar and first name with an initial ("Ada O."), the way the
-- projector already shows them. Only while the lesson is in its lobby, only to
-- people in that lesson, at most 60, and no names when the teacher chose
-- anonymous names for the lesson.

create or replace function live.session_lobby(p_session uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_s    live.class_sessions;
  v_anon boolean;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if v_s.id is null or not (live_app.in_session(v_s.id) or live_app.can_manage_session(v_s.id)) then
    raise exception 'Session not found.' using errcode = 'P0002';
  end if;
  if v_s.status <> 'live' or v_s.phase <> 'lobby' then return '[]'::jsonb; end if;
  v_anon := coalesce((v_s.settings ->> 'anonymous_names')::boolean, false);
  return coalesce((
    select jsonb_agg(jsonb_build_object('name', case when v_anon then null else x.name end, 'avatar', x.avatar, 'me', x.me) order by x.joined_at)
      from (select live_app.display_name(coalesce(g.display_name, u.full_name)) as name, sp.avatar, sp.user_id = auth.uid() as me, sp.joined_at
              from live.session_participants sp
              join live.users u on u.id = sp.user_id
              left join live.session_guests g on g.session_id = sp.session_id and g.user_id = sp.user_id
             where sp.session_id = p_session and sp.user_id <> v_s.teacher_id and sp.left_at is null and sp.removed_at is null
               and sp.last_seen_at > now() - live_app.presence_window()
             order by sp.joined_at
             limit 60) x), '[]'::jsonb);
end$$;
revoke execute on function live.session_lobby(uuid) from public, anon;
grant execute on function live.session_lobby(uuid) to authenticated;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1030')
$$;

-- ===================== 20260901001040_teacher_away_grace.sql =====================
-- 1040: kinder timings for "the teacher closed the lesson" (1020).
--
-- An iPad or phone pauses a page completely while the teacher uses another app
-- (a video, Keynote), so the teacher's "here" stops without the lesson being
-- closed. A lesson now ends:
--   * 1 minute after the teacher closed the tab (a slow refresh still comes back), or
--   * 10 minutes after the teacher's pages last said "here" (crash, no internet,
--     laptop shut, or another app for that long).

create or replace function live_app.teacher_gone(p_s live.class_sessions) returns boolean
language sql stable set search_path = '' as $$
  select p_s.status = 'live'
     and ((p_s.teacher_left_at is not null and p_s.teacher_left_at < now() - interval '1 minute')
          or coalesce(p_s.teacher_seen_at, p_s.started_at, p_s.created_at) < now() - interval '10 minutes')
$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1040')
$$;

-- ===================== 20260901001050_student_paced_stays.sql =====================
-- 1050: student-paced lessons stay open when the teacher leaves.
--
-- In a teacher-paced lesson the teacher's screen leads, so the lesson ends when
-- the teacher closes it (1020, 1040). In a student-paced lesson students work
-- through the slides on their own, often while the teacher is elsewhere, so the
-- teacher leaving doesn't end it; the teacher ends it, or hourly maintenance does
-- after 12 hours (end_abandoned_sessions).

create or replace function live_app.teacher_gone(p_s live.class_sessions) returns boolean
language sql stable set search_path = '' as $$
  select p_s.status = 'live' and p_s.mode <> 'student_paced'
     and ((p_s.teacher_left_at is not null and p_s.teacher_left_at < now() - interval '1 minute')
          or coalesce(p_s.teacher_seen_at, p_s.started_at, p_s.created_at) < now() - interval '10 minutes')
$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1050')
$$;

-- ===================== 20260901001060_lesson_library.sql =====================
-- 1060: the SwiftCipher lesson library, shared by every school.
--
-- Ready-made lessons (slides and quizzes) any teacher can copy into their own
-- school and change. A library lesson belongs to no school: it is a snapshot
-- (payload) that library_copy turns into an ordinary lesson in the teacher's
-- school. The super admin publishes lessons into it (library_publish) and can hide
-- them; a starter set on the Nigerian curriculum is included below.

create table if not exists live.library_lessons (
  id          uuid primary key default gen_random_uuid(),
  title       text not null check (length(btrim(title)) between 1 and 200),
  subject     text not null check (length(btrim(subject)) between 1 and 60),
  level       text not null check (length(btrim(level)) between 1 and 60),
  description text,
  payload     jsonb not null check (jsonb_typeof(payload -> 'slides') = 'array'),
  published   boolean not null default true,
  uses        int not null default 0,
  source_lesson uuid,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists library_lessons_browse_idx on live.library_lessons(subject, level) where published;
alter table live.library_lessons enable row level security;
revoke all on live.library_lessons from anon, authenticated;
-- Read through library_list / library_copy only.

/** A lesson as a library payload: its slides in order, each activity with its questions and options. */
create or replace function live_app.library_payload(p_lesson uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'default_mode', l.default_mode,
    'slides', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kind', s.kind, 'content', s.content, 'notes', s.notes,
               'activity', case when a.id is null then null else jsonb_build_object(
                 'kind', a.kind, 'title', a.title, 'instructions', a.instructions, 'settings', a.settings,
                 'questions', coalesce((
                   select jsonb_agg(jsonb_build_object(
                            'kind', q.kind, 'prompt', q.prompt, 'media', q.media, 'config', q.config, 'answer_key', q.answer_key,
                            'explanation', q.explanation, 'points', q.points, 'tags', q.tags, 'difficulty', q.difficulty, 'topic', q.topic,
                            'options', coalesce((select jsonb_agg(jsonb_build_object('label', o.label, 'is_correct', o.is_correct, 'feedback', o.feedback) order by o.position)
                                                   from live.question_options o where o.question_id = q.id), '[]'::jsonb))
                          order by q.position)
                   from live.questions q where q.activity_id = a.id), '[]'::jsonb)) end)
             order by s.position)
      from live.lesson_slides s left join live.activities a on a.id = s.activity_id
      where s.lesson_id = l.id), '[]'::jsonb))
  from live.lessons l where l.id = p_lesson
$$;
revoke execute on function live_app.library_payload(uuid) from public, anon, authenticated;

/** Browse the library (staff): optional subject, level and words to search for. */
create or replace function live.library_list(p_subject text default null, p_level text default null, p_query text default null)
returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.id, 'title', b.title, 'subject', b.subject, 'level', b.level, 'description', b.description,
           'slides', jsonb_array_length(b.payload -> 'slides'),
           'questions', (select coalesce(sum(jsonb_array_length(coalesce(s -> 'activity' -> 'questions', '[]'::jsonb))), 0)
                           from jsonb_array_elements(b.payload -> 'slides') s),
           'uses', b.uses, 'published', b.published)
         order by b.subject, b.level, b.title), '[]'::jsonb)
    from live.library_lessons b
   where (live_app.is_teacher() or live_app.is_super_admin())
     and (b.published or live_app.is_super_admin())
     and (p_subject is null or b.subject = p_subject)
     and (p_level is null or b.level = p_level)
     and (p_query is null or btrim(p_query) = '' or b.title ilike '%' || btrim(p_query) || '%' or b.description ilike '%' || btrim(p_query) || '%')
$$;

/** Copy a library lesson into the teacher's school as their own draft. Returns the new lesson. */
create or replace function live.library_copy(p_item uuid, p_title text default null) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me   live.users := live_app.me();
  v_item live.library_lessons;
  v_new  uuid;
  v_act  uuid;
  v_q    uuid;
  v_pos  int := 0;
  v_qpos int;
  v_opos int;
  s      jsonb;
  q      jsonb;
  o      jsonb;
begin
  if v_me.id is null or not live_app.is_teacher() then raise exception 'Only teachers can use library lessons.' using errcode = '42501'; end if;
  select * into v_item from live.library_lessons where id = p_item and (published or live_app.is_super_admin());
  if v_item.id is null then raise exception 'That library lesson is not available.' using errcode = 'P0002'; end if;

  insert into live.lessons (tenant_id, owner_id, title, description, subject, grade_level, default_mode)
    values (v_me.tenant_id, v_me.id, coalesce(nullif(btrim(p_title), ''), v_item.title), v_item.description, v_item.subject, v_item.level,
            coalesce(v_item.payload ->> 'default_mode', 'live_participation'))
    returning id into v_new;

  for s in select value from jsonb_array_elements(v_item.payload -> 'slides') loop
    v_act := null;
    if jsonb_typeof(s -> 'activity') = 'object' then
      insert into live.activities (tenant_id, lesson_id, owner_id, kind, title, instructions, settings)
        values (v_me.tenant_id, v_new, v_me.id, coalesce(s -> 'activity' ->> 'kind', 'quiz'), coalesce(s -> 'activity' ->> 'title', 'Activity'),
                s -> 'activity' ->> 'instructions', coalesce(s -> 'activity' -> 'settings', '{}'::jsonb))
        returning id into v_act;
      v_qpos := 0;
      for q in select value from jsonb_array_elements(coalesce(s -> 'activity' -> 'questions', '[]'::jsonb)) loop
        insert into live.questions (tenant_id, activity_id, owner_id, kind, prompt, media, config, answer_key, explanation, points, position, tags, difficulty, topic)
          values (v_me.tenant_id, v_act, v_me.id, q ->> 'kind', q ->> 'prompt', coalesce(q -> 'media', '{}'::jsonb), coalesce(q -> 'config', '{}'::jsonb),
                  coalesce(q -> 'answer_key', '{}'::jsonb), q ->> 'explanation', coalesce((q ->> 'points')::numeric, 1), v_qpos,
                  coalesce((select array_agg(t) from jsonb_array_elements_text(coalesce(q -> 'tags', '[]'::jsonb)) t), '{}'::text[]),
                  (q ->> 'difficulty')::smallint, q ->> 'topic')
          returning id into v_q;
        v_opos := 0;
        for o in select value from jsonb_array_elements(coalesce(q -> 'options', '[]'::jsonb)) loop
          insert into live.question_options (tenant_id, question_id, label, is_correct, feedback, position)
            values (v_me.tenant_id, v_q, o ->> 'label', coalesce((o ->> 'is_correct')::boolean, false), o ->> 'feedback', v_opos);
          v_opos := v_opos + 1;
        end loop;
        v_qpos := v_qpos + 1;
      end loop;
    end if;
    insert into live.lesson_slides (tenant_id, lesson_id, position, kind, content, notes, activity_id)
      values (v_me.tenant_id, v_new, v_pos, coalesce(s ->> 'kind', 'text'), coalesce(s -> 'content', '{}'::jsonb), s ->> 'notes', v_act);
    v_pos := v_pos + 1;
  end loop;

  update live.library_lessons set uses = uses + 1 where id = p_item;
  perform live_app.audit('lesson.from_library', 'lesson', v_new::text, jsonb_build_object('library_lesson', p_item));
  return v_new;
end$$;

/** Super admin: put one of their lessons into the library (or refresh it), shown to every school. */
create or replace function live.library_publish(p_lesson uuid, p_subject text, p_level text, p_description text default null) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_l live.lessons; v_id uuid;
begin
  if not live_app.is_super_admin() then raise exception 'Only the platform owner can publish to the library.' using errcode = '42501'; end if;
  select * into v_l from live.lessons where id = p_lesson;
  if v_l.id is null then raise exception 'Lesson not found.' using errcode = 'P0002'; end if;
  select id into v_id from live.library_lessons where source_lesson = p_lesson;
  if v_id is null then
    insert into live.library_lessons (title, subject, level, description, payload, source_lesson)
      values (v_l.title, btrim(p_subject), btrim(p_level), coalesce(nullif(btrim(p_description), ''), v_l.description), live_app.library_payload(p_lesson), p_lesson)
      returning id into v_id;
  else
    update live.library_lessons set title = v_l.title, subject = btrim(p_subject), level = btrim(p_level),
           description = coalesce(nullif(btrim(p_description), ''), v_l.description), payload = live_app.library_payload(p_lesson), updated_at = now()
     where id = v_id;
  end if;
  perform live_app.audit('library.published', 'library_lesson', v_id::text, jsonb_build_object('lesson', p_lesson));
  return v_id;
end$$;

/** Super admin: show or hide a library lesson. */
create or replace function live.library_set_published(p_item uuid, p_published boolean) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not live_app.is_super_admin() then raise exception 'Only the platform owner can change the library.' using errcode = '42501'; end if;
  update live.library_lessons set published = p_published, updated_at = now() where id = p_item;
  if not found then raise exception 'Library lesson not found.' using errcode = 'P0002'; end if;
end$$;

revoke execute on function live.library_list(text, text, text), live.library_copy(uuid, text),
  live.library_publish(uuid, text, text, text), live.library_set_published(uuid, boolean) from public, anon;
grant execute on function live.library_list(text, text, text), live.library_copy(uuid, text),
  live.library_publish(uuid, text, text, text), live.library_set_published(uuid, boolean) to authenticated;

