-- ===================== 20260901001140_screens_on_by_default.sql =====================
-- Students' screens are on by default: everyone who joins gets the "Start learning"
-- step (one tap, then the browser's own Share box), whether or not Lockdown is on.
-- Guests are included by default too; the teacher can still turn guests off in the
-- control room, and where the school requires parental consent guests are never captured.
alter table live.class_sessions alter column guest_monitoring set default true;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1140')
$$;

-- ===================== 20260901001150_digit_codes.sql =====================
-- Codes students type are 6 digits, shown without a dash: a lesson's join code, a
-- class code and a Challenge code. (Teacher invites, lesson share links and device
-- pairing codes keep letters too.) Codes already handed out keep working; a teacher
-- can give a class a new digit code with "New code".
-- Same as 0600, with the digit branch.
create or replace function live_app.unique_code(p_len int, p_table text) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare v text; v_taken boolean; v_bytes bytea;
begin
  for i in 1 .. 30 loop
    if p_table in ('classes', 'class_sessions', 'game_sessions') then
      -- Digits only, never starting with 0 (so it can't lose a digit in a spreadsheet).
      v_bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
      v := ((get_byte(v_bytes, 0) % 9) + 1)::text;
      for j in 1 .. 5 loop v := v || (get_byte(v_bytes, j) % 10)::text; end loop;
    else
      v := live_app.gen_code(p_len);
    end if;
    execute format('select exists (select 1 from live.%I where %I = $1)', p_table,
                   case when p_table = 'device_pairing_codes' then 'code'
                        when p_table in ('invites','lesson_shares') then 'code'
                        else 'join_code' end)
      into v_taken using v;
    if not v_taken then return v; end if;
  end loop;
  raise exception 'Could not allocate a unique code; try again.' using errcode = 'P0001';
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1150')
$$;

-- ===================== 20260901001160_full_leaderboard.sql =====================
-- The leaderboard shows the whole class: the snapshot keeps every player (up to 500,
-- was the top 10), and students see all of it (was the top 5 and their own place).
-- Same as 0890 and 0940 otherwise.
create or replace function live_app.snapshot_leaderboard(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_board jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('name', r.name, 'avatar', r.avatar, 'score', r.score, 'rank', r.rank,
                                               'delta', coalesce(r.last_rank, r.rank) - r.rank) order by r.rank, r.name), '[]'::jsonb)
    into v_board
    from (select * from live_app.session_ranks(p_session) order by rank, name limit 500) r;
  update live.session_participants p set last_rank = r.rank
    from live_app.session_ranks(p_session) r where p.session_id = p_session and p.user_id = r.user_id;
  update live.class_sessions set show_leaderboard = true, leaderboard = jsonb_build_object('at', now(), 'top', v_board)
   where id = p_session;
  return v_board;
end$$;
revoke execute on function live_app.snapshot_leaderboard(uuid) from public, anon, authenticated;

create or replace function live.session_student_state(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me    live.users := live_app.me();
  v_s     live.class_sessions;
  v_p     live.session_participants;
  v_spot  live.spotlights;
  v_act   live.activities;
  v_pass  live.session_guests;
begin
  select * into v_s from live.class_sessions where id = p_session;
  if exists (select 1 from live.session_participants where session_id = p_session and user_id = v_me.id and removed_at is not null) then
    raise exception 'Your teacher removed you from this lesson.' using errcode = '42501';
  end if;
  if v_s.id is null or not (live_app.in_class(v_s.class_id) or live_app.is_session_guest(v_s.id)) then raise exception 'Session not found.' using errcode = 'P0002'; end if;
  select * into v_p from live.session_participants where session_id = p_session and user_id = v_me.id;
  if v_p.removed_at is not null then raise exception 'Your teacher removed you from this lesson.' using errcode = '42501'; end if;
  select * into v_pass from live.session_guests where session_id = p_session and user_id = v_me.id;
  if v_s.status = 'live' then
    insert into live.session_participants (session_id, user_id, tenant_id, status, current_slide)
      values (v_s.id, v_me.id, v_me.tenant_id, 'online', v_s.current_slide)
      on conflict (session_id, user_id) do update set last_seen_at = now(), left_at = null,
        status = case when live.session_participants.status = 'offline' then 'online' else live.session_participants.status end
      returning * into v_p;
  end if;
  select * into v_spot from live.spotlights where session_id = p_session and ended_at is null;
  select * into v_act from live.activities where id = v_s.active_activity_id;

  return jsonb_build_object(
    'session', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'phase', v_s.phase, 'mode', v_s.mode,
                                  'join_code', v_s.join_code, 'settings', v_s.settings,
                                  'current_slide', v_s.current_slide, 'group_chat_enabled', v_s.group_chat_enabled and v_me.role <> 'guest',
                                  'responses_visible', v_s.responses_visible, 'class_id', v_s.class_id,
                                  'teacher', (select full_name from live.users where id = v_s.teacher_id),
                                  'environment_active', v_s.environment_active),
    'my_slide', coalesce(v_p.current_slide, v_s.current_slide),
    'active_activity', case when v_act.id is null then null else jsonb_build_object(
                         'id', v_act.id, 'kind', v_act.kind, 'title', v_act.title) end,
    'spotlight', case when v_spot.id is null then null else jsonb_build_object(
                   'me', v_spot.student_id = v_me.id, 'show_to_class', v_spot.show_to_class, 'anonymized', v_spot.anonymized) end,
    'hand', (select jsonb_build_object('id', h.id, 'created_at', h.created_at) from live.raise_hands h
             where h.session_id = p_session and h.student_id = v_me.id and h.status = 'open'),
    'environment_notice', case when exists (select 1 from live.environment_events e where e.class_session_id = p_session
                                            and e.student_id = v_me.id and e.resolved_at is null
                                            and e.kind in ('environment_left','domain_blocked'))
                               then 'Your class session requires you to return to the lesson.' end,
    'device_monitored', exists (select 1 from live.browser_sessions b where b.class_session_id = p_session
                                and b.student_id = v_me.id and b.last_heartbeat_at > now() - interval '45 seconds'),
    'announcements', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at)
                       order by a.created_at desc), '[]'::jsonb)
                      from (select * from live.announcements where session_id = p_session order by created_at desc limit 5) a),
    'guest', v_me.role = 'guest',
    'revealed_activity_id', v_s.revealed_activity_id,
    -- Own score and rank only; the class sees the top 5 when the teacher shows the board.
    'my', (select jsonb_build_object('score', r.score, 'rank', r.rank, 'streak', r.streak,
                                     'of', (select count(*) from live_app.session_ranks(p_session)))
             from live_app.session_ranks(p_session) r where r.user_id = v_me.id),
    'leaderboard', case when v_s.show_leaderboard and coalesce((v_s.settings ->> 'leaderboard')::boolean, true) then
      (select coalesce(jsonb_agg(e order by (e ->> 'rank')::int), '[]'::jsonb) from jsonb_array_elements(v_s.leaderboard -> 'top') e) end,
    'me', jsonb_build_object('name', coalesce(v_pass.display_name, v_me.full_name), 'avatar', v_p.avatar),
    'participants', (select count(*) from live.session_participants sp
                      where sp.session_id = p_session and sp.user_id <> v_s.teacher_id and sp.left_at is null and sp.removed_at is null
                        and sp.last_seen_at > now() - live_app.presence_window()),
    'summary', case when v_s.status = 'ended' then (
       select jsonb_build_object('answered', count(*), 'correct', count(*) filter (where a.is_correct))
         from live.quiz_answers a join live.quiz_attempts t on t.id = a.attempt_id
        where t.session_id = p_session and t.student_id = v_me.id) end,
    'server_now', now(),
    'timer', live_app.live_timer(v_s));
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1160')
$$;

-- ===================== 20260901001170_control_reply.sql =====================
-- The reply to every lesson button (Next, Reveal, Leaderboard, Pause…) carries the new
-- state the teacher's screens show, including the leaderboard, so Present and the control
-- room change at once even when the full lesson state is slow to load.
-- Same as 0940 otherwise.
create or replace function live.session_control(p_session uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s      live.class_sessions := live_app.require_live_session(p_session);
  v_n      int;
  v_target int;
  v_user   uuid;
  v_bad    text;
  v_act    uuid;
  v_att    uuid;
begin
  p_args := coalesce(p_args, '{}'::jsonb);
  case p_action
    when 'start' then
      if v_s.phase <> 'lobby' then raise exception 'The lesson has already started.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'active', started_at = now() where id = p_session;
    when 'pause' then
      if v_s.phase <> 'active' then raise exception 'Only a running lesson can be paused.' using errcode = 'P0001'; end if;
      update live.class_sessions set phase = 'paused', paused_at = now() where id = p_session;
    when 'resume' then
      if v_s.phase <> 'paused' then raise exception 'The lesson isn''t paused.' using errcode = 'P0001'; end if;
      -- The question clock (and the speed bonus) stand still while paused.
      update live.class_sessions set phase = 'active', paused_at = null,
             slide_changed_at = slide_changed_at + (now() - coalesce(paused_at, now())),
             activity_opened_at = activity_opened_at + (now() - coalesce(paused_at, now()))
       where id = p_session;
    when 'next', 'prev', 'goto' then
      if v_s.phase <> 'active' then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      select count(*) into v_n from live.lesson_slides where lesson_id = v_s.lesson_id;
      v_target := case p_action when 'next' then v_s.current_slide + 1 when 'prev' then v_s.current_slide - 1
                                else (p_args ->> 'slide')::int end;
      if v_target is null then raise exception 'Which slide?' using errcode = '22023'; end if;
      perform live.set_session_state(p_session, greatest(0, least(v_target, greatest(v_n - 1, 0))));
    when 'kick' then
      v_user := nullif(p_args ->> 'user_id', '')::uuid;
      if v_user is null or v_user = v_s.teacher_id then raise exception 'Who should be removed?' using errcode = '22023'; end if;
      update live.session_participants set removed_at = now(), left_at = now(), status = 'offline'
       where session_id = p_session and user_id = v_user and removed_at is null;
      if not found then raise exception 'That person isn''t in this lesson.' using errcode = 'P0002'; end if;
      update live.session_guests set removed_at = now() where session_id = p_session and user_id = v_user and removed_at is null;
      update live.raise_hands set status = 'resolved', resolved_at = now() where session_id = p_session and student_id = v_user and status = 'open';
      perform live_app.audit('session.participant_removed', 'user', v_user::text, jsonb_build_object('session_id', p_session));
    when 'settings' then
      select k into v_bad from jsonb_object_keys(p_args) k
       where k <> all (array['leaderboard', 'anonymous_names', 'late_join', 'speed_bonus', 'timer', 'auto_reveal'])
          or jsonb_typeof(p_args -> k) <> 'boolean' limit 1;
      if v_bad is not null then raise exception 'Unknown or invalid setting: %.', v_bad using errcode = '22023'; end if;
      update live.class_sessions set settings = settings || p_args where id = p_session;
    when 'leaderboard' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      if coalesce((p_args ->> 'show')::boolean, true) then perform live_app.snapshot_leaderboard(p_session);
      else update live.class_sessions set show_leaderboard = false where id = p_session; end if;
    when 'reveal' then
      if v_s.phase not in ('active', 'paused') then raise exception 'Start the lesson first.' using errcode = 'P0001'; end if;
      v_act := coalesce(nullif(p_args ->> 'activity_id', '')::uuid, v_s.active_activity_id,
                        (select sl.activity_id from live.lesson_slides sl where sl.lesson_id = v_s.lesson_id and sl.position = v_s.current_slide));
      if v_act is null then raise exception 'There is no activity on this slide to reveal.' using errcode = 'P0001'; end if;
      -- Answers close: unfinished attempts are submitted as they stand, then everyone sees the result.
      for v_att in select id from live.quiz_attempts where session_id = p_session and activity_id = v_act and status = 'in_progress' loop
        update live.quiz_attempts set status = 'submitted', submitted_at = now() where id = v_att;
        perform live_app.recompute_attempt(v_att);
      end loop;
      update live.class_sessions set revealed_activity_id = v_act, responses_visible = true where id = p_session;
    when 'end' then
      return live.end_session(p_session);
    else
      raise exception 'Unknown action: %.', p_action using errcode = '22023';
  end case;
  select * into v_s from live.class_sessions where id = p_session;
  -- Everything the teacher's screens show after a button, so they needn't wait for a refresh (1170).
  return jsonb_build_object('phase', v_s.phase, 'slide', v_s.current_slide, 'settings', v_s.settings, 'v', v_s.state_version,
    'status', v_s.status, 'activity', v_s.active_activity_id, 'responses_visible', v_s.responses_visible,
    'revealed', v_s.revealed_activity_id, 'show_leaderboard', v_s.show_leaderboard,
    'leaderboard', case when v_s.show_leaderboard then v_s.leaderboard end);
end$$;

create or replace function live.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok', true, 'db_time', now(), 'schema', '1170')
$$;

-- ===== 20260101006110_live_sync.sql =====
-- =========================================================================
-- Phase 14d-2: keeps the live-lesson engine's schools, people and classes in
-- step with Synergy Swift (the "handshake": no separate accounts or rosters).
--   tenants            → live.tenants, one live.schools row, live.tenant_settings
--   users              → live.users (students, teachers, school admins/principals, IT admins)
--   students           → live.student_profiles + class membership
--   class_groups       → live.classes (teacher = form teacher, else a subject teacher)
--   subject_offerings  → live.class_subjects (subject teachers)
--   class_staff        → live.class_members role 'teacher' (co-teachers with live lessons)
-- Deactivated people are suspended, never deleted, so their lessons stay.
-- Apply AFTER 20260101006100. Idempotent.
-- =========================================================================

-- Which live role a Synergy Swift account gets (null = no live account).
create or replace function live_app.sync_role(p_role text, p_extra text[]) returns text
language sql immutable set search_path = '' as $$
  select case
    when p_role in ('school_admin', 'principal') then 'school_admin'
    when p_role = 'it_admin' then 'it_admin'
    when p_role = 'student' then 'student'
    when p_role = 'teacher' or 'teacher' = any(coalesce(p_extra, '{}')) or 'principal' = any(coalesce(p_extra, '{}')) then 'teacher'
    else null end;
$$;

create or replace function live_app.sync_tenant(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare t record;
begin
  select id, name, slug, country, timezone, status, modules into t from public.tenants where id = p_id;
  if not found then return; end if;
  -- The engine refuses everything for a suspended school, so a closed school or one without
  -- the Live module (tenants.modules.live = false) is blocked in the database, not just in menus.
  insert into live.tenants (id, name, slug, plan_code, country, timezone, status)
  values (t.id, left(t.name, 200), t.slug, 'school', t.country, coalesce(t.timezone, 'UTC'),
          case when t.status = 'active' and coalesce(t.modules->>'live', 'true') <> 'false' then 'active' else 'suspended' end)
  on conflict (id) do update set name = excluded.name, slug = excluded.slug, country = excluded.country, timezone = excluded.timezone, status = excluded.status;
  insert into live.schools (id, tenant_id, name) values (t.id, t.id, left(t.name, 200))
  on conflict (id) do update set name = excluded.name;
  insert into live.tenant_settings (tenant_id) values (t.id) on conflict (tenant_id) do nothing;
end $$;

create or replace function live_app.sync_user(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare u record; v_role text; v_grade text; v_no text;
begin
  select id, tenant_id, email, full_name, role, extra_roles, active, username into u from public.users where id = p_id;
  if not found then return; end if;
  v_role := live_app.sync_role(u.role, u.extra_roles);
  if v_role is null then
    -- No live role (any more): keep their work, stop their access.
    update live.users set status = 'suspended' where id = p_id;
    return;
  end if;
  perform live_app.sync_tenant(u.tenant_id);
  insert into live.users (id, tenant_id, school_id, email, full_name, role, status, login_name)
  values (u.id, u.tenant_id, u.tenant_id, u.email, left(coalesce(nullif(btrim(u.full_name), ''), u.email), 200), v_role,
          case when u.active then 'active' else 'suspended' end,
          case when u.username ~ '^[a-z0-9][a-z0-9.]{2,40}$' then u.username end)
  on conflict (id) do update set email = excluded.email, full_name = excluded.full_name, role = excluded.role, status = excluded.status, login_name = excluded.login_name;
  if v_role = 'student' then
    select g.level, s.admission_no into v_grade, v_no from public.students s left join public.class_groups g on g.id = s.class_group_id where s.user_id = p_id limit 1;
    insert into live.student_profiles (user_id, tenant_id, grade_level, student_number) values (u.id, u.tenant_id, v_grade, v_no)
    on conflict (user_id) do update set grade_level = excluded.grade_level, student_number = excluded.student_number;
  end if;
end $$;

-- A fresh class code in the engine's format (A–Z, 0–9, 8 characters).
create or replace function live_app.sync_class_code() returns text
language sql volatile set search_path = '' as $$
  select upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));
$$;

create or replace function live_app.sync_class(p_class uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare g record; v_teacher uuid; v_code text;
begin
  select id, tenant_id, name, level, form_teacher_id into g from public.class_groups where id = p_class;
  if not found then delete from live.classes where id = p_class; return; end if;
  perform live_app.sync_tenant(g.tenant_id);
  -- The class teacher: the form teacher if they have a live account, else the first subject teacher who does.
  select lu.id into v_teacher from live.users lu where lu.id = g.form_teacher_id and lu.role in ('teacher','school_admin') and lu.status = 'active';
  if v_teacher is null then
    select lu.id into v_teacher from public.subject_offerings o join live.users lu on lu.id = o.teacher_id and lu.role in ('teacher','school_admin') and lu.status = 'active'
    where o.class_group_id = p_class order by o.id limit 1;
  end if;
  if v_teacher is null then
    -- Nobody can run it yet; an existing live class keeps its last teacher.
    if exists (select 1 from live.classes where id = p_class) then
      update live.classes set name = left(g.name, 200), grade_level = g.level where id = p_class;
    else
      return;
    end if;
  else
    loop
      v_code := live_app.sync_class_code();
      begin
        insert into live.classes (id, tenant_id, school_id, teacher_id, name, grade_level, join_code)
        values (g.id, g.tenant_id, g.tenant_id, v_teacher, left(g.name, 200), g.level, v_code)
        on conflict (id) do update set teacher_id = excluded.teacher_id, name = excluded.name, grade_level = excluded.grade_level;
        exit;
      exception when unique_violation then
        -- Only the join code can clash (the id conflict is handled above): try another.
        null;
      end;
    end loop;
  end if;
  -- Subject teachers.
  delete from live.class_subjects cs where cs.class_id = p_class
    and not exists (select 1 from public.subject_offerings o where o.id = cs.id and o.teacher_id = cs.teacher_id);
  insert into live.class_subjects (id, tenant_id, class_id, teacher_id, subject)
  select o.id, g.tenant_id, p_class, o.teacher_id, left(s.name, 60)
  from public.subject_offerings o join public.subjects s on s.id = o.subject_id
  join live.users lu on lu.id = o.teacher_id and lu.role in ('teacher','school_admin')
  where o.class_group_id = p_class
    and not exists (select 1 from live.class_subjects x where x.class_id = p_class and lower(x.subject) = lower(left(s.name, 60)) and x.id <> o.id)
  on conflict (id) do update set teacher_id = excluded.teacher_id, subject = excluded.subject;
  -- Students in the class, and co-teachers who may run live lessons.
  delete from live.class_members m where m.class_id = p_class
    and not exists (select 1 from public.students s where s.user_id = m.user_id and s.class_group_id = p_class and s.status = 'active' and m.role = 'student')
    and not exists (select 1 from public.class_staff cs where cs.user_id = m.user_id and cs.class_group_id = p_class and cs.can_teach_live and m.role = 'teacher');
  insert into live.class_members (class_id, user_id, tenant_id, role)
  select p_class, s.user_id, g.tenant_id, 'student' from public.students s join live.users lu on lu.id = s.user_id and lu.role = 'student'
  where s.class_group_id = p_class and s.status = 'active'
  on conflict (class_id, user_id) do update set role = excluded.role;
  insert into live.class_members (class_id, user_id, tenant_id, role)
  select p_class, cs.user_id, g.tenant_id, 'teacher' from public.class_staff cs join live.users lu on lu.id = cs.user_id and lu.role in ('teacher','school_admin')
  where cs.class_group_id = p_class and cs.can_teach_live and cs.user_id <> v_teacher
  on conflict (class_id, user_id) do update set role = excluded.role;
end $$;

-- ---------- triggers on Synergy Swift's tables ----------
create or replace function live_app.on_tenant() returns trigger language plpgsql security definer set search_path = '' as $$
begin perform live_app.sync_tenant(new.id); return new; end $$;

-- Deleting a school removes everything it had in the live engine (lessons, sessions, results) in one go.
-- BEFORE DELETE must return OLD, or the school's own delete is silently skipped.
create or replace function live_app.on_tenant_delete() returns trigger language plpgsql security definer set search_path = '' as $$
begin delete from live.tenants where id = old.id; return old; end $$;

create or replace function live_app.on_user() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    -- A teacher who still owns lessons cannot simply vanish: suspend them instead (deleting the school removes everything).
    begin delete from live.users where id = old.id;
    exception when foreign_key_violation then update live.users set status = 'suspended' where id = old.id;
    end;
    return old;
  end if;
  perform live_app.sync_user(new.id);
  -- A teacher's role change can make them a class's teacher, or stop it.
  if tg_op = 'UPDATE' and (new.role is distinct from old.role or new.extra_roles is distinct from old.extra_roles or new.active is distinct from old.active) then
    perform live_app.sync_class(g.id) from public.class_groups g where g.form_teacher_id = new.id;
    perform live_app.sync_class(o.class_group_id) from public.subject_offerings o where o.teacher_id = new.id;
  end if;
  return new;
end $$;

create or replace function live_app.on_student() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op in ('UPDATE', 'DELETE') and old.class_group_id is not null then perform live_app.sync_class(old.class_group_id); end if;
  if tg_op in ('INSERT', 'UPDATE') then
    if new.user_id is not null then perform live_app.sync_user(new.user_id); end if;
    if new.class_group_id is not null then perform live_app.sync_class(new.class_group_id); end if;
  end if;
  return coalesce(new, old);
end $$;

create or replace function live_app.on_class_group() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then delete from live.classes where id = old.id; return old; end if;
  perform live_app.sync_class(new.id);
  return new;
end $$;

create or replace function live_app.on_class_child() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then perform live_app.sync_class(old.class_group_id); end if;
  if tg_op in ('INSERT', 'UPDATE') and (tg_op = 'INSERT' or new.class_group_id is distinct from old.class_group_id or true) then perform live_app.sync_class(new.class_group_id); end if;
  return coalesce(new, old);
end $$;

revoke all on function live_app.sync_role(text, text[]), live_app.sync_tenant(uuid), live_app.sync_user(uuid), live_app.sync_class(uuid), live_app.sync_class_code(),
  live_app.on_tenant(), live_app.on_tenant_delete(), live_app.on_user(), live_app.on_student(), live_app.on_class_group(), live_app.on_class_child() from public, anon, authenticated;

drop trigger if exists live_sync on public.tenants;
create trigger live_sync after insert or update of name, slug, country, timezone, status, modules on public.tenants for each row execute function live_app.on_tenant();
drop trigger if exists live_sync_delete on public.tenants;
create trigger live_sync_delete before delete on public.tenants for each row execute function live_app.on_tenant_delete();
drop trigger if exists live_sync on public.users;
create trigger live_sync after insert or update of email, full_name, role, extra_roles, active, username or delete on public.users for each row execute function live_app.on_user();
drop trigger if exists live_sync on public.students;
create trigger live_sync after insert or update of class_group_id, user_id, status, admission_no or delete on public.students for each row execute function live_app.on_student();
drop trigger if exists live_sync on public.class_groups;
create trigger live_sync after insert or update of name, level, form_teacher_id or delete on public.class_groups for each row execute function live_app.on_class_group();
drop trigger if exists live_sync on public.subject_offerings;
create trigger live_sync after insert or update or delete on public.subject_offerings for each row execute function live_app.on_class_child();
drop trigger if exists live_sync on public.class_staff;
create trigger live_sync after insert or update or delete on public.class_staff for each row execute function live_app.on_class_child();

-- ---------- bring everything across once ----------
select live_app.sync_tenant(id) from public.tenants;
select live_app.sync_user(id) from public.users;
select live_app.sync_class(id) from public.class_groups;

-- ===== 20260101006120_live_seb.sql =====
-- =========================================================================
-- Phase 14d-2: Safe Exam Browser lock for live classes and lessons.
--   * live.classes.require_seb: the class's default ("lock this class")
--   * live.class_sessions.require_seb: the lesson's own Locked/Unlocked switch
--     (copied from the class when the lesson starts; teachers can change it)
--   * live.seb_passes: written only by the server after it has checked the
--     student's Safe Exam Browser request headers (or user agent)
--   * joining a locked lesson (live.session_participants) is refused in the
--     database without a pass; locking a running lesson sends everyone who is
--     not in Safe Exam Browser back to the join screen
-- Apply AFTER 20260101006110. Idempotent.
-- =========================================================================

alter table live.classes add column if not exists require_seb boolean not null default false;
alter table live.class_sessions add column if not exists require_seb boolean not null default false;
alter table public.tenant_settings add column if not exists live_seb_config_keys text[] not null default '{}';

create table if not exists live.seb_passes (
  session_id  uuid not null references live.class_sessions(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  level       text not null default 'user_agent' check (level in ('hash','user_agent')),
  expires_at  timestamptz not null,
  created_at  timestamptz not null default now(),
  primary key (session_id, user_id)
);
alter table live.seb_passes enable row level security;
revoke all on live.seb_passes from anon, authenticated;
drop policy if exists seb_passes_own on live.seb_passes;
create policy seb_passes_own on live.seb_passes for select to authenticated using (user_id = auth.uid());
grant select on live.seb_passes to authenticated;

-- New lessons take the class's lock.
create or replace function live_app.session_seb_default() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.class_id is not null and not new.require_seb then
    select c.require_seb into new.require_seb from live.classes c where c.id = new.class_id;
    new.require_seb := coalesce(new.require_seb, false);
  end if;
  return new;
end $$;
drop trigger if exists session_seb_default on live.class_sessions;
create trigger session_seb_default before insert on live.class_sessions for each row execute function live_app.session_seb_default();

-- Nobody joins a locked lesson without a current Safe Exam Browser pass (teachers on the lesson excepted).
create or replace function live_app.participant_seb_check() returns trigger
language plpgsql security definer set search_path = '' as $$
declare s record;
begin
  select require_seb, teacher_id, class_id into s from live.class_sessions where id = new.session_id;
  if not coalesce(s.require_seb, false) or new.user_id = s.teacher_id then return new; end if;
  if exists (select 1 from live.class_members m where m.class_id = s.class_id and m.user_id = new.user_id and m.role = 'teacher') then return new; end if;
  if not exists (select 1 from live.seb_passes p where p.session_id = new.session_id and p.user_id = new.user_id and p.expires_at > now()) then
    raise exception 'safe_exam_browser_required' using hint = 'This lesson must be opened in Safe Exam Browser.';
  end if;
  return new;
end $$;
drop trigger if exists participant_seb_check on live.session_participants;
create trigger participant_seb_check before insert on live.session_participants for each row execute function live_app.participant_seb_check();

-- May the caller change this lesson's or class's lock? (its teacher, a co-teacher, or a school admin)
create or replace function live_app.can_lock(p_class uuid, p_teacher uuid, p_tenant uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select auth.uid() = p_teacher
      or exists (select 1 from live.classes c where c.id = p_class and c.teacher_id = auth.uid())
      or exists (select 1 from live.class_members m where m.class_id = p_class and m.user_id = auth.uid() and m.role = 'teacher')
      or exists (select 1 from live.class_subjects cs where cs.class_id = p_class and cs.teacher_id = auth.uid())
      or exists (select 1 from live.users u where u.id = auth.uid() and u.tenant_id = p_tenant and u.role = 'school_admin' and u.status = 'active');
$$;

/** Lock or unlock a running (or scheduled) lesson. Locking sends students without a pass back to the join screen. */
create or replace function live.set_session_seb(p_session uuid, p_on boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare s record; v_removed int := 0;
begin
  select id, class_id, teacher_id, tenant_id, status into s from live.class_sessions where id = p_session;
  if not found or not live_app.can_lock(s.class_id, s.teacher_id, s.tenant_id) then raise exception 'not allowed'; end if;
  update live.class_sessions set require_seb = p_on where id = p_session;
  if p_on then
    with gone as (
      delete from live.session_participants sp where sp.session_id = p_session and sp.user_id <> s.teacher_id
        and not exists (select 1 from live.seb_passes p where p.session_id = p_session and p.user_id = sp.user_id and p.expires_at > now())
        and not exists (select 1 from live.class_members m where m.class_id = s.class_id and m.user_id = sp.user_id and m.role = 'teacher')
      returning 1)
    select count(*) into v_removed from gone;
  end if;
  return jsonb_build_object('require_seb', p_on, 'sent_back', v_removed);
end $$;

/** Lock or unlock a class: every new lesson in it starts locked (or not). */
create or replace function live.set_class_seb(p_class uuid, p_on boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c record;
begin
  select id, teacher_id, tenant_id into c from live.classes where id = p_class;
  if not found or not live_app.can_lock(c.id, c.teacher_id, c.tenant_id) then raise exception 'not allowed'; end if;
  update live.classes set require_seb = p_on where id = p_class;
  return jsonb_build_object('require_seb', p_on);
end $$;

revoke all on function live_app.session_seb_default(), live_app.participant_seb_check() from public, anon, authenticated;
revoke all on function live_app.can_lock(uuid, uuid, uuid) from public, anon;
grant execute on function live_app.can_lock(uuid, uuid, uuid) to authenticated, service_role;
revoke all on function live.set_session_seb(uuid, boolean), live.set_class_seb(uuid, boolean) from public, anon;
grant execute on function live.set_session_seb(uuid, boolean), live.set_class_seb(uuid, boolean) to authenticated, service_role;

-- ===== 20260101006130_live_games.sql =====
-- =============================================================================
-- Synergy Swift — live games rework (Phase 14d-3)
--
-- Game modes (settings.mode):
--   classic      the teacher moves the class through the questions together
--   team_battle  teams, scored by the AVERAGE of their players (a big team no longer wins by size)
--   survival     everyone starts with lives; a wrong or missed answer costs one; last ones standing win
--   race         the class races along a track: every right answer is one step to the finish line
--   self_paced   homework mode: no host, each player goes at their own pace until the game closes
-- Power-ups are earned (never bought): every 3 right answers in a row gives one (up to 3 held):
--   double  next right answer scores double     shield  next wrong answer keeps your streak and life
--   fifty   hides half of the wrong options on the current question
-- Comeback bonus: a right answer from the bottom half of the board scores +25% (max +250).
-- Characters: students collect the critters by earning XP; games now give XP for right answers.
-- Guests of a live lesson can play the Challenge the teacher launches from that lesson.
-- Leaderboards carry an opaque per-player key, so "you" is found by key, not by name
-- (two guests called "Sam", or anonymous names, used to break it).
-- Everything here replaces engine functions (20260101006100) in place.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
alter table live.game_sessions drop constraint if exists game_sessions_status_check;
alter table live.game_sessions add constraint game_sessions_status_check
  check (status in ('lobby','question','review','ended','open'));
alter table live.game_sessions add column if not exists closes_at timestamptz;

alter table live.game_players
  add column if not exists avatar          text check (avatar is null or avatar ~ '^[a-z]{2,16}$'),
  add column if not exists lives           int,
  add column if not exists out_at          timestamptz,
  add column if not exists powerups        text[] not null default '{}',
  add column if not exists active_powerup  text check (active_powerup is null or active_powerup in ('double','shield','fifty')),
  add column if not exists hidden_options  uuid[] not null default '{}',
  add column if not exists hidden_for      int,
  add column if not exists earned_powerup  text,
  add column if not exists earned_for      int,
  add column if not exists worst_rank      int,
  add column if not exists q_index         int not null default 0,
  add column if not exists q_started_at    timestamptz,
  add column if not exists finished_at     timestamptz;

alter table live.game_answers
  add column if not exists powerup        text,
  add column if not exists powerup_bonus  int not null default 0,
  add column if not exists comeback_bonus int not null default 0;

alter table live.xp_events drop constraint if exists xp_events_source_check;
alter table live.xp_events add constraint xp_events_source_check
  check (source in ('answer','reasoning','completion','perfect','game','teacher','question','game_result'));

-- Characters a student has collected, and the one they play as.
create table if not exists live.student_characters (
  student_id   uuid not null,
  tenant_id    uuid not null,
  critter      text not null check (critter ~ '^[a-z]{2,16}$'),
  unlocked_at  timestamptz not null default now(),
  primary key (student_id, critter),
  foreign key (student_id, tenant_id) references live.users(id, tenant_id) on delete cascade
);
alter table live.student_characters enable row level security;
drop policy if exists student_characters_read on live.student_characters;
create policy student_characters_read on live.student_characters for select to authenticated
  using (tenant_id = (select live_app.tenant_id())
         and (student_id = (select auth.uid()) or live_app.teaches_student(student_id) or live_app.is_parent_of(student_id)));
alter table live.student_profiles add column if not exists critter text check (critter is null or critter ~ '^[a-z]{2,16}$');

-- ---------------------------------------------------------------------------
-- 2. Characters: the collection, unlocked by XP
-- ---------------------------------------------------------------------------
-- Keep in step with src/live/components/live/avatars.ts (CHARACTERS).
create or replace function live_app.critters() returns table (critter text, unlock_xp int, rarity text)
language sql immutable set search_path = '' as $$
  values ('fox', 0, 'starter'), ('owl', 0, 'starter'), ('panda', 0, 'starter'), ('frog', 0, 'starter'),
         ('tiger', 100, 'common'), ('koala', 250, 'common'), ('penguin', 400, 'common'), ('rabbit', 600, 'common'),
         ('turtle', 900, 'rare'), ('lion', 1300, 'rare'), ('octopus', 1800, 'rare'), ('cat', 2400, 'rare'),
         ('unicorn', 3200, 'epic'), ('whale', 4200, 'epic'), ('dragon', 5500, 'legendary'), ('phoenix', 7500, 'legendary')
$$;

create or replace function live_app.critter_xp(p_key text) returns int
language sql immutable set search_path = '' as $$
  select c.unlock_xp from live_app.critters() c where c.critter = p_key
$$;

create or replace function live_app.student_xp(p_student uuid) returns bigint
language sql stable security definer set search_path = '' as $$
  select coalesce(sum(points), 0) from live.xp_events where student_id = p_student
$$;

-- May this person play as this character? Starters for everyone; the rest once earned.
create or replace function live_app.can_use_character(p_user uuid, p_key text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(live_app.critter_xp(p_key) = 0, false)
      or exists (select 1 from live.student_characters c where c.student_id = p_user and c.critter = p_key)
$$;

-- After XP: collect every character the new total reaches, and say so.
create or replace function live_app.on_xp_characters() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_total bigint; r record;
begin
  v_total := live_app.student_xp(new.student_id);
  for r in
    insert into live.student_characters (student_id, tenant_id, critter)
      select new.student_id, new.tenant_id, c.critter from live_app.critters() c
       where c.unlock_xp > 0 and c.unlock_xp <= v_total
      on conflict do nothing
      returning critter
  loop
    perform live_app.notify(new.student_id, 'character', 'New character unlocked: ' || initcap(r.critter),
      'Play as it in your next game.', '/live/student/characters', 'info', jsonb_build_object('critter', r.critter));
  end loop;
  return null;
end$$;
drop trigger if exists xp_events_characters on live.xp_events;
create trigger xp_events_characters after insert on live.xp_events for each row execute function live_app.on_xp_characters();

create or replace function live.my_characters() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_me live.users := live_app.me(); v_xp bigint;
begin
  if v_me.id is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  v_xp := live_app.student_xp(v_me.id);
  return jsonb_build_object(
    'xp', v_xp, 'level', live_app.xp_level(v_xp),
    'chosen', (select p.critter from live.student_profiles p where p.user_id = v_me.id),
    'characters', (select coalesce(jsonb_agg(jsonb_build_object('key', c.critter, 'unlock_xp', c.unlock_xp, 'rarity', c.rarity,
                     'unlocked', c.unlock_xp = 0 or s.critter is not null, 'unlocked_at', s.unlocked_at) order by c.unlock_xp, c.critter), '[]'::jsonb)
                   from live_app.critters() c
                   left join live.student_characters s on s.student_id = v_me.id and s.critter = c.critter),
    'next', (select jsonb_build_object('key', c.critter, 'unlock_xp', c.unlock_xp, 'to_go', c.unlock_xp - v_xp)
               from live_app.critters() c where c.unlock_xp > v_xp order by c.unlock_xp limit 1));
end$$;

create or replace function live.choose_character(p_key text) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v_me live.users := live_app.me();
begin
  if v_me.id is null or v_me.role <> 'student' then raise exception 'Only students collect characters.' using errcode = '42501'; end if;
  if live_app.critter_xp(p_key) is null then raise exception 'Unknown character.' using errcode = '22023'; end if;
  if not live_app.can_use_character(v_me.id, p_key) then
    raise exception 'Earn % XP to unlock this character.', live_app.critter_xp(p_key) using errcode = 'P0001';
  end if;
  insert into live.student_profiles (user_id, tenant_id, critter) values (v_me.id, v_me.tenant_id, p_key)
    on conflict (user_id) do update set critter = excluded.critter;
end$$;

-- The lobby avatar: only characters this person has (guests: the starters).
create or replace function live.set_avatar(p_session uuid, p_avatar text) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if p_avatar !~ '^[a-z]{2,16}$' or live_app.critter_xp(p_avatar) is null then raise exception 'Unknown avatar.' using errcode = '22023'; end if;
  if not live_app.can_use_character(auth.uid(), p_avatar) then
    raise exception 'Earn % XP to unlock this character.', live_app.critter_xp(p_avatar) using errcode = 'P0001';
  end if;
  update live.session_participants set avatar = p_avatar
   where session_id = p_session and user_id = auth.uid() and removed_at is null;
  if not found then raise exception 'Join the lesson first.' using errcode = 'P0002'; end if;
end$$;

-- Joining a game gives XP to students only (guests have no XP to keep).
create or replace function live_app.game_xp() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_class uuid;
begin
  if new.user_id is null or not exists (select 1 from live.users u where u.id = new.user_id and u.role = 'student') then return null; end if;
  select class_id into v_class from live.game_sessions where id = new.game_id;
  perform live_app.give_xp(new.tenant_id, new.user_id, v_class, 'game', new.game_id, 10, 'Played a class game');
  return null;
end$$;

-- ---------------------------------------------------------------------------
-- 3. Settings, access and helpers
-- ---------------------------------------------------------------------------
create or replace function live_app.game_settings(p jsonb) returns jsonb
language sql immutable set search_path = '' as $$
  with m as (select case when p ->> 'mode' in ('classic','team_battle','survival','race','self_paced') then p ->> 'mode' else 'classic' end as mode)
  select jsonb_build_object(
    'mode',             m.mode,
    -- 0 = untimed: the teacher moves on when the class is ready; no speed bonus.
    'question_seconds', case when coalesce((p ->> 'question_seconds')::int, 20) = 0 then 0
                             else least(greatest(coalesce((p ->> 'question_seconds')::int, 20), 5), 240) end,
    'speed_bonus',      coalesce((p ->> 'speed_bonus')::boolean, true) and coalesce((p ->> 'question_seconds')::int, 20) <> 0,
    'streak_bonus',     coalesce((p ->> 'streak_bonus')::boolean, true),
    'rank_visibility',  case when coalesce((p ->> 'class_goal')::boolean, false) then 'hidden'
                             when p ->> 'rank_visibility' in ('after_each','end_only','hidden') then p ->> 'rank_visibility' else 'after_each' end,
    'display_mode',     case when p ->> 'display_mode' in ('first_name_initial','nickname','anonymous') then p ->> 'display_mode' else 'first_name_initial' end,
    'team_mode',        m.mode = 'team_battle' or (m.mode <> 'self_paced' and coalesce((p ->> 'team_mode')::boolean, false)),
    'team_count',       least(greatest(coalesce((p ->> 'team_count')::int, 2), 2), 6),
    'shuffle_questions', coalesce((p ->> 'shuffle_questions')::boolean, false),
    'shuffle_options',  coalesce((p ->> 'shuffle_options')::boolean, true),
    'podium_size',      least(greatest(coalesce((p ->> 'podium_size')::int, 3), 1), 10),
    'certificates',     coalesce((p ->> 'certificates')::boolean, true),
    -- Whole class works towards one target: this share of all answers correct.
    'class_goal',       coalesce((p ->> 'class_goal')::boolean, false) and m.mode in ('classic','race'),
    'goal_percent',     least(greatest(coalesce((p ->> 'goal_percent')::int, 70), 30), 100),
    'locked',           coalesce((p ->> 'locked')::boolean, false),
    'lives',            least(greatest(coalesce((p ->> 'lives')::int, 3), 1), 5),
    'powerups',         coalesce((p ->> 'powerups')::boolean, true),
    'comeback',         coalesce((p ->> 'comeback')::boolean, true))
  from m
$$;

create or replace function live_app.game_mode(p_game live.game_sessions) returns text
language sql immutable set search_path = '' as $$
  select coalesce(p_game.settings ->> 'mode', 'classic')
$$;

-- Who may play: the class, plus guests of the live lesson the game was launched from.
create or replace function live_app.game_can_play(p_game live.game_sessions) returns boolean
language sql stable security definer set search_path = '' as $$
  select live_app.in_class(p_game.class_id) or (p_game.session_id is not null and live_app.is_session_guest(p_game.session_id))
$$;

-- An opaque, stable id for a player on a board (never their user id).
create or replace function live_app.board_key(p_scope uuid, p_user uuid) returns text
language sql immutable set search_path = '' as $$
  select left(encode(sha256(convert_to(p_scope::text || ':' || p_user::text, 'UTF8')), 'hex'), 16)
$$;

-- Who runs a game: whoever created it, the class teacher, co-teachers and school admins.
create or replace function live_app.can_host_game(p_class uuid, p_host uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select p_host = auth.uid() or live_app.can_manage_class(p_class)
$$;

create or replace function live_app.require_game_host(p_game uuid) returns live.game_sessions
language plpgsql stable security definer set search_path = '' as $$
declare v live.game_sessions;
begin
  select * into v from live.game_sessions where id = p_game;
  if v.id is null then raise exception 'Game not found.' using errcode = 'P0002'; end if;
  if not live_app.can_host_game(v.class_id, v.host_id) then raise exception 'Only the host can control this game.' using errcode = '42501'; end if;
  return v;
end$$;

-- The game tables follow the same rule (and guests of the lesson see their game).
drop policy if exists game_sessions_read on live.game_sessions;
create policy game_sessions_read on live.game_sessions for select to authenticated
  using (live_app.can_host_game(class_id, host_id) or live_app.in_class(class_id)
         or (session_id is not null and live_app.is_session_guest(session_id)));
drop policy if exists game_players_read on live.game_players;
create policy game_players_read on live.game_players for select to authenticated
  using (user_id = (select auth.uid())
         or exists (select 1 from live.game_sessions g where g.id = game_id and live_app.can_host_game(g.class_id, g.host_id)));
drop policy if exists game_answers_read on live.game_answers;
create policy game_answers_read on live.game_answers for select to authenticated
  using (exists (select 1 from live.game_players p where p.id = player_id and p.user_id = (select auth.uid()))
         or exists (select 1 from live.game_sessions g where g.id = game_id and live_app.can_host_game(g.class_id, g.host_id)));
drop policy if exists leaderboard_entries_read on live.leaderboard_entries;
create policy leaderboard_entries_read on live.leaderboard_entries for select to authenticated
  using (exists (select 1 from live.game_sessions g where g.id = game_id and live_app.can_host_game(g.class_id, g.host_id)));
drop policy if exists game_flags_read on live.game_flags;
create policy game_flags_read on live.game_flags for select to authenticated
  using (exists (select 1 from live.game_sessions g where g.id = game_id and live_app.can_host_game(g.class_id, g.host_id)));

-- Question kinds a game can mark on the spot.
create or replace function live_app.game_kind(p_kind text) returns boolean
language sql immutable set search_path = '' as $$
  select p_kind in ('mcq','true_false','multi_select','fill_blank','matching','ordering','categorize')
$$;

-- Time's up: a question closes on the next look (after the same 1.5 s grace answers get),
-- and a self-paced game past its closing time is finished.
create or replace function live_app.game_tick(p_game uuid) returns live.game_sessions
language plpgsql volatile security definer set search_path = '' as $$
declare v live.game_sessions;
begin
  select * into v from live.game_sessions where id = p_game;
  if v.status = 'question' and now() > v.question_ends_at + interval '1500 milliseconds' then
    perform live_app.close_question(p_game);
  elsif v.status = 'open' and v.closes_at is not null and now() > v.closes_at then
    perform live_app.finish_game(p_game);
  end if;
  select * into v from live.game_sessions where id = p_game;
  return v;
end$$;

-- ---------------------------------------------------------------------------
-- 4. Create and join
-- ---------------------------------------------------------------------------
create or replace function live.create_game(
  p_class uuid, p_activity uuid, p_settings jsonb default '{}'::jsonb, p_session uuid default null, p_title text default null
) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me     live.users := live_app.me();
  v_act    live.activities;
  v_set    jsonb := live_app.game_settings(p_settings);
  v_order  uuid[];
  v_game   live.game_sessions;
  v_closes timestamptz;
  v_colors text[] := array['#ef4444','#3b82f6','#22c55e','#f59e0b','#a855f7','#14b8a6'];
  v_names  text[] := array['Red Rockets','Blue Comets','Green Geckos','Gold Falcons','Purple Owls','Teal Tigers'];
begin
  -- Subject teachers run games for the classes they teach, not only the class teacher.
  if not live_app.can_teach_class(p_class) then raise exception 'Not your class.' using errcode = '42501'; end if;
  if not live_app.feature(v_me.tenant_id, 'games') then raise exception 'Games are not included in your plan.' using errcode = 'P0001'; end if;
  select * into v_act from live.activities where id = p_activity and tenant_id = v_me.tenant_id;
  if v_act.id is null or not live_app.can_view_activity(p_activity) then raise exception 'Quiz not found.' using errcode = 'P0002'; end if;
  if p_session is not null and live_app.session_class(p_session) is distinct from p_class then
    raise exception 'That live session belongs to another class.' using errcode = '22023';
  end if;

  select array_agg(q.id order by case when (v_set ->> 'shuffle_questions')::boolean then md5(random()::text) else lpad(q.position::text, 6, '0') || q.created_at::text end)
    into v_order
  from live.questions q where q.activity_id = p_activity and live_app.game_kind(q.kind);
  if coalesce(array_length(v_order, 1), 0) = 0 then
    raise exception 'Games need at least one question that is marked automatically (choice, true/false, gap fill, matching, ordering or sorting).' using errcode = 'P0001';
  end if;

  if v_set ->> 'mode' = 'self_paced' then
    begin v_closes := (p_settings ->> 'closes_at')::timestamptz;
    exception when others then raise exception 'Choose when the game closes.' using errcode = '22023'; end;
    v_closes := coalesce(v_closes, now() + interval '7 days');
    if v_closes < now() + interval '10 minutes' or v_closes > now() + interval '60 days' then
      raise exception 'A self-paced game closes between 10 minutes and 60 days from now.' using errcode = '22023';
    end if;
  end if;

  insert into live.game_sessions (tenant_id, class_id, host_id, activity_id, session_id, title, join_code, settings, question_order,
                                  status, closes_at, started_at)
    values (v_me.tenant_id, p_class, v_me.id, p_activity, p_session, coalesce(nullif(btrim(p_title), ''), v_act.title),
            live_app.unique_code(6, 'game_sessions'), v_set, v_order,
            case when v_closes is null then 'lobby' else 'open' end, v_closes, case when v_closes is null then null else now() end)
    returning * into v_game;

  if (v_set ->> 'team_mode')::boolean then
    insert into live.game_teams (tenant_id, game_id, name, color)
      select v_me.tenant_id, v_game.id, v_names[i], v_colors[i] from generate_series(1, (v_set ->> 'team_count')::int) i;
  end if;

  perform live_app.audit('game.created', 'game', v_game.id::text, jsonb_build_object('class_id', p_class, 'activity_id', p_activity, 'mode', v_set ->> 'mode'));
  perform live_app.notify(m.user_id, 'game_created',
    case when v_closes is null then 'A Challenge is open: ' else 'New game to play by ' || to_char(v_closes, 'DD Mon') || ': ' end || v_game.title,
    'Join code ' || v_game.join_code, '/live/student/game/' || v_game.id, 'info', jsonb_build_object('game_id', v_game.id))
  from live.class_members m where m.class_id = p_class and m.role = 'student';
  return to_jsonb(v_game);
end$$;

create or replace function live.join_game(p_code text, p_nickname text default null) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_me     live.users := live_app.me();
  v_game   live.game_sessions;
  v_name   text;
  v_team   uuid;
  v_player live.game_players;
  v_n      int;
  v_avatar text;
begin
  select * into v_game from live.game_sessions where join_code = upper(btrim(p_code)) and status <> 'ended';
  if v_game.id is null then raise exception 'No open game with that code.' using errcode = 'P0002'; end if;
  if v_me.role not in ('student','guest') or not live_app.game_can_play(v_game) then
    raise exception 'This game is for students in another class.' using errcode = '42501';
  end if;
  if v_game.status = 'open' and v_game.closes_at is not null and now() > v_game.closes_at then
    raise exception 'This game has closed.' using errcode = 'P0001';
  end if;

  select * into v_player from live.game_players where game_id = v_game.id and user_id = v_me.id;
  if v_player.id is not null then return jsonb_build_object('game_id', v_game.id, 'player_id', v_player.id, 'display_name', v_player.display_name); end if;
  if coalesce((v_game.settings ->> 'locked')::boolean, false) then
    raise exception 'Your teacher has locked this game. Ask them to let you in.' using errcode = 'P0001';
  end if;

  case v_game.settings ->> 'display_mode'
    when 'nickname' then
      v_name := regexp_replace(btrim(coalesce(p_nickname, '')), '\s+', ' ', 'g');
      if v_name !~ '^[A-Za-z0-9][A-Za-z0-9 _-]{1,19}$' then
        raise exception 'Nicknames are 2-20 letters, numbers, spaces, - or _.' using errcode = '22023';
      end if;
      if exists (select 1 from live.game_players where game_id = v_game.id and lower(display_name) = lower(v_name)) then
        raise exception 'That nickname is taken in this game.' using errcode = 'P0001';
      end if;
    when 'anonymous' then
      select count(*) + 1 into v_n from live.game_players where game_id = v_game.id;
      v_name := 'Player ' || v_n;
    else
      v_name := live_app.display_name(coalesce(
        (select g.display_name from live.session_guests g where g.session_id = v_game.session_id and g.user_id = v_me.id), v_me.full_name));
  end case;

  if (v_game.settings ->> 'team_mode')::boolean then
    select t.id into v_team from live.game_teams t
      left join live.game_players p on p.team_id = t.id
     where t.game_id = v_game.id group by t.id order by count(p.id), t.name limit 1;
  end if;

  -- Play as your chosen character, else the avatar picked in the lesson's lobby.
  v_avatar := coalesce((select p.critter from live.student_profiles p where p.user_id = v_me.id),
                       (select sp.avatar from live.session_participants sp where sp.session_id = v_game.session_id and sp.user_id = v_me.id));

  insert into live.game_players (tenant_id, game_id, user_id, display_name, team_id, avatar, lives)
    values (v_me.tenant_id, v_game.id, v_me.id, v_name, v_team, v_avatar,
            case when v_game.settings ->> 'mode' = 'survival' then (v_game.settings ->> 'lives')::int end)
    returning * into v_player;
  return jsonb_build_object('game_id', v_game.id, 'player_id', v_player.id, 'display_name', v_player.display_name);
end$$;

-- From a link or notification: the player screen knows the game, not its code.
create or replace function live.join_game_by_id(p_game uuid, p_nickname text default null) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_code text;
begin
  select join_code into v_code from live.game_sessions where id = p_game and tenant_id = live_app.tenant_id();
  if v_code is null then raise exception 'No open game with that code.' using errcode = 'P0002'; end if;
  return live.join_game(v_code, p_nickname);
end$$;

-- ---------------------------------------------------------------------------
-- 5. Running the game
-- ---------------------------------------------------------------------------
create or replace function live_app.snapshot_leaderboard(p_game uuid, p_index int) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  insert into live.leaderboard_entries (tenant_id, game_id, player_id, question_index, rank, score)
  select p.tenant_id, p.game_id, p.id, p_index,
         rank() over (order by p.score desc, p.correct_count desc), p.score
  from live.game_players p where p.game_id = p_game
  on conflict (game_id, question_index, player_id) do update set rank = excluded.rank, score = excluded.score;
  -- Lowest place each player has been in (for the comeback badge).
  update live.game_players p set worst_rank = greatest(coalesce(p.worst_rank, 0), e.rank)
    from live.leaderboard_entries e where e.game_id = p_game and e.question_index = p_index and e.player_id = p.id;
end$$;

-- Earn a power-up every third right answer in a row (at most three held).
create or replace function live_app.maybe_powerup(p_player uuid, p_index int) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare v live.game_players; v_kind text;
begin
  select * into v from live.game_players where id = p_player;
  if v.streak = 0 or v.streak % 3 <> 0 or coalesce(array_length(v.powerups, 1), 0) >= 3 then return null; end if;
  v_kind := (array['double','shield','fifty'])[1 + (get_byte(decode(md5(p_player::text || p_index::text), 'hex'), 0) % 3)];
  update live.game_players set powerups = powerups || v_kind, earned_powerup = v_kind, earned_for = p_index where id = p_player;
  return v_kind;
end$$;

create or replace function live_app.close_question(p_game uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v live.game_sessions; r record;
begin
  update live.game_sessions set status = 'review', question_ends_at = least(question_ends_at, now())
   where id = p_game and status = 'question' returning * into v;
  if v.id is null then return; end if;

  -- No answer ends a streak, and in survival costs a life (a shield protects both, once).
  update live.game_players p set
      streak = case when p.active_powerup = 'shield' then p.streak else 0 end,
      lives = case when v.settings ->> 'mode' = 'survival' and p.active_powerup is distinct from 'shield'
                   then greatest(coalesce(p.lives, 1) - 1, 0) else p.lives end,
      out_at = case when v.settings ->> 'mode' = 'survival' and p.active_powerup is distinct from 'shield' and coalesce(p.lives, 1) <= 1
                    then now() else p.out_at end,
      active_powerup = case when p.active_powerup = 'shield' then null else p.active_powerup end
   where p.game_id = p_game and p.out_at is null
     and not exists (select 1 from live.game_answers a where a.player_id = p.id and a.question_index = v.current_index);

  if coalesce((v.settings ->> 'powerups')::boolean, true) then
    for r in select a.player_id from live.game_answers a where a.game_id = p_game and a.question_index = v.current_index and a.is_correct loop
      perform live_app.maybe_powerup(r.player_id, v.current_index);
    end loop;
  end if;
  perform live_app.snapshot_leaderboard(p_game, v.current_index);
end$$;

create or replace function live_app.finish_game(p_game uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare v live.game_sessions; v_total int; v_podium int; v_n int; v_mode text; v_top_team uuid;
begin
  select * into v from live.game_sessions where id = p_game;
  if v.status = 'ended' then return; end if;
  -- Ending mid-question costs nobody a life or a streak: the round just stops.
  if v.status = 'question' then perform live_app.snapshot_leaderboard(p_game, v.current_index); end if;
  update live.game_sessions set status = 'ended', ended_at = now() where id = p_game;
  v_total := coalesce(array_length(v.question_order, 1), 0);
  v_podium := (v.settings ->> 'podium_size')::int;
  v_mode := live_app.game_mode(v);
  select count(*) into v_n from live.game_players where game_id = p_game;

  if (v.settings ->> 'team_mode')::boolean then
    select p.team_id into v_top_team from live.game_players p where p.game_id = p_game and p.team_id is not null
     group by p.team_id order by avg(p.score) desc, sum(p.correct_count) desc limit 1;
  end if;

  with ranked as (
    select p.id, p.user_id, p.tenant_id, p.correct_count, p.best_streak, p.worst_rank, p.out_at, p.team_id, p.finished_at,
           live_app.game_rank(v, p) as rk,
           (select avg(a.scored_elapsed_ms) from live.game_answers a where a.player_id = p.id and a.is_correct) as avg_ms,
           (select count(*) from live.game_answers a where a.player_id = p.id) as answered
    from live.game_players p where p.game_id = p_game),
  fastest as (select id from ranked where avg_ms is not null order by avg_ms limit 1)
  update live.game_players p set badges = array_remove(array[
      case when r.rk = 1 then 'gold' when r.rk = 2 then 'silver' when r.rk = 3 then 'bronze' end,
      case when r.rk <= v_podium then 'podium' end,
      case when v_total > 0 and r.correct_count = v_total then 'perfect' end,
      case when r.best_streak >= 10 then 'streak_10' when r.best_streak >= 5 then 'streak_5' end,
      case when r.id in (select id from fastest) then 'speedster' end,
      case when v_mode = 'survival' and r.out_at is null and r.answered > 0 then 'survivor' end,
      case when v_n >= 4 and r.rk <= 3 and coalesce(r.worst_rank, 0) > ceil(v_n / 2.0) then 'comeback' end,
      case when v_top_team is not null and r.team_id = v_top_team then 'team_win' end,
      case when v_mode = 'self_paced' and r.finished_at is not null then 'finisher' end], null)
  from ranked r where r.id = p.id;

  -- XP for students: 5 a right answer, plus a podium bonus (capped at 100 a game).
  perform live_app.give_xp(p.tenant_id, p.user_id, v.class_id, 'game_result', p_game,
            p.correct_count * 5 + case when 'gold' = any(p.badges) then 25 when 'silver' = any(p.badges) then 15
                                       when 'bronze' = any(p.badges) then 10 else 0 end
                                + case when 'comeback' = any(p.badges) then 10 else 0 end,
            'Game: ' || left(v.title, 150))
    from live.game_players p join live.users u on u.id = p.user_id
   where p.game_id = p_game and u.role = 'student';
end$$;

-- A player's place. Survival: still in beats out, and later out beats earlier out.
create or replace function live_app.game_rank(p_game live.game_sessions, p_player live.game_players) returns bigint
language sql stable security definer set search_path = '' as $$
  select count(*) + 1 from live.game_players p
   where p.game_id = p_game.id and p.id <> p_player.id
     and case when live_app.game_mode(p_game) = 'survival' then
            (p.out_at is null and p_player.out_at is not null)
            or ((p.out_at is null) = (p_player.out_at is null)
                and (coalesce(p.out_at, 'infinity') > coalesce(p_player.out_at, 'infinity')
                     or (coalesce(p.out_at, 'infinity') = coalesce(p_player.out_at, 'infinity')
                         and (p.score > p_player.score or (p.score = p_player.score and p.correct_count > p_player.correct_count)))))
          else p.score > p_player.score or (p.score = p_player.score and p.correct_count > p_player.correct_count) end
$$;

create or replace function live.game_control(p_game uuid, p_action text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v live.game_sessions := live_app.require_game_host(p_game); v_total int;
begin
  v_total := coalesce(array_length(v.question_order, 1), 0);
  if live_app.game_mode(v) = 'self_paced' and p_action not in ('end','lock','unlock','extend') then
    raise exception 'Players go at their own pace in this game.' using errcode = 'P0001';
  end if;
  case p_action
    when 'start' then
      if v.status <> 'lobby' then raise exception 'The game has already started.' using errcode = 'P0001'; end if;
      perform live_app.open_question(v, 0);
    when 'close' then
      perform live_app.close_question(p_game);
    when 'next' then
      if v.status = 'question' then perform live_app.close_question(p_game); end if;
      if v.current_index + 1 >= v_total then perform live_app.finish_game(p_game);
      else perform live_app.open_question(v, v.current_index + 1); end if;
    when 'end' then
      perform live_app.finish_game(p_game);
    when 'lock' then
      update live.game_sessions set settings = settings || '{"locked": true}'::jsonb where id = p_game;
    when 'unlock' then
      update live.game_sessions set settings = settings || '{"locked": false}'::jsonb where id = p_game;
    when 'extend' then
      if v.status <> 'open' then raise exception 'Only an open self-paced game can be extended.' using errcode = 'P0001'; end if;
      update live.game_sessions set closes_at = least(greatest(closes_at, now()) + interval '1 day', now() + interval '60 days') where id = p_game;
    else raise exception 'Unknown action.' using errcode = '22023';
  end case;
  perform live_app.audit('game.' || p_action, 'game', p_game::text);
  select * into v from live.game_sessions where id = p_game;
  return jsonb_build_object('status', v.status, 'current_index', v.current_index, 'closes_at', v.closes_at,
                            'locked', coalesce((v.settings ->> 'locked')::boolean, false));
end$$;

-- Use a power-up on the current question (before answering it).
create or replace function live.game_use_powerup(p_game uuid, p_kind text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_game   live.game_sessions := live_app.game_tick(p_game);
  v_player live.game_players;
  v_index  int;
  v_q      live.questions;
  v_hide   uuid[];
begin
  if v_game.id is null then raise exception 'Game not found.' using errcode = 'P0002'; end if;
  select * into v_player from live.game_players where game_id = p_game and user_id = auth.uid() for update;
  if v_player.id is null then raise exception 'Join the game first.' using errcode = '42501'; end if;
  if not coalesce((v_game.settings ->> 'powerups')::boolean, true) then raise exception 'Power-ups are off in this game.' using errcode = 'P0001'; end if;
  if p_kind is null or not (p_kind = any(v_player.powerups)) then raise exception 'You do not have that power-up.' using errcode = 'P0001'; end if;
  if v_player.active_powerup is not null then raise exception 'You already have a power-up running.' using errcode = 'P0001'; end if;
  if v_player.out_at is not null then raise exception 'You are out of lives.' using errcode = 'P0001'; end if;

  v_index := case when v_game.status = 'open' then v_player.q_index else v_game.current_index end;
  if not (v_game.status = 'question' or (v_game.status = 'open' and v_player.finished_at is null)) then
    raise exception 'Use power-ups while a question is open.' using errcode = 'P0001';
  end if;
  if exists (select 1 from live.game_answers where player_id = v_player.id and question_index = v_index) then
    raise exception 'You already answered this question.' using errcode = 'P0001';
  end if;

  if p_kind = 'fifty' then
    select * into v_q from live.questions where id = v_game.question_order[v_index + 1];
    if v_q.kind not in ('mcq','multi_select') then raise exception '50:50 works on multiple-choice questions.' using errcode = 'P0001'; end if;
    select array_agg(id) into v_hide from (
      select o.id from live.question_options o where o.question_id = v_q.id and not o.is_correct
       order by md5(o.id::text || v_player.id::text)
       limit (select floor(count(*) / 2.0)::int from live.question_options o2 where o2.question_id = v_q.id and not o2.is_correct)) h;
    if coalesce(array_length(v_hide, 1), 0) = 0 then raise exception 'There are too few options to halve.' using errcode = 'P0001'; end if;
  end if;

  -- Spend one copy (a player may hold the same power-up twice).
  update live.game_players set
      powerups = coalesce((select array_agg(u.k order by u.i) from unnest(powerups) with ordinality u(k, i)
                            where u.i <> array_position(powerups, p_kind)), '{}'),
      active_powerup = p_kind,
      hidden_options = coalesce(v_hide, '{}'), hidden_for = case when v_hide is not null then v_index end
   where id = v_player.id;
  return jsonb_build_object('active', p_kind, 'hidden_options', coalesce(to_jsonb(v_hide), '[]'::jsonb));
end$$;

create or replace function live.game_answer(p_game uuid, p_index int, p_choice jsonb, p_client_elapsed_ms int default null)
returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_game     live.game_sessions;
  v_player   live.game_players;
  v_q        live.questions;
  v_grade    jsonb;
  v_correct  boolean;
  v_server   int;
  v_scored   int;
  v_dur      int;
  v_pts      jsonb;
  v_self     boolean;
  v_started  timestamptz;
  v_timeout  boolean := coalesce((p_choice ->> 'timeout')::boolean, false);
  v_power    text;
  v_double   int := 0;
  v_comeback int := 0;
  v_shield   boolean;
  v_n        int;
  v_rank     int;
  v_lives    int;
  v_out      boolean := false;
  v_earned   text;
  v_total    int;
begin
  select * into v_game from live.game_sessions where id = p_game;
  if v_game.id is null then raise exception 'Game not found.' using errcode = 'P0002'; end if;
  select * into v_player from live.game_players where game_id = p_game and user_id = auth.uid() for update;
  if v_player.id is null then raise exception 'Join the game first.' using errcode = '42501'; end if;
  if v_player.out_at is not null then raise exception 'You are out of lives. Watch the rest and cheer your class on!' using errcode = 'P0001'; end if;
  v_self := live_app.game_mode(v_game) = 'self_paced';
  v_total := coalesce(array_length(v_game.question_order, 1), 0);

  if v_self then
    if v_game.status <> 'open' or now() > v_game.closes_at then raise exception 'This game has closed.' using errcode = 'P0001'; end if;
    if v_player.finished_at is not null or v_player.q_index >= v_total then raise exception 'You have finished this game.' using errcode = 'P0001'; end if;
    if p_index <> v_player.q_index then raise exception 'The answer window is closed.' using errcode = 'P0001'; end if;
    v_started := coalesce(v_player.q_started_at, now());
    -- Past the time limit: it counts as no answer.
    if (v_game.settings ->> 'question_seconds')::int > 0
       and now() > v_started + make_interval(secs => (v_game.settings ->> 'question_seconds')::int) + interval '1500 milliseconds' then
      v_timeout := true;
    end if;
  else
    if v_game.status <> 'question' or v_game.current_index <> p_index
       or now() > v_game.question_ends_at + interval '1500 milliseconds' then
      raise exception 'The answer window is closed.' using errcode = 'P0001';
    end if;
    v_started := v_game.question_started_at;
  end if;
  if exists (select 1 from live.game_answers where player_id = v_player.id and question_index = p_index) then
    raise exception 'You already answered this question.' using errcode = 'P0001';
  end if;

  select * into v_q from live.questions where id = v_game.question_order[p_index + 1];
  if v_timeout then
    v_correct := false;
  else
    v_grade := live_app.grade_response(v_q, p_choice);
    v_correct := coalesce((v_grade ->> 'is_correct')::boolean, false);
  end if;
  v_server := greatest(0, (extract(epoch from (now() - v_started)) * 1000)::int);
  v_scored := live_app.normalize_elapsed(v_server, p_client_elapsed_ms);
  v_dur := (v_game.settings ->> 'question_seconds')::int * 1000;
  v_pts := live_app.game_points(v_correct, v_q.points, (v_game.settings ->> 'speed_bonus')::boolean,
                           (v_game.settings ->> 'streak_bonus')::boolean, v_scored, v_dur, v_player.streak);

  v_power := v_player.active_powerup;
  v_shield := coalesce(v_power = 'shield', false) and not v_correct;
  if v_power = 'double' and v_correct then
    v_double := (v_pts ->> 'base')::int + (v_pts ->> 'speed')::int + (v_pts ->> 'streak')::int;
  end if;
  -- Comeback: a right answer from the bottom half of a board of four or more.
  if v_correct and coalesce((v_game.settings ->> 'comeback')::boolean, true) then
    select count(*) into v_n from live.game_players where game_id = p_game;
    v_rank := live_app.game_rank(v_game, v_player);
    if v_n >= 4 and v_rank > ceil(v_n / 2.0) then v_comeback := least(250, round((v_pts ->> 'base')::int * 0.25)::int); end if;
  end if;

  insert into live.game_answers (tenant_id, game_id, player_id, question_id, question_index, choice, is_correct,
                                   base_points, speed_bonus, streak_bonus, server_elapsed_ms, scored_elapsed_ms,
                                   powerup, powerup_bonus, comeback_bonus)
    values (v_game.tenant_id, p_game, v_player.id, v_q.id, p_index, p_choice, v_correct,
            (v_pts ->> 'base')::int, (v_pts ->> 'speed')::int, (v_pts ->> 'streak')::int, v_server, v_scored,
            v_power, v_double, v_comeback);

  v_lives := v_player.lives;
  if live_app.game_mode(v_game) = 'survival' and not v_correct and not v_shield then
    v_lives := greatest(coalesce(v_lives, 1) - 1, 0);
    v_out := v_lives = 0;
  end if;

  update live.game_players set
    score = score + (v_pts ->> 'base')::int + (v_pts ->> 'speed')::int + (v_pts ->> 'streak')::int + v_double + v_comeback,
    correct_count = correct_count + case when v_correct then 1 else 0 end,
    streak = case when v_correct then streak + 1 when v_shield then streak else 0 end,
    best_streak = greatest(best_streak, case when v_correct then streak + 1 else 0 end),
    lives = v_lives,
    out_at = case when v_out then now() else out_at end,
    active_powerup = null,
    hidden_options = '{}', hidden_for = null,
    q_index = case when v_self then q_index + 1 else q_index end,
    q_started_at = case when v_self then null else q_started_at end,
    finished_at = case when v_self and (v_out or q_index + 1 >= v_total) then now() else finished_at end
  where id = v_player.id;

  -- Suspicious-pattern logging (never auto-penalised).
  if v_server < 400 and not v_timeout then
    insert into live.game_flags (tenant_id, game_id, player_id, kind, detail)
      values (v_game.tenant_id, p_game, v_player.id, 'answer_too_fast', jsonb_build_object('index', p_index, 'server_ms', v_server));
  end if;
  if p_client_elapsed_ms is not null and abs(p_client_elapsed_ms - v_server) > 5000 then
    insert into live.game_flags (tenant_id, game_id, player_id, kind, detail)
      values (v_game.tenant_id, p_game, v_player.id, 'clock_mismatch',
              jsonb_build_object('index', p_index, 'server_ms', v_server, 'client_ms', p_client_elapsed_ms));
  end if;

  if v_self then
    -- At your own pace you see how you did straight away.
    if v_correct and coalesce((v_game.settings ->> 'powerups')::boolean, true) then v_earned := live_app.maybe_powerup(v_player.id, p_index); end if;
    if (select finished_at from live.game_players where id = v_player.id) is not null then
      perform live_app.give_xp(v_player.tenant_id, v_player.user_id, v_game.class_id, 'game_result', p_game,
                               (select correct_count from live.game_players where id = v_player.id) * 5, 'Game: ' || left(v_game.title, 150))
        where exists (select 1 from live.users u where u.id = v_player.user_id and u.role = 'student');
    end if;
    return jsonb_build_object('accepted', true, 'is_correct', v_correct, 'timeout', v_timeout,
      'points', (v_pts ->> 'base')::int + (v_pts ->> 'speed')::int + (v_pts ->> 'streak')::int + v_double + v_comeback,
      'comeback', v_comeback, 'double', v_double, 'shielded', v_shield, 'lives', v_lives, 'out', v_out, 'earned', v_earned,
      'review', live_app.reveal_answer(v_q));
  end if;

  -- Everyone still in when the question opened has answered? Close early.
  if (select count(*) from live.game_answers a join live.game_players p on p.id = a.player_id
       where a.game_id = p_game and a.question_index = p_index and (p.out_at is null or p.out_at >= v_game.question_started_at))
     >= (select count(*) from live.game_players p where p.game_id = p_game and (p.out_at is null or p.out_at >= v_game.question_started_at)) then
    perform live_app.close_question(p_game);
  end if;
  return jsonb_build_object('accepted', true);
end$$;

-- ---------------------------------------------------------------------------
-- 6. What the screens see
-- ---------------------------------------------------------------------------
create or replace function live_app.game_teams_board(p_game live.game_sessions) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(t order by (t ->> 'score')::int desc, t ->> 'name'), '[]'::jsonb) from (
    select jsonb_build_object('team_id', tm.id, 'name', tm.name, 'color', tm.color,
             -- Average per player, so team size never decides the winner.
             'score', coalesce((select round(avg(p.score))::int from live.game_players p where p.team_id = tm.id), 0),
             'total', coalesce((select sum(p.score)::int from live.game_players p where p.team_id = tm.id), 0),
             'members', (select count(*) from live.game_players p where p.team_id = tm.id)) as t
      from live.game_teams tm where tm.game_id = p_game.id) x
$$;

create or replace function live.game_leaderboard(p_game uuid, p_limit int default 10) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_game    live.game_sessions := live_app.game_tick(p_game);
  v_host    boolean;
  v_vis     text;
  v_show    boolean;
  v_me      live.game_players;
begin
  if v_game.id is null then raise exception 'Game not found.' using errcode = 'P0002'; end if;
  v_host := live_app.can_host_game(v_game.class_id, v_game.host_id);
  if not v_host and not live_app.game_can_play(v_game) then raise exception 'Not your game.' using errcode = '42501'; end if;

  v_vis := v_game.settings ->> 'rank_visibility';
  v_show := v_host or (v_vis = 'after_each' and v_game.status in ('review','ended','open'))
                   or (v_vis = 'end_only' and v_game.status = 'ended');
  select * into v_me from live.game_players where game_id = p_game and user_id = auth.uid();

  return jsonb_build_object(
    'visible', v_show,
    'status', v_game.status,
    'mode', live_app.game_mode(v_game),
    'players', (select count(*) from live.game_players where game_id = p_game),
    'top', case when v_show then (
      select coalesce(jsonb_agg(row order by (row ->> 'rank')::int, row ->> 'name'), '[]'::jsonb) from (
        select jsonb_build_object('rank', live_app.game_rank(v_game, p),
               'player_id', p.id, 'key', live_app.board_key(p_game, p.user_id), 'avatar', p.avatar,
               'name', case when v_host then p.display_name || case when v_game.settings ->> 'display_mode' <> 'first_name_initial'
                                                                  then ' (' || u.full_name || ')' else '' end
                            else p.display_name end,
               'guest', u.role = 'guest',
               'score', p.score, 'correct', p.correct_count, 'streak', p.best_streak, 'badges', p.badges,
               'team_id', p.team_id, 'lives', p.lives, 'out', p.out_at is not null,
               'progress', case when v_game.status = 'open' then p.q_index end) as row
        from live.game_players p join live.users u on u.id = p.user_id
        where p.game_id = p_game
        order by live_app.game_rank(v_game, p) limit greatest(p_limit, 1)) s) else '[]'::jsonb end,
    'teams', case when (v_game.settings ->> 'team_mode')::boolean and v_show then live_app.game_teams_board(v_game) end,
    -- Players always see their own position, even when the board is hidden.
    'me', case when v_me.id is null then null else jsonb_build_object(
      'player_id', v_me.id, 'key', live_app.board_key(p_game, v_me.user_id), 'name', v_me.display_name, 'avatar', v_me.avatar,
      'score', v_me.score, 'streak', v_me.streak, 'correct', v_me.correct_count, 'badges', v_me.badges,
      'lives', v_me.lives, 'out', v_me.out_at is not null, 'rank', live_app.game_rank(v_game, v_me)) end);
end$$;

-- Everything a player or host screen needs, in one round trip.
create or replace function live.game_state(p_game uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_game   live.game_sessions := live_app.game_tick(p_game);
  v_host   boolean;
  v_q      live.questions;
  v_player live.game_players;
  v_answer live.game_answers;
  v_out    jsonb;
  v_mode   text;
  v_index  int;
  v_pub    jsonb;
  v_total  int;
  v_show   boolean;
begin
  if v_game.id is null then raise exception 'Game not found.' using errcode = 'P0002'; end if;
  v_host := live_app.can_host_game(v_game.class_id, v_game.host_id);
  if not v_host and not live_app.game_can_play(v_game) then raise exception 'Not your game.' using errcode = '42501'; end if;
  v_mode := live_app.game_mode(v_game);
  v_total := coalesce(array_length(v_game.question_order, 1), 0);
  v_show := v_host or v_game.settings ->> 'rank_visibility' <> 'hidden';

  v_out := jsonb_build_object(
    'id', v_game.id, 'title', v_game.title, 'status', v_game.status, 'join_code', v_game.join_code, 'mode', v_mode,
    'current_index', v_game.current_index, 'total', v_total,
    'question_started_at', v_game.question_started_at, 'question_ends_at', v_game.question_ends_at, 'closes_at', v_game.closes_at,
    'server_now', now(), 'settings', v_game.settings, 'is_host', v_host,
    'players', (select count(*) from live.game_players where game_id = p_game),
    'alive', case when v_mode = 'survival' then (select count(*) from live.game_players where game_id = p_game and out_at is null) end,
    'teams', case when (v_game.settings ->> 'team_mode')::boolean and v_show then live_app.game_teams_board(v_game) end,
    -- The race track: every right answer is a step (the top 40 runners).
    'race', case when v_mode = 'race' and v_show and v_game.status <> 'lobby' then (
      select coalesce(jsonb_agg(jsonb_build_object('key', live_app.board_key(p_game, r.user_id), 'name', r.display_name, 'avatar', r.avatar,
                                                   'steps', r.correct_count, 'team_id', r.team_id) order by r.correct_count desc, r.score desc), '[]'::jsonb)
        from (select * from live.game_players where game_id = p_game order by correct_count desc, score desc limit 40) r) end);

  select * into v_player from live.game_players where game_id = p_game and user_id = auth.uid();
  v_index := case when v_mode = 'self_paced' then coalesce(v_player.q_index, 0) else v_game.current_index end;

  if (v_game.status in ('question','review') and v_index >= 0)
     or (v_game.status = 'open' and v_player.id is not null and v_player.finished_at is null and v_index < v_total) then
    select * into v_q from live.questions where id = v_game.question_order[v_index + 1];
    v_pub := live_app.sanitize_question(v_q, ('x' || left(md5(v_game.id::text), 8))::bit(32)::int, (v_game.settings ->> 'shuffle_options')::boolean);
    if v_player.id is not null and v_player.hidden_for = v_index and coalesce(array_length(v_player.hidden_options, 1), 0) > 0 then
      v_pub := jsonb_set(v_pub, '{options}', (select coalesce(jsonb_agg(o), '[]'::jsonb) from jsonb_array_elements(v_pub -> 'options') o
                                              where not ((o ->> 'id')::uuid = any(v_player.hidden_options))));
    end if;
    v_out := v_out || jsonb_build_object('question', v_pub, 'question_index', v_index);
    if v_mode = 'self_paced' then
      -- Your own clock starts when you first see the question.
      if v_player.q_started_at is null then
        update live.game_players set q_started_at = now() where id = v_player.id returning * into v_player;
      end if;
      v_out := v_out || jsonb_build_object('question_started_at', v_player.q_started_at,
        'question_ends_at', case when (v_game.settings ->> 'question_seconds')::int > 0
                                 then v_player.q_started_at + make_interval(secs => (v_game.settings ->> 'question_seconds')::int) end);
    else
      v_out := v_out || jsonb_build_object('answered',
        (select count(*) from live.game_answers where game_id = p_game and question_index = v_game.current_index));
    end if;
    if v_game.status = 'review' then
      v_out := v_out || jsonb_build_object('review', live_app.reveal_answer(v_q) || jsonb_build_object(
        'distribution', (select coalesce(jsonb_object_agg(o.id, (select count(*) from live.game_answers a
                           where a.game_id = p_game and a.question_index = v_game.current_index
                             and (a.choice ->> 'option_id' = o.id::text or a.choice -> 'option_ids' ? o.id::text))), '{}'::jsonb)
                         from live.question_options o where o.question_id = v_q.id),
        'right', (select count(*) from live.game_answers a where a.game_id = p_game and a.question_index = v_game.current_index and a.is_correct)));
    end if;
  end if;

  if v_host then
    v_out := v_out || jsonb_build_object(
      'roster', (select coalesce(jsonb_agg(jsonb_build_object('player_id', p.id, 'name', p.display_name, 'avatar', p.avatar,
                   'full_name', u.full_name, 'guest', u.role = 'guest', 'team_id', p.team_id, 'lives', p.lives, 'out', p.out_at is not null,
                   'progress', p.q_index, 'finished', p.finished_at is not null, 'score', p.score,
                   'answered', exists (select 1 from live.game_answers a where a.player_id = p.id and a.question_index = v_game.current_index))
                   order by p.joined_at), '[]'::jsonb)
                 from live.game_players p join live.users u on u.id = p.user_id where p.game_id = p_game),
      'flags', (select count(*) from live.game_flags where game_id = p_game));
  elsif v_player.id is not null then
    select * into v_answer from live.game_answers where player_id = v_player.id and question_index = v_index;
    v_out := v_out || jsonb_build_object('me', jsonb_build_object(
      'player_id', v_player.id, 'key', live_app.board_key(p_game, v_player.user_id), 'name', v_player.display_name, 'avatar', v_player.avatar,
      'score', v_player.score, 'streak', v_player.streak, 'correct', v_player.correct_count,
      'answered', v_answer.id is not null,
      'lives', v_player.lives, 'out', v_player.out_at is not null,
      'powerups', to_jsonb(v_player.powerups), 'active_powerup', v_player.active_powerup,
      'earned', case when v_player.earned_for = v_game.current_index and v_game.status = 'review' then v_player.earned_powerup end,
      'progress', v_player.q_index, 'finished', v_player.finished_at is not null,
      'rank', live_app.game_rank(v_game, v_player),
      'last', case when v_answer.id is not null and v_game.status in ('review','ended') then jsonb_build_object(
                'is_correct', v_answer.is_correct,
                'points', v_answer.base_points + v_answer.speed_bonus + v_answer.streak_bonus + v_answer.powerup_bonus + v_answer.comeback_bonus,
                'comeback', v_answer.comeback_bonus, 'double', v_answer.powerup_bonus, 'powerup', v_answer.powerup) end));
  end if;
  return v_out;
end$$;

create or replace function live.game_goal(p_game uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v live.game_sessions; v_players int; v_asked int; v_correct int;
begin
  select * into v from live.game_sessions where id = p_game;
  if v.id is null then raise exception 'Game not found.' using errcode = 'P0002'; end if;
  if not live_app.can_host_game(v.class_id, v.host_id) and not live_app.game_can_play(v) then raise exception 'Not your game.' using errcode = '42501'; end if;
  select count(*) into v_players from live.game_players where game_id = p_game;
  v_asked := greatest(v.current_index + 1, 0);
  select count(*) into v_correct from live.game_answers where game_id = p_game and is_correct;
  return jsonb_build_object('enabled', coalesce((v.settings ->> 'class_goal')::boolean, false),
    'correct', v_correct,
    'target', ceil(v_players * coalesce(array_length(v.question_order, 1), 0) * (v.settings ->> 'goal_percent')::numeric / 100),
    'possible_so_far', v_players * v_asked,
    'goal_percent', (v.settings ->> 'goal_percent')::int);
end$$;

-- Guests of the lesson may also listen to its game's channel (same as can_listen in the engine otherwise).
create or replace function live_app.can_listen(p_topic text) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare v_kind text := split_part(p_topic, ':', 1); v_id uuid; v_user uuid;
begin
  begin
    v_id := nullif(split_part(p_topic, ':', 2), '')::uuid;
    v_user := nullif(split_part(p_topic, ':', 3), '')::uuid;
  exception when others then return false; end;
  if v_id is null or live_app.tenant_id() is null then return false; end if;
  return case v_kind
    when 'session' then live_app.in_session(v_id) or live_app.can_manage_session(v_id)
    when 'staff'   then live_app.can_manage_session(v_id)
    -- teachers watch; the student may join only their own channel (to send frames)
    when 'screen'  then live_app.can_manage_session(v_id) or (v_user = auth.uid() and live_app.in_session(v_id))
    when 'user'    then v_id = auth.uid()
    -- parent threads: only the parent and the teacher (never the child, nor other staff)
    when 'thread'  then exists (select 1 from live.chat_threads t where t.id = v_id and t.tenant_id = live_app.tenant_id()
                                and case when t.kind = 'parent' then auth.uid() in (t.parent_id, t.teacher_id)
                                         else (t.student_id = auth.uid() or t.teacher_id = auth.uid()
                                               or (t.kind = 'group' and live_app.in_session(t.session_id)) or live_app.can_manage_class(t.class_id)) end)
    -- boards and games: exactly the people who can read the row (mirrors their RLS policies)
    when 'board'   then exists (select 1 from live.collab_boards b where b.id = v_id and b.tenant_id = live_app.tenant_id()
                                and (b.owner_id = auth.uid()
                                     or (b.session_id is not null and (live_app.can_manage_session(b.session_id) or live_app.in_session(b.session_id)))
                                     or (b.session_id is null and live_app.is_teacher())))
    when 'game'    then exists (select 1 from live.game_sessions g where g.id = v_id and g.tenant_id = live_app.tenant_id()
                                and (live_app.can_host_game(g.class_id, g.host_id) or live_app.game_can_play(g)))
    when 'annot'   then live_app.in_session(v_id) or live_app.can_manage_session(v_id)
    else false end;
end$$;

-- The lesson leaderboard (same as the engine's 1160), with each row's opaque key.
create or replace function live_app.snapshot_leaderboard(p_session uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare v_board jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('key', live_app.board_key(p_session, r.user_id), 'name', r.name, 'avatar', r.avatar,
                                               'score', r.score, 'rank', r.rank,
                                               'delta', coalesce(r.last_rank, r.rank) - r.rank) order by r.rank, r.name), '[]'::jsonb)
    into v_board
    from (select * from live_app.session_ranks(p_session) order by rank, name limit 500) r;
  update live.session_participants p set last_rank = r.rank
    from live_app.session_ranks(p_session) r where p.session_id = p_session and p.user_id = r.user_id;
  update live.class_sessions set show_leaderboard = true, leaderboard = jsonb_build_object('at', now(), 'top', v_board)
   where id = p_session;
  return v_board;
end$$;

-- My key on a lesson's leaderboard (the board itself is one snapshot shared by the class).
create or replace function live.my_board_key(p_session uuid) returns text
language sql stable security definer set search_path = '' as $$
  select case when live_app.in_session(p_session) or live_app.can_manage_session(p_session)
              then live_app.board_key(p_session, auth.uid()) end
$$;

-- ---------------------------------------------------------------------------
-- 7. Privileges
-- ---------------------------------------------------------------------------
revoke execute on function live_app.critters(), live_app.critter_xp(text), live_app.student_xp(uuid), live_app.can_use_character(uuid, text),
  live_app.on_xp_characters(), live_app.game_mode(live.game_sessions), live_app.game_can_play(live.game_sessions), live_app.board_key(uuid, uuid),
  live_app.game_kind(text), live_app.game_tick(uuid), live_app.maybe_powerup(uuid, int), live_app.game_rank(live.game_sessions, live.game_players),
  live_app.game_teams_board(live.game_sessions), live_app.snapshot_leaderboard(uuid, int), live_app.snapshot_leaderboard(uuid),
  live_app.close_question(uuid), live_app.finish_game(uuid), live_app.game_xp()
  from public, anon, authenticated;
revoke execute on function live.my_characters(), live.choose_character(text), live.set_avatar(uuid, text), live.join_game_by_id(uuid, text),
  live.game_use_powerup(uuid, text), live.my_board_key(uuid), live.create_game(uuid, uuid, jsonb, uuid, text), live.join_game(text, text),
  live.game_control(uuid, text), live.game_answer(uuid, int, jsonb, int), live.game_leaderboard(uuid, int), live.game_state(uuid), live.game_goal(uuid)
  from public, anon;
grant execute on function live.my_characters(), live.choose_character(text), live.set_avatar(uuid, text), live.join_game_by_id(uuid, text),
  live.game_use_powerup(uuid, text), live.my_board_key(uuid), live.create_game(uuid, uuid, jsonb, uuid, text), live.join_game(text, text),
  live.game_control(uuid, text), live.game_answer(uuid, int, jsonb, int), live.game_leaderboard(uuid, int), live.game_state(uuid), live.game_goal(uuid)
  to authenticated;
grant select on live.student_characters to authenticated;
grant execute on function live_app.can_host_game(uuid, uuid) to authenticated;

-- ===== 20260101006200_entrance_automation.sql =====
-- =========================================================================
-- Synergy Swift: entrance exam automation (Phase 14e).
--  * entrance_plans: the rules for one intake (level + intake): which test,
--    when it is assigned (on applying, once the form fee is paid, or by hand),
--    where it is taken (online at home, at a centre, or the family chooses),
--    face checks at home, Safe Exam Browser at centres, weights for the test,
--    interview and previous school report, pass marks (overall and per
--    section), the borderline band that leads to an interview, automatic or
--    approve-first decisions, the waiting list size, when results are released,
--    and the class new students join.
--  * entrance_sittings: online windows and centre sessions with seats.
--  * entrance_attempts gain a sitting, a one-time PIN (hashed) for centre
--    computers, check-in, absence, section scores and face-check flags.
--  * applications gain the intake, the report score, the weighted score,
--    merit rank and the proposed decision with its reason.
--  * entrance_events: camera photos and face-check flags during home tests.
--  * entrance_lookups: wrong PIN / results-checker tries, for throttling.
-- The test is assigned the moment an application arrives (or its fee is paid)
-- by a trigger; messages, PINs, reminders, absences and decisions are sent by
-- the dispatch job (src/lib/entrance-server.ts). Idempotent.
-- =========================================================================

create table if not exists public.entrance_plans (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null references public.tenants(id) on delete cascade,
  name                text not null check (length(btrim(name)) between 1 and 120),
  level               text not null check (length(btrim(level)) between 1 and 60),
  intake              text not null default '',
  exam_id             uuid references public.exams(id) on delete set null,
  status              text not null default 'open' check (status in ('draft','open','closed')),
  assign_on           text not null default 'fee_paid' check (assign_on in ('submitted','fee_paid','manual')),
  where_mode          text not null default 'online' check (where_mode in ('online','centre','choice')),
  face_check          boolean not null default false,
  seb_at_centre       boolean not null default true,
  test_weight         int not null default 100 check (test_weight between 0 and 100),
  interview_weight    int not null default 0 check (interview_weight between 0 and 100),
  report_weight       int not null default 0 check (report_weight between 0 and 100),
  pass_mark           numeric(5,2) not null default 50 check (pass_mark between 0 and 100),
  section_pass_marks  jsonb not null default '{}'::jsonb,
  borderline_band     numeric(5,2) not null default 5 check (borderline_band between 0 and 50),
  interview_for       text not null default 'borderline' check (interview_for in ('none','borderline','passed','everyone')),
  decision_mode       text not null default 'approve' check (decision_mode in ('auto','approve')),
  waitlist_size       int not null default 10 check (waitlist_size between 0 and 10000),
  release_at          timestamptz,
  show_scores         boolean not null default false,
  offer_valid_days    int check (offer_valid_days between 1 and 120),
  acceptance_fee      numeric(14,2) check (acceptance_fee >= 0),
  class_group_id      uuid references public.class_groups(id) on delete set null,
  created_by          uuid references public.users(id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint entrance_plans_weights check (test_weight + interview_weight + report_weight = 100 and test_weight > 0)
);
create unique index if not exists entrance_plans_intake on public.entrance_plans(tenant_id, lower(level), lower(intake));

create table if not exists public.entrance_sittings (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  plan_id           uuid not null references public.entrance_plans(id) on delete cascade,
  kind              text not null default 'centre' check (kind in ('online','centre')),
  centre            text,
  address           text,
  starts_at         timestamptz not null,
  ends_at           timestamptz not null,
  seats             int check (seats between 1 and 100000),
  created_at        timestamptz not null default now(),
  constraint entrance_sittings_window check (ends_at > starts_at),
  constraint entrance_sittings_centre check (kind = 'online' or length(btrim(coalesce(centre, ''))) > 0)
);
create index if not exists entrance_sittings_plan on public.entrance_sittings(plan_id, starts_at);

alter table public.entrance_attempts add column if not exists sitting_id uuid references public.entrance_sittings(id) on delete set null;
alter table public.entrance_attempts add column if not exists pin_hash text;
alter table public.entrance_attempts add column if not exists pin_expires_at timestamptz;
alter table public.entrance_attempts add column if not exists checked_in_at timestamptz;
alter table public.entrance_attempts add column if not exists notified_at timestamptz;
alter table public.entrance_attempts add column if not exists reminded_at timestamptz;
alter table public.entrance_attempts add column if not exists absent boolean not null default false;
alter table public.entrance_attempts add column if not exists section_scores jsonb not null default '{}'::jsonb;
alter table public.entrance_attempts add column if not exists face_flags int not null default 0;
create unique index if not exists entrance_attempts_pin on public.entrance_attempts(pin_hash) where pin_hash is not null;
create index if not exists entrance_attempts_sitting on public.entrance_attempts(sitting_id);

alter table public.applications add column if not exists entrance_plan_id uuid references public.entrance_plans(id) on delete set null;
alter table public.applications add column if not exists report_score numeric(5,2) check (report_score between 0 and 100);
alter table public.applications add column if not exists composite_score numeric(5,2);
alter table public.applications add column if not exists merit_rank int;
alter table public.applications add column if not exists proposed_decision text check (proposed_decision in ('offer','interview','waitlist','regret'));
alter table public.applications add column if not exists decision_reason text;
alter table public.applications add column if not exists decided_at timestamptz;
create index if not exists applications_entrance_plan on public.applications(entrance_plan_id);

create table if not exists public.entrance_events (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  attempt_id  uuid not null references public.entrance_attempts(id) on delete cascade,
  kind        text not null check (kind in ('snapshot','no_face','multiple_faces','camera_off','blur','checked_in','seb_refused')),
  meta        jsonb not null default '{}'::jsonb,
  at          timestamptz not null default now()
);
create index if not exists entrance_events_attempt on public.entrance_events(attempt_id, at desc);

create table if not exists public.entrance_lookups (
  id     bigint generated always as identity primary key,
  ip     text not null,
  kind   text not null check (kind in ('pin','results')),
  ok     boolean not null default false,
  at     timestamptz not null default now()
);
create index if not exists entrance_lookups_ip on public.entrance_lookups(ip, kind, at desc);

-- ---------- RLS: admissions staff only; the public pages go through the server ----------
alter table public.entrance_plans enable row level security;
alter table public.entrance_sittings enable row level security;
alter table public.entrance_events enable row level security;
alter table public.entrance_lookups enable row level security;
drop policy if exists entrance_plans_admissions on public.entrance_plans;
create policy entrance_plans_admissions on public.entrance_plans for all
  using (tenant_id = public.my_tenant_id() and public.is_admissions())
  with check (tenant_id = public.my_tenant_id() and public.is_admissions());
drop policy if exists entrance_sittings_admissions on public.entrance_sittings;
create policy entrance_sittings_admissions on public.entrance_sittings for all
  using (tenant_id = public.my_tenant_id() and public.is_admissions())
  with check (tenant_id = public.my_tenant_id() and public.is_admissions()
              and exists (select 1 from public.entrance_plans p where p.id = plan_id and p.tenant_id = public.my_tenant_id()));
-- Camera photos and flags are written only by the server.
drop policy if exists entrance_events_read on public.entrance_events;
create policy entrance_events_read on public.entrance_events for select
  using (tenant_id = public.my_tenant_id() and public.is_admissions());
-- entrance_lookups: no policies (server only).
revoke all on public.entrance_lookups from anon, authenticated;
revoke insert, update, delete on public.entrance_events from anon, authenticated;

-- ---------- Assignment ----------
-- The intake an application belongs to: same level; a named intake wins over the default ('').
create or replace function public.entrance_plan_for(p_tenant uuid, p_level text)
returns public.entrance_plans language sql stable security definer set search_path = public as $$
  select p.* from public.entrance_plans p
   where p.tenant_id = p_tenant and lower(p.level) = lower(btrim(p_level)) and p.status = 'open'
   order by (p.intake = ''), p.created_at desc limit 1
$$;

-- Books a sitting for a test that hasn't started. The sitting row is locked, so two
-- families can never take the last seat at the same moment. A new sitting clears the
-- PIN and the "sent" mark, so the family is told the new time and place.
create or replace function public.entrance_book_sitting(p_attempt uuid, p_sitting uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare s public.entrance_sittings; t public.entrance_attempts;
begin
  select * into t from public.entrance_attempts where id = p_attempt;
  select * into s from public.entrance_sittings where id = p_sitting for update;
  if t.id is null or s.id is null or t.status <> 'assigned' or s.ends_at <= now() or s.tenant_id <> t.tenant_id then return false; end if;
  if t.sitting_id = s.id then return true; end if;
  if s.seats is not null and (select count(*) from public.entrance_attempts x where x.sitting_id = s.id) >= s.seats then return false; end if;
  update public.entrance_attempts set sitting_id = s.id,
         opens_at = case when s.kind = 'online' then s.starts_at end, closes_at = case when s.kind = 'online' then s.ends_at end,
         pin_hash = null, pin_expires_at = null, notified_at = null, reminded_at = null, absent = false
   where id = t.id;
  update public.applications set assessment_at = s.starts_at, updated_at = now() where id = t.application_id;
  return true;
end $$;

-- Puts a test in the earliest sitting of its intake that has a free seat (online windows for
-- online intakes, centres for centre intakes; families choose for themselves in 'choice').
create or replace function public.entrance_seat(p_attempt uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare t public.entrance_attempts; p public.entrance_plans; r record;
begin
  select * into t from public.entrance_attempts where id = p_attempt;
  select pl.* into p from public.entrance_plans pl join public.applications a on a.entrance_plan_id = pl.id where a.id = t.application_id;
  if t.id is null or p.id is null or p.where_mode = 'choice' or t.sitting_id is not null then return t.sitting_id is not null; end if;
  for r in select st.id from public.entrance_sittings st
            where st.plan_id = p.id and st.kind = case when p.where_mode = 'online' then 'online' else 'centre' end and st.ends_at > now()
            order by st.starts_at loop
    if public.entrance_book_sitting(t.id, r.id) then return true; end if;
  end loop;
  return false;
end $$;

-- Assigns the intake's entrance test to an application and seats it.
-- Returns the attempt id, or null when the intake has no test or the application is past testing.
create or replace function public.entrance_assign(p_app uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare a public.applications; p public.entrance_plans; v_id uuid;
begin
  select * into a from public.applications where id = p_app;
  if a.id is null or a.status not in ('new','reviewing','assessment') then return null; end if;
  p := public.entrance_plan_for(a.tenant_id, a.applying_for);
  if p.id is null or p.exam_id is null then return null; end if;
  update public.applications set entrance_plan_id = p.id,
         status = case when status in ('new','reviewing') then 'assessment' else status end, updated_at = now()
   where id = a.id;
  insert into public.entrance_attempts (tenant_id, application_id, exam_id)
    values (a.tenant_id, a.id, p.exam_id)
    on conflict (application_id, exam_id) do nothing
    returning id into v_id;
  if v_id is not null then perform public.entrance_seat(v_id); end if;
  return v_id;
end $$;

-- Seats every waiting test of an intake (after a sitting is added or seats are raised).
create or replace function public.entrance_seat_waiting(p_plan uuid)
returns int language plpgsql security definer set search_path = public as $$
declare r record; n int := 0;
begin
  for r in select t.id from public.entrance_attempts t join public.applications a on a.id = t.application_id
            where a.entrance_plan_id = p_plan and t.status = 'assigned' and t.sitting_id is null order by a.created_at loop
    if public.entrance_seat(r.id) then n := n + 1; end if;
  end loop;
  return n;
end $$;

-- The handshake: an application that arrives (or whose form fee is paid) gets its test at once.
create or replace function public.entrance_auto_assign()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.entrance_plans;
begin
  p := public.entrance_plan_for(new.tenant_id, new.applying_for);
  if p.id is null then return null; end if;
  if (p.assign_on = 'submitted' and tg_op = 'INSERT')
     or (p.assign_on = 'fee_paid' and new.fee_paid and (tg_op = 'INSERT' or not coalesce(old.fee_paid, false))) then
    perform public.entrance_assign(new.id);
  elsif tg_op = 'INSERT' then
    update public.applications set entrance_plan_id = p.id where id = new.id and entrance_plan_id is null;
  end if;
  return null;
end $$;
drop trigger if exists applications_entrance_assign on public.applications;
create trigger applications_entrance_assign after insert or update of fee_paid on public.applications
  for each row execute function public.entrance_auto_assign();

-- Staff actions (checked against their own school).
create or replace function public.entrance_staff_assign(p_app uuid)
returns uuid language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admissions() or not exists (select 1 from public.applications where id = p_app and tenant_id = public.my_tenant_id()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return public.entrance_assign(p_app);
end $$;
create or replace function public.entrance_staff_seat_waiting(p_plan uuid)
returns int language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admissions() or not exists (select 1 from public.entrance_plans where id = p_plan and tenant_id = public.my_tenant_id()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return public.entrance_seat_waiting(p_plan);
end $$;
create or replace function public.entrance_staff_book(p_attempt uuid, p_sitting uuid)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admissions() or not exists (select 1 from public.entrance_attempts where id = p_attempt and tenant_id = public.my_tenant_id()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return public.entrance_book_sitting(p_attempt, p_sitting);
end $$;

revoke all on function public.entrance_plan_for(uuid, text), public.entrance_book_sitting(uuid, uuid), public.entrance_seat(uuid),
  public.entrance_assign(uuid), public.entrance_seat_waiting(uuid), public.entrance_auto_assign() from public, anon, authenticated;
grant execute on function public.entrance_book_sitting(uuid, uuid), public.entrance_seat(uuid), public.entrance_assign(uuid),
  public.entrance_seat_waiting(uuid) to service_role;
revoke all on function public.entrance_staff_assign(uuid), public.entrance_staff_seat_waiting(uuid), public.entrance_staff_book(uuid, uuid) from public, anon;
grant execute on function public.entrance_staff_assign(uuid), public.entrance_staff_seat_waiting(uuid), public.entrance_staff_book(uuid, uuid) to authenticated;

grant select, insert, update, delete on public.entrance_plans, public.entrance_sittings to authenticated;
grant select on public.entrance_events to authenticated;

-- ===== 20260101006300_elections.sql =====
-- =========================================================================
-- Synergy Swift: elections and voting (Phase 14f).
--  * elections: prefects, PTA, class reps, houses, staff or anything else, for
--    students, parents, staff or everyone (optionally only some classes), with
--    a voting window, one vote per family (PTA) option, a teacher-run kiosk,
--    live results for the election officers, and results published to voters.
--  * election_posts: the offices (Head girl, 2 seats …); election_candidates.
--  * The SECRET BALLOT: election_voters records THAT someone voted (and how:
--    online or at a kiosk); election_ballots + election_votes record WHAT was
--    chosen, with a random ballot id, no voter, no time. Nothing links them,
--    so not even school admins can see how anyone voted. Each voter gets a
--    receipt code to check their ballot was counted.
--  * Votes are cast only through cast_ballot() / cast_ballot_kiosk(), which
--    check eligibility, the window, the number of choices and "one vote".
-- Idempotent.
-- =========================================================================

create table if not exists public.elections (
  id                     uuid primary key default gen_random_uuid(),
  tenant_id              uuid not null references public.tenants(id) on delete cascade,
  title                  text not null check (length(btrim(title)) between 2 and 160),
  kind                   text not null default 'prefects' check (kind in ('prefects','pta','class_rep','house','staff','other')),
  description            text,
  audience               text not null default 'students' check (audience in ('students','parents','staff','everyone')),
  class_group_ids        uuid[],                       -- null = the whole school
  one_per_family         boolean not null default false, -- parents: one vote for each family
  allow_kiosk            boolean not null default true,  -- teachers can run a voting tablet for their class
  live_results           boolean not null default false, -- officers see counts while voting is open
  publish_to_voters      boolean not null default true,
  status                 text not null default 'draft' check (status in ('draft','open','closed','published')),
  opens_at               timestamptz,
  closes_at              timestamptz,
  created_by             uuid references public.users(id) on delete set null,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint elections_window check (closes_at is null or opens_at is null or closes_at > opens_at)
);
create index if not exists elections_tenant on public.elections(tenant_id, created_at desc);

create table if not exists public.election_posts (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  election_id  uuid not null references public.elections(id) on delete cascade,
  title        text not null check (length(btrim(title)) between 1 and 120),
  description  text,
  seats        int not null default 1 check (seats between 1 and 50),
  position     int not null default 0
);
create index if not exists election_posts_election on public.election_posts(election_id, position);

create table if not exists public.election_candidates (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  election_id  uuid not null references public.elections(id) on delete cascade,
  post_id      uuid not null references public.election_posts(id) on delete cascade,
  name         text not null check (length(btrim(name)) between 1 and 120),
  student_id   uuid references public.students(id) on delete set null,
  user_id      uuid references public.users(id) on delete set null,
  photo_url    text,
  manifesto    text check (length(manifesto) <= 4000),
  position     int not null default 0
);
create index if not exists election_candidates_post on public.election_candidates(post_id, position);

-- Who voted (never what). voter_key: 'user:<id>', 'student:<id>' (kiosk or online) or 'family:<student id>'.
create table if not exists public.election_voters (
  election_id  uuid not null references public.elections(id) on delete cascade,
  voter_key    text not null,
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  user_id      uuid references public.users(id) on delete set null,   -- who was signed in (the voter, or the kiosk teacher)
  student_id   uuid references public.students(id) on delete set null,
  channel      text not null check (channel in ('online','kiosk')),
  voted_at     timestamptz not null default now(),
  primary key (election_id, voter_key)
);

-- What was chosen (never who). No voter, no time.
create table if not exists public.election_ballots (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  election_id   uuid not null references public.elections(id) on delete cascade,
  receipt_hash  text not null unique
);
create table if not exists public.election_votes (
  ballot_id     uuid not null references public.election_ballots(id) on delete cascade,
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  election_id   uuid not null references public.elections(id) on delete cascade,
  post_id       uuid not null references public.election_posts(id) on delete cascade,
  candidate_id  uuid not null references public.election_candidates(id) on delete cascade,
  primary key (ballot_id, candidate_id)
);
create index if not exists election_votes_count on public.election_votes(election_id, candidate_id);

-- ---------- Helpers ----------
create or replace function public.is_election_officer()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin()
$$;

-- Where an election is: draft, scheduled (open but before its start), voting, closed or published.
create or replace function public.election_phase(e public.elections)
returns text language sql stable set search_path = public as $$
  select case
    when e.status = 'draft' then 'draft'
    when e.status = 'published' then 'published'
    when e.status = 'closed' or (e.closes_at is not null and now() >= e.closes_at) then 'closed'
    when e.opens_at is not null and now() < e.opens_at then 'scheduled'
    else 'voting' end
$$;

-- Is this student in the election's classes (active students only)?
create or replace function public.election_student_ok(e public.elections, p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.students s where s.id = p_student and s.tenant_id = e.tenant_id and s.status = 'active'
                   and (e.class_group_ids is null or s.class_group_id = any(e.class_group_ids)))
$$;

-- The signed-in person's vote key for an election, or null when they may not vote in it.
create or replace function public.election_voter_key(p_election uuid)
returns text language plpgsql stable security definer set search_path = public as $$
declare e public.elections; u public.users; v_student uuid; v_family uuid;
begin
  select * into e from public.elections where id = p_election;
  select * into u from public.users where id = auth.uid();
  if e.id is null or u.id is null or u.tenant_id <> e.tenant_id then return null; end if;
  if e.audience in ('students','everyone') and u.role = 'student' then
    select s.id into v_student from public.students s where s.user_id = u.id and s.tenant_id = e.tenant_id limit 1;
    if v_student is not null and public.election_student_ok(e, v_student) then return 'student:' || v_student; end if;
    return null;
  end if;
  if e.audience in ('parents','everyone') and (u.role = 'parent' or exists (select 1 from public.guardians g where g.user_id = u.id)) then
    -- A parent of an active child in the election's classes; for one vote per family, the family is the eldest such child's record.
    select min(s.id::text)::uuid into v_family
      from public.guardians g join public.student_guardians sg on sg.guardian_id = g.id join public.students s on s.id = sg.student_id
     where g.user_id = u.id and g.tenant_id = e.tenant_id and public.election_student_ok(e, s.id);
    if v_family is not null then
      return case when e.one_per_family then 'family:' || v_family else 'user:' || u.id end;
    end if;
    if u.role = 'parent' then return null; end if;
  end if;
  if e.audience in ('staff','everyone') and u.role not in ('student','parent','alumni') then return 'user:' || u.id; end if;
  return null;
end $$;

-- Records one ballot: the voter row (who) and the ballot with its votes (what), unlinked.
-- p_choices: {"<post id>": ["<candidate id>", ...], ...}; a post left out is an abstention.
create or replace function public.election_record(e public.elections, p_key text, p_choices jsonb, p_channel text, p_student uuid)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v_ballot uuid; v_receipt text := upper(substr(encode(gen_random_bytes(8), 'hex'), 1, 12)); r record; v_n int; v_ok int;
begin
  if public.election_phase(e) <> 'voting' then raise exception 'Voting is not open for this election.' using errcode = 'P0001'; end if;
  if p_choices is null or jsonb_typeof(p_choices) <> 'object' then raise exception 'Choose your candidates.' using errcode = '22023'; end if;
  for r in select key, value from jsonb_each(p_choices) loop
    if jsonb_typeof(r.value) <> 'array' then raise exception 'Choose your candidates.' using errcode = '22023'; end if;
    if not exists (select 1 from public.election_posts p where p.id::text = r.key and p.election_id = e.id) then
      raise exception 'That post is not in this election.' using errcode = '22023';
    end if;
    select count(*), count(*) filter (where exists (select 1 from public.election_candidates c where c.id::text = x and c.post_id::text = r.key))
      into v_n, v_ok from jsonb_array_elements_text(r.value) x;
    if v_n <> v_ok then raise exception 'A choice is not a candidate for that post.' using errcode = '22023'; end if;
    if v_n > (select seats from public.election_posts where id::text = r.key) then
      raise exception 'Too many choices for one post.' using errcode = '22023';
    end if;
    if v_n <> (select count(distinct x) from jsonb_array_elements_text(r.value) x) then raise exception 'The same candidate twice.' using errcode = '22023'; end if;
  end loop;
  begin
    insert into public.election_voters (election_id, voter_key, tenant_id, user_id, student_id, channel)
      values (e.id, p_key, e.tenant_id, auth.uid(), p_student, p_channel);
  exception when unique_violation then
    raise exception 'This vote has already been cast.' using errcode = 'P0001';
  end;
  insert into public.election_ballots (tenant_id, election_id, receipt_hash)
    values (e.tenant_id, e.id, encode(sha256(convert_to('ballot:' || v_receipt, 'UTF8')), 'hex')) returning id into v_ballot;
  insert into public.election_votes (ballot_id, tenant_id, election_id, post_id, candidate_id)
    select v_ballot, e.tenant_id, e.id, ch.key::uuid, x::uuid from jsonb_each(p_choices) ch, jsonb_array_elements_text(ch.value) x;
  return v_receipt;
end $$;

-- Online vote by the signed-in student, parent or member of staff. Returns the receipt code.
create or replace function public.cast_ballot(p_election uuid, p_choices jsonb)
returns text language plpgsql volatile security definer set search_path = public as $$
declare e public.elections; v_key text;
begin
  select * into e from public.elections where id = p_election and tenant_id = public.my_tenant_id();
  if e.id is null then raise exception 'Election not found.' using errcode = 'P0002'; end if;
  v_key := public.election_voter_key(p_election);
  if v_key is null then raise exception 'You are not on the voters'' list for this election.' using errcode = '42501'; end if;
  return public.election_record(e, v_key, p_choices, 'online', case when v_key like 'student:%' then substr(v_key, 9)::uuid end);
end $$;

-- A teacher's voting tablet: the student votes on the teacher's device (the teacher never sees the choices).
create or replace function public.cast_ballot_kiosk(p_election uuid, p_student uuid, p_choices jsonb)
returns text language plpgsql volatile security definer set search_path = public as $$
declare e public.elections; s public.students;
begin
  select * into e from public.elections where id = p_election and tenant_id = public.my_tenant_id();
  if e.id is null then raise exception 'Election not found.' using errcode = 'P0002'; end if;
  if not e.allow_kiosk or e.audience not in ('students','everyone') then raise exception 'This election does not use voting tablets.' using errcode = 'P0001'; end if;
  select * into s from public.students where id = p_student and tenant_id = e.tenant_id;
  if s.id is null or not public.election_student_ok(e, s.id) then raise exception 'That student is not on the voters'' list.' using errcode = '42501'; end if;
  if not (public.is_election_officer() or public.teaches_class(s.class_group_id)) then
    raise exception 'Only the student''s teachers can run a voting tablet for them.' using errcode = '42501';
  end if;
  return public.election_record(e, 'student:' || s.id, p_choices, 'kiosk', s.id);
end $$;

-- How many may vote and how many have (by channel and class). Officers only.
create or replace function public.election_turnout(p_election uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare e public.elections; v_students int := 0; v_parents int := 0; v_staff int := 0;
begin
  select * into e from public.elections where id = p_election and tenant_id = public.my_tenant_id();
  if e.id is null or not public.is_election_officer() then raise exception 'not allowed' using errcode = '42501'; end if;
  if e.audience in ('students','everyone') then
    select count(*) into v_students from public.students s where s.tenant_id = e.tenant_id and public.election_student_ok(e, s.id);
  end if;
  if e.audience in ('parents','everyone') then
    select case when e.one_per_family then count(distinct fam) else count(distinct gid) end into v_parents from (
      select g.user_id as gid, (select min(s2.id::text) from public.student_guardians sg2 join public.students s2 on s2.id = sg2.student_id
                                 join public.guardians g2 on g2.id = sg2.guardian_id where g2.user_id = g.user_id and public.election_student_ok(e, s2.id)) as fam
        from public.guardians g join public.student_guardians sg on sg.guardian_id = g.id join public.students s on s.id = sg.student_id
       where g.tenant_id = e.tenant_id and g.user_id is not null and public.election_student_ok(e, s.id)) x;
  end if;
  if e.audience in ('staff','everyone') then
    select count(*) into v_staff from public.users u where u.tenant_id = e.tenant_id and u.role not in ('student','parent','alumni')
      and coalesce(u.active, true);
  end if;
  return jsonb_build_object(
    'eligible', v_students + v_parents + v_staff,
    'voted', (select count(*) from public.election_voters where election_id = e.id),
    'online', (select count(*) from public.election_voters where election_id = e.id and channel = 'online'),
    'kiosk', (select count(*) from public.election_voters where election_id = e.id and channel = 'kiosk'),
    'by_class', (select coalesce(jsonb_agg(jsonb_build_object('class', g.name, 'voted', x.n) order by g.name), '[]'::jsonb)
                   from (select s.class_group_id, count(*) n from public.election_voters v join public.students s on s.id = v.student_id
                          where v.election_id = e.id group by 1) x join public.class_groups g on g.id = x.class_group_id));
end $$;

-- Counts per candidate and the winners. Officers: once voting closes (or live, when allowed);
-- voters: once published (when the election publishes to voters).
create or replace function public.election_results(p_election uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare e public.elections; v_phase text;
begin
  select * into e from public.elections where id = p_election and tenant_id = public.my_tenant_id();
  if e.id is null then raise exception 'Election not found.' using errcode = 'P0002'; end if;
  v_phase := public.election_phase(e);
  if not ((public.is_election_officer() and (v_phase in ('closed','published') or e.live_results))
          or (v_phase = 'published' and e.publish_to_voters and public.election_voter_key(p_election) is not null)) then
    raise exception 'Results are not available yet.' using errcode = '42501';
  end if;
  return jsonb_build_object('phase', v_phase, 'ballots', (select count(*) from public.election_ballots where election_id = e.id),
    'posts', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'title', p.title, 'seats', p.seats,
      'abstained', (select count(*) from public.election_ballots b where b.election_id = e.id
                     and not exists (select 1 from public.election_votes v where v.ballot_id = b.id and v.post_id = p.id)),
      -- rk: place (equal votes share a place); ge: candidates with at least as many votes. Elected when
      -- ge fits the seats; a tie on the line (ge > seats while placed inside them) is flagged for a decision.
      'candidates', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'photo_url', c.photo_url, 'votes', c.votes, 'rank', c.rk,
                       'elected', c.votes > 0 and c.ge <= p.seats, 'tie', c.votes > 0 and c.rk <= p.seats and c.ge > p.seats) order by c.votes desc, c.name), '[]'::jsonb)
                     from (select c1.id, c1.name, c1.photo_url, c1.votes, rank() over (order by c1.votes desc) as rk, count(*) over (order by c1.votes desc) as ge
                             from (select c0.*, (select count(*) from public.election_votes v where v.candidate_id = c0.id) as votes
                                     from public.election_candidates c0 where c0.post_id = p.id) c1) c)) order by p.position, p.title), '[]'::jsonb)
      from public.election_posts p where p.election_id = e.id));
end $$;

-- "Was my ballot counted?" Anyone in the school with the receipt code.
create or replace function public.election_check_receipt(p_election uuid, p_receipt text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.election_ballots b join public.elections e on e.id = b.election_id
                  where b.election_id = p_election and e.tenant_id = public.my_tenant_id()
                    and b.receipt_hash = encode(sha256(convert_to('ballot:' || upper(btrim(p_receipt)), 'UTF8')), 'hex'))
$$;

-- Elections the signed-in person can vote in (or see results of), with whether they have voted.
create or replace function public.my_elections()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'title', e.title, 'kind', e.kind, 'description', e.description,
           'opens_at', e.opens_at, 'closes_at', e.closes_at, 'phase', public.election_phase(e),
           'voted', exists (select 1 from public.election_voters v where v.election_id = e.id and v.voter_key = public.election_voter_key(e.id)),
           'results', public.election_phase(e) = 'published' and e.publish_to_voters) order by e.closes_at nulls last), '[]'::jsonb)
    from public.elections e
   where e.tenant_id = public.my_tenant_id() and e.status <> 'draft'
     and (e.closes_at is null or e.closes_at > now() - interval '60 days')
     and public.election_voter_key(e.id) is not null
$$;

-- For a teacher's voting tablet: which of their class's students have voted (any way), never how.
create or replace function public.election_class_voted(p_election uuid, p_class uuid)
returns uuid[] language plpgsql stable security definer set search_path = public as $$
begin
  if not exists (select 1 from public.elections where id = p_election and tenant_id = public.my_tenant_id())
     or not (public.is_election_officer() or public.teaches_class(p_class)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return coalesce((select array_agg(v.student_id) from public.election_voters v join public.students s on s.id = v.student_id
                    where v.election_id = p_election and s.class_group_id = p_class), '{}');
end $$;

-- ---------- RLS ----------
alter table public.elections enable row level security;
alter table public.election_posts enable row level security;
alter table public.election_candidates enable row level security;
alter table public.election_voters enable row level security;
alter table public.election_ballots enable row level security;
alter table public.election_votes enable row level security;

drop policy if exists elections_officers on public.elections;
create policy elections_officers on public.elections for all
  using (tenant_id = public.my_tenant_id() and public.is_election_officer())
  with check (tenant_id = public.my_tenant_id() and public.is_election_officer());
drop policy if exists elections_voters on public.elections;
create policy elections_voters on public.elections for select
  using (tenant_id = public.my_tenant_id() and status <> 'draft' and (public.election_voter_key(id) is not null or public.is_staff()));
drop policy if exists election_posts_officers on public.election_posts;
create policy election_posts_officers on public.election_posts for all
  using (tenant_id = public.my_tenant_id() and public.is_election_officer())
  with check (tenant_id = public.my_tenant_id() and public.is_election_officer()
              and exists (select 1 from public.elections e where e.id = election_id and e.tenant_id = public.my_tenant_id()));
drop policy if exists election_posts_read on public.election_posts;
create policy election_posts_read on public.election_posts for select
  using (tenant_id = public.my_tenant_id() and exists (select 1 from public.elections e where e.id = election_id));
drop policy if exists election_candidates_officers on public.election_candidates;
create policy election_candidates_officers on public.election_candidates for all
  using (tenant_id = public.my_tenant_id() and public.is_election_officer())
  with check (tenant_id = public.my_tenant_id() and public.is_election_officer()
              and exists (select 1 from public.election_posts p where p.id = post_id and p.election_id = election_candidates.election_id and p.tenant_id = public.my_tenant_id()));
drop policy if exists election_candidates_read on public.election_candidates;
create policy election_candidates_read on public.election_candidates for select
  using (tenant_id = public.my_tenant_id() and exists (select 1 from public.elections e where e.id = election_id));
-- Who voted: officers (turnout) and each voter's own row. Never written directly.
drop policy if exists election_voters_read on public.election_voters;
create policy election_voters_read on public.election_voters for select
  using (tenant_id = public.my_tenant_id() and (public.is_election_officer() or user_id = auth.uid()));
-- Ballots and votes: no policies at all. Only the counting functions read them.
revoke all on public.election_ballots, public.election_votes from anon, authenticated;
revoke insert, update, delete on public.election_voters from anon, authenticated;
grant select, insert, update, delete on public.elections, public.election_posts, public.election_candidates to authenticated;
grant select on public.election_voters to authenticated;

-- Candidates and posts can't change once voting has started (the ballot paper is fixed).
create or replace function public.election_paper_fixed()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_status text;
begin
  select status into v_status from public.elections where id = coalesce(new.election_id, old.election_id);
  if v_status is not null and v_status <> 'draft' and exists (select 1 from public.election_voters where election_id = coalesce(new.election_id, old.election_id)) then
    raise exception 'Votes have been cast; the ballot paper can no longer change.' using errcode = 'P0001';
  end if;
  return coalesce(new, old);
end $$;
drop trigger if exists election_posts_fixed on public.election_posts;
create trigger election_posts_fixed before insert or update or delete on public.election_posts for each row execute function public.election_paper_fixed();
drop trigger if exists election_candidates_fixed on public.election_candidates;
create trigger election_candidates_fixed before insert or update or delete on public.election_candidates for each row execute function public.election_paper_fixed();

revoke all on function public.is_election_officer(), public.election_phase(public.elections), public.election_student_ok(public.elections, uuid),
  public.election_voter_key(uuid), public.election_record(public.elections, text, jsonb, text, uuid), public.cast_ballot(uuid, jsonb),
  public.cast_ballot_kiosk(uuid, uuid, jsonb), public.election_turnout(uuid), public.election_results(uuid), public.election_check_receipt(uuid, text),
  public.my_elections(), public.election_paper_fixed(), public.election_class_voted(uuid, uuid) from public, anon;
revoke all on function public.election_record(public.elections, text, jsonb, text, uuid), public.election_paper_fixed() from authenticated;
grant execute on function public.is_election_officer(), public.election_phase(public.elections), public.election_student_ok(public.elections, uuid),
  public.election_voter_key(uuid), public.cast_ballot(uuid, jsonb), public.cast_ballot_kiosk(uuid, uuid, jsonb), public.election_turnout(uuid),
  public.election_results(uuid), public.election_check_receipt(uuid, text), public.my_elections(), public.election_class_voted(uuid, uuid) to authenticated;

-- ===== 20260101006400_sales_crm.sql =====
-- =========================================================================
-- Synergy Swift: the platform's own sales CRM (Phase 14g-1).
--  * sales_leads: prospect schools from first contact (or the website's
--    "Book a demo" form) to won (a school created) or lost, with size, value,
--    owner, next action and a score.
--  * sales_activities: calls, notes, WhatsApp, meetings, demos, stage changes.
--  * sales_quotes: priced from the platform's plans and size bands.
--  * tenant_onboarding: the go-live checklist for a new school (created, data
--    imported, staff trained, parents invited, live).
--  * demo_request_tries: throttling for the public form.
-- Only the platform team, through the server (service role). Schools never see
-- any of it. Idempotent.
-- =========================================================================

create table if not exists public.sales_leads (
  id                 uuid primary key default gen_random_uuid(),
  school_name        text not null check (length(btrim(school_name)) between 2 and 200),
  contact_name       text,
  contact_role       text,
  phone              text,
  email              text,
  city               text,
  state              text,
  students_estimate  int check (students_estimate between 0 and 100000),
  source             text not null default 'other' check (source in ('website','referral','event','cold_call','social','partner','other')),
  stage              text not null default 'new' check (stage in ('new','contacted','demo_booked','demo_done','trial','proposal','won','lost')),
  owner_id           uuid references auth.users(id) on delete set null,      -- platform team (no school profile)
  next_action        text,
  next_action_at     timestamptz,
  demo_at            timestamptz,
  package_code       text,
  value_estimate     bigint,                       -- naira a year
  score              int not null default 0,
  lost_reason        text,
  tenant_id          uuid references public.tenants(id) on delete set null,
  needs              text,                         -- what they asked for on the form
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  stage_changed_at   timestamptz not null default now()
);
create index if not exists sales_leads_stage on public.sales_leads(stage, next_action_at);
create index if not exists sales_leads_tenant on public.sales_leads(tenant_id);

create table if not exists public.sales_activities (
  id        uuid primary key default gen_random_uuid(),
  lead_id   uuid not null references public.sales_leads(id) on delete cascade,
  kind      text not null check (kind in ('note','call','email','whatsapp','meeting','demo','stage','quote','system')),
  body      text not null check (length(body) <= 4000),
  actor_id  uuid references auth.users(id) on delete set null,
  at        timestamptz not null default now()
);
create index if not exists sales_activities_lead on public.sales_activities(lead_id, at desc);

create table if not exists public.sales_quotes (
  id              uuid primary key default gen_random_uuid(),
  lead_id         uuid not null references public.sales_leads(id) on delete cascade,
  number          text not null unique,
  plan_code       text not null,
  band            int,
  students        int,
  add_on_groups   text[] not null default '{}',
  cycle           text not null default 'annual' check (cycle in ('annual','termly')),
  custom_annual   bigint,
  discount_pct    numeric not null default 0 check (discount_pct between 0 and 100),
  lines           jsonb not null default '[]'::jsonb,
  annual          bigint,
  valid_until     date,
  status          text not null default 'draft' check (status in ('draft','sent','accepted','declined','expired')),
  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  sent_at         timestamptz,
  decided_at      timestamptz
);

create table if not exists public.tenant_onboarding (
  tenant_id  uuid not null references public.tenants(id) on delete cascade,
  step       text not null check (step in ('school_created','data_imported','staff_trained','parents_invited','go_live')),
  done_at    timestamptz not null default now(),
  done_by    uuid references auth.users(id) on delete set null,
  auto       boolean not null default false,
  note       text,
  primary key (tenant_id, step)
);

create table if not exists public.demo_request_tries (
  id   bigint generated always as identity primary key,
  ip   text not null,
  at   timestamptz not null default now()
);
create index if not exists demo_request_tries_ip on public.demo_request_tries(ip, at desc);

create sequence if not exists public.sales_quote_seq;
create or replace function public.next_sales_quote_number()
returns text language sql volatile security definer set search_path = public as $$
  select 'Q-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.sales_quote_seq')::text, 5, '0')
$$;

-- Customer health, per school: size, sign-ins and actions this month against last month,
-- overdue platform invoices, the subscription and its renewal. For the platform team only.
create or replace function public.platform_customer_metrics()
returns table (tenant_id uuid, name text, status text, created_at timestamptz, students int, staff int, parents_with_login int,
               staff_signed_in_30 int, users_signed_in_30 int, actions_30 int, actions_prev_30 int, last_action_at timestamptz,
               invoices_overdue int, oldest_overdue_days int, sub_status text, period_end timestamptz, plan_name text, custom_annual bigint)
language sql stable security definer set search_path = public as $$
  select t.id, t.name, t.status, t.created_at,
    (select count(*) from public.students s where s.tenant_id = t.id and s.status = 'active')::int,
    (select count(*) from public.users u where u.tenant_id = t.id and u.role not in ('student','parent','alumni'))::int,
    (select count(*) from public.guardians g where g.tenant_id = t.id and g.user_id is not null)::int,
    (select count(*) from public.users u join auth.users au on au.id = u.id
      where u.tenant_id = t.id and u.role not in ('student','parent','alumni') and au.last_sign_in_at > now() - interval '30 days')::int,
    (select count(*) from public.users u join auth.users au on au.id = u.id where u.tenant_id = t.id and au.last_sign_in_at > now() - interval '30 days')::int,
    (select count(*) from public.audit_logs a where a.tenant_id = t.id and a.ts > now() - interval '30 days')::int,
    (select count(*) from public.audit_logs a where a.tenant_id = t.id and a.ts <= now() - interval '30 days' and a.ts > now() - interval '60 days')::int,
    greatest((select max(a.ts) from public.audit_logs a where a.tenant_id = t.id),
             (select max(au.last_sign_in_at) from public.users u join auth.users au on au.id = u.id where u.tenant_id = t.id)),
    (select count(*) from public.invoices i where i.tenant_id = t.id and i.status = 'open' and i.due_at < now())::int,
    (select coalesce(max(extract(day from now() - i.due_at)), 0) from public.invoices i where i.tenant_id = t.id and i.status = 'open' and i.due_at < now())::int,
    sub.status, sub.period_end, p.name, sub.custom_annual
  from public.tenants t
  left join lateral (select * from public.subscriptions s where s.tenant_id = t.id order by s.created_at desc limit 1) sub on true
  left join public.plans p on p.id = sub.plan_id
$$;
revoke all on function public.platform_customer_metrics() from public, anon, authenticated;
grant execute on function public.platform_customer_metrics() to service_role;

-- Platform only: RLS on, no policies, no grants to signed-in users.
do $$
declare t text;
begin
  foreach t in array array['sales_leads','sales_activities','sales_quotes','tenant_onboarding','demo_request_tries'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;
revoke all on sequence public.sales_quote_seq from anon, authenticated;
revoke all on function public.next_sales_quote_number() from public, anon, authenticated;
grant execute on function public.next_sales_quote_number() to service_role;

-- ===== 20260101006500_collections_fundraising.sql =====
-- =========================================================================
-- Synergy Swift: fee collections and fundraising (Phase 14g-2).
--  * fee_promises: a parent's promise to pay an amount by a date; checked
--    daily against payments since the promise: kept or broken.
--  * fee_collection_cases: one per family that owes: escalation level
--    (0 none … 4 final notice), owner, next step.
--  * fundraising_campaigns + donations: appeals with a goal and dates, a public
--    giving page (online payment through the school's provider), pledges, cash,
--    transfer and cheque gifts, receipts and donor lists (alumni and parents).
-- Finance staff (bursar, admins) only; the public giving page goes through the
-- server. Idempotent.
-- =========================================================================

create table if not exists public.fee_promises (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  guardian_id  uuid not null references public.guardians(id) on delete cascade,
  student_ids  uuid[] not null default '{}',
  amount       numeric(14,2) not null check (amount > 0),
  promised_by  date not null,
  status       text not null default 'open' check (status in ('open','kept','broken','cancelled')),
  paid         numeric(14,2) not null default 0,
  note         text check (length(note) <= 1000),
  created_by   uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now(),
  settled_at   timestamptz
);
create index if not exists fee_promises_open on public.fee_promises(tenant_id, status, promised_by);
create index if not exists fee_promises_guardian on public.fee_promises(guardian_id, created_at desc);

create table if not exists public.fee_collection_cases (
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  guardian_id     uuid not null references public.guardians(id) on delete cascade,
  level           int not null default 0 check (level between 0 and 4),
  owner_id        uuid references public.users(id) on delete set null,
  next_action_at  timestamptz,
  note            text check (length(note) <= 1000),
  updated_at      timestamptz not null default now(),
  primary key (tenant_id, guardian_id)
);

create table if not exists public.fundraising_campaigns (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  title         text not null check (length(btrim(title)) between 2 and 160),
  slug          text not null check (slug ~ '^[a-z0-9][a-z0-9-]{1,60}$'),
  purpose       text check (length(purpose) <= 4000),
  goal          numeric(14,2) check (goal > 0),
  starts_on     date,
  ends_on       date,
  status        text not null default 'draft' check (status in ('draft','open','closed')),
  show_donors   boolean not null default true,     -- donor names on the public page (never anonymous ones)
  show_raised   boolean not null default true,     -- progress bar on the public page
  cover_url     text,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  unique (tenant_id, slug)
);

create table if not exists public.donations (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  campaign_id   uuid references public.fundraising_campaigns(id) on delete set null,
  donor_name    text not null check (length(btrim(donor_name)) between 1 and 160),
  email         text,
  phone         text,
  guardian_id   uuid references public.guardians(id) on delete set null,
  alumni_id     uuid references public.alumni(id) on delete set null,
  amount        numeric(14,2) not null check (amount > 0),
  currency      text not null default 'NGN',
  kind          text not null default 'gift' check (kind in ('gift','pledge')),
  status        text not null default 'pending' check (status in ('pending','paid','failed','pledged','cancelled')),
  method        text not null default 'online' check (method in ('online','cash','transfer','cheque','pos')),
  anonymous     boolean not null default false,
  message       text check (length(message) <= 1000),
  reference     text unique,
  provider      text,
  receipt_no    text,
  pledge_due    date,
  paid_at       timestamptz,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now()
);
create index if not exists donations_campaign on public.donations(campaign_id, status);
create index if not exists donations_tenant on public.donations(tenant_id, created_at desc);

-- ---------- RLS: finance staff ----------
do $$
declare t text;
begin
  foreach t in array array['fee_promises','fee_collection_cases','fundraising_campaigns','donations'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_finance', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_finance()) with check (tenant_id = public.my_tenant_id() and public.is_finance())', t || '_finance', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;
-- Online gifts are confirmed by the server only (verified with the payment provider).
drop policy if exists donations_finance on public.donations;
drop policy if exists donations_read on public.donations;
create policy donations_read on public.donations for select using (tenant_id = public.my_tenant_id() and public.is_finance());
drop policy if exists donations_offline on public.donations;
create policy donations_offline on public.donations for insert
  with check (tenant_id = public.my_tenant_id() and public.is_finance() and method <> 'online');
drop policy if exists donations_offline_update on public.donations;
create policy donations_offline_update on public.donations for update
  using (tenant_id = public.my_tenant_id() and public.is_finance() and method <> 'online')
  with check (tenant_id = public.my_tenant_id() and public.is_finance() and method <> 'online');

-- Raised so far per campaign (paid gifts), and pledged but not yet paid.
create or replace function public.campaign_totals(p_campaign uuid)
returns table (raised numeric, pledged numeric, donors bigint)
language sql stable security definer set search_path = public as $$
  select coalesce(sum(amount) filter (where status = 'paid'), 0),
         coalesce(sum(amount) filter (where status = 'pledged'), 0),
         count(distinct coalesce(lower(email), lower(donor_name))) filter (where status in ('paid','pledged'))
    from public.donations where campaign_id = p_campaign
$$;
revoke all on function public.campaign_totals(uuid) from public, anon, authenticated;
grant execute on function public.campaign_totals(uuid) to service_role;

-- ===== 20260101006600_whatsapp_inbox.sql =====
-- =========================================================================
-- Synergy Swift: two-way WhatsApp in the school inbox (Phase 14g-3).
--  * Parents' WhatsApp messages to the school's number arrive in the shared
--    school-office inbox as WhatsApp conversations; staff replies go back to the
--    parent's WhatsApp (within WhatsApp's 24-hour window; after it, the parent
--    gets the usual notification to open the portal).
--  * provider_id keeps each WhatsApp message once (webhooks are retried).
--  * whatsapp_unmatched keeps messages from numbers no school knows (platform only).
-- Idempotent.
-- =========================================================================

alter table public.conversations add column if not exists channel text not null default 'app';
alter table public.conversations drop constraint if exists conversations_channel_check;
alter table public.conversations add constraint conversations_channel_check check (channel in ('app','whatsapp'));

alter table public.conversation_messages add column if not exists channel text not null default 'app';
alter table public.conversation_messages add column if not exists provider_id text;
alter table public.conversation_messages add column if not exists delivery text;
alter table public.conversation_messages drop constraint if exists conversation_messages_delivery_check;
alter table public.conversation_messages add constraint conversation_messages_delivery_check check (delivery is null or delivery in ('sent','failed','notified'));
create unique index if not exists conversation_messages_provider on public.conversation_messages(provider_id) where provider_id is not null;

alter table public.tenant_settings add column if not exists whatsapp_inbox boolean not null default true;

create table if not exists public.whatsapp_unmatched (
  id           bigint generated always as identity primary key,
  from_phone   text not null,
  name         text,
  body         text,
  provider_id  text unique,
  received_at  timestamptz not null default now()
);
alter table public.whatsapp_unmatched enable row level security;
revoke all on public.whatsapp_unmatched from anon, authenticated;

-- Families whose phone or WhatsApp number ends with the same ten digits (numbers are stored as
-- typed: spaces, 0803…, +234…), in schools that are active and use the WhatsApp inbox.
create or replace function public.guardians_by_phone(p_digits text)
returns table (guardian_id uuid, tenant_id uuid, full_name text)
language sql stable security definer set search_path = public as $$
  select g.id, g.tenant_id, g.full_name
    from public.guardians g
    join public.tenants t on t.id = g.tenant_id and t.status = 'active'
    left join public.tenant_settings s on s.tenant_id = g.tenant_id
   where coalesce(s.whatsapp_inbox, true)
     and length(regexp_replace(p_digits, '\D', '', 'g')) >= 10
     and (right(regexp_replace(coalesce(g.whatsapp_phone, ''), '\D', '', 'g'), 10) = right(regexp_replace(p_digits, '\D', '', 'g'), 10)
       or right(regexp_replace(coalesce(g.phone, ''), '\D', '', 'g'), 10) = right(regexp_replace(p_digits, '\D', '', 'g'), 10))
$$;
revoke all on function public.guardians_by_phone(text) from public, anon, authenticated;
grant execute on function public.guardians_by_phone(text) to service_role;

-- ===== 20260101006700_sen_engagement.sql =====
-- =========================================================================
-- Synergy Swift: SEN engagement — parents, students and school (Phase 14h).
--  * Parents of a child on the SEN register (when the profile is shared with
--    them) see the support plan, say how each target is going at home, agree
--    the plan, write in a two-way home–school book (with how the day went) and
--    ask for a review meeting.
--  * Students see their own plan in plain words and say how each target is
--    going and what helps them. What the child writes reaches school staff
--    only, never the family (a child may disclose something about home).
--  * The handshake into live lessons: the SENCO's extra time, read-aloud,
--    easy-to-read font and calm mode reach the live-lesson engine
--    (live.student_supports) automatically.
-- Idempotent.
-- =========================================================================

alter table public.sen_profiles add column if not exists share_with_parents boolean not null default true;
alter table public.sen_profiles add column if not exists live_read_aloud boolean not null default false;
alter table public.sen_profiles add column if not exists live_readable_font boolean not null default false;
alter table public.sen_profiles add column if not exists live_calm_mode boolean not null default false;

alter table public.ieps add column if not exists parent_agreed_name text;
alter table public.ieps add column if not exists parent_agreed_by uuid references public.users(id) on delete set null;

create table if not exists public.sen_home_notes (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  student_id         uuid not null references public.students(id) on delete cascade,
  author_kind        text not null check (author_kind in ('staff','parent','student')),
  author_user_id     uuid references public.users(id) on delete set null,
  author_name        text not null,
  kind               text not null default 'note' check (kind in ('note','meeting_request','praise')),
  body               text not null check (length(btrim(body)) between 1 and 4000),
  mood               int check (mood between 1 and 5),       -- how the day went (1 hard … 5 great)
  read_by_staff_at   timestamptz,
  read_by_family_at  timestamptz,
  created_at         timestamptz not null default now()
);
create index if not exists sen_home_notes_student on public.sen_home_notes(student_id, created_at desc);

create table if not exists public.iep_target_feedback (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  target_id       uuid not null references public.iep_targets(id) on delete cascade,
  author_kind     text not null check (author_kind in ('parent','student','staff')),
  author_user_id  uuid references public.users(id) on delete set null,
  author_name     text not null,
  rating          int not null check (rating between 1 and 5),
  comment         text check (length(comment) <= 1000),
  created_at      timestamptz not null default now()
);
create index if not exists iep_target_feedback_target on public.iep_target_feedback(target_id, created_at desc);

-- ---------- who may see what ----------
-- A parent of the child, when the school shares the SEN profile with parents.
create or replace function public.sen_family_can(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_guardian_of(p_student)
     and exists (select 1 from public.sen_profiles p where p.student_id = p_student and p.share_with_parents and p.status <> 'closed')
$$;
-- The child themself.
create or replace function public.sen_is_me(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.students s where s.id = p_student and s.user_id = auth.uid() and s.tenant_id = public.my_tenant_id())
$$;
create or replace function public.iep_target_student(p_target uuid)
returns uuid language sql stable security definer set search_path = public as $$
  select i.student_id from public.iep_targets t join public.ieps i on i.id = t.iep_id where t.id = p_target and t.tenant_id = public.my_tenant_id()
$$;
revoke all on function public.sen_family_can(uuid), public.sen_is_me(uuid), public.iep_target_student(uuid) from public, anon;
grant execute on function public.sen_family_can(uuid), public.sen_is_me(uuid), public.iep_target_student(uuid) to authenticated;

alter table public.sen_home_notes enable row level security;
alter table public.iep_target_feedback enable row level security;
drop policy if exists sen_home_notes_staff on public.sen_home_notes;
create policy sen_home_notes_staff on public.sen_home_notes for select using (tenant_id = public.my_tenant_id() and public.can_read_sen(student_id));
drop policy if exists sen_home_notes_staff_write on public.sen_home_notes;
create policy sen_home_notes_staff_write on public.sen_home_notes for insert
  with check (tenant_id = public.my_tenant_id() and public.can_read_sen(student_id) and author_kind = 'staff' and author_user_id = auth.uid());
drop policy if exists sen_home_notes_family on public.sen_home_notes;
create policy sen_home_notes_family on public.sen_home_notes for select
  using (tenant_id = public.my_tenant_id() and public.sen_family_can(student_id) and author_kind <> 'student');
drop policy if exists sen_home_notes_family_write on public.sen_home_notes;
create policy sen_home_notes_family_write on public.sen_home_notes for insert
  with check (tenant_id = public.my_tenant_id() and public.sen_family_can(student_id) and author_kind = 'parent' and author_user_id = auth.uid());
-- Students see what they wrote and praise from staff.
drop policy if exists sen_home_notes_student on public.sen_home_notes;
create policy sen_home_notes_student on public.sen_home_notes for select
  using (tenant_id = public.my_tenant_id() and public.sen_is_me(student_id) and (author_user_id = auth.uid() or kind = 'praise'));
drop policy if exists sen_home_notes_student_write on public.sen_home_notes;
create policy sen_home_notes_student_write on public.sen_home_notes for insert
  with check (tenant_id = public.my_tenant_id() and public.sen_is_me(student_id) and author_kind = 'student' and author_user_id = auth.uid() and kind = 'note');

drop policy if exists iep_target_feedback_read on public.iep_target_feedback;
create policy iep_target_feedback_read on public.iep_target_feedback for select using (
  tenant_id = public.my_tenant_id() and (public.can_read_sen(public.iep_target_student(target_id))
    or (author_kind <> 'student' and public.sen_family_can(public.iep_target_student(target_id))) or author_user_id = auth.uid()));
drop policy if exists iep_target_feedback_write on public.iep_target_feedback;
create policy iep_target_feedback_write on public.iep_target_feedback for insert with check (
  tenant_id = public.my_tenant_id() and author_user_id = auth.uid() and (
    (author_kind = 'staff' and public.can_read_sen(public.iep_target_student(target_id)))
    or (author_kind = 'parent' and public.sen_family_can(public.iep_target_student(target_id)))
    or (author_kind = 'student' and public.sen_is_me(public.iep_target_student(target_id)))));
grant select, insert on public.sen_home_notes, public.iep_target_feedback to authenticated;

-- ---------- the handshake into live lessons ----------
create or replace function public.sen_live_sync()
returns trigger language plpgsql security definer set search_path = public as $$
declare r public.sen_profiles := coalesce(new, old); v_user uuid; v_pct int;
begin
  if to_regclass('live.student_supports') is null then return null; end if;
  select user_id into v_user from public.students where id = r.student_id;
  if v_user is null or not exists (select 1 from live.users where id = v_user) then return null; end if;
  if tg_op = 'DELETE' or r.status = 'closed' then
    delete from live.student_supports where student_id = v_user and note = 'From the SEN register';
    return null;
  end if;
  v_pct := case when r.extra_time_pct <= 0 then 0 when r.extra_time_pct <= 25 then 25 when r.extra_time_pct <= 50 then 50 else 100 end;
  insert into live.student_supports (student_id, tenant_id, read_aloud, readable_font, extra_time_pct, calm_mode, note, updated_at)
    values (v_user, r.tenant_id, r.live_read_aloud or 'reader' = any(r.arrangements), r.live_readable_font or 'enlarged_print' = any(r.arrangements),
            v_pct, r.live_calm_mode, 'From the SEN register', now())
    on conflict (student_id) do update set read_aloud = excluded.read_aloud, readable_font = excluded.readable_font, extra_time_pct = excluded.extra_time_pct,
      calm_mode = excluded.calm_mode, note = excluded.note, updated_at = now();
  return null;
exception when others then
  return null; -- the live engine is an add-on: never block the SEN register
end $$;
drop trigger if exists sen_profiles_live on public.sen_profiles;
create trigger sen_profiles_live after insert or update or delete on public.sen_profiles for each row execute function public.sen_live_sync();
revoke all on function public.sen_live_sync() from public, anon, authenticated;

-- ===== 20260101006800_staff_time.sql =====
-- =========================================================================
-- Synergy Swift: staff time (Phase 14i-1).
--  * staff_shifts + staff_shift_assignments: shift patterns (day, evening and
--    overnight, e.g. security and boarding staff) with grace minutes and an
--    early-leaving threshold, given to staff for a period. A person cannot be
--    given two shifts whose hours overlap on the same weekday.
--  * staff_time_requests: "I will be late", "I need to leave early" and "I
--    forgot to clock in". The line manager or HR decides; an approved missed
--    clock adds the missing sign-in record, an approved late or early
--    departure is excused (no deduction).
--  * hr_settings: optional payroll deductions for unexcused lateness and
--    absence. Off by default.
--  * tenant_settings: campuses, and how staff may clock in from a phone (a
--    rotating QR code at the entrance, the school's geofence, or both).
--  * gate_events: the campus a sign-in happened at, and early departures.
-- Idempotent.
-- =========================================================================

-- ---------- shifts ----------
create table if not exists public.staff_shifts (
  id                   uuid primary key default gen_random_uuid(),
  tenant_id            uuid not null references public.tenants(id) on delete cascade,
  name                 text not null check (length(btrim(name)) between 2 and 60),
  starts_at            time not null,
  ends_at              time not null,                      -- earlier than starts_at = runs overnight
  days                 int[] not null default '{1,2,3,4,5}', -- ISO weekdays, 1 = Monday
  grace_minutes        int not null default 10 check (grace_minutes between 0 and 120),
  early_leave_minutes  int not null default 15 check (early_leave_minutes between 0 and 240),
  campus               text check (length(campus) <= 60),
  works_holidays       boolean not null default false,       -- security, boarding: the shift runs on school holidays too
  active               boolean not null default true,
  created_at           timestamptz not null default now(),
  unique (tenant_id, name),
  check (ends_at <> starts_at),
  check (cardinality(days) between 1 and 7 and days <@ '{1,2,3,4,5,6,7}'::int[])
);

create table if not exists public.staff_shift_assignments (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  staff_id    uuid not null references public.staff(id) on delete cascade,
  shift_id    uuid not null references public.staff_shifts(id) on delete cascade,
  starts_on   date not null default current_date,
  ends_on     date,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  check (ends_on is null or ends_on >= starts_on)
);
create index if not exists staff_shift_assignments_staff on public.staff_shift_assignments(staff_id, starts_on);
create index if not exists staff_shift_assignments_tenant on public.staff_shift_assignments(tenant_id);

-- Do two daily time ranges overlap? Either may run past midnight.
create or replace function public.time_ranges_overlap(s1 time, e1 time, s2 time, e2 time)
returns boolean language sql immutable set search_path = public as $$
  with a as (select extract(epoch from s1) / 60 s, extract(epoch from e1) / 60 + case when e1 <= s1 then 1440 else 0 end e),
       b as (select extract(epoch from s2) / 60 s, extract(epoch from e2) / 60 + case when e2 <= s2 then 1440 else 0 end e)
  select exists (select 1 from a, b, (values (-1440), (0), (1440)) k(off) where a.s < b.e + k.off and b.s + k.off < a.e)
$$;

create or replace function public.staff_shift_clash()
returns trigger language plpgsql security definer set search_path = public as $$
declare n public.staff_shifts; c record;
begin
  -- Someone who may not assign shifts learns nothing here: row-level security turns them away.
  if auth.uid() is not null and not public.is_hr() then return new; end if;
  select * into n from public.staff_shifts where id = new.shift_id;
  if n.id is null or n.tenant_id <> new.tenant_id then raise exception 'shift not found'; end if;
  if not exists (select 1 from public.staff where id = new.staff_id and tenant_id = new.tenant_id) then raise exception 'staff member not found'; end if;
  for c in
    select s.name, s.starts_at, s.ends_at from public.staff_shift_assignments a join public.staff_shifts s on s.id = a.shift_id
    where a.staff_id = new.staff_id and a.id <> new.id and s.days && n.days
      and a.starts_on <= coalesce(new.ends_on, 'infinity'::date) and coalesce(a.ends_on, 'infinity'::date) >= new.starts_on
  loop
    if public.time_ranges_overlap(c.starts_at, c.ends_at, n.starts_at, n.ends_at) then
      raise exception 'clashes with the % shift this person already has', c.name;
    end if;
  end loop;
  return new;
end $$;
drop trigger if exists staff_shift_clash on public.staff_shift_assignments;
create trigger staff_shift_clash before insert or update on public.staff_shift_assignments for each row execute function public.staff_shift_clash();
revoke all on function public.staff_shift_clash() from public, anon, authenticated;

-- ---------- late, early and missed-clock requests ----------
create table if not exists public.staff_time_requests (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  staff_id       uuid not null references public.staff(id) on delete cascade,
  kind           text not null check (kind in ('late_arrival','early_departure','missed_clock')),
  on_date        date not null,
  at_time        time,                                     -- expected arrival, leaving time, or when the missed clock happened
  direction      text check (direction in ('in','out')),   -- missed clock only
  reason         text not null check (length(btrim(reason)) between 3 and 1000),
  status         text not null default 'pending' check (status in ('pending','approved','declined','cancelled')),
  decided_by     uuid references public.users(id) on delete set null,
  decided_at     timestamptz,
  decision_note  text check (length(decision_note) <= 500),
  gate_event_id  uuid references public.gate_events(id) on delete set null,
  created_by     uuid references public.users(id) on delete set null,
  created_at     timestamptz not null default now(),
  check (kind <> 'missed_clock' or (direction is not null and at_time is not null))
);
create index if not exists staff_time_requests_staff on public.staff_time_requests(tenant_id, staff_id, on_date desc);

-- HR, or the person's line manager, decides.
create or replace function public.can_decide_staff_time(p_staff uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_hr() or public.manages_staff(p_staff)
$$;
revoke all on function public.can_decide_staff_time(uuid) from public, anon;
grant execute on function public.can_decide_staff_time(uuid) to authenticated;

create or replace function public.staff_time_request_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_tz text; v_ev uuid;
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null and new.status <> 'pending' then raise exception 'a new request starts as pending'; end if;
    return new;
  end if;
  if new.staff_id <> old.staff_id or new.kind <> old.kind or new.on_date <> old.on_date or new.at_time is distinct from old.at_time
     or new.direction is distinct from old.direction or new.reason <> old.reason then
    raise exception 'a request cannot be changed; cancel it and make a new one';
  end if;
  if new.status is distinct from old.status then
    if old.status <> 'pending' then raise exception 'this request has already been decided'; end if;
    if new.status = 'cancelled' then
      if auth.uid() is not null and old.staff_id is distinct from public.my_staff_id() and not public.can_decide_staff_time(old.staff_id) then
        raise exception 'only the person who asked can cancel this request';
      end if;
    elsif new.status in ('approved','declined') then
      if auth.uid() is not null then
        if not public.can_decide_staff_time(old.staff_id) then raise exception 'only the line manager or HR can decide this request'; end if;
        if old.staff_id = public.my_staff_id() then raise exception 'you cannot decide your own request'; end if;
      end if;
      new.decided_by := coalesce(auth.uid(), new.decided_by);
      new.decided_at := now();
      -- An approved missed clock adds the sign-in record that was missed.
      if new.status = 'approved' and old.kind = 'missed_clock' and old.gate_event_id is null then
        select timezone into v_tz from public.tenants where id = old.tenant_id;
        insert into public.gate_events (tenant_id, person_type, staff_id, direction, method, recorded_by, note, at)
          values (old.tenant_id, 'staff', old.staff_id, old.direction, 'manual', new.decided_by, 'Missed clock approved',
                  (old.on_date + old.at_time) at time zone coalesce(v_tz, 'Africa/Lagos'))
          returning id into v_ev;
        new.gate_event_id := v_ev;
      end if;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists staff_time_request_guard on public.staff_time_requests;
create trigger staff_time_request_guard before insert or update on public.staff_time_requests for each row execute function public.staff_time_request_guard();
revoke all on function public.staff_time_request_guard() from public, anon, authenticated;

-- ---------- settings ----------
alter table public.hr_settings add column if not exists late_deduction_mode text not null default 'off';
alter table public.hr_settings add column if not exists late_deduction_amount numeric not null default 0;
alter table public.hr_settings add column if not exists late_free_per_month int not null default 3;
alter table public.hr_settings add column if not exists early_counts_as_late boolean not null default true;
alter table public.hr_settings add column if not exists absence_deduction boolean not null default false;
do $$ begin
  alter table public.hr_settings drop constraint if exists hr_settings_late_rules_check;
  alter table public.hr_settings add constraint hr_settings_late_rules_check check (late_deduction_mode in ('off','per_late','per_minute')
    and late_deduction_amount between 0 and 1000000 and late_free_per_month between 0 and 31);
end $$;

alter table public.tenant_settings add column if not exists campuses text[] not null default '{}';
alter table public.tenant_settings add column if not exists staff_self_clock text not null default 'auto';
do $$ begin
  alter table public.tenant_settings drop constraint if exists tenant_settings_staff_self_clock_check;
  alter table public.tenant_settings add constraint tenant_settings_staff_self_clock_check
    check (staff_self_clock in ('auto','qr','geofence','qr_or_geofence','qr_and_geofence') and cardinality(campuses) <= 20);
end $$;

alter table public.gate_events add column if not exists campus text check (length(campus) <= 60);
alter table public.gate_events add column if not exists early boolean not null default false;

-- ---------- RLS ----------
alter table public.staff_shifts enable row level security;
alter table public.staff_shift_assignments enable row level security;
alter table public.staff_time_requests enable row level security;

-- Rosters are visible to staff; HR keeps them.
drop policy if exists staff_shifts_read on public.staff_shifts;
create policy staff_shifts_read on public.staff_shifts for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists staff_shifts_write on public.staff_shifts;
create policy staff_shifts_write on public.staff_shifts for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());
drop policy if exists staff_shift_assignments_read on public.staff_shift_assignments;
create policy staff_shift_assignments_read on public.staff_shift_assignments for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists staff_shift_assignments_write on public.staff_shift_assignments;
create policy staff_shift_assignments_write on public.staff_shift_assignments for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

-- Requests: the person, their line manager and HR.
drop policy if exists staff_time_requests_read on public.staff_time_requests;
create policy staff_time_requests_read on public.staff_time_requests for select using (
  tenant_id = public.my_tenant_id() and (staff_id = public.my_staff_id() or public.can_decide_staff_time(staff_id)));
drop policy if exists staff_time_requests_insert on public.staff_time_requests;
create policy staff_time_requests_insert on public.staff_time_requests for insert with check (
  tenant_id = public.my_tenant_id() and status = 'pending' and created_by = auth.uid()
  and (staff_id = public.my_staff_id() or public.is_hr()));
drop policy if exists staff_time_requests_update on public.staff_time_requests;
create policy staff_time_requests_update on public.staff_time_requests for update using (
  tenant_id = public.my_tenant_id() and (staff_id = public.my_staff_id() or public.can_decide_staff_time(staff_id)));

grant select, insert, update, delete on public.staff_shifts, public.staff_shift_assignments to authenticated;
grant select, insert, update on public.staff_time_requests to authenticated;

-- ===== 20260101006900_bus_exam_safety.sql =====
-- =========================================================================
-- Synergy Swift: bus exceptions and exam-hall safety (Phase 14i-2).
--  * bus_exceptions: a child who boarded the morning bus but is not in
--    school, or boarded the afternoon bus and was never dropped off. Found
--    by the scheduler, sent to transport staff and the heads at once, and
--    closed by a person (with a note) or by itself when the child turns up.
--  * exam_checkins: candidates checked in at the hall door (card, code or by
--    hand) before the paper opens; a series can require it before an online
--    paper starts.
--  * exam_invigilations: invigilators confirm they are in the hall, and
--    cover is recorded when someone else takes the duty.
-- Idempotent.
-- =========================================================================

create table if not exists public.bus_exceptions (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  date             date not null,
  student_id       uuid not null references public.students(id) on delete cascade,
  route_id         uuid references public.transport_routes(id) on delete set null,
  kind             text not null check (kind in ('boarded_not_in_school','not_dropped_off')),
  boarded_at       timestamptz,
  detected_at      timestamptz not null default now(),
  resolved_at      timestamptz,
  resolved_by      uuid references public.users(id) on delete set null,
  resolution_note  text check (length(resolution_note) <= 500),
  unique (tenant_id, date, student_id, kind)
);
create index if not exists bus_exceptions_open on public.bus_exceptions(tenant_id, date desc) where resolved_at is null;

alter table public.exam_series add column if not exists require_checkin boolean not null default false;

create table if not exists public.exam_checkins (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  series_id      uuid not null references public.exam_series(id) on delete cascade,
  paper_id       uuid not null references public.exam_papers(id) on delete cascade,
  student_id     uuid not null references public.students(id) on delete cascade,
  hall_id        uuid references public.exam_halls(id) on delete set null,
  method         text not null default 'card' check (method in ('card','code','manual')),
  checked_in_by  uuid references public.users(id) on delete set null,
  checked_in_at  timestamptz not null default now(),
  unique (paper_id, student_id)
);
create index if not exists exam_checkins_series on public.exam_checkins(series_id, paper_id);

alter table public.exam_invigilations add column if not exists checked_in_at timestamptz;
alter table public.exam_invigilations add column if not exists cover_for uuid references public.users(id) on delete set null;

-- ---------- RLS: staff read; the server writes after its own checks ----------
alter table public.bus_exceptions enable row level security;
alter table public.exam_checkins enable row level security;
drop policy if exists bus_exceptions_staff_read on public.bus_exceptions;
create policy bus_exceptions_staff_read on public.bus_exceptions for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists exam_checkins_staff_read on public.exam_checkins;
create policy exam_checkins_staff_read on public.exam_checkins for select using (tenant_id = public.my_tenant_id() and public.is_staff());
-- A candidate (and their parents) can see that they were checked in.
drop policy if exists exam_checkins_own_read on public.exam_checkins;
create policy exam_checkins_own_read on public.exam_checkins for select using (
  tenant_id = public.my_tenant_id() and exists (select 1 from public.students s where s.id = exam_checkins.student_id and (s.user_id = auth.uid() or public.is_guardian_of(s.id))));
grant select on public.bus_exceptions, public.exam_checkins to authenticated;

-- ===== 20260101007000_exam_office.sql =====
-- =========================================================================
-- Synergy Swift: the exams office (Phase 14j).
--  * A new staff role, exam_officer, who runs the exam planner (halls,
--    timetable, seating, invigilators) alongside the admins.
--  * exam_requests: extra time, a late sitting, a resit, or a special
--    arrangement (reader, scribe, separate room…) for one candidate and one
--    exam, asked for by staff, a parent or the student, decided by the exams
--    office. Approved extra time, late sittings and resits apply to online
--    papers automatically.
--  * exam_attempt_archive: a resit keeps the first attempt, word for word.
-- Idempotent.
-- =========================================================================

alter table public.users drop constraint if exists users_role_check;
alter table public.users add constraint users_role_check check (role in (
  'student','teacher','school_admin','it_admin','parent','platform_admin',
  'principal','bursar','librarian','hr_manager','qa_officer','gate_officer',
  'transport_officer','hostel_warden','nurse','admissions_officer','cashier',
  'counsellor','alumni','exam_officer'
));
create or replace function public.is_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['teacher','school_admin','it_admin','platform_admin','principal',
    'bursar','librarian','hr_manager','qa_officer','gate_officer','transport_officer',
    'hostel_warden','nurse','admissions_officer','cashier','counsellor','exam_officer']);
$$;

create or replace function public.is_exam_office()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or public.has_role(array['exam_officer']);
$$;
revoke all on function public.is_exam_office() from public, anon;
grant execute on function public.is_exam_office() to authenticated;

-- The exams office runs the planner too.
do $$
declare t text;
begin
  foreach t in array array['exam_halls','exam_series','exam_papers','exam_seats','exam_invigilations'] loop
    execute format('drop policy if exists %I on public.%I', t || '_admin_write', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_exam_office()) with check (tenant_id = public.my_tenant_id() and public.is_exam_office())', t || '_admin_write', t);
  end loop;
end $$;

-- ---------- requests ----------
create table if not exists public.exam_requests (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  exam_id         uuid references public.exams(id) on delete cascade,          -- an online paper
  paper_id        uuid references public.exam_papers(id) on delete cascade,    -- or a timetabled paper
  student_id      uuid not null references public.students(id) on delete cascade,
  kind            text not null check (kind in ('extra_time','late_sitting','resit','special_arrangement')),
  minutes         int check (minutes between 1 and 240),
  opens_at        timestamptz,
  closes_at       timestamptz,
  arrangement     text check (length(arrangement) <= 200),
  reason          text not null check (length(btrim(reason)) between 3 and 1000),
  requested_by    uuid references public.users(id) on delete set null,
  requested_as    text not null default 'staff' check (requested_as in ('staff','parent','student')),
  status          text not null default 'pending' check (status in ('pending','approved','declined','cancelled')),
  decided_by      uuid references public.users(id) on delete set null,
  decided_at      timestamptz,
  decision_note   text check (length(decision_note) <= 500),
  used_at         timestamptz,
  created_at      timestamptz not null default now(),
  check (exam_id is not null or paper_id is not null),
  check (kind <> 'extra_time' or minutes is not null),
  check (kind <> 'late_sitting' or (opens_at is not null and closes_at is not null and closes_at > opens_at)),
  check (kind <> 'special_arrangement' or arrangement is not null)
);
create index if not exists exam_requests_open on public.exam_requests(tenant_id, status, created_at desc);
create index if not exists exam_requests_student on public.exam_requests(student_id, exam_id);

create or replace function public.exam_request_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null and new.status <> 'pending' then raise exception 'a new request starts as pending'; end if;
    return new;
  end if;
  if new.student_id <> old.student_id or new.kind <> old.kind or new.exam_id is distinct from old.exam_id or new.paper_id is distinct from old.paper_id
     or new.reason <> old.reason or new.requested_by is distinct from old.requested_by then
    raise exception 'a request cannot be changed; cancel it and ask again';
  end if;
  if new.status is distinct from old.status then
    if old.status <> 'pending' then raise exception 'this request has already been decided'; end if;
    if new.status = 'cancelled' then
      if auth.uid() is not null and old.requested_by is distinct from auth.uid() and not public.is_exam_office() then
        raise exception 'only the person who asked can cancel this request';
      end if;
    elsif auth.uid() is not null and not public.is_exam_office() then
      raise exception 'only the exams office decides exam requests';
    else
      new.decided_by := coalesce(auth.uid(), new.decided_by);
      new.decided_at := now();
    end if;
  elsif auth.uid() is not null and not public.is_exam_office() and (new.minutes is distinct from old.minutes or new.opens_at is distinct from old.opens_at
        or new.closes_at is distinct from old.closes_at or new.used_at is distinct from old.used_at) then
    raise exception 'only the exams office changes a request';
  end if;
  return new;
end $$;
drop trigger if exists exam_request_guard on public.exam_requests;
create trigger exam_request_guard before insert or update on public.exam_requests for each row execute function public.exam_request_guard();
revoke all on function public.exam_request_guard() from public, anon, authenticated;

alter table public.exam_requests enable row level security;
drop policy if exists exam_requests_read on public.exam_requests;
create policy exam_requests_read on public.exam_requests for select using (
  tenant_id = public.my_tenant_id() and (public.is_staff() or public.is_guardian_of(student_id) or public.is_student_self(student_id)));
drop policy if exists exam_requests_insert on public.exam_requests;
create policy exam_requests_insert on public.exam_requests for insert with check (
  tenant_id = public.my_tenant_id() and status = 'pending' and requested_by = auth.uid() and (
    (requested_as = 'staff' and public.is_staff())
    or (requested_as = 'parent' and public.is_guardian_of(student_id))
    or (requested_as = 'student' and public.is_student_self(student_id))));
drop policy if exists exam_requests_update on public.exam_requests;
create policy exam_requests_update on public.exam_requests for update using (
  tenant_id = public.my_tenant_id() and (public.is_exam_office() or requested_by = auth.uid()));
grant select, insert, update on public.exam_requests to authenticated;

-- ---------- a resit keeps the first attempt ----------
create table if not exists public.exam_attempt_archive (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  exam_id          uuid not null references public.exams(id) on delete cascade,
  student_user_id  uuid references public.users(id) on delete set null,
  request_id       uuid references public.exam_requests(id) on delete set null,
  attempt          jsonb not null,
  archived_at      timestamptz not null default now()
);
create index if not exists exam_attempt_archive_exam on public.exam_attempt_archive(exam_id, student_user_id);
alter table public.exam_attempt_archive enable row level security;
drop policy if exists exam_attempt_archive_read on public.exam_attempt_archive;
create policy exam_attempt_archive_read on public.exam_attempt_archive for select using (tenant_id = public.my_tenant_id() and public.is_staff());
grant select on public.exam_attempt_archive to authenticated;

-- ===== 20260101007100_platform_centre.sql =====
-- =========================================================================
-- Synergy Swift: the super admin centre (Phase 14k).
--  * Support access, instead of signing in as a real person: a platform
--    admin opens a short, audited session in one school (15–60 minutes)
--    with a reason. It is a separate account named "Synergy Swift support",
--    so everything it does is recorded under that name, the school can see
--    every visit, and the database stops honouring it the moment it expires
--    (my_tenant_id checks users.support_until).
--  * platform_module_usage(), platform_db_size(): numbers for the centre,
--    service role only.
-- Idempotent.
-- =========================================================================

alter table public.users add column if not exists support_until timestamptz;

create table if not exists public.platform_support_sessions (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  support_user_id  uuid references auth.users(id) on delete set null,
  started_by       uuid references auth.users(id) on delete set null,
  started_by_name  text not null,
  reason           text not null check (length(btrim(reason)) between 10 and 500),
  role             text not null default 'school_admin',
  starts_at        timestamptz not null default now(),
  expires_at       timestamptz not null,
  ended_at         timestamptz,
  ended_by         uuid references auth.users(id) on delete set null,
  check (expires_at > starts_at and expires_at <= starts_at + interval '61 minutes')
);
create index if not exists platform_support_sessions_tenant on public.platform_support_sessions(tenant_id, starts_at desc);
alter table public.platform_support_sessions enable row level security;
revoke all on public.platform_support_sessions from anon, authenticated;

-- The school sees every support visit (who, why, when), never anything about other schools.
create or replace function public.my_support_sessions()
returns table (id uuid, started_by_name text, reason text, starts_at timestamptz, expires_at timestamptz, ended_at timestamptz)
language sql stable security definer set search_path = public as $$
  select s.id, s.started_by_name, s.reason, s.starts_at, s.expires_at, s.ended_at
  from public.platform_support_sessions s
  where s.tenant_id = public.my_tenant_id() and public.is_school_admin()
  order by s.starts_at desc limit 50
$$;
revoke all on function public.my_support_sessions() from public, anon;
grant execute on function public.my_support_sessions() to authenticated;

-- A support account counts only until its session ends. Support sessions are opened by the
-- platform with a one-time link, so the school's second-factor and device rules do not apply to them.
create or replace function public.my_tenant_id()
returns uuid language sql stable security definer set search_path = public as $$
  select u.tenant_id
  from public.users u
  join public.tenants t on t.id = u.tenant_id
  left join public.tenant_settings s on s.tenant_id = u.tenant_id
  where u.id = auth.uid() and t.status = 'active' and u.active and u.role <> 'alumni'
    and (u.support_until is null or u.support_until > now())
    and (u.support_until is not null or (public.mfa_ok(s.require_mfa, u.role, u.extra_roles) and public.session_block(u, s) is null));
$$;

-- Numbers for the centre: in how many schools each module was actually used lately (a row written in the
-- module's main table), and the database size. A table that does not exist is skipped.
create or replace function public.platform_module_activity(p_days int default 30)
returns table (module text, tenants int)
language plpgsql stable security definer set search_path = public as $$
declare m record; n int;
begin
  for m in select * from (values
    ('exams','exam_attempts','started_at'), ('attendance','class_attendance','marked_at'), ('fees','fee_payments','created_at'),
    ('gate','gate_events','at'), ('transport','transport_events','at'), ('library','library_loans','issued_at'),
    ('hr','leave_requests','created_at'), ('payroll','payroll_runs','created_at'), ('lms','assignments','created_at'),
    ('homework','homework','created_at'), ('inbox','conversation_messages','created_at'), ('messaging','message_outbox','created_at'),
    ('admissions','applications','created_at'), ('elections','elections','created_at'), ('sen','sen_profiles','updated_at'),
    ('classroom','point_events','created_at'), ('pickup','pickup_codes','created_at'), ('events','school_events','created_at'),
    ('cover','cover_assignments','created_at'), ('requisitions','requisitions','created_at'), ('hostel','exeat_requests','created_at'),
    ('wallet','wallet_transactions','created_at'), ('lesson_notes','lesson_notes','created_at'), ('inventory','inventory_items','created_at')
  ) v(module, tbl, col)
  loop
    begin
      execute format('select count(distinct tenant_id)::int from public.%I where %I > now() - make_interval(days => $1)', m.tbl, m.col) into n using greatest(1, least(p_days, 365));
      module := m.module; tenants := n; return next;
    exception when others then null;
    end;
  end loop;
end $$;
create or replace function public.platform_db_size()
returns bigint language sql stable security definer set search_path = public as $$
  select pg_database_size(current_database())
$$;
revoke all on function public.platform_module_activity(int), public.platform_db_size() from public, anon, authenticated;
grant execute on function public.platform_module_activity(int), public.platform_db_size() to service_role;

-- ===== 20260101007200_result_pins_perf.sql =====
-- =========================================================================
-- Synergy Swift: result PINs and performance budgets (Phase 14l).
--  * result_pin_batches / result_pins: scratch cards a school prints or sells.
--    A parent enters the admission number and the PIN on the school's result
--    checker page and sees the published report card. Each PIN works a set
--    number of times, belongs to the first student it is used for, and is
--    stored only as a hash (the school prints PINs when the batch is made).
--  * result_pin_tries: slows down guessing (per address and per student).
--  * perf_samples: page speed from real browsers (web vitals) and slow
--    database calls, for the super admin centre's performance budgets.
-- Idempotent.
-- =========================================================================

create table if not exists public.result_pin_batches (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  name        text not null check (length(btrim(name)) between 2 and 80),
  term_id     uuid references public.terms(id) on delete set null,   -- null: any published term
  max_uses    int not null default 5 check (max_uses between 1 and 50),
  price       numeric not null default 0 check (price >= 0),
  pins        int not null check (pins between 1 and 5000),
  expires_on  date,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now()
);

create table if not exists public.result_pins (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  batch_id       uuid not null references public.result_pin_batches(id) on delete cascade,
  serial         text not null,
  pin_hash       text not null,
  student_id     uuid references public.students(id) on delete set null,
  uses           int not null default 0,
  status         text not null default 'active' check (status in ('active','void')),
  first_used_at  timestamptz,
  last_used_at   timestamptz,
  unique (tenant_id, serial),
  unique (tenant_id, pin_hash)
);
create index if not exists result_pins_batch on public.result_pins(batch_id);
create sequence if not exists public.result_pin_serial_seq;
revoke all on sequence public.result_pin_serial_seq from anon, authenticated;

create table if not exists public.result_pin_tries (
  id    bigint generated always as identity primary key,
  key   text not null,
  at    timestamptz not null default now()
);
create index if not exists result_pin_tries_key on public.result_pin_tries(key, at desc);

-- Staff who run results and fees see batches and PIN use; the server makes and checks PINs.
alter table public.result_pin_batches enable row level security;
alter table public.result_pins enable row level security;
alter table public.result_pin_tries enable row level security;
revoke all on public.result_pin_tries from anon, authenticated;
drop policy if exists result_pin_batches_read on public.result_pin_batches;
create policy result_pin_batches_read on public.result_pin_batches for select using (
  tenant_id = public.my_tenant_id() and public.has_role(array['school_admin','principal','platform_admin','bursar','exam_officer']));
drop policy if exists result_pins_read on public.result_pins;
create policy result_pins_read on public.result_pins for select using (
  tenant_id = public.my_tenant_id() and public.has_role(array['school_admin','principal','platform_admin','bursar','exam_officer']));
grant select on public.result_pin_batches, public.result_pins to authenticated;

-- ---------- performance ----------
create table if not exists public.perf_samples (
  id        bigint generated always as identity primary key,
  kind      text not null check (kind in ('vital','slow_call')),
  name      text not null check (length(name) <= 60),     -- LCP, INP, CLS, TTFB, FCP; or the table / function called
  path      text check (length(path) <= 200),             -- the page (with ids replaced) or the API route
  value     double precision not null,                    -- milliseconds (CLS: unitless)
  rating    text check (rating in ('good','needs-improvement','poor')),
  at        timestamptz not null default now()
);
create index if not exists perf_samples_recent on public.perf_samples(kind, at desc);
alter table public.perf_samples enable row level security;
revoke all on public.perf_samples from anon, authenticated;

-- ===== 20260101007300_portfolios_transcripts.sql =====
-- =========================================================================
-- Synergy Swift: portfolios, share links, transcripts and targets (Phase 14o).
--  * Students add their own achievements with a photo; a teacher verifies
--    them before they count (shown as "verified" on the portfolio).
--  * Teachers keep an achievement portfolio too (awards, qualifications,
--    training, publications…), with photos.
--  * portfolio_shares: a private link to a student's or teacher's portfolio
--    dashboard (or one achievement), revocable, with an expiry.
--  * students.transcript_allowed: the transcript can be seen in the portal,
--    but downloaded or printed only once the school allows it for that child
--    (often held back while fees are outstanding).
--  * student_targets / class_targets: targets for a term, with progress.
-- Idempotent.
-- =========================================================================

alter table public.student_achievements add column if not exists photo_path text;
alter table public.student_achievements add column if not exists source text not null default 'staff';
alter table public.student_achievements add column if not exists status text not null default 'verified';
alter table public.student_achievements add column if not exists verified_by uuid references public.users(id) on delete set null;
do $$ begin
  alter table public.student_achievements drop constraint if exists student_achievements_source_status_check;
  alter table public.student_achievements add constraint student_achievements_source_status_check
    check (source in ('staff','student') and status in ('verified','pending','rejected'));
end $$;

create table if not exists public.staff_achievements (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  staff_id     uuid not null references public.staff(id) on delete cascade,
  kind         text not null default 'award' check (kind in ('award','qualification','training','certification','publication','competition','leadership','service','other')),
  title        text not null check (length(btrim(title)) between 2 and 160),
  description  text check (length(description) <= 1000),
  issuer       text check (length(issuer) <= 120),
  achieved_on  date not null default current_date,
  photo_path   text,
  link_url     text check (link_url is null or link_url ~ '^https://'),
  created_at   timestamptz not null default now()
);
create index if not exists staff_achievements_staff on public.staff_achievements(staff_id, achieved_on desc);
alter table public.staff_achievements enable row level security;
drop policy if exists staff_achievements_read on public.staff_achievements;
create policy staff_achievements_read on public.staff_achievements for select using (tenant_id = public.my_tenant_id() and public.is_staff());
grant select on public.staff_achievements to authenticated;

create table if not exists public.portfolio_shares (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  token           text not null unique default encode(gen_random_bytes(20), 'hex'),
  student_id      uuid references public.students(id) on delete cascade,
  staff_id        uuid references public.staff(id) on delete cascade,
  achievement_id  uuid,                    -- one achievement only; null = the whole portfolio
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  expires_at      timestamptz not null default now() + interval '90 days',
  revoked_at      timestamptz,
  views           int not null default 0,
  check ((student_id is null) <> (staff_id is null))
);
create index if not exists portfolio_shares_owner on public.portfolio_shares(tenant_id, student_id, staff_id);
alter table public.portfolio_shares enable row level security;
revoke all on public.portfolio_shares from anon, authenticated;

alter table public.students add column if not exists transcript_allowed boolean not null default false;
alter table public.students add column if not exists transcript_allowed_by uuid references public.users(id) on delete set null;
alter table public.students add column if not exists transcript_allowed_at timestamptz;

create table if not exists public.student_targets (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  student_id   uuid not null references public.students(id) on delete cascade,
  term_id      uuid references public.terms(id) on delete set null,
  subject_id   uuid references public.subjects(id) on delete set null,
  kind         text not null check (kind in ('average','subject_score','attendance','personal')),
  target       numeric check (target is null or target between 0 and 100),
  description  text check (length(description) <= 300),
  set_by       uuid references public.users(id) on delete set null,
  set_by_kind  text not null default 'staff' check (set_by_kind in ('staff','student','parent')),
  status       text not null default 'active' check (status in ('active','met','missed','dropped')),
  created_at   timestamptz not null default now(),
  check (kind <> 'subject_score' or subject_id is not null),
  check (kind = 'personal' or target is not null)
);
create index if not exists student_targets_student on public.student_targets(student_id, created_at desc);

create table if not exists public.class_targets (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_group_id  uuid not null references public.class_groups(id) on delete cascade,
  term_id         uuid references public.terms(id) on delete set null,
  kind            text not null check (kind in ('average','attendance','pass_rate','other')),
  target          numeric check (target is null or target between 0 and 100),
  description     text check (length(description) <= 300),
  set_by          uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists class_targets_class on public.class_targets(class_group_id, created_at desc);

alter table public.student_targets enable row level security;
alter table public.class_targets enable row level security;
drop policy if exists student_targets_read on public.student_targets;
create policy student_targets_read on public.student_targets for select using (
  tenant_id = public.my_tenant_id() and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists class_targets_read on public.class_targets;
create policy class_targets_read on public.class_targets for select using (
  tenant_id = public.my_tenant_id() and (public.is_staff() or exists (
    select 1 from public.students s where s.class_group_id = class_targets.class_group_id and (s.user_id = auth.uid() or public.is_guardian_of(s.id)))));
grant select on public.student_targets, public.class_targets to authenticated;

-- ===== 20260101007400_rls_performance.sql =====
-- =========================================================================
-- Synergy Swift: row-level security that scales (Phase 14m, from the 20,000-user test).
--  * Every policy that calls my_tenant_id(), is_staff(), is_school_admin(),
--    is_hr(), my_staff_id(), is_exam_office() or has_role(array[...]) is
--    rewritten to call it once per query — "(select my_tenant_id())" — instead
--    of once per row. Same rules, same answers; the test showed a school's
--    attendance count taking about 1.2 s instead of 3 ms before this.
--  * Indexes for the busiest per-school reads.
-- Idempotent: an already-wrapped call is left alone, and a policy that cannot be
-- rewritten is skipped with a notice (it keeps working as before).
-- =========================================================================

-- The same three per-student checks as sets, worked out once per query: the children whose guardian I am,
-- my own student record, and the students in classes I teach or am form teacher of (same rules as
-- is_guardian_of, is_student_self and teaches_student).
create or replace function public.my_guardian_students()
returns uuid[] language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(sg.student_id), '{}') from public.student_guardians sg join public.guardians g on g.id = sg.guardian_id where g.user_id = auth.uid()
$$;
create or replace function public.my_self_students()
returns uuid[] language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(s.id), '{}') from public.students s where s.user_id = auth.uid()
$$;
create or replace function public.my_taught_students()
returns uuid[] language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(s.id), '{}') from public.students s join public.class_groups g on g.id = s.class_group_id
  where g.form_teacher_id = auth.uid()
     or exists (select 1 from public.subject_offerings o where o.class_group_id = s.class_group_id and o.teacher_id = auth.uid())
$$;
-- Like the other helpers used inside policies, signed-out requests may call them too (they get empty lists),
-- so a table read without a session answers "nothing" instead of failing.
revoke all on function public.my_guardian_students(), public.my_self_students(), public.my_taught_students() from public;
grant execute on function public.my_guardian_students(), public.my_self_students(), public.my_taught_students() to anon, authenticated;

do $$
declare
  r record; q text; c text; n int := 0;
  pat text := '(?<!select )(?<![a-z_.])(public\.)?(my_tenant_id|is_staff|is_school_admin|is_hr|my_staff_id|is_exam_office)\(\)';
  hr  text := '(?<!select )(?<![a-z_.])(public\.)?has_role\((ARRAY\[[^\]]*\])\)';
  -- is_guardian_of(x) → (x = any ((select my_guardian_students())::uuid[])), and the same for the other two.
  per text := '(?<![a-z_.])(public\.)?(is_guardian_of|is_student_self|teaches_student)\(([a-z_]+\.)?([a-z_]+)\)';
begin
  for r in select schemaname, tablename, policyname, qual, with_check from pg_policies where schemaname = 'public' loop
    q := r.qual; c := r.with_check;
    if q is not null then q := regexp_replace(regexp_replace(q, pat, '(select public.\2())', 'gi'), hr, '(select public.has_role(\2))', 'gi'); end if;
    if c is not null then c := regexp_replace(regexp_replace(c, pat, '(select public.\2())', 'gi'), hr, '(select public.has_role(\2))', 'gi'); end if;
    -- Only plain column arguments are rewritten (a policy passing an expression keeps the per-row check).
    if q is not null then
      q := regexp_replace(q, per, '(\3\4 = any ((select public.my_\2_set())::uuid[]))', 'gi');
      q := replace(replace(replace(q, 'my_is_guardian_of_set', 'my_guardian_students'), 'my_is_student_self_set', 'my_self_students'), 'my_teaches_student_set', 'my_taught_students');
    end if;
    if c is not null then
      c := regexp_replace(c, per, '(\3\4 = any ((select public.my_\2_set())::uuid[]))', 'gi');
      c := replace(replace(replace(c, 'my_is_guardian_of_set', 'my_guardian_students'), 'my_is_student_self_set', 'my_self_students'), 'my_teaches_student_set', 'my_taught_students');
    end if;
    if q is not distinct from r.qual and c is not distinct from r.with_check then continue; end if;
    begin
      if q is not null and c is not null then
        execute format('alter policy %I on %I.%I using (%s) with check (%s)', r.policyname, r.schemaname, r.tablename, q, c);
      elsif q is not null then
        execute format('alter policy %I on %I.%I using (%s)', r.policyname, r.schemaname, r.tablename, q);
      else
        execute format('alter policy %I on %I.%I with check (%s)', r.policyname, r.schemaname, r.tablename, c);
      end if;
      n := n + 1;
    exception when others then
      raise notice 'policy % on % left as it was: %', r.policyname, r.tablename, sqlerrm;
    end;
  end loop;
  raise notice 'row-level security: % policies now check once per query', n;
end $$;

